// Simplified 7-segment display body with CLEAR recessed segment windows + optional decimal point + pins
// Target overall size (bounding box): [12.7, 19, 8.2]  (X, Y, Z)
// One connected solid (pins overlap into body; windows are cutouts)

$fn = 64;

// ---------------- Parameters ----------------
body_W = 12.7;   // X
body_H = 19;     // Y
body_D = 8.2;    // Z

// Robust overlap for booleans + connectivity (1-2mm requested)
overlap = 1.2;

// Front recess / bezel
bezel_thk = 0.8;
bezel_margin = 0.9;

// Segment window geometry (cutouts) - tuned to be recognizable at this small size
seg_depth = 1.6;     // depth of segment recess
seg_thk   = 1.8;     // stroke thickness in XY
seg_end   = 0.7;     // rounding at ends
seg_gap   = 0.7;     // spacing between segments and margins

// Decimal point window (cutout)
dp_enable = true;
dp_radius = 0.85;
dp_depth  = 1.6;

// Pins (2 pins, connected to body by overlap)
pin_radius = 0.7;
pin_len    = 2.5;
pin_pitchX = 6.8;    // distance between pins in X (kept within body width)
pin_inset_Y = 2.2;   // from bottom edge in Y

// ---------------- Helpers ----------------
module rounded_bar_2d(L, T, r) {
    r2 = min(r, T/2);
    hull() {
        translate([-L/2 + r2, 0]) circle(r=r2);
        translate([ L/2 - r2, 0]) circle(r=r2);
    }
}

module seg_window_h(L, T, depth) {
    linear_extrude(height=depth, center=true)
        rounded_bar_2d(L, T, seg_end);
}

module seg_window_v(L, T, depth) {
    rotate([0,0,90]) seg_window_h(L, T, depth);
}

// ---------------- Main solid ----------------
module main_body() {
    cube([body_W, body_H, body_D], center=true);
}

module pins_union() {
    // Place pins on bottom face (Z-), overlapping into body by "overlap"
    // Ensures pins touch/merge with body (no floating)
    z_pin = -body_D/2 - pin_len/2 + overlap;

    // Two pins centered in Y near bottom edge; symmetric in X
    y_pin = -body_H/2 + pin_inset_Y;

    union() {
        translate([-pin_pitchX/2, y_pin, z_pin])
            cylinder(r=pin_radius, h=pin_len, center=true);
        translate([ pin_pitchX/2, y_pin, z_pin])
            cylinder(r=pin_radius, h=pin_len, center=true);
    }
}

// ---------------- Cutouts ----------------
module front_recess_cutout() {
    // Shallow recess on the front face to suggest bezel area
    // Cutout is guaranteed to intersect the body by overlap
    z_recess = body_D/2 - bezel_thk/2; // centered within the front skin
    translate([0, 0, z_recess])
        cube([body_W - 2*bezel_margin, body_H - 2*bezel_margin, bezel_thk + overlap], center=true);
}

module segments_cutouts() {
    // Active area for segments (inside bezel)
    inner_W = body_W - 2*bezel_margin;
    inner_H = body_H - 2*bezel_margin;

    // Keep within inner area and ensure a recognizable 7-seg silhouette
    // Horizontal segments length: leave room for vertical strokes + gaps
    h_len = max(0.1, inner_W - 2*(seg_thk + seg_gap*1.2));

    // Vertical segments length: upper/lower halves with a center gap around middle segment
    // Allocate: top seg_thk + mid seg_thk + bottom seg_thk + 4 gaps + 2*v_len = inner_H
    v_len = max(0.1, (inner_H - 3*seg_thk - 4*seg_gap) / 2);

    // Cut into the front face (Z+). Center the cut volume so it intersects the front face.
    z_cut = body_D/2 - seg_depth/2;

    // Horizontal segment Y positions (a, g, d)
    y_top =  inner_H/2 - seg_thk/2 - seg_gap;
    y_mid =  0;
    y_bot = -inner_H/2 + seg_thk/2 + seg_gap;

    // Vertical segment X positions (f/e on left, b/c on right)
    x_left  = -inner_W/2 + seg_thk/2 + seg_gap;
    x_right =  inner_W/2 - seg_thk/2 - seg_gap;

    // Vertical segment Y positions (upper: f/b, lower: e/c)
    y_upper =  (seg_thk/2 + seg_gap) + v_len/2;
    y_lower = -(seg_thk/2 + seg_gap) - v_len/2;

    union() {
        // a, g, d
        translate([0, y_top, z_cut]) seg_window_h(h_len, seg_thk, seg_depth + overlap);
        translate([0, y_mid, z_cut]) seg_window_h(h_len, seg_thk, seg_depth + overlap);
        translate([0, y_bot, z_cut]) seg_window_h(h_len, seg_thk, seg_depth + overlap);

        // f, b, e, c
        translate([x_left,  y_upper, z_cut]) seg_window_v(v_len, seg_thk, seg_depth + overlap);
        translate([x_right, y_upper, z_cut]) seg_window_v(v_len, seg_thk, seg_depth + overlap);
        translate([x_left,  y_lower, z_cut]) seg_window_v(v_len, seg_thk, seg_depth + overlap);
        translate([x_right, y_lower, z_cut]) seg_window_v(v_len, seg_thk, seg_depth + overlap);

        // Decimal point (bottom-right)
        if (dp_enable) {
            dp_x = inner_W/2 - dp_radius - seg_gap;
            dp_y = -inner_H/2 + dp_radius + seg_gap;
            translate([dp_x, dp_y, body_D/2 - dp_depth/2])
                cylinder(r=dp_radius, h=dp_depth + overlap, center=true);
        }
    }
}

// ---------------- Final model ----------------
module display_digit() {
    // Single connected solid: body + pins, with segment recesses cut into front
    difference() {
        union() {
            main_body();
            pins_union();
        }
        front_recess_cutout();
        segments_cutouts();
    }
}

display_digit();

// Parameters
mast_h = 150; //[75:300:1]
mast_d = 6; //[3:12:0.1]
base_d = 20; //[10:40:0.5]
base_h = 8; //[4:16:0.5]
flange_d = 30; //[15:60:0.5]
flange_h = 3; //[1.5:8:0.5]
hole_count = 4; //[2:8:1]
hole_d = 3.2; //[2:6:0.1]
hole_circle_d = 22; //[12:44:0.5]
connector_d = 8; //[4:16:0.5]
connector_h = 12; //[6:30:1]
tip_h = 12; //[6:30:1]
tip_d2 = 1.5; //[0.5:4:0.1]
boot_h = 18; //[8:40:1]
boot_d = 14; //[8:28:0.5]
knurl_count = 24; //[8:64:1]
knurl_depth = 0.8; //[0.3:2:0.1]
knurl_w = 1.2; //[0.6:3:0.1]
knurl_h = 6; //[2:12:0.5]
overlap = 1; //[0.5:2:0.1]
hole_extra_h = 2; //[1:6:0.5]
enable_flange = 1; //[0:1:1]
enable_connector = 1; //[0:1:1]

// Base Cylinder
module base_cyl() {
  translate([0, 0, 0])
    cylinder(h=base_h, r=base_d/2, center=true);
}

// Mast Cylinder
module mast_cyl() {
  translate([0, 0, base_h/2 + mast_h/2 - overlap])
    cylinder(h=mast_h, r=mast_d/2, center=true);
}

// Tapered Tip Cone
module tapered_tip_cone() {
  translate([0, 0, base_h/2 + mast_h - overlap + tip_h/2])
    cylinder(h=tip_h, r1=mast_d/2, r2=tip_d2/2, center=true);
}

// Strain Relief Boot Cone
module strain_relief_boot_cone() {
  translate([0, 0, base_h/2 + boot_h/2 - overlap])
    cylinder(h=boot_h, r1=boot_d/2, r2=mast_d/2, center=true);
}

// Mounting Flange Cylinder
module mounting_flange_cyl() {
  translate([0, 0, -base_h/2 - (flange_h*enable_flange)/2 + overlap])
    cylinder(h=flange_h*enable_flange, r=flange_d/2, center=true);
}

// Connector Stub Cylinder
module connector_stub_cyl() {
  translate([0, 0, -base_h/2 - (flange_h*enable_flange) - (connector_h*enable_connector)/2 + overlap])
    cylinder(h=connector_h*enable_connector, r=connector_d/2, center=true);
}

// Mounting Holes
module mount_hole_0() {
  translate([hole_circle_d/2, 0, -base_h/2 - (flange_h*enable_flange)/2 + overlap])
    cylinder(h=flange_h*enable_flange + hole_extra_h, r=hole_d/2, center=true);
}

module mount_hole_90() {
  translate([0, hole_circle_d/2, -base_h/2 - (flange_h*enable_flange)/2 + overlap])
    cylinder(h=flange_h*enable_flange + hole_extra_h, r=hole_d/2, center=true);
}

module mount_hole_180() {
  translate([-hole_circle_d/2, 0, -base_h/2 - (flange_h*enable_flange)/2 + overlap])
    cylinder(h=flange_h*enable_flange + hole_extra_h, r=hole_d/2, center=true);
}

module mount_hole_270() {
  translate([0, -hole_circle_d/2, -base_h/2 - (flange_h*enable_flange)/2 + overlap])
    cylinder(h=flange_h*enable_flange + hole_extra_h, r=hole_d/2, center=true);
}

// Knurl Ribs
module knurl_rib(angle) {
  rotate([0, 0, angle])
    translate([base_d/2 + knurl_depth/2 - overlap, 0, -base_h/2 + knurl_h/2 + overlap])
      cube([knurl_depth, knurl_w, knurl_h], center=true);
}

// Assemble the antenna
module antenna() {
  difference() {
    union() {
      // Main solids
      union() {
        base_cyl();
        mast_cyl();
        tapered_tip_cone();
        strain_relief_boot_cone();
        mounting_flange_cyl();
        connector_stub_cyl();
      }
      // Knurling
      for (i = [0:knurl_count-1])
        knurl_rib(i * 360/knurl_count);
    }
    // Mounting holes
    mount_hole_0();
    mount_hole_90();
    mount_hole_180();
    mount_hole_270();
  }
}

// Render the antenna
antenna();

$fn = 64;

// Target overall dimensions (A axial): [3.4, 1.75, 0.3]
length = 3.4;
width  = 1.75;
height = 0.3;

// Small edge rounding to make it look like a real axial body while
// keeping the exact overall bounding box dimensions.
edge_r = min(0.08, height/2 - 0.001, width/2 - 0.001, length/2 - 0.001);

module rounded_box_exact(L, W, H, r) {
    // Minkowski expands by r, so shrink core by 2r to keep exact outer size.
    minkowski() {
        cube([L - 2*r, W - 2*r, H - 2*r], center=true);
        sphere(r=r);
    }
}

module axial_body() {
    color([0.85, 0.85, 0.8])
        rounded_box_exact(length, width, height, edge_r);
}

axial_body();

// Axial target
ax_x = 5.21; //[2.605:10.42:0.01]
ax_y = 2.72; //[1.36:5.44:0.01]
ax_z = 0;    //[−5:5:0.01]

// Geometry
rod_radius = 0.5;            //[0.25:1:0.05]
origin_marker_radius = 1;    //[0.5:2:0.05]
origin_marker_height = 1;    //[0.5:2:0.05]
arrowhead_length = 2;        //[1:4:0.1]
arrowhead_radius = 1.2;      //[0.6:2.4:0.05]
end_marker_radius = 0.9;     //[0.45:1.8:0.05]
connect_overlap = 0.6;       //[0.2:1.5:0.05]

// Derived
vlen = sqrt(ax_x*ax_x + ax_y*ax_y + ax_z*ax_z);
eps = 1e-9;

// Rotate +Z to vector [vx, vy, vz]
module orient_to_vector(vx, vy, vz) {
    L = sqrt(vx*vx + vy*vy + vz*vz) + eps;

    // axis = cross([0,0,1],[vx,vy,vz]) = [-vy, vx, 0]
    ax = -vy;
    ay =  vx;
    az =  0;

    ang = acos(vz / L) * 180 / PI;

    if (abs(vx) < 1e-8 && abs(vy) < 1e-8) {
        if (vz >= 0) children();
        else rotate([180,0,0]) children();
    } else {
        rotate(a=ang, v=[ax, ay, az]) children();
    }
}

module axis_indicator_union() {
    union() {
        // Origin marker (centered at origin)
        cylinder(h=origin_marker_height, r=origin_marker_radius, center=true, $fn=64);

        // Rod: centered so it overlaps into origin marker and into arrowhead base
        orient_to_vector(ax_x, ax_y, ax_z)
            translate([0, 0, (vlen - arrowhead_length/2)/2])
                cylinder(
                    h=(vlen - arrowhead_length/2) + 2*connect_overlap,
                    r=rod_radius,
                    center=true,
                    $fn=64
                );

        // Arrowhead: base overlaps rod end
        orient_to_vector(ax_x, ax_y, ax_z)
            translate([0, 0, vlen - arrowhead_length/2 + connect_overlap])
                cylinder(
                    h=arrowhead_length,
                    r1=arrowhead_radius,
                    r2=0,
                    center=true,
                    $fn=64
                );

        // End marker: place along the axis direction so it intersects the arrow tip
        // (ensures one connected solid even when ax_z=0 and view projections look separated)
        orient_to_vector(ax_x, ax_y, ax_z)
            translate([0, 0, vlen + end_marker_radius - connect_overlap])
                sphere(r=end_marker_radius, $fn=64);
    }
}

axis_indicator_union();

// Parameters
bore_d = 8.0; //[4.0:16.0:0.1]
outer_d = 22.0; //[11.0:44.0:0.1]
width = 7.0; //[3.5:14.0:0.1]
inner_ring_radial_thk = 3.0; //[1.5:6.0:0.1]
outer_ring_radial_thk = 3.0; //[1.5:6.0:0.1]
ball_d = 3.5; //[1.5:7.0:0.1]
ball_count = 7; //[5:12:1]
ball_clearance = 0.2; //[0.0:0.6:0.05]
groove_depth = 0.6; //[0.2:1.2:0.05]
groove_radius = 1.9; //[1.0:3.5:0.05]
cage_thk = 0.8; //[0.4:1.6:0.05]
cage_clearance = 0.2; //[0.0:0.6:0.05]
shield_thk = 0.3; //[0.15:0.8:0.05]
shield_radial_gap = 0.3; //[0.1:1.0:0.05]
overlap = 0.8; //[0.5:2.0:0.1]

// Base Shapes
module outer_ring_outer_cyl() {
  cylinder(r=outer_d/2, h=width, center=true);
}

module outer_ring_inner_bore_cyl() {
  cylinder(r=outer_d/2 - outer_ring_radial_thk, h=width + 2*overlap, center=true);
}

module inner_ring_outer_cyl() {
  cylinder(r=bore_d/2 + inner_ring_radial_thk, h=width, center=true);
}

module inner_ring_bore_cyl() {
  cylinder(r=bore_d/2, h=width + 2*overlap, center=true);
}

module outer_race_groove_torus() {
  rotate_extrude() translate([((outer_d/2 - outer_ring_radial_thk) - (bore_d/2 + inner_ring_radial_thk))/2 + (bore_d/2 + inner_ring_radial_thk), 0, 0])
    circle(r=groove_radius);
}

module inner_race_groove_torus() {
  rotate_extrude() translate([((outer_d/2 - outer_ring_radial_thk) - (bore_d/2 + inner_ring_radial_thk))/2 + (bore_d/2 + inner_ring_radial_thk), 0, 0])
    circle(r=groove_radius);
}

module ball(position_angle) {
  translate([((outer_d/2 - outer_ring_radial_thk) + (bore_d/2 + inner_ring_radial_thk))/2 * cos(position_angle),
             ((outer_d/2 - outer_ring_radial_thk) + (bore_d/2 + inner_ring_radial_thk))/2 * sin(position_angle), 0])
    sphere(r=ball_d/2);
}

module cage_outer_cyl() {
  cylinder(r=((outer_d/2 - outer_ring_radial_thk) + (bore_d/2 + inner_ring_radial_thk))/2 + (ball_d/2 + cage_clearance) + cage_thk,
           h=width - 2*(shield_thk + overlap), center=true);
}

module cage_inner_cyl() {
  cylinder(r=((outer_d/2 - outer_ring_radial_thk) + (bore_d/2 + inner_ring_radial_thk))/2 - (ball_d/2 + cage_clearance) - cage_thk,
           h=width - 2*(shield_thk + overlap) + 2*overlap, center=true);
}

module shield_top_disk() {
  translate([0, 0, width/2 - shield_thk/2])
    cylinder(r=outer_d/2 - overlap, h=shield_thk, center=true);
}

module shield_top_hole() {
  translate([0, 0, width/2 - shield_thk/2])
    cylinder(r=bore_d/2 + inner_ring_radial_thk + shield_radial_gap, h=shield_thk + 2*overlap, center=true);
}

module shield_bottom_disk() {
  translate([0, 0, -width/2 + shield_thk/2])
    cylinder(r=outer_d/2 - overlap, h=shield_thk, center=true);
}

module shield_bottom_hole() {
  translate([0, 0, -width/2 + shield_thk/2])
    cylinder(r=bore_d/2 + inner_ring_radial_thk + shield_radial_gap, h=shield_thk + 2*overlap, center=true);
}

// Operations
module outer_ring_raw() {
  difference() {
    outer_ring_outer_cyl();
    outer_ring_inner_bore_cyl();
  }
}

module inner_ring_raw() {
  difference() {
    inner_ring_outer_cyl();
    inner_ring_bore_cyl();
  }
}

module outer_race_groove_scaled() {
  scale([1, 1, groove_depth/groove_radius])
    outer_race_groove_torus();
}

module inner_race_groove_scaled() {
  scale([1, 1, groove_depth/groove_radius])
    inner_race_groove_torus();
}

module outer_ring() {
  difference() {
    outer_ring_raw();
    outer_race_groove_scaled();
  }
}

module inner_ring() {
  difference() {
    inner_ring_raw();
    inner_race_groove_scaled();
  }
}

module raceway_grooves() {
  union() {
    outer_race_groove_scaled();
    inner_race_groove_scaled();
  }
}

module ball_set() {
  union() {
    for (i = [0:ball_count-1]) {
      ball(360/ball_count*i);
    }
  }
}

module cage_ring() {
  difference() {
    cage_outer_cyl();
    cage_inner_cyl();
  }
}

module cage() {
  union() {
    cage_ring();
    ball_set();
  }
}

module shield_top() {
  difference() {
    shield_top_disk();
    shield_top_hole();
  }
}

module shield_bottom() {
  difference() {
    shield_bottom_disk();
    shield_bottom_hole();
  }
}

module shields_or_seals() {
  union() {
    shield_top();
    shield_bottom();
  }
}

module bearing_core() {
  union() {
    outer_ring();
    inner_ring();
    cage();
    shields_or_seals();
  }
}

// Final Output
bearing_core();

// Simplified ball bearing (single connected solid) with visible balls/races/shields
// Target dimensions: 10.0mm bore, 30.0mm outer diameter, 9.0mm width

$fn = 180;

// --- Locked target dimensions ---
bore_d  = 10.0;
outer_d = 30.0;
width   = 9.0;

// --- Proportional detail parameters (kept simple/recognizable) ---
ring_radial_thk = 4.0;     // radial thickness of each race ring
raceway_depth   = 1.0;     // groove depth (visual)
ball_d          = 5.0;     // sized to fit between rings
ball_count      = 10;      // recognizable ring of balls
cage_thk        = 1.2;
cage_clearance  = 0.35;
seal_thk        = 0.7;
seal_radial_margin = 0.8;
chamfer_r       = 0.6;

// Connectivity overlap (small, dimension-based)
overlap = 0.6;             // 1-2mm requested; keep modest but effective

// --- Derived radii ---
bore_r  = bore_d/2;
outer_r = outer_d/2;

// Ring boundaries
inner_ring_or = bore_r + ring_radial_thk;     // inner ring outer radius
outer_ring_ir = outer_r - ring_radial_thk;    // outer ring inner radius

// Ball pitch radius (center of balls)
ball_pitch_r = (inner_ring_or + outer_ring_ir)/2;

// --- Helpers ---
module torus(major_r, minor_r) {
    rotate_extrude(convexity=10)
        translate([major_r, 0, 0])
            circle(r=minor_r);
}

// Raceway groove cutter: torus centered at ball pitch radius
module raceway_cutter() {
    torus(ball_pitch_r, raceway_depth);
}

// Outer ring with groove and chamfers
module outer_ring() {
    difference() {
        cylinder(r=outer_r, h=width, center=true);

        // Inner void
        cylinder(r=outer_ring_ir, h=width + 2*overlap, center=true);

        // Raceway groove (subtract)
        raceway_cutter();

        // Chamfers (subtract small tori at edges)
        translate([0,0, width/2 - chamfer_r])
            torus(outer_r - chamfer_r, chamfer_r);
        translate([0,0,-width/2 + chamfer_r])
            torus(outer_r - chamfer_r, chamfer_r);

        translate([0,0, width/2 - chamfer_r])
            torus(outer_ring_ir + chamfer_r, chamfer_r);
        translate([0,0,-width/2 + chamfer_r])
            torus(outer_ring_ir + chamfer_r, chamfer_r);
    }
}

// Inner ring with groove and chamfers
module inner_ring() {
    difference() {
        cylinder(r=inner_ring_or, h=width, center=true);

        // Bore
        cylinder(r=bore_r, h=width + 2*overlap, center=true);

        // Raceway groove (subtract)
        raceway_cutter();

        // Chamfers
        translate([0,0, width/2 - chamfer_r])
            torus(inner_ring_or - chamfer_r, chamfer_r);
        translate([0,0,-width/2 + chamfer_r])
            torus(inner_ring_or - chamfer_r, chamfer_r);

        translate([0,0, width/2 - chamfer_r])
            torus(bore_r + chamfer_r, chamfer_r);
        translate([0,0,-width/2 + chamfer_r])
            torus(bore_r + chamfer_r, chamfer_r);
    }
}

// Balls: slightly oversized so they visibly intersect both races (single solid union)
module balls() {
    // Ensure balls bridge the gap between rings:
    // gap = outer_ring_ir - inner_ring_or; ball radius should be >= gap/2
    // We keep ball_d as given, but add a small scale to guarantee intersection.
    for (i = [0:ball_count-1]) {
        rotate([0,0, i*360/ball_count])
            translate([ball_pitch_r, 0, 0])
                scale([1.06, 1.06, 1.06]) sphere(r=ball_d/2);
    }
}

// Cage (thin ring with ball pockets), centered; overlaps balls slightly
module cage() {
    cage_or = ball_pitch_r + ball_d/2 - cage_clearance;
    cage_ir = ball_pitch_r - ball_d/2 + cage_clearance;

    difference() {
        cylinder(r=cage_or, h=cage_thk, center=true);
        cylinder(r=cage_ir, h=cage_thk + 2*overlap, center=true);

        for (i = [0:ball_count-1]) {
            rotate([0,0, i*360/ball_count])
                translate([ball_pitch_r, 0, 0])
                    cylinder(r=ball_d/2 + cage_clearance, h=cage_thk + 2*overlap, center=true);
        }
    }
}

// Shields (two thin washers), placed just inside faces with overlap into rings
module shields() {
    shield_r_outer = outer_r - seal_radial_margin;
    shield_r_inner = bore_r + seal_radial_margin;

    // Put shields slightly inside the bearing faces so they intersect rings
    // z = (width/2 - seal_thk/2) minus a small amount to force overlap
    z_pos = (width/2 - seal_thk/2) - overlap;

    for (s = [-1, 1]) {
        translate([0,0, s*z_pos])
            difference() {
                cylinder(r=shield_r_outer, h=seal_thk + 2*overlap, center=true);
                cylinder(r=shield_r_inner, h=seal_thk + 2*overlap + 0.2, center=true);
            }
    }
}

// Internal connector web: thin annulus that bridges inner and outer rings (hidden inside)
// Keep it thin so silhouette remains a bearing, but ensure strong connection.
module connector_web() {
    connector_h = 0.8; // thin but printable/robust
    web_or = outer_ring_ir + overlap;   // reaches into outer ring
    web_ir = inner_ring_or - overlap;   // reaches into inner ring

    // Guard against accidental inversion if parameters change
    web_ir_safe = min(web_ir, web_or - 0.2);

    difference() {
        cylinder(r=web_or, h=connector_h, center=true);
        cylinder(r=web_ir_safe, h=connector_h + 2*overlap, center=true);
    }
}

// --- Complete bearing (ONE connected solid) ---
module bearing_complete() {
    union() {
        outer_ring();
        inner_ring();

        // Visible ball set between races
        balls();

        // Cage centered; intersects balls slightly
        cage();

        // Shields overlap into rings
        shields();

        // Guaranteed internal connection between inner and outer rings
        connector_web();
    }
}

