    }
}

module flange() {
    // Flange is a ring attached to the outer ring on +Z side
    // OD = flange_d, ID = od_d (true flange lip)
    translate([0,0,flange_z])
    difference() {
        cylinder(r=flange_r, h=flange_t, center=true);
        cylinder(r=od_r,     h=flange_t + 2*overlap, center=true);
    }
}

module shields() {
    // Thin shields inside the outer ring, leaving a visible gap to the inner ring.
    // Make them TOUCH the outer ring by setting shield_r slightly larger than outer_inner_r.
    // This guarantees connectivity even if balls are small.
    shield_r = max(outer_inner_r + overlap, od_r - shield_clear_r);

    // Keep shield within OD
    shield_r = min(shield_r, od_r);

    zL = -width_w/2 + shield_t/2 + overlap;
    zR =  width_w/2 - shield_t/2 - overlap;

    for (zpos = [zL, zR]) {
        translate([0,0,zpos])
        difference() {
            cylinder(r=shield_r, h=shield_t, center=true);
            cylinder(r=inner_od_r_safe + race_gap/2, h=shield_t + 2*overlap, center=true);
        }
    }
}

module balls() {
    // Balls overlap slightly into both rings so the final model is one connected solid.
    r = max(ball_r_eff, 0.18);

    // Nudge ball path so balls intersect both rings reliably
    // (still derived from ring radii; no arbitrary placement)
    ball_path_r_nudged = ball_path_r;

    for (i = [0:ball_count-1]) {
        a = i * 360 / ball_count;
        translate([ball_path_r_nudged*cos(a), ball_path_r_nudged*sin(a), 0])
            sphere(r=r);
    }
}

module complete_model() {
    union() {
        outer_ring();
        inner_ring();
        flange();
        shields();
        balls();
    }
}

// Render
complete_model();

// Flanged ball bearing (single connected solid)
// Target: 5.0mm bore, 16.0mm OD, 5.0mm width, 18.0mm flange OD

$fn = 160;

// Parameters
bore_d        = 5.0;   //[2.5:10.0:0.1]
od_d          = 16.0;  //[8.0:32.0:0.1]
width         = 5.0;   //[2.5:10.0:0.1]
flange_od_d   = 18.0;  //[9.0:36.0:0.1]
flange_thk    = 1.0;   //[0.5:2.0:0.05]

// Visual/detail parameters (kept subtle but visible)
inner_ring_od_d   = 9.0;   //[4.5:18.0:0.1]
outer_ring_id_d   = 12.0;  //[6.0:24.0:0.1]
groove_depth      = 0.45;  //[0.2:0.9:0.05]
groove_width      = 1.2;   //[0.6:2.4:0.05]
shield_thk        = 0.25;  //[0.1:0.6:0.05]
ball_d            = 2.0;   //[1.0:4.0:0.05]
ball_count        = 8;     //[6:14:1]
cage_thk          = 0.8;   //[0.4:1.6:0.05]
cage_radial_thk   = 0.6;   //[0.3:1.2:0.05]

// Robust boolean overlap
overlap = 0.6; //[0.2:2.0:0.1]

// Derived
ball_path_r = (outer_ring_id_d/2 + inner_ring_od_d/2)/2;

// Safety checks (geometry sanity)
assert(bore_d < inner_ring_od_d, "bore_d must be smaller than inner_ring_od_d");
assert(inner_ring_od_d < outer_ring_id_d, "inner_ring_od_d must be smaller than outer_ring_id_d");
assert(outer_ring_id_d < od_d, "outer_ring_id_d must be smaller than od_d");
assert(flange_od_d >= od_d, "flange_od_d should be >= od_d");
assert(flange_thk <= width, "flange_thk must be <= width");

// -------------------- Base solids --------------------
module outer_ring_solid() {
    cylinder(h=width, r=od_d/2, center=true);
}

module flange_solid() {
    // Flange on +Z face, connected with slight overlap
    translate([0,0, width/2 - flange_thk/2 - overlap/2])
        cylinder(h=flange_thk + overlap, r=flange_od_d/2, center=true);
}

module inner_ring_solid() {
    cylinder(h=width, r=inner_ring_od_d/2, center=true);
}

// -------------------- Cuts / details --------------------
module bore_cut() {
    cylinder(h=width + 4*overlap, r=bore_d/2, center=true);
}

module outer_ring_id_cut() {
    cylinder(h=width + 4*overlap, r=outer_ring_id_d/2, center=true);
}

// Race grooves (torus-like cuts limited to bearing width)
module groove_window(z_center=0) {
    translate([0,0,z_center])
        cube([od_d + 4*overlap, od_d + 4*overlap, groove_width], center=true);
}

module outer_race_groove_cut() {
    // Cut a circular groove near the inner diameter of the outer ring
    intersection() {
        rotate_extrude()
            translate([outer_ring_id_d/2 + groove_depth, 0, 0])
                circle(r=groove_width/2);
        groove_window(0);
    }
}

module inner_race_groove_cut() {
    // Cut a circular groove near the outer diameter of the inner ring
    intersection() {
        rotate_extrude()
            translate([inner_ring_od_d/2 - groove_depth, 0, 0])
                circle(r=groove_width/2);
        groove_window(0);
    }
}

// Shields (thin rings) - kept connected via tiny overlap into outer ring
module shield(zsign=1) {
    z = zsign*(width/2 - shield_thk/2);
    translate([0,0,z])
        difference() {
            cylinder(h=shield_thk + overlap, r=outer_ring_id_d/2 - 0.15, center=true);
            cylinder(h=shield_thk + 3*overlap, r=inner_ring_od_d/2 + 0.15, center=true);
        }
}

// Cage ring (simple ring around balls) - connected by slight overlap to shields/balls
module cage_ring() {
    difference() {
        cylinder(h=cage_thk + overlap, r=ball_path_r + ball_d/2 + cage_radial_thk, center=true);
        cylinder(h=cage_thk + 3*overlap, r=ball_path_r - ball_d/2 - cage_radial_thk, center=true);
    }
}

// Balls (for visual detail). They will be fused into the single solid.
module balls() {
    for (i = [0:ball_count-1]) {
        rotate([0,0,i*360/ball_count])
            translate([ball_path_r, 0, 0])
                sphere(r=ball_d/2);
    }
}

// -------------------- Final assembly (ONE connected solid) --------------------
module bearing() {
    // Make a single connected solid with a real through-bore.
    difference() {
        union() {
            // Outer ring with flange
            difference() {
                union() {
                    outer_ring_solid();
                    flange_solid();
                }
                // Outer ring inner diameter
                outer_ring_id_cut();
                // Outer race groove
                outer_race_groove_cut();
            }

            // Inner ring (kept as solid ring; bore cut applied at end)
            difference() {
                inner_ring_solid();
                // Inner race groove
                inner_race_groove_cut();
            }

            // Shields + cage + balls (all fused)
            shield( 1);
            shield(-1);
            cage_ring();
            balls();
        }

        // Final through-bore cut ensures visible 5mm hole through everything
        bore_cut();
    }
}

bearing();

// Flanged ball bearing: 3.0mm bore, 8.0mm OD, 3.0mm width, 9.5mm flange OD
// One connected solid; visible through-bore; recognizable inner/outer race + ball groove + cage pockets.

$fn = 128;

// Parameters
bore_d   = 3.0;   //[1.5:6.0:0.1]
od_d     = 8.0;   //[4.0:16.0:0.1]
width_w  = 3.0;   //[1.5:6.0:0.1]
flange_d = 9.5;   //[6.0:19.0:0.1]
flange_t = 0.6;   //[0.3:1.2:0.05]

race_radial_t   = 0.8;  //[0.4:1.6:0.05]
race_axial_step = 0.3;  //[0.15:0.6:0.05]
chamfer_c       = 0.2;  //[0.1:0.5:0.05]

ball_d     = 0.9; //[0.5:1.8:0.05]
ball_count = 8;   //[4:16:1]

seal_t  = 0.25; //[0.15:0.6:0.05]
overlap = 0.2;  //[0.05:1.0:0.05]

// Derived
body_r   = od_d/2;
bore_r   = bore_d/2;
flange_r = flange_d/2;

inner_race_r = bore_r + race_radial_t;
outer_race_r = body_r - race_radial_t;

ball_path_r = (inner_race_r + outer_race_r)/2;

// Keep balls inside the body envelope
ball_path_r = min(ball_path_r, body_r - ball_d/2 - 0.15);
ball_path_r = max(ball_path_r, bore_r + ball_d/2 + 0.15);

// Groove (torus) radius for raceway impression
groove_r = ball_d*0.55;

// Cage ring dimensions (kept within bearing body)
cage_thick = max(0.35, ball_d*0.45);
cage_r_out = min(body_r - 0.25, ball_path_r + ball_d/2 + cage_thick);
cage_r_in  = max(bore_r + 0.25, ball_path_r - ball_d/2 - cage_thick);
cage_h     = min(width_w - 2*seal_t - 0.2, ball_d + 0.25);
cage_h     = max(cage_h, ball_d*0.9);

// Helpers
module torus(R, r) {
  rotate_extrude(convexity=10)
    translate([R, 0, 0])
      circle(r=r, $fn=64);
}

module chamfer_ring(z, r_outer, r_inner, c) {
  // subtractive chamfer ring at face z (centered model)
  translate([0,0,z])
    difference() {
      cylinder(h=c + 2*overlap, r=r_outer + overlap, center=true);
      cylinder(h=c + 4*overlap, r=r_inner - overlap, center=true);
      // cone to create chamfer
      cylinder(h=c + 2*overlap, r1=r_outer + overlap, r2=r_outer - c, center=true);
    }
}

module bearing_solid_with_flange() {
  union() {
    // Main body
    cylinder(r=body_r, h=width_w, center=true);

    // Flange on +Z face, connected with slight overlap
    translate([0,0, width_w/2 - flange_t/2 + overlap/2])
      cylinder(r=flange_r, h=flange_t + overlap, center=true);
  }
}

module bore_through() {
  cylinder(r=bore_r, h=width_w + flange_t + 6*overlap, center=true);
}

module raceway_grooves() {
  // Subtractive grooves to suggest ball tracks (inner + outer)
  // Positioned at mid-plane so they are visible in section and edges.
  union() {
    // Outer race groove
    torus(ball_path_r, groove_r);

    // Slightly offset second groove to hint inner/outer separation
    // (still subtractive, creates a more "bearing-like" profile)
    translate([0,0,0])
      torus(ball_path_r, groove_r*0.75);
  }
}

module inner_outer_race_steps() {
  // Additive steps to show inner/outer race separation (still one solid overall)
  union() {
    // Inner race ring (around bore)
    cylinder(r=inner_race_r, h=width_w - 2*race_axial_step, center=true);

    // Outer race ring (near OD)
    difference() {
      cylinder(r=body_r, h=width_w - 2*race_axial_step, center=true);
      cylinder(r=outer_race_r, h=width_w - 2*race_axial_step + 2*overlap, center=true);
    }
  }
}

module seals() {
  // Thin shields near faces (additive)
  union() {
    translate([0,0, width_w/2 - seal_t/2 - chamfer_c/2])
      cylinder(r=body_r - chamfer_c, h=seal_t, center=true);

    translate([0,0,-width_w/2 + seal_t/2 + chamfer_c/2])
      cylinder(r=body_r - chamfer_c, h=seal_t, center=true);
  }
}

module cage_with_pockets() {
  // Cage ring with ball pockets (additive, connected to races via overlap)
  difference() {
    cylinder(r=cage_r_out, h=cage_h, center=true);
    cylinder(r=cage_r_in,  h=cage_h + 2*overlap, center=true);

    // Ball pockets
    for (i = [0:ball_count-1]) {
      rotate([0,0,i*360/ball_count])
        translate([ball_path_r, 0, 0])
          sphere(r=ball_d/2 + 0.08, $fn=48);
    }
  }
}

module balls() {
  // Add balls (additive) so they are visible; they intersect grooves/cage slightly to ensure connectivity.
  for (i = [0:ball_count-1]) {
    rotate([0,0,i*360/ball_count])
      translate([ball_path_r, 0, 0])
        sphere(r=ball_d/2, $fn=48);
  }
}

module face_chamfers_subtractive() {
  // Subtractive chamfers on main body OD (not flange OD)
  union() {
    // Top face chamfer on body OD
    translate([0,0, width_w/2 - chamfer_c/2])
      cylinder(h=chamfer_c + 2*overlap, r1=body_r + overlap, r2=body_r - chamfer_c, center=true);

    // Bottom face chamfer on body OD
    translate([0,0,-width_w/2 + chamfer_c/2])
      cylinder(h=chamfer_c + 2*overlap, r1=body_r - chamfer_c, r2=body_r + overlap, center=true);
  }
}

// Final model (one connected solid)
difference() {
  union() {
    bearing_solid_with_flange();
    inner_outer_race_steps();
    seals();
    cage_with_pockets();
    balls();
  }

  // Ensure visible through-bore
  bore_through();

  // Raceway grooves (subtractive)
  raceway_grooves();

  // Face chamfers (subtractive)
  face_chamfers_subtractive();
}

