// Ball bearing: 3.0mm bore, 6.0mm OD, 2.5mm width
// One connected solid with visible balls/cage and verifiable bore/OD/width

$fn = 160;

// ---- Target dimensions ----
bore_d  = 3.0;
outer_d = 6.0;
width   = 2.5;

// ---- Feature tuning (kept within target envelope) ----
ring_radial_thk = 0.70;   // ring wall thickness (radial)
ball_d          = 0.80;
ball_count      = 8;

cage_thk        = 0.55;   // axial thickness of cage (visible in side view)
cage_web        = 0.22;   // radial web thickness around ball pockets

shield_thk      = 0.18;   // thin shields to show bore in top/bottom views
shield_gap      = 0.10;   // radial clearance to inner ring OD

groove_r_factor = 0.55;   // race groove radius relative to ball radius
chamfer_r       = 0.10;

overlap         = 0.06;   // small overlap to guarantee connectivity

// ---- Derived ----
bore_r  = bore_d/2;
outer_r = outer_d/2;

inner_ring_or = bore_r + ring_radial_thk;
outer_ring_ir = outer_r - ring_radial_thk;

ball_r = ball_d/2;

// Ball path radius (center of balls) - centered between ring raceways
ball_path_r = (inner_ring_or + outer_ring_ir)/2;

// ---- Helpers ----
module cyl(r, h) { cylinder(r=r, h=h, center=true); }

module torus(R, r) {
  rotate_extrude(convexity=10)
    translate([R, 0, 0])
      circle(r=r, $fn=max(36, $fn/3));
}

// ---- Rings with race grooves and chamfers ----
module outer_ring() {
  difference() {
    cyl(outer_r, width);
    cyl(outer_ring_ir, width + 2*overlap);
  }
}

module inner_ring() {
  difference() {
    cyl(inner_ring_or, width);
    cyl(bore_r, width + 2*overlap);
  }
}

module outer_ring_detailed() {
  groove_r = ball_r * groove_r_factor;
  difference() {
    outer_ring();
    // race groove (continuous)
    torus(ball_path_r, groove_r);
    // outer edge chamfers (top/bottom)
    translate([0,0, width/2]) torus(outer_r - chamfer_r, chamfer_r);
    translate([0,0,-width/2]) torus(outer_r - chamfer_r, chamfer_r);
  }
}

module inner_ring_detailed() {
  groove_r = ball_r * groove_r_factor;
  difference() {
    inner_ring();
    // race groove (continuous)
    torus(ball_path_r, groove_r);
    // bore edge chamfers (top/bottom)
    translate([0,0, width/2]) torus(bore_r + chamfer_r, chamfer_r);
    translate([0,0,-width/2]) torus(bore_r + chamfer_r, chamfer_r);
  }
}

// ---- Balls ----
module balls() {
  for (i = [0:ball_count-1]) {
    rotate([0,0, i*360/ball_count])
      translate([ball_path_r, 0, 0])
        sphere(r=ball_r, $fn=max(48, $fn/2));
  }
}

// ---- Cage (ring with ball pockets) ----
module cage() {
  // Cage ring bounds around ball centers; keep it visible and connected
  cage_or = ball_path_r + ball_r + cage_web;
  cage_ir = ball_path_r - ball_r - cage_web;

  // Ensure cage stays within bearing envelope
  cage_or = min(cage_or, outer_ring_ir - overlap);
  cage_ir = max(cage_ir, inner_ring_or + overlap);

  difference() {
    // Overlap slightly into rings/balls so the whole model is one connected solid
    cyl(cage_or, cage_thk + 2*overlap);
    cyl(cage_ir, cage_thk + 2*overlap + 2*overlap);

    // Ball pockets (through the cage thickness)
    for (i = [0:ball_count-1]) {
      rotate([0,0, i*360/ball_count])
        translate([ball_path_r, 0, 0])
          cylinder(r=ball_r*1.10, h=cage_thk + 6*overlap, center=true, $fn=max(48, $fn/2));
    }
  }
}

// ---- Shields (thin discs with center opening so bore is visible in top/bottom views) ----
module shield(zpos) {
  shield_r = outer_r - chamfer_r*0.6;          // within OD
  hole_r   = inner_ring_or + shield_gap;       // clears inner ring OD

  translate([0,0,zpos])
    difference() {
      // Slight overlap into outer ring so it fuses
      cyl(shield_r, shield_thk + overlap);
      cyl(hole_r,   shield_thk + 2*overlap);
    }
}

module shields() {
  // Place shields just inside the bearing faces (computed from width)
  z = width/2 - shield_thk/2 - overlap*0.25;
  shield( z);
  shield(-z);
}

// ---- Final: one connected solid ----
union() {
  outer_ring_detailed();
  inner_ring_detailed();

  // Balls + cage (unioned; cage overlaps slightly so everything is connected)
  balls();
  cage();

  // Shields (unioned; overlap into outer ring)
  shields();
}

// Ball bearing: 3.0mm bore, 8.0mm outer diameter, 3.0mm width
// Single connected solid (rings + balls fused by tiny bridges)

$fn = 128;

// Required dimensions
bore_d  = 3.0;
outer_d = 8.0;
width   = 3.0;

// Visual/feature parameters (kept within available radial space)
ring_radial_thk = 1.0;     // ring thickness (radial)
ball_d          = 1.0;     // ball diameter
ball_count      = 7;

// Small values
eps     = 0.02;            // boolean robustness
bridge  = 0.12;            // tiny connectors to ensure ONE connected solid

// Derived radii
bore_r  = bore_d/2;
outer_r = outer_d/2;

// Ring radii
inner_ring_or = bore_r + ring_radial_thk;     // inner ring outer radius
outer_ring_ir = outer_r - ring_radial_thk;    // outer ring inner radius

// Ball path radius (midway between race faces)
ball_path_r = (inner_ring_or + outer_ring_ir)/2;

// Raceway groove (subtractive) size
groove_r = min(0.55, (outer_ring_ir - inner_ring_or)/2 - 0.05);
groove_r = max(groove_r, 0.25);

// Helper: torus-like groove made by rotate_extrude of a circle
module groove_torus(r_path, r_groove) {
    rotate_extrude(angle=360)
        translate([r_path, 0, 0])
            circle(r=r_groove);
}

// Rings with raceway grooves
module rings() {
    difference() {
        // Base rings (connected only via bridges later)
        union() {
            // Outer ring
            difference() {
                cylinder(r=outer_r, h=width, center=true);
                cylinder(r=outer_ring_ir, h=width + 2*eps, center=true);
            }
            // Inner ring
            difference() {
                cylinder(r=inner_ring_or, h=width, center=true);
                cylinder(r=bore_r, h=width + 2*eps, center=true);
            }
        }

        // Cut grooves into both rings (slightly inset from faces)
        // Outer ring groove
        groove_torus(ball_path_r, groove_r);

        // Inner ring groove (same torus removes from inner ring too)
        // (Using same groove gives a typical deep-groove look)
    }
}

// Balls
module balls() {
    for (i = [0:ball_count-1]) {
        angle = i * 360/ball_count;
        rotate([0,0,angle])
            translate([ball_path_r, 0, 0])
                sphere(r=ball_d/2);
    }
}

// Tiny bridges to guarantee a single connected solid (do not change OD/ID/width)
module connectivity_bridges() {
    // Bridge from each ball to inner ring and outer ring (radial direction)
    // Positioned at mid-plane so width remains exactly 'width'
    for (i = [0:ball_count-1]) {
        angle = i * 360/ball_count;

        // Inner bridge: from ball toward inner ring outer surface
        rotate([0,0,angle])
            translate([(ball_path_r + inner_ring_or)/2, 0, 0])
                cube([ball_path_r - inner_ring_or + bridge, bridge, bridge], center=true);

        // Outer bridge: from ball toward outer ring inner surface
        rotate([0,0,angle])
            translate([(ball_path_r + outer_ring_ir)/2, 0, 0])
                cube([outer_ring_ir - ball_path_r + bridge, bridge, bridge], center=true);
    }
}

// Final bearing (ONE connected solid)
union() {
    rings();
    balls();
    connectivity_bridges();
}

// Ball bearing: 5.0mm bore, 8.0mm OD, 2.5mm width
// Single connected solid with visible balls and race grooves

$fn = 160;

// Required dimensions
bore_d  = 5.0;
outer_d = 8.0;
width   = 2.5;

// Visual parameters (kept within OD/ID/width)
ball_count = 7;

// Groove/ball sizing (chosen to clearly show bearing features)
groove_r      = 0.33;   // groove radius (also ball radius)
groove_clear  = 0.06;   // extra clearance so grooves are visible
bridge_thk    = 0.22;   // thin web to ensure ONE connected solid
overlap       = 0.03;   // overlap to avoid coincident faces

// Derived radii
bore_r  = bore_d/2;
outer_r = outer_d/2;

// Choose a ball path radius that leaves enough material to bore/OD
// Ensure: ball_path_r - groove_r > bore_r  and  ball_path_r + groove_r < outer_r
ball_path_r = (bore_r + outer_r)/2;

// Clamp helper
function clamp(x, a, b) = x < a ? a : (x > b ? b : x);

// Ensure groove/ball fits radially
max_groove_r = min(ball_path_r - bore_r, outer_r - ball_path_r) - 0.10;
ball_r = clamp(groove_r, 0.18, max_groove_r);
ball_d = 2*ball_r;

// --- Modules ---
module ring(r_out, r_in, h) {
    difference() {
        cylinder(r=r_out, h=h, center=true);
        cylinder(r=r_in,  h=h + 2*overlap, center=true);
    }
}

module balls() {
    for (i = [0:ball_count-1]) {
        rotate([0,0,i*360/ball_count])
            translate([ball_path_r, 0, 0])
                sphere(r=ball_r);
    }
}

// Cut race grooves into a solid ring so it reads as a bearing
module race_grooves() {
    // Use slightly larger cutter than the balls for a visible groove
    cutter_r = ball_r + groove_clear;

    // Cut a toroidal groove around the ring at mid-width
    rotate_extrude()
        translate([ball_path_r, 0, 0])
            circle(r=cutter_r);

    // Add shallow side reliefs so the groove is visible in side/top views
    // (kept within width by using small axial offsets)
    for (zsgn = [-1, 1]) {
        translate([0,0,zsgn*(width/2 - cutter_r*0.55)])
            rotate_extrude()
                translate([ball_path_r, 0, 0])
                    circle(r=cutter_r*0.85);
    }
}

// Thin web that connects inner region to outer region so the whole model is ONE solid
module connector_web() {
    // A narrow radial rib at one angular position, spanning from near bore to near OD
    // It overlaps into the main ring to guarantee connectivity.
    rib_len = (outer_r - bore_r) - 2*bridge_thk;
    rib_w   = bridge_thk;
    rib_h   = width;

    // Place rib centered at radius mid, with overlap into both sides
    translate([(bore_r + outer_r)/2, 0, 0])
        cube([rib_len + 2*overlap, rib_w, rib_h], center=true);
}

module bearing_solid() {
    union() {
        // Start from a single solid ring that exactly matches OD/ID/width
        difference() {
            ring(outer_r, bore_r, width);
            // Carve race grooves so it looks like a bearing
            race_grooves();
        }

        // Add balls (visual) and ensure they intersect the ring slightly for a single manifold
        // (tiny scale-up ensures overlap into the groove area)
        scale([1,1,1])
            balls();

        // Ensure ONE connected solid even if balls don't touch due to clearances
        connector_web();
    }
}

