module edge_chamfers() {
  // Optional: disable for fastest render
  if (edge_chamfer > 0) {
    for (sx = [-1, 1], sy = [-1, 1]) {
      translate([sx*(block_W/2 - edge_chamfer), sy*(block_L/2 - edge_chamfer), 0])
        rotate([0, 0, 45])
          cube([edge_chamfer*2, edge_chamfer*2, block_H + 2*overlap], center=true);
    }
  }
}

module all_cuts() {
  shaft_bore();
  bearing_pocket();
  bearing_end_relief();
  mounting_cuts();
  grease_port();
  set_screw();
  edge_chamfers();
}

// =====================
// Final
// =====================
difference() {
  union() { body(); }
  all_cuts();
}

