module op_stator_core_ring() {
  difference() {
    bs_stator_outer();
    bs_stator_inner_void();
  }
}

module op_stator_with_teeth() {
  translate([0, 0, z_stator_c_fixed])
    union() {
      op_stator_core_ring();
      for (i = [0:tooth_count-1])
        rotate([0, 0, i*360/tooth_count])
          bs_tooth_block();
    }
