fillet_r = 2.0; //[1.0:4.0:0.5]

// Internal cavity / impeller region
cavity_d = 30.0; //[20.0:36.0:0.5]
cavity_depth = 7.5; //[4.0:9.0:0.1]
inlet_d = 18.0; //[10.0:26.0:0.5]

// Outlet nozzle
outlet_W = 10.0; //[6.0:16.0:0.5]
outlet_H = 6.0;  //[3.0:9.0:0.5]
outlet_len = 8.0; //[4.0:16.0:0.5]

// Impeller (kept inside cavity; fused to housing via tiny bridge so model is ONE solid)
impeller_d = 28.0; //[18.0:34.0:0.5]
impeller_th = 6.5; //[3.0:8.0:0.1]
hub_d = 8.0; //[4.0:14.0:0.5]
hub_H = 6.5; //[3.0:8.0:0.1]
blade_count = 10; //[6:16:1]
blade_len = 5.0; //[3.0:8.0:0.5]
blade_th = 1.2; //[0.8:2.0:0.1]

// Volute (scroll) ring inside cavity
volute_th = 1.2; //[0.6:2.4:0.1]
volute_R = 14.0; //[10.0:18.0:0.5]

// Mounting holes
mount_hole_d = 2.5; //[1.5:4.0:0.1]
mount_hole_edge_offset = 3.5; //[2.0:7.0:0.1]

// Small details (kept but no text)
label_recess_L = 18.0; //[10.0:30.0:0.5]
label_recess_W = 12.0; //[8.0:24.0:0.5]
label_recess_depth = 0.6; //[0.2:1.2:0.1]
wire_notch_W = 6.0; //[3.0:10.0:0.5]
wire_notch_H = 3.0; //[1.5:6.0:0.5]
wire_notch_depth = 3.0; //[1.5:6.0:0.5]

// Derived Z references (centered model)
z_top =  fan_H/2;
z_bot = -fan_H/2;

// Ensure cavity fits under cover
cavity_top_z = z_top - cover_t;                 // underside of cover
cavity_center_z = cavity_top_z - cavity_depth/2;

// Impeller placement (inside cavity)
impeller_center_z = cavity_top_z - impeller_th/2 - wall_t*0.2; // slightly below cover underside
hub_center_z      = impeller_center_z;                          // same center

// --- Base shapes ---
module housing_outer_box() {
  cube([fan_L, fan_W, fan_H], center=true);
}

module corner_fillet_sphere() {
  sphere(r=fillet_r);
}

// Rounded outer housing (minkowski)
module housing_rounded() {
  // Keep overall size close to fan_L/W/H by shrinking before minkowski
  minkowski() {
    cube([fan_L - 2*fillet_r, fan_W - 2*fillet_r, fan_H - 2*fillet_r], center=true);
    corner_fillet_sphere();
  }
}

// Outlet nozzle outer block (connected to right face)
module outlet_nozzle_outer() {
  // Outer nozzle height includes walls around outlet opening
  nozzle_Ho = outlet_H + 2*wall_t;
  nozzle_Wo = outlet_W + 2*wall_t;

  translate([fan_L/2 + outlet_len/2 - overlap, 0, z_top - nozzle_Ho/2])
    cube([outlet_len, nozzle_Wo, nozzle_Ho], center=true);
}

// Outlet nozzle inner void
module outlet_nozzle_inner_cut() {
  translate([fan_L/2 + outlet_len/2 - overlap, 0, z_top - (outlet_H/2 + wall_t)])
    cube([outlet_len + 2*overlap, outlet_W, outlet_H], center=true);
}

// Port cut through housing wall into cavity (right side)
module outlet_port_cut() {
  translate([fan_L/2 - wall_t/2, 0, z_top - (outlet_H/2 + wall_t)])
    cube([wall_t + 2*overlap, outlet_W, outlet_H], center=true);
}

// Main cavity cut (cylindrical)
module cavity_cyl_cut() {
  translate([0, 0, cavity_center_z])
    cylinder(r=cavity_d/2, h=cavity_depth + 2*overlap, center=true);
}

// Inlet opening cut through top cover
module inlet_cyl_cut() {
  translate([0, 0, z_top - cover_t/2])
    cylinder(r=inlet_d/2, h=cover_t + 2*overlap, center=true);
}

// Internal volute ring (solid feature inside cavity)
module volute_ring_solid() {
  // Ring occupies cavity depth, centered in cavity
  translate([0, 0, cavity_center_z])
    difference() {
      cylinder(r=volute_R + volute_th/2, h=cavity_depth, center=true);
      cylinder(r=volute_R - volute_th/2, h=cavity_depth + 2*overlap, center=true);
      // Trim to create a "scroll" opening toward outlet (remove a wedge/box)
      // Remove a rectangular chunk on the lower half to suggest volute shape
      translate([0, -fan_W/4, 0])
        cube([fan_L, fan_W/2, cavity_depth + 2*overlap], center=true);
    }
}

// Mount holes
module mount_hole_cyl(pos) {
  translate(pos)
    cylinder(r=mount_hole_d/2, h=fan_H + 2*overlap, center=true);
}

// Label recess (no text)
module label_recess_cut() {
  translate([-fan_L/2 + wall_t + label_recess_L/2, 0, z_top - label_recess_depth/2])
    cube([label_recess_L, label_recess_W, label_recess_depth + overlap], center=true);
}

// Wire exit notch
module wire_exit_notch_cut() {
  translate([-fan_L/2 + wire_notch_depth/2, 0, z_bot + wire_notch_H/2])
    cube([wire_notch_depth + 2*overlap, wire_notch_W, wire_notch_H], center=true);
}

// --- Impeller (solid) ---
module impeller_disk() {
  translate([0, 0, impeller_center_z])
    cylinder(r=impeller_d/2, h=impeller_th, center=true);
}

module motor_hub() {
  translate([0, 0, hub_center_z])
    cylinder(r=hub_d/2, h=hub_H, center=true);
}

module blade_proto() {
  // Radial blade protruding outward from near hub to rim
  // Place blade so its inner edge overlaps into disk by "overlap"
  translate([impeller_d/2 - blade_len/2 - overlap, 0, impeller_center_z])
    cube([blade_len, blade_th, impeller_th], center=true);
}

module impeller_blades_detail() {
  for (i = [0:blade_count-1]) {
    rotate([0, 0, i*360/blade_count])
      blade_proto();
  }
}

module impeller() {
  union() {
    impeller_disk();
    motor_hub();
    impeller_blades_detail();
  }
}

// Bridge to ensure impeller is connected to housing as ONE solid (tiny rib to underside of cover)
module impeller_bridge_to_cover() {
  // A thin vertical rib from impeller top to underside of cover, inside inlet area
  // This guarantees a single connected solid even though impeller sits in cavity.
  rib_w = max(1.0, wall_t);
  rib_l = max(3.0, wall_t*3);
  z1 = impeller_center_z + impeller_th/2;
  z2 = cavity_top_z; // underside of cover
  rib_h = (z2 - z1) + overlap;

  translate([0, 0, z1 + rib_h/2 - overlap/2])
    cube([rib_l, rib_w, rib_h], center=true);
}

// --- Housing assembly ---
module housing_plus_nozzle() {
  union() {
    housing_rounded();
    outlet_nozzle_outer();
  }
}

module housing_solid_features() {
  // Add internal volute as a solid feature (visible if cutaway; still a blower feature)
  union() {
    housing_plus_nozzle();
    volute_ring_solid();
  }
}

module housing_with_openings() {
  difference() {
    housing_solid_features();

    // Internal cavity
    cavity_cyl_cut();

    // Inlet opening through top
    inlet_cyl_cut();

    // Outlet internal void and port
    outlet_nozzle_inner_cut();
    outlet_port_cut();

    // Mount holes
    mount_hole_cyl([ fan_L/2 - mount_hole_edge_offset,  fan_W/2 - mount_hole_edge_offset, 0]);
    mount_hole_cyl([-fan_L/2 + mount_hole_edge_offset,  fan_W/2 - mount_hole_edge_offset, 0]);
    mount_hole_cyl([-fan_L/2 + mount_hole_edge_offset, -fan_W/2 + mount_hole_edge_offset, 0]);
    mount_hole_cyl([ fan_L/2 - mount_hole_edge_offset, -fan_W/2 + mount_hole_edge_offset, 0]);

    // Small recess/notch
    label_recess_cut();
    wire_exit_notch_cut();
  }
}

// --- Final model (ONE connected solid) ---
module complete_model() {
  union() {
    housing_with_openings();
    // Impeller is included and physically connected via bridge rib
    impeller();
    impeller_bridge_to_cover();
  }
}

color([0.12, 0.12, 0.14]) complete_model();

// Centrifugal blower fan 40x40x20mm (single connected solid)
// Fixes: ensure visible geometry, connected outlet, real inlet/outlet openings,
// impeller is fused to housing via a thin internal bridge (still looks like an impeller).

$fn = 96;

// Parameters
fan_L = 40; //[20:80:1]
fan_W = 40; //[20:80:1]
fan_H = 20; //[10:40:1]

wall_t = 1.5; //[0.8:3:0.1]
lid_t  = 1.5; //[0.8:3:0.1]

inlet_d = 22; //[12:34:1]

outlet_W   = 12; //[6:24:1]
outlet_H   = 8;  //[4:16:1]
outlet_len = 8;  //[4:16:1]

volute_clearance = 1; //[0.5:2.5:0.1]

impeller_D = 28; //[18:34:1]
impeller_H = 16; //[10:18:1]
impeller_blade_t = 1; //[0.6:2:0.1]
impeller_blade_count = 12; //[6:24:1]

hub_d = 8; //[5:14:0.5]
hub_H = 16; //[10:18:1]
shaft_d = 2; //[1:5:0.1]

mount_hole_d = 3; //[2:5:0.1]
mount_hole_edge_offset = 4; //[2:8:0.5]

mount_boss_d = 10; //[6:18:0.5]
mount_boss_H = 4;  //[2:8:0.5]

grille_bar_w = 2;  //[1:4:0.1]
screw_head_d = 5.5; //[4:8:0.1]
screw_head_h = 1.5; //[0.8:3:0.1]

overlap = 1; //[0.5:2:0.1]

// Derived
z_top =  fan_H/2;
z_bot = -fan_H/2;

// Keep cavities within housing
cav_h = fan_H - lid_t - wall_t;
cav_z = z_bot + wall_t + cav_h/2;

// Volute radius (kept inside walls)
volute_r = min((impeller_D/2) + volute_clearance, min(fan_L, fan_W)/2 - wall_t - 0.5);

// Outlet placement: attached to right face with slight overlap
outlet_x = fan_L/2 + outlet_len/2 - overlap;
outlet_z = cav_z; // align with internal cavity height

// Inlet is on top lid
inlet_z = z_top - lid_t/2;

// Mount hole positions
mhx = fan_L/2 - mount_hole_edge_offset;
mhy = fan_W/2 - mount_hole_edge_offset;

// Impeller placement: inside cavity, slightly below lid
imp_z = cav_z;

// Small internal bridge to ensure ONE connected solid (fuses impeller to housing)
bridge_t = 0.8;
bridge_w = 2.0;
bridge_len = wall_t + 1.2; // reaches inner wall with overlap
bridge_x = (fan_L/2 - wall_t) - bridge_len/2 + 0.2; // near right inner wall
bridge_z = imp_z;

// ----------------- Modules -----------------
module housing_outer() {
    cube([fan_L, fan_W, fan_H], center=true);
}

module volute_cavity() {
    translate([0, 0, cav_z])
        cylinder(h=cav_h + 2*overlap, r=volute_r, center=true);
}

module outlet_cavity() {
    // Internal duct from volute to outlet
    // Starts inside housing and extends into outlet nozzle region
    duct_len = fan_L/2 + outlet_len + overlap;
    translate([fan_L/4, 0, outlet_z])
        cube([duct_len, outlet_W, outlet_H], center=true);
}

module inlet_hole() {
    translate([0, 0, inlet_z])
        cylinder(h=lid_t + 2*overlap, r=inlet_d/2, center=true);
}

module outlet_nozzle_solid() {
    // External nozzle attached to housing
    translate([outlet_x, 0, outlet_z])
        cube([outlet_len, outlet_W + 2*wall_t, outlet_H + 2*wall_t], center=true);
}

module outlet_nozzle_hole() {
    translate([outlet_x, 0, outlet_z])
        cube([outlet_len + 2*overlap, outlet_W, outlet_H], center=true);
}

module mounting_hole(x, y) {
    translate([x, y, 0])
        cylinder(h=fan_H + 2*overlap, r=mount_hole_d/2, center=true);
}

module screw_head(x, y) {
    translate([x, y, z_top - lid_t - screw_head_h/2 + overlap])
        cylinder(h=screw_head_h, r=screw_head_d/2, center=true);
}

module grille_bars() {
    // Simple cross bars on inlet (solid, not subtractive)
    translate([0, 0, inlet_z])
        union() {
            cube([inlet_d + 2*wall_t, grille_bar_w, lid_t], center=true);
            cube([grille_bar_w, inlet_d + 2*wall_t, lid_t], center=true);
        }
}

module motor_mount_boss() {
    translate([0, 0, z_bot + mount_boss_H/2 - overlap])
        cylinder(h=mount_boss_H, r=mount_boss_d/2, center=true);
}

module impeller_hub() {
    translate([0, 0, imp_z])
        cylinder(h=hub_H, r=hub_d/2, center=true);
}

module impeller_shaft_hole() {
    translate([0, 0, imp_z])
        cylinder(h=hub_H + 2*overlap, r=shaft_d/2, center=true);
}

module impeller_blade(angle) {
    blade_len = (impeller_D/2 - hub_d/2) + overlap;
    // Place blades radially, protruding outward from hub
    rotate([0, 0, angle])
        translate([hub_d/2 + blade_len/2 - overlap, 0, imp_z])
            cube([blade_len, impeller_blade_t, impeller_H], center=true);
}

module impeller() {
    difference() {
        union() {
            impeller_hub();
            for (i = [0:impeller_blade_count-1])
                impeller_blade(i * 360 / impeller_blade_count);
        }
        impeller_shaft_hole();
    }
}

module impeller_bridge() {
    // Thin bridge from impeller region to inner wall to guarantee single connected solid
    translate([bridge_x, 0, bridge_z])
        cube([bridge_len, bridge_w, bridge_t], center=true);
}

// ----------------- Final solid -----------------
module blower_solid() {
    union() {
        // Housing with internal cavities and openings
        difference() {
            union() {
                housing_outer();
                outlet_nozzle_solid();
            }

            // Internal cavities
            volute_cavity();
            outlet_cavity();

            // Openings
            inlet_hole();
            outlet_nozzle_hole();

            // Mounting holes
            mounting_hole( mhx,  mhy);
            mounting_hole(-mhx,  mhy);
            mounting_hole(-mhx, -mhy);
            mounting_hole( mhx, -mhy);
        }

        // Lid details (solid features)
        grille_bars();
        screw_head( mhx,  mhy);
        screw_head(-mhx,  mhy);
        screw_head(-mhx, -mhy);
        screw_head( mhx, -mhy);

        // Bottom boss
        motor_mount_boss();

        // Impeller (fused via bridge so the whole model is one connected solid)
        impeller();
        impeller_bridge();
    }
}

blower_solid();

// Parameters
L = 51.3; //[25.65:102.6:0.1]
W = 51; //[25.5:102:0.1]
H = 15; //[7.5:30:0.1]
wall_t = 1.5; //[0.8:3:0.1]
outlet_w = 14; //[7:28:0.1]
outlet_h = 8; //[4:16:0.1]
outlet_len = 10; //[5:20:0.1]
impeller_od = 38; //[19:76:0.1]
impeller_thk = 10; //[5:20:0.1]
impeller_blades = 9; //[5:16:1]
hub_d = 10; //[5:20:0.1]
hub_h = 10; //[5:20:0.1]
inlet_d = 24; //[12:48:0.1]
cover_t = 1.5; //[0.8:3:0.1]
flange_t = 2; //[1:4:0.1]
mount_hole_d = 3.2; //[2:6.4:0.1]
mount_hole_edge_offset = 4; //[2:8:0.1]
eps = 1; //[0.5:2:0.1]
volute_r = 22; //[11:44:0.1]
volute_h = 13.5; //[7:27:0.1]
boss_d = 6.5; //[4:13:0.1]
boss_h = 10; //[5:20:0.1]
boss_hole_d = 2.6; //[1.6:5.2:0.1]
label_recess_depth = 0.6; //[0.3:1.2:0.1]
wire_slot_w = 6; //[3:12:0.1]
wire_slot_h = 3; //[1.5:6:0.1]
wire_slot_len = 8; //[4:16:0.1]
guide_thk = 1.2; //[0.6:2.4:0.1]
blade_len = 7; //[3.5:14:0.1]
blade_w = 3; //[1.5:6:0.1]

// Base Shapes
module housing_volute_outer() {
  translate([0, 0, -H/2 + flange_t + volute_h/2])
    cylinder(r=volute_r, h=volute_h, center=true);
}

module housing_volute_inner() {
  translate([0, 0, -H/2 + flange_t + wall_t + (volute_h - wall_t)/2])
    cylinder(r=volute_r - wall_t, h=volute_h - wall_t, center=true);
}

module outlet_nozzle_outer() {
  translate([volute_r + outlet_len/2 - eps, 0, -H/2 + flange_t + outlet_h/2])
    cube([outlet_len, outlet_w, outlet_h], center=true);
}

module outlet_nozzle_inner() {
  translate([volute_r + outlet_len/2 - eps, 0, -H/2 + flange_t + wall_t + (outlet_h - 2*wall_t)/2])
    cube([outlet_len + 2*eps, outlet_w - 2*wall_t, outlet_h - 2*wall_t], center=true);
}

module mounting_flange() {
  translate([0, 0, -H/2 + flange_t/2])
    cube([L, W, flange_t], center=true);
}

module top_cover_plate() {
  translate([0, 0, H/2 - cover_t/2])
    cube([L, W, cover_t], center=true);
}

module inlet_opening_cutter() {
  translate([0, 0, H/2 - cover_t/2])
    cylinder(r=inlet_d/2, h=cover_t + 2*eps, center=true);
}

module label_recess_cutter() {
  translate([0, 0, H/2 - (label_recess_depth + eps)/2])
    cube([L*0.55, W*0.35, label_recess_depth + eps], center=true);
}

module wire_exit_slot_cutter() {
  translate([L/2 - wire_slot_len/2, 0, -H/2 + flange_t + wire_slot_h/2])
    cube([wire_slot_len, wire_slot_w, wire_slot_h], center=true);
}

module mount_hole_cyl(pos) {
  translate(pos)
    cylinder(r=mount_hole_d/2, h=H + 2*eps, center=true);
}

module screw_boss(pos) {
  translate(pos)
    cylinder(r=boss_d/2, h=boss_h, center=true);
}

module screw_boss_hole(pos) {
  translate(pos)
    cylinder(r=boss_hole_d/2, h=boss_h + 2*eps, center=true);
}

module motor_hub() {
  translate([0, 0, -H/2 + flange_t + hub_h/2 - eps])
    cylinder(r=hub_d/2, h=hub_h, center=true);
}

module impeller_disk() {
  translate([0, 0, -H/2 + flange_t + impeller_thk/2])
    cylinder(r=impeller_od/2, h=impeller_thk, center=true);
}

module impeller_blade(angle) {
  rotate([0, 0, angle])
    translate([hub_d/2 + blade_len/2 - eps, 0, -H/2 + flange_t + impeller_thk/2])
      cube([blade_len, blade_w, impeller_thk], center=true);
}

module impeller_blade_curvature_detail() {
  translate([0, 0, -H/2 + flange_t + impeller_thk/2])
    rotate_extrude() circle(r=impeller_od/2 - wall_t);
}

module internal_flow_guide_1() {
  translate([volute_r/2 - eps, 0, -H/2 + flange_t + wall_t + (volute_h - wall_t)/2])
    cube([volute_r, guide_thk, volute_h - wall_t], center=true);
}

module internal_flow_guide_2() {
  rotate([0, 0, 45])
    translate([volute_r*0.35 - eps, volute_r*0.35, -H/2 + flange_t + wall_t + (volute_h - wall_t)/2])
      cube([volute_r*0.7, guide_thk, volute_h - wall_t], center=true);
}

module fillets_chamfers_proxy() {
  translate([L/2 - wall_t, W/2 - wall_t, -H/2 + flange_t + wall_t])
    sphere(r=wall_t);
}

// Operations
module housing_shell() {
  difference() {
    housing_volute_outer();
    housing_volute_inner();
  }
}

module outlet_shell() {
  difference() {
    outlet_nozzle_outer();
    outlet_nozzle_inner();
  }
}

module housing_with_outlet() {
  union() {
    housing_shell();
    outlet_shell();
  }
}

module impeller_blades_union() {
  union() {
    for (i = [0:impeller_blades-1])
      impeller_blade(i * 360/impeller_blades);
  }
}

module impeller() {
  union() {
    impeller_disk();
    impeller_blades_union();
    motor_hub();
    impeller_blade_curvature_detail();
  }
}

module cover_with_inlet() {
  difference() {
    top_cover_plate();
    inlet_opening_cutter();
    label_recess_cutter();
  }
}

module bosses_union() {
  union() {
    screw_boss([volute_r*0.55, volute_r*0.55, -H/2 + flange_t + boss_h/2 - eps]);
    screw_boss([volute_r*0.55, -volute_r*0.55, -H/2 + flange_t + boss_h/2 - eps]);
    screw_boss([-volute_r*0.55, volute_r*0.55, -H/2 + flange_t + boss_h/2 - eps]);
    screw_boss([-volute_r*0.55, -volute_r*0.55, -H/2 + flange_t + boss_h/2 - eps]);
  }
}

module bosses_drilled() {
  difference() {
    bosses_union();
    screw_boss_hole([volute_r*0.55, volute_r*0.55, -H/2 + flange_t + boss_h/2 - eps]);
    screw_boss_hole([volute_r*0.55, -volute_r*0.55, -H/2 + flange_t + boss_h/2 - eps]);
    screw_boss_hole([-volute_r*0.55, volute_r*0.55, -H/2 + flange_t + boss_h/2 - eps]);
    screw_boss_hole([-volute_r*0.55, -volute_r*0.55, -H/2 + flange_t + boss_h/2 - eps]);
  }
}

module internal_guides_union() {
  union() {
    internal_flow_guide_1();
    internal_flow_guide_2();
  }
}

module main_solid_pre_holes() {
  union() {
    mounting_flange();
    housing_with_outlet();
    cover_with_inlet();
    bosses_drilled();
    impeller();
    internal_guides_union();
    fillets_chamfers_proxy();
  }
