    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx*(module_length/2 - mount_hole_edge_margin_x),
                   sy*(module_width/2  - mount_hole_edge_margin_y),
                   0])
            cylinder(h=module_thickness + 2, r=mount_hole_diameter/2, center=true);
    }
