slot_inner_w     = 10.0;   // wider internal cavity width
slot_depth       = 6.0;    // depth from outer face toward center

edge_chamfer     = 0.8;    // corner chamfer size
overlap          = 0.2;    // small overlap for robust booleans

// --- Helpers ---
module extrusion_main_body() {
    cube([profile_size, profile_size, length], center=true);
}

module central_bore() {
    cylinder(h=length + 2*overlap, r=bore_d/2, center=true);
}

// One face T-slot cut (along +X face), then rotated for 4 sides
module tslot_one_face() {
    // Place cuts so their outer face is slightly outside the profile to guarantee opening
    x_outer = profile_size/2 + overlap;
    x_inner = profile_size/2 - slot_depth;

    // Internal cavity (wider), starts at x_inner and reaches x_outer
    translate([(x_inner + x_outer)/2, 0, 0])
        cube([ (x_outer - x_inner), slot_inner_w, length + 2*overlap ], center=true);

    // Mouth (narrower) near the surface; make it slightly deeper to ensure it connects to cavity
    mouth_depth = slot_depth * 0.55;
    x_mouth_inner = profile_size/2 - mouth_depth;
    translate([(x_mouth_inner + x_outer)/2, 0, 0])
        cube([ (x_outer - x_mouth_inner), slot_opening_w, length + 2*overlap ], center=true);
}

module t_slots_4x() {
    for (a = [0:90:270])
        rotate([0,0,a]) tslot_one_face();
}

// Corner chamfers: subtract small cubes at the four outer corners
module edge_chamfers() {
    // Chamfer cube centered at each corner, pushed slightly outward so it actually removes material
    dx = profile_size/2 - edge_chamfer/2;
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx*dx, sy*dx, 0])
            cube([edge_chamfer + 2*overlap, edge_chamfer + 2*overlap, length + 2*overlap], center=true);
}

// Final extrusion (single connected solid)
difference() {
    extrusion_main_body();
    central_bore();
    t_slots_4x();
    edge_chamfers();
}

// 20x20 aluminum extrusion profile, 100mm long (simplified 2020 T-slot)
// FIX: Ensure a single continuous 20x20x100 solid with connected cross-section.
// The previous boolean set could remove the entire mid-body, leaving only corner bits.
// This version keeps a guaranteed continuous outer body and uses conservative cuts.

$fn = 96;

// Parameters (mm)
profile_W = 20.0;
profile_H = 20.0;
length_L  = 100.0;

// Simplified 2020-ish features
center_bore_d   = 5.0;   // through bore
slot_opening_w  = 6.0;   // mouth opening at the surface
slot_neck_w     = 4.0;   // narrow neck just inside
slot_depth      = 6.2;   // depth from outer face toward center
slot_undercut_w = 10.0;  // wider internal cavity for T-nut
slot_undercut_d = 2.4;   // thickness of undercut region (radial)
wall_t          = 2.0;   // outer wall thickness
overlap         = 1.0;   // boolean robustness

// Keep a guaranteed solid core so the profile cannot split into separate corner pieces
core_size = 8.0; // mm (conservative, keeps the silhouette correct and the body connected)

// ---------- Helpers ----------
module outer_body() {
    // One continuous 20x20x100 body
    cube([profile_W, profile_H, length_L], center=true);
}

// Conservative internal cavity: hollow ring + solid core (prevents separation)
module inner_void() {
    inner_w = profile_W - 2*wall_t;
    inner_h = profile_H - 2*wall_t;

    // Hollow region is the inner rectangle minus a solid core.
    // This avoids the "two slabs" approach that can accidentally remove the entire mid-body.
    difference() {
        cube([inner_w, inner_h, length_L + 2*overlap], center=true);
        cube([core_size, core_size, length_L + 4*overlap], center=true); // extra overlap for robust boolean
    }
}

module center_bore() {
    cylinder(h=length_L + 2*overlap, r=center_bore_d/2, center=true);
}

// One face T-slot cut, oriented along +X face (cuts into the body)
module tslot_cut_1face() {
    // Ensure the slot opens to the outer face at x = +profile_W/2
    x_center    = (profile_W/2 + overlap) - slot_depth/2;
    x_uc_center = (profile_W/2 + overlap) - (slot_depth - slot_undercut_d/2);

    union() {
        // Mouth opening (at surface)
        translate([x_center, 0, 0])
            cube([slot_depth + 2*overlap, slot_opening_w, length_L + 2*overlap], center=true);

        // Neck (narrower)
        translate([x_center, 0, 0])
            cube([slot_depth + 2*overlap, slot_neck_w, length_L + 2*overlap], center=true);

        // Undercut (wider region deeper inside)
        translate([x_uc_center, 0, 0])
            cube([slot_undercut_d + 2*overlap, slot_undercut_w, length_L + 2*overlap], center=true);
    }
}

module tslots_4faces() {
    union() {
        tslot_cut_1face();                    // +X
        rotate([0,0,180]) tslot_cut_1face();  // -X
        rotate([0,0,90])  tslot_cut_1face();  // +Y
        rotate([0,0,270]) tslot_cut_1face();  // -Y
    }
}

// ---------- Final solid ----------
difference() {
    outer_body();

    // Internal cavity (keeps a solid core so the part remains one connected extrusion)
    inner_void();

    // Center bore
    center_bore();

    // 4 T-slots
    tslots_4faces();
}

// 20x40 T-slot aluminium extrusion (simplified), 100mm long
// FIX: Ensure a single connected 20x40 body with recognizable extrusion silhouette.
// The previous "internal_void_keep_webs()" removed a full-height and full-width cross,
// splitting the solid into two separate long bars. This version keeps a central web
// by subtracting four quadrant pockets instead of two full-span voids.

$fn = 96;

// Parameters (mm)
profile_W = 20.0;
profile_H = 40.0;
length_L  = 100.0;

// Geometry (simplified but robust)
wall_t         = 2.0;   // outer wall thickness
slot_depth_d   = 6.0;   // depth from outer face to inner cavity
slot_opening_w = 6.0;   // mouth opening width
slot_cavity_w  = 12.0;  // internal cavity width
slot_cavity_h  = 6.0;   // cavity height (inward thickness)
center_bore_d  = 5.0;   // center bore diameter

eps = 0.25;             // overlap for booleans

module outer_solid() {
    cube([profile_W, profile_H, length_L], center=true);
}

module center_bore() {
    cylinder(h=length_L + 2*eps, r=center_bore_d/2, center=true);
}

// T-slot cut on a given face, oriented along Z (extrusion length)
module tslot_on_face(face="top") {
    if (face == "top") {
        translate([0, profile_H/2 - slot_depth_d/2 + eps, 0])
            cube([slot_opening_w, slot_depth_d + 2*eps, length_L + 2*eps], center=true);

        translate([0, profile_H/2 - slot_depth_d - slot_cavity_h/2 + eps, 0])
            cube([slot_cavity_w, slot_cavity_h + 2*eps, length_L + 2*eps], center=true);
    }
    else if (face == "bottom") {
        translate([0, -profile_H/2 + slot_depth_d/2 - eps, 0])
            cube([slot_opening_w, slot_depth_d + 2*eps, length_L + 2*eps], center=true);

        translate([0, -profile_H/2 + slot_depth_d + slot_cavity_h/2 - eps, 0])
            cube([slot_cavity_w, slot_cavity_h + 2*eps, length_L + 2*eps], center=true);
    }
    else if (face == "left") {
        translate([-profile_W/2 + slot_depth_d/2 - eps, 0, 0])
            cube([slot_depth_d + 2*eps, slot_opening_w, length_L + 2*eps], center=true);

        translate([-profile_W/2 + slot_depth_d + slot_cavity_h/2 - eps, 0, 0])
            cube([slot_cavity_h + 2*eps, slot_cavity_w, length_L + 2*eps], center=true);
    }
    else if (face == "right") {
        translate([profile_W/2 - slot_depth_d/2 + eps, 0, 0])
            cube([slot_depth_d + 2*eps, slot_opening_w, length_L + 2*eps], center=true);

        translate([profile_W/2 - slot_depth_d - slot_cavity_h/2 + eps, 0, 0])
            cube([slot_cavity_h + 2*eps, slot_cavity_w, length_L + 2*eps], center=true);
    }
}

// Internal void: remove four quadrant pockets, leaving a central "+" web so the profile stays one piece
module internal_void_keep_webs() {
    web_t = 2.5; // guaranteed connecting web thickness (both X and Y)

    inner_W = profile_W - 2*wall_t;
    inner_H = profile_H - 2*wall_t;

    // Quadrant pocket sizes (each pocket stays within the inner boundary)
    pocket_W = max(0.1, (inner_W - web_t)/2);
    pocket_H = max(0.1, (inner_H - web_t)/2);

    // Pocket centers: offset from origin so pockets do NOT cross the central web
    cx = web_t/2 + pocket_W/2;
    cy = web_t/2 + pocket_H/2;

    union() {
        // Four pockets (NE, NW, SE, SW)
        translate([+cx, +cy, 0]) cube([pocket_W, pocket_H, length_L + 2*eps], center=true);
        translate([-cx, +cy, 0]) cube([pocket_W, pocket_H, length_L + 2*eps], center=true);
        translate([+cx, -cy, 0]) cube([pocket_W, pocket_H, length_L + 2*eps], center=true);
        translate([-cx, -cy, 0]) cube([pocket_W, pocket_H, length_L + 2*eps], center=true);
    }
}

module all_cuts() {
    union() {
        center_bore();
        internal_void_keep_webs();

        // T-slots on all 4 faces
        tslot_on_face("top");
        tslot_on_face("bottom");
        tslot_on_face("left");
        tslot_on_face("right");
    }
}

// Final model: single continuous 20x40 extrusion, 100mm long
difference() {
    outer_solid();
    all_cuts();
}

// 20x60 aluminium extrusion profile, 100mm long (simplified, correct 20:60 cross-section)

// Parameters
profile_W = 20;   // X (mm)
profile_H = 60;   // Y (mm)
length_L  = 100;  // Z (mm)

// Small overlap to avoid coplanar artifacts
eps = 0.02;

// Profile detail parameters (simplified but proportionally plausible)
wall_t      = 2.0;   // outer wall thickness
slot_open   = 6.0;   // T-slot mouth opening at surface
slot_depth  = 6.0;   // depth from surface to inner cavity
slot_cavity = 12.0;  // inner cavity width behind the mouth
core_r      = 6.0;   // central bore radius

function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// Clamp slot sizes to fit each face independently (20mm faces vs 60mm faces)
slot_open_W   = clamp(slot_open, 2, profile_W - 2*wall_t - 1);
slot_open_H   = clamp(slot_open, 2, profile_H - 2*wall_t - 1);

slot_depth_W  = clamp(slot_depth, 2, profile_W/2 - wall_t - 1);
slot_depth_H  = clamp(slot_depth, 2, profile_H/2 - wall_t - 1);

slot_cavity_W = clamp(slot_cavity, slot_open_W + 2, profile_W - 2*wall_t - 2);
slot_cavity_H = clamp(slot_cavity, slot_open_H + 2, profile_H - 2*wall_t - 2);

module tslot_on_face(face="top", L=length_L) {
    // Cuts a simplified T-slot on one face of the 20x60 rectangle.
    // All translate() values are derived from profile dimensions.
    if (face == "top") {
        // Opens to +Y face (width along X)
        translate([0, profile_H/2 - slot_depth_H/2 + eps, 0])
            cube([slot_open_H, slot_depth_H + 2*eps, L + 2*eps], center=true);

        translate([0, profile_H/2 - slot_depth_H - wall_t - slot_depth_H/2 + eps, 0])
            cube([slot_cavity_H, slot_depth_H + 2*eps, L + 2*eps], center=true);
    } else if (face == "bottom") {
        // Opens to -Y face
        translate([0, -profile_H/2 + slot_depth_H/2 - eps, 0])
            cube([slot_open_H, slot_depth_H + 2*eps, L + 2*eps], center=true);

        translate([0, -profile_H/2 + slot_depth_H + wall_t + slot_depth_H/2 - eps, 0])
            cube([slot_cavity_H, slot_depth_H + 2*eps, L + 2*eps], center=true);
    } else if (face == "right") {
        // Opens to +X face (width along Y)
        translate([profile_W/2 - slot_depth_W/2 + eps, 0, 0])
            cube([slot_depth_W + 2*eps, slot_open_W, L + 2*eps], center=true);

        translate([profile_W/2 - slot_depth_W - wall_t - slot_depth_W/2 + eps, 0, 0])
            cube([slot_depth_W + 2*eps, slot_cavity_W, L + 2*eps], center=true);
    } else if (face == "left") {
        // Opens to -X face
        translate([-profile_W/2 + slot_depth_W/2 - eps, 0, 0])
            cube([slot_depth_W + 2*eps, slot_open_W, L + 2*eps], center=true);

        translate([-profile_W/2 + slot_depth_W + wall_t + slot_depth_W/2 - eps, 0, 0])
            cube([slot_depth_W + 2*eps, slot_cavity_W, L + 2*eps], center=true);
    }
}

module extrusion_20x60(L=length_L) {
    color("Silver")
    difference() {
        // Outer body: correct 20 x 60 cross-section, length L
        cube([profile_W, profile_H, L], center=true);

        // Central bore (through)
        cylinder(r=core_r, h=L + 2*eps, center=true, $fn=64);

        // Four T-slots: one on each face (top/bottom use 60mm face, left/right use 20mm face)
        tslot_on_face("top",    L);
        tslot_on_face("bottom", L);
        tslot_on_face("left",   L);
        tslot_on_face("right",  L);

        // Corner relief pockets (kept inside walls; derived from dimensions)
        pocket_r = 4.5;
        pocket_x = profile_W/2 - wall_t - pocket_r - 0.5;
        pocket_y = profile_H/2 - wall_t - pocket_r - 0.5;

        for (sx = [-1, 1], sy = [-1, 1]) {
            translate([sx*pocket_x, sy*pocket_y, 0])
                cylinder(r=pocket_r, h=L + 2*eps, center=true, $fn=48);
        }
    }
}

// Render
extrusion_20x60(length_L);

// 20x80 aluminium extrusion profile (T-slot style), 100mm long
