// 30x60 aluminum extrusion profile (simplified but recognizable), 100mm long
// One connected solid, correct overall dimensions: 60 (X) x 30 (Y) x 100 (Z)

$fn = 64;

// Parameters
profile_W = 60.0;   // X
profile_H = 30.0;   // Y
length_L  = 100.0;  // Z

wall_t    = 2.0;    // outer wall thickness
slot_open = 6.0;    // T-slot mouth opening width
slot_depth= 7.0;    // depth from outer face to inner cavity
slot_wide = 12.0;   // wider internal part of T-slot
web_t     = 2.0;    // internal web thickness
center_hole_d = 6.0;

corner_chamfer = 1.5;

eps = 0.05;

// --- Helpers ---
module chamfered_block(w,h,l,c){
    // Chamfer only the 4 long edges (along Z) using 45° cuts
    difference(){
        cube([w,h,l], center=true);

        // TR
        translate([ w/2 - c/2,  h/2 - c/2, 0])
            rotate([0,0,45]) cube([c,c,l+2*eps], center=true);
        // TL
        translate([-w/2 + c/2,  h/2 - c/2, 0])
            rotate([0,0,45]) cube([c,c,l+2*eps], center=true);
        // BR
        translate([ w/2 - c/2, -h/2 + c/2, 0])
            rotate([0,0,45]) cube([c,c,l+2*eps], center=true);
        // BL
        translate([-w/2 + c/2, -h/2 + c/2, 0])
            rotate([0,0,45]) cube([c,c,l+2*eps], center=true);
    }
}

module tslot_cut_y(sign=1){
    // Cuts a T-slot on +Y (sign=1) or -Y (sign=-1) face
    union(){
        // mouth
        translate([0, sign*(profile_H/2 - slot_depth/2), 0])
            cube([slot_open, slot_depth + 2*eps, length_L + 2*eps], center=true);

        // wider internal pocket
        translate([0, sign*(profile_H/2 - (slot_depth*0.75)/2), 0])
            cube([slot_wide, slot_depth*0.75 + 2*eps, length_L + 2*eps], center=true);
    }
}

module tslot_cut_x(sign=1){
    // Cuts a T-slot on +X (sign=1) or -X (sign=-1) face
    union(){
        // mouth
        translate([sign*(profile_W/2 - slot_depth/2), 0, 0])
            cube([slot_depth + 2*eps, slot_open, length_L + 2*eps], center=true);

        // wider internal pocket
        translate([sign*(profile_W/2 - (slot_depth*0.75)/2), 0, 0])
            cube([slot_depth*0.75 + 2*eps, slot_wide, length_L + 2*eps], center=true);
    }
}

module internal_void(){
    // Main internal cavity leaving outer walls
    cube([profile_W - 2*wall_t, profile_H - 2*wall_t, length_L + 2*eps], center=true);
}

module internal_webs(){
    // Cross webs (keeps one connected solid). Slightly oversized in Z for robust union.
    union(){
        cube([web_t, profile_H - 2*wall_t + 2*eps, length_L + 2*eps], center=true);
        cube([profile_W - 2*wall_t + 2*eps, web_t, length_L + 2*eps], center=true);
    }
}

module center_bore(){
    cylinder(d=center_hole_d, h=length_L + 2*eps, center=true);
}

module extrusion_body(){
    // Build as: (outer shell with slots and bore) UNION (webs)
    // This guarantees a single connected solid and avoids "blank" top-level CSG issues.
    union(){
        difference(){
            chamfered_block(profile_W, profile_H, length_L, corner_chamfer);

            // Hollow interior
            internal_void();

            // T-slots on all four sides
            tslot_cut_y( 1);
            tslot_cut_y(-1);
            tslot_cut_x( 1);
            tslot_cut_x(-1);

            // Center bore
            center_bore();
        }

        // Webs overlap into remaining material by eps to ensure manifold connectivity
        internal_webs();
    }
}

// --- Final model ---
extrusion_body();

// 40x40 aluminium extrusion profile, 100mm long (simplified 4040 T-slot style)
// ONE connected solid: outer 40x40 with T-slots and internal voids that do NOT split the body.

profile_w = 40.0;
profile_h = 40.0;
length    = 100.0;

$fn = 96;
eps = 0.05;

// Feature sizing (parametric, derived from profile size)
wall          = profile_w * 0.10;   // ~4.0 outer wall
slot_open     = profile_w * 0.15;   // ~6.0 opening at surface
slot_neck     = profile_w * 0.10;   // ~4.0 neck width
slot_depth    = profile_w * 0.22;   // ~8.8 depth from surface
slot_cavity_w = profile_w * 0.22;   // ~8.8 inner cavity width
slot_cavity_d = profile_w * 0.12;   // ~4.8 inner cavity depth
center_hole_r = profile_w * 0.12;   // ~4.8

// Keep a guaranteed connected "plus" web through the center
web = profile_w * 0.14;             // ~5.6 (thicker than before to prevent quadrant split)

// 2D cross-section (solid minus voids), then extruded along Z
module profile_2d() {
    difference() {
        // Outer boundary (40x40)
        square([profile_w, profile_h], center=true);

        // Central bore
        circle(r=center_hole_r);

        // Corner relief pockets, but clipped so they cannot cut through the central web
        pocket = profile_w * 0.18; // ~7.2
        for (sx = [-1, 1], sy = [-1, 1]) {
            translate([
                sx*(profile_w/2 - wall - pocket/2),
                sy*(profile_h/2 - wall - pocket/2)
            ])
            intersection() {
                square([pocket, pocket], center=true);
                // Keep-out region around center to preserve connectivity
                difference() {
                    square([profile_w, profile_h], center=true);
                    square([web, profile_h + 2], center=true);
                    square([profile_w + 2, web], center=true);
                }
            }
        }

        // T-slots on each side (cuts from outside inward)
        // Right
        translate([ profile_w/2 - slot_depth/2 + eps, 0])
            square([slot_depth + 2*eps, slot_open], center=true);
        translate([ profile_w/2 - slot_depth + slot_cavity_d/2 + eps, 0])
            square([slot_cavity_d + 2*eps, slot_cavity_w], center=true);
        translate([ profile_w/2 - slot_depth/2 + eps, 0])
            square([slot_depth + 2*eps, slot_neck], center=true);

        // Left
        translate([-profile_w/2 + slot_depth/2 - eps, 0])
            square([slot_depth + 2*eps, slot_open], center=true);
        translate([-profile_w/2 + slot_depth - slot_cavity_d/2 - eps, 0])
            square([slot_cavity_d + 2*eps, slot_cavity_w], center=true);
        translate([-profile_w/2 + slot_depth/2 - eps, 0])
            square([slot_depth + 2*eps, slot_neck], center=true);

        // Top
        translate([0,  profile_h/2 - slot_depth/2 + eps])
            square([slot_open, slot_depth + 2*eps], center=true);
        translate([0,  profile_h/2 - slot_depth + slot_cavity_d/2 + eps])
            square([slot_cavity_w, slot_cavity_d + 2*eps], center=true);
        translate([0,  profile_h/2 - slot_depth/2 + eps])
            square([slot_neck, slot_depth + 2*eps], center=true);

        // Bottom
        translate([0, -profile_h/2 + slot_depth/2 - eps])
            square([slot_open, slot_depth + 2*eps], center=true);
        translate([0, -profile_h/2 + slot_depth - slot_cavity_d/2 - eps])
            square([slot_cavity_w, slot_cavity_d + 2*eps], center=true);
        translate([0, -profile_h/2 + slot_depth/2 - eps])
            square([slot_neck, slot_depth + 2*eps], center=true);

        // Internal lightening voids: ONLY in the four quadrants, leaving a solid central plus-web.
        // This prevents the "four separate blocks" failure.
        quad_w = (profile_w/2 - wall) - web/2;
        quad_h = (profile_h/2 - wall) - web/2;

        if (quad_w > 1 && quad_h > 1) {
            for (sx = [-1, 1], sy = [-1, 1]) {
                translate([sx*(web/2 + quad_w/2), sy*(web/2 + quad_h/2)])
                    square([quad_w, quad_h], center=true);
            }
        }
    }
}

module extrusion_4040(len=length) {
    color("Silver")
    linear_extrude(height=len, center=true, convexity=10)
        profile_2d();
}

// Final model: 40x40 cross-section, 100mm long
extrusion_4040(length);

// 40x40 T-slot aluminium extrusion (simplified, standard-looking), 100mm long
// One connected solid; all placements derived from dimensions.

$fn = 96;

// Parameters
profile_W = 40.0;
profile_H = 40.0;
length_L  = 100.0;

// Typical 40-series features (approximate)
corner_radius_r = 2.0;

center_bore_d = 6.8;          // through bore
slot_opening_w = 8.0;         // mouth width at outer face
slot_opening_depth = 2.2;     // how far the narrow mouth goes in
slot_cavity_w = 14.0;         // wider internal cavity width
slot_cavity_depth = 9.0;      // depth of cavity from outer face

// Keep enough material between cavity and center bore
slot_web_thickness = 2.0;

overlap_eps = 0.2;

// Helpers
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// Rounded outer body (2D) then extrude
module rounded_rect_2d(w, h, r) {
    r2 = clamp(r, 0, min(w, h)/2);
    hull() {
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx*(w/2 - r2), sy*(h/2 - r2)]) circle(r=r2);
    }
}

module outer_body() {
    linear_extrude(height=length_L, center=true)
        rounded_rect_2d(profile_W, profile_H, corner_radius_r);
}

module center_bore() {
    cylinder(h=length_L + 2*overlap_eps, r=center_bore_d/2, center=true);
}

// Single side T-slot cut (points outward along +X), then rotate for other sides
module tslot_cut_posX() {
    // Limit cavity depth so it doesn't break into the center bore web
    max_cavity_depth = profile_W/2 - center_bore_d/2 - slot_web_thickness;
    cav_d = clamp(slot_cavity_depth, 0, max_cavity_depth);

    // Mouth: narrow slot near the outer face
    mouth_center_x = profile_W/2 - slot_opening_depth/2;
    // Cavity: wider slot behind the mouth
    cavity_center_x = profile_W/2 - cav_d/2;

    union() {
        translate([mouth_center_x, 0, 0])
            cube([slot_opening_depth + 2*overlap_eps,
                  slot_opening_w,
                  length_L + 2*overlap_eps], center=true);

        translate([cavity_center_x, 0, 0])
            cube([cav_d + 2*overlap_eps,
                  slot_cavity_w,
                  length_L + 2*overlap_eps], center=true);
    }
}

module all_tslots() {
    union() {
        tslot_cut_posX();
        rotate([0,0,180]) tslot_cut_posX();
        rotate([0,0, 90]) tslot_cut_posX();
        rotate([0,0,-90]) tslot_cut_posX();
    }
}

// Final model
difference() {
    outer_body();
    center_bore();
    all_tslots();
}

// 40x80 aluminium extrusion profile, 100mm long
// Featureful, standard-ish 40x80 T-slot style approximation.
// One connected solid; all placements derived from dimensions.

$fn = 96;

// ---------------- Parameters ----------------
profile_W = 40.0;   // X
profile_H = 80.0;   // Y
length_L  = 100.0;  // Z

wall_t    = 2.6;    // outer wall thickness
web_t     = 2.4;    // internal web thickness (keeps model connected)
slot_open = 8.2;    // slot mouth opening (at surface)
slot_neck = 5.8;    // neck width just inside mouth
slot_depth= 12.0;   // depth from outer face to inner slot cavity
slot_cav_w= 14.0;   // inner cavity width (T-nut area)
slot_cav_d= 6.0;    // inner cavity depth (beyond neck)

center_void_W = 18.0;
center_void_H = 58.0;

corner_r  = 1.0;    // small outer corner rounding (approx)
detail_r  = 1.2;    // internal relief radius
overlap   = 0.25;   // robust boolean overlap

// ---------------- Helpers ----------------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

minHalf = min(profile_W, profile_H)/2;

// Clamp to keep valid geometry
wall_t_eff = clamp(wall_t, 1.0, minHalf-1.0);
web_t_eff  = clamp(web_t,  1.0, minHalf-1.0);

slot_depth_eff = clamp(slot_depth, 2.0, minHalf - wall_t_eff - 2.0);
slot_open_eff  = clamp(slot_open,  2.0, min(profile_W, profile_H) - 2*wall_t_eff - 2.0);
slot_neck_eff  = clamp(slot_neck,  2.0, slot_open_eff - 0.5);
slot_cav_w_eff = clamp(slot_cav_w, slot_neck_eff + 0.5, min(profile_W, profile_H) - 2*wall_t_eff - 1.0);
slot_cav_d_eff = clamp(slot_cav_d, 2.0, slot_depth_eff - 1.0);

center_void_W_eff = clamp(center_void_W, 6.0, profile_W - 2*wall_t_eff - 2*web_t_eff - 2.0);
center_void_H_eff = clamp(center_void_H, 6.0, profile_H - 2*wall_t_eff - 2*web_t_eff - 2.0);

corner_r_eff = clamp(corner_r, 0.0, minHalf-0.5);
detail_r_eff = clamp(detail_r, 0.0, 3.0);

// 2D rounded rectangle (for outer silhouette)
module rounded_rect_2d(w, h, r) {
    r2 = clamp(r, 0, min(w,h)/2 - 0.01);
    if (r2 <= 0)
        square([w,h], center=true);
    else
        offset(r=r2) offset(delta=-r2) square([w,h], center=true);
}

// ---------------- Base body ----------------
module extrusion_body() {
    // Slightly rounded outer corners to look more like real extrusion
    linear_extrude(height=length_L, center=true)
        rounded_rect_2d(profile_W, profile_H, corner_r_eff);
}

// ---------------- Internal voids ----------------
module internal_void_center() {
    cube([center_void_W_eff, center_void_H_eff, length_L + 2*overlap], center=true);
}

// Internal webs to keep a realistic connected profile (material left behind)
// (These are NOT subtracted; they remain as solid.)
module internal_webs_solid() {
    union() {
        // Vertical web (along Y)
        cube([web_t_eff, profile_H - 2*wall_t_eff, length_L], center=true);
        // Horizontal web (along X)
        cube([profile_W - 2*wall_t_eff, web_t_eff, length_L], center=true);
    }
}

// ---------------- T-slot cutters (subtracted) ----------------
// Each face gets a "T" shaped channel: mouth -> neck -> cavity.
// Implemented as union of rectangles, positioned by formulas.

module tslot_cutter_face(dir=[0,1,0]) {
    // dir indicates outward normal: [0,1,0]=top, [0,-1,0]=bottom, [1,0,0]=right, [-1,0,0]=left
    // Build in local coordinates where +Y is outward, then rotate to face.
    // Local: profile spans X (width) and Y (thickness into part), extruded along Z.

    // Mouth thickness (small) and neck/cavity depths
    mouth_d = wall_t_eff + 0.8; // small cut through outer wall to open slot
    mouth_d_eff = clamp(mouth_d, 1.0, slot_depth_eff-1.0);

    // Ensure cavity sits inside the slot depth
    neck_d = slot_depth_eff - slot_cav_d_eff;
    neck_d_eff = clamp(neck_d, 1.0, slot_depth_eff-1.0);

    // Local placement: outer surface at y = +profile_face/2
    // We'll place cutters so their outermost face slightly exceeds the surface (overlap).
    module local_cutter() {
        union() {
            // Mouth opening (at surface)
            translate([0, (profile_H/2) - mouth_d_eff/2 + overlap/2, 0])
                cube([slot_open_eff, mouth_d_eff + overlap, length_L + 2*overlap], center=true);

            // Neck (narrower) from just inside mouth to cavity start
            translate([0,
                       (profile_H/2) - mouth_d_eff - neck_d_eff/2,
                       0])
                cube([slot_neck_eff, neck_d_eff + overlap, length_L + 2*overlap], center=true);

            // Inner cavity (wider) deeper inside
            translate([0,
                       (profile_H/2) - mouth_d_eff - neck_d_eff - slot_cav_d_eff/2,
                       0])
                cube([slot_cav_w_eff, slot_cav_d_eff + overlap, length_L + 2*overlap], center=true);
        }
    }

    // Rotate local cutter to requested face
    // Local assumes top face (+Y). Map to other faces.
    if (dir[0]==0 && dir[1]==1) {
        local_cutter();
    } else if (dir[0]==0 && dir[1]==-1) {
        rotate([0,0,180]) local_cutter();
    } else if (dir[0]==1 && dir[1]==0) {
        rotate([0,0,-90]) local_cutter();
    } else if (dir[0]==-1 && dir[1]==0) {
        rotate([0,0,90]) local_cutter();
    } else {
        local_cutter();
    }
}

// For left/right faces, we need the local cutter to use profile_W as "height" instead of profile_H.
// Easiest: reuse same local cutter but swap axes by rotating 90° about Z already handled above,
// however local cutter uses profile_H/2 for surface position. So we provide two variants.

module tslot_cutter_topbottom(sign=1) { // sign=+1 top, -1 bottom
    mouth_d = clamp(wall_t_eff + 0.8, 1.0, slot_depth_eff-1.0);
    neck_d  = clamp(slot_depth_eff - slot_cav_d_eff, 1.0, slot_depth_eff-1.0);

    union() {
        // Mouth
        translate([0, sign*(profile_H/2 - mouth_d/2 + overlap/2), 0])
            cube([slot_open_eff, mouth_d + overlap, length_L + 2*overlap], center=true);
        // Neck
        translate([0, sign*(profile_H/2 - mouth_d - neck_d/2), 0])
            cube([slot_neck_eff, neck_d + overlap, length_L + 2*overlap], center=true);
        // Cavity
        translate([0, sign*(profile_H/2 - mouth_d - neck_d - slot_cav_d_eff/2), 0])
            cube([slot_cav_w_eff, slot_cav_d_eff + overlap, length_L + 2*overlap], center=true);
    }
}

module tslot_cutter_leftright(sign=1) { // sign=+1 right, -1 left
    mouth_d = clamp(wall_t_eff + 0.8, 1.0, slot_depth_eff-1.0);
    neck_d  = clamp(slot_depth_eff - slot_cav_d_eff, 1.0, slot_depth_eff-1.0);

    union() {
        // Mouth
        translate([sign*(profile_W/2 - mouth_d/2 + overlap/2), 0, 0])
            cube([mouth_d + overlap, slot_open_eff, length_L + 2*overlap], center=true);
        // Neck
        translate([sign*(profile_W/2 - mouth_d - neck_d/2), 0, 0])
            cube([neck_d + overlap, slot_neck_eff, length_L + 2*overlap], center=true);
        // Cavity
        translate([sign*(profile_W/2 - mouth_d - neck_d - slot_cav_d_eff/2), 0, 0])
            cube([slot_cav_d_eff + overlap, slot_cav_w_eff, length_L + 2*overlap], center=true);
    }
}

module all_tslots_cutters() {
    union() {
        tslot_cutter_topbottom(+1);
        tslot_cutter_topbottom(-1);
        tslot_cutter_leftright(+1);
        tslot_cutter_leftright(-1);
    }
}

// Internal reliefs (small cylinders) to mimic extrusion fillets/reliefs
module internal_reliefs_cutters() {
    if (detail_r_eff > 0) {
        // Place near inner corners of the outer wall (not at the center void corners)
        // These are SUBTRACTED to create small reliefs.
        for (xs = [-1, 1])
            for (ys = [-1, 1])
                translate([xs*(profile_W/2 - wall_t_eff - detail_r_eff),
                           ys*(profile_H/2 - wall_t_eff - detail_r_eff),
                           0])
                    cylinder(r=detail_r_eff, h=length_L + 2*overlap, center=true);
    }
}

// ---------------- Final model ----------------
module complete_model() {
    // Build as: outer body MINUS (center void + t-slots + small reliefs) PLUS internal webs
    // Use union at top-level to ensure one connected solid (webs connect to outer walls).
    difference() {
        union() {
            extrusion_body();
            internal_webs_solid();
        }
        union() {
            internal_void_center();
            all_tslots_cutters();
            internal_reliefs_cutters();
        }
    }
}

complete_model();

// 10x10 aluminium extrusion profile, 100mm long (simple T-slot style)
// One connected solid; all feature placement uses formulas from dimensions.

$fn = 64;

// Target dimensions
profile_w = 10.0;
profile_h = 10.0;
length    = 100.0;

// Profile feature parameters (kept conservative so walls remain)
wall            = 1.2;   // outer wall thickness
slot_open       = 2.2;   // opening at the surface for each T-slot
slot_depth      = 2.6;   // depth of slot from outer surface toward center
slot_inner_w    = 4.6;   // wider inner cavity width (T-slot undercut look)
center_hole_d   = 3.2;   // central bore diameter
eps             = 0.02;  // small overlap for robust boolean ops

module tslot_cut_x() {
    // Cuts a T-slot from +X face inward (along X), extruded along Z
    // Opening (narrow) near surface:
    translate([ profile_w/2 - slot_depth/2, 0, 0 ])
        cube([slot_depth + eps, slot_open, length + 2*eps], center=true);

    // Inner cavity (wider) slightly deeper:
    translate([ profile_w/2 - slot_depth + (slot_depth/2), 0, 0 ])
        cube([slot_depth + eps, slot_inner_w, length + 2*eps], center=true);
}

module tslot_cut_y() {
    // Cuts a T-slot from +Y face inward (along Y), extruded along Z
    translate([ 0, profile_h/2 - slot_depth/2, 0 ])
        cube([slot_open, slot_depth + eps, length + 2*eps], center=true);

    translate([ 0, profile_h/2 - slot_depth + (slot_depth/2), 0 ])
        cube([slot_inner_w, slot_depth + eps, length + 2*eps], center=true);
}

module extrusion_10x10(len=length) {
    // Ensure parameters don't destroy the profile
    assert(wall > 0);
    assert(slot_depth > 0 && slot_depth < profile_w/2);
    assert(slot_open > 0 && slot_open < profile_h - 2*wall);
    assert(slot_inner_w > slot_open && slot_inner_w < profile_h - 2*wall);

    color("Silver")
    difference() {
        // Outer body
        cube([profile_w, profile_h, len], center=true);

        // Central bore
        cylinder(h=len + 2*eps, d=center_hole_d, center=true);

        // Four T-slots (one per face), made by rotating the same cutters
        // +X face
        tslot_cut_x();
        // -X face
        rotate([0,0,180]) tslot_cut_x();

        // +Y face
        tslot_cut_y();
        // -Y face
        rotate([0,0,180]) tslot_cut_y();

        // Optional: keep a minimum wall at corners by trimming slot reach (implicit via slot_depth)
        // No extra arbitrary translations.
    }
