  cylinder(r=thread_OD/2, h=thread_L, center=true);
}

module cooling_fin(pos) {
  translate([0, 0, pos])
  cylinder(r=fin_OD/2, h=fin_thk, center=true);
}

module cooling_fins() {
  color("Silver")
  union() {
    for (i = [0:fin_count-1]) {
      cooling_fin(total_L/2 - (fin_thk/2) - overlap - i*(fin_thk + fin_gap));
