// Hot end (connected) - 70mm total length, 3.7mm barrel diameter, 1.75mm filament path
// Fix: orient hotend along X (length) so FRONT/BACK/LEFT/RIGHT orthographic views show length clearly.
// Output is one connected solid; all placements are derived from dimensions (no arbitrary offsets).

$fn = 96;

// -------------------- Parameters --------------------
total_L = 70;                 // total length (X)
barrel_D = 3.7;               // heatbreak/barrel OD
filament_D = 1.75;            // filament
bore_clearance = 0.25;        // extra clearance on filament path
bore_D = filament_D + bore_clearance;

overlap = 1;                  // overlap for boolean robustness

// Segment lengths (must sum to total_L)
heatsink_L = 22;
barrel_L   = 28;
heater_block_L = 15;
nozzle_L   = total_L - (heatsink_L + barrel_L + heater_block_L); // ensures exact total length

// Heatsink geometry
fin_count = 7;
fin_thk = 1.2;
fin_gap = 1.2;
fin_OD  = 16;
heatsink_core_D = 8.5;        // core under fins (typical heatsink body)
top_cap_D = 12;               // top collar
top_cap_L = 3;

// Groove mount (simple ring groove)
mount_groove_W = 6;
mount_groove_depth = 0.6;

// Heater block geometry
heater_block_W = 16;          // Y
heater_block_H = 12;          // Z

// Nozzle geometry (simple hex + cone tip)
nozzle_hex_AF = 7;            // across flats
nozzle_hex_L  = max(3, nozzle_L*0.55);
nozzle_cone_L = nozzle_L - nozzle_hex_L;
nozzle_base_D = 7.5;
nozzle_tip_D  = 0.8;

// Heater cartridge / thermistor holes
cartridge_D = 6;
thermistor_D = 3;

// -------------------- Derived X layout --------------------
// Model spans x = [-total_L/2, +total_L/2]
x_top =  total_L/2;
x_bot = -total_L/2;

x_heatsink_top = x_top;
x_heatsink_bot = x_heatsink_top - heatsink_L;

x_barrel_top = x_heatsink_bot;
x_barrel_bot = x_barrel_top - barrel_L;

x_block_top = x_barrel_bot;
x_block_bot = x_block_top - heater_block_L;

x_nozzle_top = x_block_bot;
x_nozzle_bot = x_bot; // exact

// Centers
x_heatsink_c = (x_heatsink_top + x_heatsink_bot)/2;
x_barrel_c   = (x_barrel_top   + x_barrel_bot)/2;
x_block_c    = (x_block_top    + x_block_bot)/2;
x_nozzle_c   = (x_nozzle_top   + x_nozzle_bot)/2;

// -------------------- Helpers --------------------
module x_cyl(x0, x1, r1, r2=r1) {
    // cylinder spanning [x0,x1] along X axis
    translate([(x0+x1)/2, 0, 0])
        rotate([0,90,0])
            cylinder(h=abs(x1-x0), r1=r1, r2=r2, center=true);
}

module hex_prism_x(af, h) {
    // across-flats hex prism along X axis
    // For a regular hex: AF = 2*R*cos(30) => R = AF/(2*cos30)
    R = af/(2*cos(30));
    rotate([0,90,0])
        cylinder(h=h, r=R, $fn=6, center=true);
}

// -------------------- Solids --------------------
module heatsink_solid() {
    union() {
        // Core
        x_cyl(x_heatsink_bot - overlap, x_heatsink_top + overlap, heatsink_core_D/2);

        // Top cap (collar)
        x_cyl(x_heatsink_top - top_cap_L, x_heatsink_top, top_cap_D/2);

        // Fins distributed within heatsink length, guaranteed to stay inside
        fin_stack_L = fin_count*fin_thk + (fin_count-1)*fin_gap;
        fin_margin = max(0, (heatsink_L - fin_stack_L)/2);
        for (i = [0:fin_count-1]) {
            x0 = x_heatsink_top - fin_margin - (i*(fin_thk+fin_gap)) - fin_thk;
            x1 = x0 + fin_thk;
            x_cyl(x0, x1, fin_OD/2);
        }
    }
}

module barrel_solid() {
    // Heatbreak/barrel (3.7mm OD) spanning barrel segment, overlapped into neighbors
    x_cyl(x_barrel_bot - overlap, x_barrel_top + overlap, barrel_D/2);
}

module heater_block_solid() {
    // Block centered on its segment, overlapped into barrel/nozzle
    translate([x_block_c, 0, 0])
        cube([heater_block_L + 2*overlap, heater_block_W, heater_block_H], center=true);
}

module nozzle_solid() {
    union() {
        // Hex section at top of nozzle segment
        x_hex_top = x_nozzle_top;
        x_hex_bot = x_nozzle_top - nozzle_hex_L;
        translate([(x_hex_top+x_hex_bot)/2, 0, 0])
            hex_prism_x(nozzle_hex_AF, abs(x_hex_top - x_hex_bot) + 2*overlap);

        // Transition from block to nozzle base (short taper)
        x_cyl(x_nozzle_top - overlap, x_nozzle_top + overlap, nozzle_base_D/2);

        // Cone to tip
        x_cone_top = x_hex_bot;
        x_cone_bot = x_nozzle_bot;
        x_cyl(x_cone_bot, x_cone_top, nozzle_tip_D/2, nozzle_base_D/2);
    }
}

module mount_groove_cut() {
    // Groove ring cut into heatsink core area (simple)
    // Place groove within heatsink, near its lower half
    groove_center_x = x_heatsink_bot + heatsink_L*0.45;
    translate([groove_center_x, 0, 0])
        rotate([0,90,0])
            cylinder(h=mount_groove_W, r=heatsink_core_D/2 + mount_groove_depth, center=true);
}

module heater_cartridge_hole_cut() {
    // Through Y direction, centered in heater block
    translate([x_block_c, 0, 0])
        rotate([90,0,0])
            cylinder(h=heater_block_W + 2*overlap, r=cartridge_D/2, center=true);
}

module thermistor_hole_cut() {
    // Through Z direction, slightly below center in block
    therm_y = 0;
    therm_z = -heater_block_H*0.20;
    translate([x_block_c, therm_y, therm_z])
        cylinder(h=heater_block_H + 2*overlap, r=thermistor_D/2, center=true);
}

module filament_bore_cut() {
    // Continuous filament path through entire hotend along X
    rotate([0,90,0])
        cylinder(h=total_L + 4*overlap, r=bore_D/2, center=true);
}

// -------------------- Assembly --------------------
module hotend_connected() {
    // Union of all solids (with overlaps) ensures one connected body
    union() {
        heatsink_solid();
        barrel_solid();
        heater_block_solid();
        nozzle_solid();
    }
}

difference() {
    difference() {
        difference() {
            hotend_connected();
            mount_groove_cut();
        }
        heater_cartridge_hole_cut();
        thermistor_hole_cut();
    }
    filament_bore_cut();
}

$fn = 128;

// =====================
// Target constraints
// =====================
total_length = 62.0;                 // overall Z length (verifiable)
barrel_diameter = 3.7;               // heatbreak/barrel OD (verifiable)
filament_diameter = 1.75;
filament_clearance = 0.25;
bore_diameter = filament_diameter + filament_clearance;  // verifiable filament path

// =====================
// Hotend proportions (E3D-ish silhouette)
// All Z positions are computed from these lengths so total_length is exact.
// =====================
overlap = 0.6;                       // small overlap to guarantee one connected solid

// Segment lengths along Z (top -> bottom)
heatsink_height = 18.0;
mount_groove_height = 3.0;
barrel_length = 23.0;                // thin heatbreak section between heatsink and block
heater_block_height = 12.0;
nozzle_length = total_length - (heatsink_height + mount_groove_height + barrel_length + heater_block_height); // ensures exact total

// Heatsink geometry
heatsink_outer_diameter = 16.0;
heatsink_core_diameter  = 8.0;
heatsink_fin_count = 7;
heatsink_fin_thickness = 1.2;
heatsink_fin_gap = (heatsink_height - heatsink_fin_count*heatsink_fin_thickness) / (heatsink_fin_count-1);

// Groove mount collar
mount_groove_diameter = 12.0;

// Heater block geometry
heater_block_length = 20.0;          // X
heater_block_width  = 16.0;          // Y

// Nozzle geometry
nozzle_hex_flat = 7.0;
nozzle_tip_diameter = 1.0;

// Side holes (typical)
heater_cartridge_diameter = 6.0;
thermistor_diameter = 3.0;
set_screw_hole_diameter = 3.0;

// =====================
// Derived Z coordinates (centered model)
// =====================
z_top = total_length/2;
z_bottom = -total_length/2;

z_heatsink_top = z_top;
z_heatsink_bottom = z_heatsink_top - heatsink_height;

z_groove_top = z_heatsink_bottom;
z_groove_bottom = z_groove_top - mount_groove_height;

z_barrel_top = z_groove_bottom;
z_barrel_bottom = z_barrel_top - barrel_length;

z_block_top = z_barrel_bottom;
z_block_bottom = z_block_top - heater_block_height;

z_nozzle_top = z_block_bottom;
z_nozzle_bottom = z_bottom;

// Centers
zc_heatsink = (z_heatsink_top + z_heatsink_bottom)/2;
zc_groove   = (z_groove_top + z_groove_bottom)/2;
zc_barrel   = (z_barrel_top + z_barrel_bottom)/2;
zc_block    = (z_block_top + z_block_bottom)/2;
zc_nozzle   = (z_nozzle_top + z_nozzle_bottom)/2;

// =====================
// Helpers
// =====================
module hex_prism(flat, h, center=true) {
    // across flats = 2*R*cos(30) => R = flat/(2*cos(30))
    R = flat/(2*cos(30));
    cylinder(h=h, r=R, $fn=6, center=center);
}

// =====================
// Parts (all connected via computed Z and overlaps)
// =====================
module heatsink() {
    union() {
        // core
        translate([0,0,zc_heatsink])
            cylinder(h=heatsink_height + overlap, r=heatsink_core_diameter/2, center=true);

        // fins
        for (i = [0:heatsink_fin_count-1]) {
            z_fin = z_heatsink_top - heatsink_fin_thickness/2 - i*(heatsink_fin_thickness + heatsink_fin_gap);
            translate([0,0,z_fin])
                cylinder(h=heatsink_fin_thickness + overlap, r=heatsink_outer_diameter/2, center=true);
        }
    }
}

module groove_mount() {
    // collar that overlaps into heatsink and barrel to ensure connectivity
    translate([0,0,zc_groove])
        cylinder(h=mount_groove_height + 2*overlap, r=mount_groove_diameter/2, center=true);
}

module barrel_heatbreak() {
    translate([0,0,zc_barrel])
        cylinder(h=barrel_length + 2*overlap, r=barrel_diameter/2, center=true);
}

module heater_block() {
    translate([0,0,zc_block])
        cube([heater_block_length, heater_block_width, heater_block_height + 2*overlap], center=true);
}

module nozzle() {
    union() {
        // hex section at top of nozzle (inside/just below block)
        hex_h = min(5.0, nozzle_length*0.55);
        translate([0,0,z_nozzle_top - hex_h/2 + overlap])
            hex_prism(nozzle_hex_flat, hex_h + 2*overlap, center=true);

        // conical tip down to bottom
        cone_h = nozzle_length - hex_h;
        translate([0,0,z_nozzle_bottom + cone_h/2])
            cylinder(h=cone_h + 2*overlap,
                     r1=(nozzle_hex_flat/(2*cos(30))) * 0.85,
                     r2=nozzle_tip_diameter/2,
                     center=true);
    }
}

// =====================
// Holes
// =====================
module filament_bore() {
    cylinder(h=total_length + 4*overlap, r=bore_diameter/2, center=true);
}

module heater_cartridge_hole() {
    // Through X direction (so FRONT/BACK/LEFT/RIGHT show full Z silhouette, not a circular cut)
    translate([0,0,zc_block])
        rotate([0,90,0])
            cylinder(h=heater_block_length + 4*overlap, r=heater_cartridge_diameter/2, center=true);
}

module thermistor_hole() {
    // Through Y direction, offset toward one side in X
    x_off = heater_block_length/2 - thermistor_diameter/2 - 1.0;
    translate([x_off,0,zc_block])
        rotate([90,0,0])
            cylinder(h=heater_block_width + 4*overlap, r=thermistor_diameter/2, center=true);
}

module set_screw_holes() {
    // Two small holes through Y direction, near ends in X
    x_off = heater_block_length/2 - set_screw_hole_diameter/2 - 2.0;
    for (sx = [-1, 1]) {
        translate([sx*x_off,0,zc_block])
            rotate([90,0,0])
                cylinder(h=heater_block_width + 4*overlap, r=set_screw_hole_diameter/2, center=true);
    }
}

// =====================
// Assembly
// =====================
module hotend_solid() {
    union() {
        heatsink();
        groove_mount();
        barrel_heatbreak();
        heater_block();
        nozzle();
    }
}

module hotend_final() {
    difference() {
        hotend_solid();
        filament_bore();
        heater_cartridge_hole();
        thermistor_hole();
        set_screw_holes();
    }
}

