module markings_text() {
  cube([overlap, overlap, overlap], center=true);
}

// Operations
module pipe_plus_socket() {
  union() {
    pipe_body();
    socket_end();
  }
}

module pipe_hollowed() {
  difference() {
    pipe_plus_socket();
    inner_bore();
    socket_inner_bore();
  }
}

module chamfer_end1() {
  difference() {
    translate([0, 0, pipe_length/2 - chamfer_length/2 + overlap])
      chamfer_outer_profile();
    translate([0, 0, pipe_length/2 - chamfer_length/2 + overlap])
      chamfer_inner_profile();
  }
}

module chamfer_end2() {
