r_pipe_i   = r_pipe_o - wall_thickness;

r_sock_o   = socket_outer_diameter/2;
r_sock_i   = r_sock_o - socket_wall_thickness;

// Safety (avoid invalid geometry)
r_pipe_i_ok = max(0.01, r_pipe_i);
r_sock_i_ok = max(0.01, r_sock_i);

