    difference() {
        polygon(points = concat(
            [ for (a = [a0 : 2 : a1]) [r_outer*cos(a), r_outer*sin(a)] ],
            [ for (a = [a1 : -2 : a0]) [r_inner*cos(a), r_inner*sin(a)] ]
