module fuse_recess_cut() {
  // Recess in fuse drawer boss to show drawer face
  recess_d = min(1.2, fuse_t - 0.6);
  z_center = panel_t/2 + flange_t + fuse_t - recess_d/2 - overlap;

  translate([0, -cutout_H/2 + fuse_H/2 + body_wall_t, z_center])
    rounded_rect_prism([fuse_W*0.88, fuse_H*0.72, recess_d + 2*overlap], r=0.8, center=true);
}

module fuse_finger_notch_cut() {
  // Small notch on fuse drawer (bottom edge) for finger pull
  notch_w = fuse_W*0.35;
  notch_h = fuse_H*0.25;
  notch_d = fuse_t + 2*overlap;

  z_center = panel_t/2 + flange_t + fuse_t/2 - overlap;
  y_center = -cutout_H/2 + fuse_H/2 + body_wall_t - fuse_H*0.30;

  translate([0, y_center, z_center])
    cube([notch_w, notch_h, notch_d], center=true);
}

module label_recesses_cut() {
  // Shallow recesses above switch and above fuse (no text)
  z_center = panel_t/2 + flange_t + front_bezel_t - (bezel_recess_d + overlap)/2;

  translate([0, cutout_H/2 - switch_H/2 - body_wall_t, z_center])
    cube([switch_W, switch_H/2, bezel_recess_d + overlap], center=true);

  translate([0, -cutout_H/2 + fuse_H/2 + body_wall_t, z_center])
    cube([fuse_W, fuse_H/2, bezel_recess_d + overlap], center=true);
}

module screw_holes_cut() {
  // Through-holes in flange/bezel (axis along Y)
  hole_len = flange_t + front_bezel_t + 2*overlap;
  z_center = panel_t/2 + (flange_t + front_bezel_t)/2 - overlap;

  translate([-flange_W/2 + screw_edge_margin, 0, z_center])
    rotate([90,0,0])
      cylinder(d=screw_hole_d, h=hole_len, center=true);

  translate([flange_W/2 - screw_edge_margin, 0, z_center])
    rotate([90,0,0])
      cylinder(d=screw_hole_d, h=hole_len, center=true);
}

// -------------------- Assembly --------------------
module inlet_module() {
  difference() {
    union() {
      // Shell body
      difference() {
        main_body_outer();
        main_body_inner_void();
      }

      // Front mounting features
      front_flange();
      front_bezel_frame();

      // Clips
      side_clips();

      // Switch + fuse bosses (positive geometry)
      rocker_switch_boss();
      fuse_drawer_boss();
    }

    // C14 cavity + details
    c14_front_cavity_cut();
    c14_key_notch_cut();
    pin_holes_cut();

    // Switch + fuse recess details
    switch_recess_cut();
    fuse_recess_cut();
    fuse_finger_notch_cut();

    // Label recesses (blank)
    label_recesses_cut();

    // Screw holes
    screw_holes_cut();
  }
}

// Final
inlet_module();

// IEC fused inlet module (JR-101-1F style) - panel cutout 36.0mm x 27.0mm
// One connected solid; all translate() values derived from dimensions (no arbitrary offsets).

$fn = 72;

// ---------------- Parameters ----------------
cutout_W = 36.0;                 // panel cutout width (X)
cutout_H = 27.0;                 // panel cutout height (Y)

body_D   = 45.0;                 // depth behind panel (Z-)
flange_W = 44.0;
flange_H = 35.0;
flange_t = 2.5;

front_bezel_t = 3.0;             // thickness in front of panel plane (Z+)

panel_t = 2.0;                   // reference panel thickness (kept connected)
clip_clearance = 0.5;

wall_t = 2.0;
overlap = 1.0;                   // intentional overlap to guarantee connectivity

round_r = 0.6;                   // small edge rounding (avoid distorting openings)

// --- IEC C14 opening (recognizable) ---
c14_opening_W = 28.0;
c14_opening_H = 20.0;
c14_opening_corner_r = 2.2;

// C14 pin apertures (front face)
pin_slot_w = 6.2;
pin_slot_h = 4.2;
pin_slot_corner_r = 1.0;
pin_pitch_x = 10.0;              // L-N spacing
pin_pitch_y = 8.0;               // Earth offset

// --- Fuse drawer (front, above C14) ---
drawer_W = 18.0;
drawer_H = 10.0;
drawer_D = 16.0;

// Fuse drawer handle notch (front)
handle_notch_W = 10.0;
handle_notch_H = 2.2;

// Fuse cylinder detail (inside drawer)
fuse_cyl_r = 2.6;
fuse_cyl_L = 20.0;

// Rear terminal block volume
rear_block_W = 30.0;
rear_block_H = 22.0;
rear_block_D = 18.0;

// Terminal blades (rear)
blade_W = 6.3;
blade_t = 0.8;
blade_L = 12.0;
blade_spacing_X = 10.0;
blade_spacing_Y = 8.0;

// Screw holes in flange
screw_hole_r = 1.6;
screw_hole_edge_margin = 6.0;

// ---------------- Derived Z references (panel plane at z=0) ----------------
// Positive Z is "front/outside"; negative Z is "rear/inside".
z_bezel_center  =  front_bezel_t/2;
z_flange_center = -flange_t/2;
z_body_center   = -(flange_t + body_D/2 - overlap);
z_rear_center   = -(flange_t + body_D - rear_block_D/2 - overlap);

// ---------------- Helpers ----------------
module rounded_rect_2d(w, h, r) {
  r2 = min(r, min(w, h)/2);
  offset(r=r2) square([w-2*r2, h-2*r2], center=true);
}

module rounded_slot_3d(w, h, r, t) {
  linear_extrude(height=t, center=true)
    rounded_rect_2d(w, h, r);
}

// ---------------- Base solids ----------------
module inlet_main_body_raw() {
  // Body sized to fit through cutout with clearance
  translate([0, 0, z_body_center])
    cube([cutout_W - 2*clip_clearance, cutout_H - 2*clip_clearance, body_D], center=true);
}

module panel_mount_flange_raw() {
  translate([0, 0, z_flange_center])
    cube([flange_W, flange_H, flange_t], center=true);
}

module front_bezel_raw() {
  // Bezel protrudes in front of panel plane
  translate([0, 0, z_bezel_center])
    cube([flange_W - 2*wall_t, flange_H - 2*wall_t, front_bezel_t], center=true);
}

module rear_terminal_block_volume_raw() {
  translate([0, 0, z_rear_center])
    cube([rear_block_W, rear_block_H, rear_block_D], center=true);
}

// Fuse drawer body (protrudes behind front bezel into the body)
module fuse_drawer_body_raw() {
  y_drawer =  cutout_H/2 - drawer_H/2 - wall_t; // top area
  z_drawer_center = -(drawer_D/2 - overlap);     // starts at panel plane and goes rearward
  translate([0, y_drawer, z_drawer_center])
    cube([drawer_W, drawer_H, drawer_D], center=true);
}

// Retention clips (small tabs near drawer, connected to body)
module retention_clip_left_raw() {
  y_drawer =  cutout_H/2 - drawer_H/2 - wall_t;
  x_clip = -(cutout_W/2 - wall_t/2 - clip_clearance);
  z_clip = -(wall_t - overlap);
  translate([x_clip, y_drawer, z_clip])
    cube([wall_t, drawer_H, wall_t*2], center=true);
}

module retention_clip_right_raw() {
  y_drawer =  cutout_H/2 - drawer_H/2 - wall_t;
  x_clip =  (cutout_W/2 - wall_t/2 - clip_clearance);
  z_clip = -(wall_t - overlap);
  translate([x_clip, y_drawer, z_clip])
    cube([wall_t, drawer_H, wall_t*2], center=true);
}

// Rear terminal blades (connected to rear block)
module terminal_blade_raw(x, y) {
  z_blade_center = -(flange_t + body_D + blade_L/2 - overlap);
  translate([x, y, z_blade_center])
    cube([blade_W, blade_t, blade_L], center=true);
}

module terminal_blades_raw() {
  terminal_blade_raw(-blade_spacing_X/2, -blade_spacing_Y/2); // L
  terminal_blade_raw( blade_spacing_X/2, -blade_spacing_Y/2); // N
  terminal_blade_raw(0,                 blade_spacing_Y/2);   // E
}

// Fuse cylinder detail (inside drawer)
module fuse_detail_cyl_raw() {
  y_drawer =  cutout_H/2 - drawer_H/2 - wall_t;
  z_drawer_center = -(drawer_D/2 - overlap);
  translate([0, y_drawer, z_drawer_center])
    rotate([0, 90, 0])
      cylinder(r=fuse_cyl_r, h=fuse_cyl_L, center=true);
}

// Panel cutout reference (kept connected via overlap into bezel)
module panel_cutout_reference_raw() {
  z_panel_center = panel_t/2 - overlap; // overlaps into bezel by overlap
  translate([0, 0, z_panel_center])
    cube([cutout_W, cutout_H, panel_t], center=true);
}

// ---------------- Subtractions (openings/holes) ----------------
module c14_opening_profile_2d() {
  // C14 outline with small "key" notches at top corners (recognizable silhouette)
  // Built as union of a rounded rectangle + two small top-corner bumps.
  union() {
    rounded_rect_2d(c14_opening_W, c14_opening_H, c14_opening_corner_r);

    // Corner key bumps (inside the opening silhouette)
    bump_w = 4.0;
    bump_h = 3.0;
    x_b = c14_opening_W/2 - bump_w/2;
    y_b = c14_opening_H/2 - bump_h/2;
    translate([ x_b, y_b]) square([bump_w, bump_h], center=true);
    translate([-x_b, y_b]) square([bump_w, bump_h], center=true);
  }
}

module c14_opening_3d_raw() {
  // Place C14 opening in lower portion (below fuse drawer)
  y_c14 = -(cutout_H/2 - c14_opening_H/2 - wall_t);
  // Cut through bezel + flange (front to panel plane and slightly beyond)
  t = front_bezel_t + flange_t + 2*overlap;
  z_open_center = (front_bezel_t - flange_t)/2; // centered across bezel+flange stack
  translate([0, y_c14, z_open_center])
    linear_extrude(height=t, center=true)
      c14_opening_profile_2d();
}

module c14_pin_apertures_raw() {
  y_c14 = -(cutout_H/2 - c14_opening_H/2 - wall_t);
  t = front_bezel_t + flange_t + 2*overlap;
  z_open_center = (front_bezel_t - flange_t)/2;

  // L and N (bottom row)
  for (sx = [-1, 1]) {
    translate([sx*pin_pitch_x/2, y_c14 - pin_pitch_y/2, z_open_center])
      rounded_slot_3d(pin_slot_w, pin_slot_h, pin_slot_corner_r, t);
  }
  // Earth (top center)
  translate([0, y_c14 + pin_pitch_y/2, z_open_center])
    rounded_slot_3d(pin_slot_w, pin_slot_h, pin_slot_corner_r, t);
}

module fuse_drawer_opening_raw() {
  y_drawer =  cutout_H/2 - drawer_H/2 - wall_t;
  t = front_bezel_t + flange_t + 2*overlap;
  z_open_center = (front_bezel_t - flange_t)/2;

  // Main drawer opening
  translate([0, y_drawer, z_open_center])
    cube([drawer_W + 2*clip_clearance, drawer_H + 2*clip_clearance, t], center=true);

  // Small handle notch at top edge of drawer opening (adds recognizability)
  y_notch = y_drawer + (drawer_H + 2*clip_clearance)/2 - handle_notch_H/2;
  translate([0, y_notch, z_open_center])
    cube([handle_notch_W, handle_notch_H, t], center=true);
}

module screw_holes_raw() {
  xL = -(flange_W/2 - screw_hole_edge_margin);
  xR =  (flange_W/2 - screw_hole_edge_margin);
  translate([xL, 0, z_flange_center])
    cylinder(r=screw_hole_r, h=flange_t + 2*overlap, center=true);
  translate([xR, 0, z_flange_center])
    cylinder(r=screw_hole_r, h=flange_t + 2*overlap, center=true);
}

// ---------------- Assembly ----------------
module raw_solid() {
  union() {
    panel_mount_flange_raw();
    front_bezel_raw();
    inlet_main_body_raw();
    rear_terminal_block_volume_raw();

    fuse_drawer_body_raw();
    retention_clip_left_raw();
    retention_clip_right_raw();

    terminal_blades_raw();
    fuse_detail_cyl_raw();

    panel_cutout_reference_raw();
  }
}

module with_openings() {
  difference() {
    raw_solid();

    screw_holes_raw();

    // Front features
    fuse_drawer_opening_raw();
    c14_opening_3d_raw();
    c14_pin_apertures_raw();
  }
}

// Rounded outer edges (small; keep openings crisp)
module final_module() {
  minkowski() {
    with_openings();
    sphere(r=round_r);
  }
}

final_module();

// IEC fused inlet (old style) - connected solid, overall face 36x27mm
// Fixes:
// - Adds recognizable IEC C14 face details (pin openings + earth slot + inner bezel recess)
// - Adds clearer fused inlet module features (fuse drawer pocket + cap lip, switch pocket + rocker)
// - Keeps overall faceplate size exactly 36.0 x 27.0 mm
// - Ensures ONE connected solid (all additive parts overlap main body/flange; all cutouts are subtractive)

$fn = 64;

// -------------------- Parameters --------------------
face_W = 36.0; //[18.0:72.0:0.5]
face_H = 27.0; //[13.5:54.0:0.5]
flange_t = 2.5; //[1.25:5.0:0.1]

body_D = 30.0; //[15.0:60.0:0.5]
body_W = 28.0; //[14.0:56.0:0.5]
body_H = 22.0; //[11.0:44.0:0.5]

panel_t = 2.0; //[1.0:4.0:0.1]
cutout_W = 27.5; //[13.75:55.0:0.5]
cutout_H = 20.5; //[10.25:41.0:0.5]

clip_W = 6.0; //[3.0:12.0:0.5]
clip_H = 2.0; //[1.0:4.0:0.1]
clip_overhang = 1.2; //[0.6:2.4:0.1]

eps = 0.25; //[0.1:1.0:0.05]

screw_hole_d = 3.2; //[2.0:6.0:0.1]
screw_edge_margin = 5.0; //[3.0:10.0:0.5]

fuse_W = 12.0; //[6.0:24.0:0.5]
fuse_H = 6.0; //[3.0:12.0:0.5]
fuse_D = 10.0; //[5.0:20.0:0.5]
fuse_cap_t = 1.5; //[0.8:3.0:0.1]

switch_W = 14.0; //[7.0:28.0:0.5]
switch_H = 10.0; //[5.0:20.0:0.5]
switch_D = 4.0; //[2.0:8.0:0.5]

blade_W = 6.3; //[3.0:12.6:0.1]
blade_T = 0.8; //[0.4:1.6:0.1]
blade_L = 10.0; //[5.0:20.0:0.5]

strain_W = 10.0; //[5.0:20.0:0.5]
strain_H = 6.0; //[3.0:12.0:0.5]
strain_D = 6.0; //[3.0:12.0:0.5]

label_W = 10.0; //[5.0:20.0:0.5]
label_H = 4.0; //[2.0:8.0:0.5]
label_depth = 0.8; //[0.4:1.6:0.1]

chamfer = 0.8; //[0.4:1.6:0.1]

// IEC C14 face detail parameters (visual, not a certified drawing)
iec_bezel_W = 24.0;
iec_bezel_H = 18.0;
iec_bezel_r = 2.0;
iec_bezel_recess = 1.2;     // recess depth into front face

pin_slot_W = 2.2;           // rectangular slot width
pin_slot_H = 6.2;           // rectangular slot height
pin_pitch = 10.0;           // L-N spacing
earth_slot_W = 6.0;
earth_slot_H = 2.6;
earth_y = -4.8;             // earth below pins

// -------------------- Helpers --------------------
module rrect2d(w,h,r){
  r2 = min(r, min(w,h)/2);
  hull(){
    for (sx=[-1,1], sy=[-1,1])
      translate([sx*(w/2-r2), sy*(h/2-r2)]) circle(r=r2);
  }
}

module rrect3d(w,h,t,r){
  linear_extrude(height=t, center=true) rrect2d(w,h,r);
}

// -------------------- Coordinate convention --------------------
// Front face outer surface at z=0, body extends to negative z.
z_flange_center = -flange_t/2;
z_body_center   = -(flange_t + body_D/2 - eps); // overlap into flange
z_body_front    = z_body_center + body_D/2;
z_body_back     = z_body_center - body_D/2;

// -------------------- Base solids --------------------
module front_faceplate_flange(){
  translate([0,0,z_flange_center])
    rrect3d(face_W, face_H, flange_t, chamfer);
}

module main_inlet_housing_body(){
  translate([0,0,z_body_center])
    rrect3d(body_W, body_H, body_D, 1.0);
}

module rear_body_extension(){
  ext_D = body_D*0.35;
  ext_W = body_W*0.85;
  ext_H = body_H*0.85;
  z_ext_center = z_body_back - ext_D/2 + eps; // overlap into main body
  translate([0,0,z_ext_center])
    rrect3d(ext_W, ext_H, ext_D, 0.8);
}

// -------------------- Subtractive details --------------------
module mounting_screw_hole(x){
  translate([x,0,z_flange_center])
    cylinder(d=screw_hole_d, h=flange_t + 2*eps, center=true);
}

module label_recess(x,y){
  translate([x,y,-label_depth/2 + eps])
    cube([label_W, label_H, label_depth + 2*eps], center=true);
}

// IEC bezel recess (gives recognizable inlet face depth)
module iec_bezel_recess(){
  // recess into front surface; keep within flange thickness
  t = min(iec_bezel_recess, flange_t - 0.3);
  translate([0,0,-t/2 + eps])
    rrect3d(iec_bezel_W, iec_bezel_H, t + 2*eps, iec_bezel_r);
}

// IEC pin openings (through flange and slightly into body)
module iec_pin_openings(){
  t = flange_t + 4*eps;

  // L and N slots (vertical rectangles)
  for (sx=[-1,1]){
    translate([sx*pin_pitch/2, 2.0, z_flange_center])
      cube([pin_slot_W, pin_slot_H, t], center=true);
  }

  // Earth slot (horizontal rectangle)
  translate([0, earth_y, z_flange_center])
    cube([earth_slot_W, earth_slot_H, t], center=true);
}

// Fuse drawer pocket (recess into front face)
module fuse_drawer_pocket(){
  x = -(face_W/2 - fuse_W/2 - eps);
  y =  (face_H/2 - fuse_H/2 - eps);

  // pocket depth into flange (not through)
  pocket_t = min(flange_t - 0.4, 1.6);
  translate([x,y,-pocket_t/2 + eps])
    cube([fuse_W*0.92, fuse_H*0.92, pocket_t + 2*eps], center=true);
}

// Switch pocket (recess into front face)
module switch_pocket(){
  x = (face_W/2 - switch_W/2 - eps);
  y = (face_H/2 - switch_H/2 - eps);

  pocket_t = min(flange_t - 0.4, 1.4);
  translate([x,y,-pocket_t/2 + eps])
    cube([switch_W*0.92, switch_H*0.92, pocket_t + 2*eps], center=true);
}

// -------------------- Additive features (must be connected) --------------------
module snap_in_retention_clip(side=1){
  // side = -1 left, +1 right
  x = side*(body_W/2 + clip_overhang/2 - eps);
  z = z_body_front - (panel_t + clip_H/2) + eps; // overlaps body
  translate([x,0,z])
    cube([clip_overhang + 2*eps, clip_W, clip_H], center=true);
}

module fuse_drawer(){
  // protruding outward (positive z) and overlapping flange
  x = -(face_W/2 - fuse_W/2 - eps);
  y =  (face_H/2 - fuse_H/2 - eps);
  z =  fuse_D/2 - eps; // overlaps front surface at z=0
  translate([x,y,z])
    cube([fuse_W, fuse_H, fuse_D], center=true);
}

module fuse_cap(){
  x = -(face_W/2 - fuse_W/2 - eps);
  y =  (face_H/2 - fuse_H/2 - eps);
  // cap overlaps drawer slightly to ensure connectivity
  z = fuse_D + fuse_cap_t/2 - 1.0*eps;
  translate([x,y,z])
    cube([fuse_W*0.9, fuse_H*0.9, fuse_cap_t], center=true);
}

module switch_rocker(){
  x = (face_W/2 - switch_W/2 - eps);
  y = (face_H/2 - switch_H/2 - eps);
  z = switch_D/2 - eps; // overlaps flange
  // slight top bevel via hull of two boxes
  translate([x,y,z])
    hull(){
      cube([switch_W, switch_H, switch_D], center=true);
      translate([0,0,switch_D*0.25])
        cube([switch_W*0.92, switch_H*0.92, switch_D*0.6], center=true);
    }
}

module terminal_blade(x,y){
  z = z_body_back - blade_L/2 + eps; // overlaps body back
  translate([x,y,z])
    cube([blade_T, blade_W, blade_L], center=true);
}

module strain_relief_features(){
  y = -(body_H/2 - strain_H/2 - eps);
  z = z_body_back - strain_D/2 + eps; // overlaps body
  translate([0,y,z])
    cube([strain_W, strain_H, strain_D], center=true);
}

// Connected reference "panel cutout" block (kept connected, not floating)
module panel_cutout_profile(){
  z_panel_center = z_body_front - panel_t/2 + eps; // overlaps body
  translate([0,0,z_panel_center])
    rrect3d(cutout_W, cutout_H, panel_t, 0.6);
}

// -------------------- Faceplate with holes/recesses --------------------
module faceplate_with_details(){
  difference(){
    front_faceplate_flange();

    // IEC face details
    iec_bezel_recess();
    iec_pin_openings();

    // Fuse + switch pockets
    fuse_drawer_pocket();
    switch_pocket();

    // Mounting holes
    mounting_screw_hole(-(face_W/2 - screw_edge_margin));
    mounting_screw_hole( (face_W/2 - screw_edge_margin));

    // Label recesses (bottom corners)
    label_recess(-(face_W/2 - label_W/2 - eps), -(face_H/2 - label_H/2 - eps));
    label_recess( (face_W/2 - label_W/2 - eps), -(face_H/2 - label_H/2 - eps));
  }
}

// -------------------- Final connected model --------------------
module complete_model(){
  union(){
    faceplate_with_details();
    main_inlet_housing_body();
    rear_body_extension();

    snap_in_retention_clip(-1);
    snap_in_retention_clip( 1);

    fuse_drawer();
    fuse_cap();
    switch_rocker();

    // Rear terminals (L, N, E) - all overlap body back
    terminal_blade(-pin_pitch/2,  0);
    terminal_blade( pin_pitch/2,  0);
    terminal_blade(0,            -pin_pitch/2);

    strain_relief_features();

    // Connected reference cutout block
    panel_cutout_profile();
  }
}

// Output
complete_model();

// IEC C14 inlet module (ATX style) - 40.0mm x 27.0mm panel cutout
// Structural fixes:
// - Make IEC C14 face unmistakable: add trapezoid cavity + 3 pin slots + small key notches
// - Ensure all Z placements are derived from the same front reference plane (z=0 at front face)
// - Recalculate translates so solids overlap slightly and remain one connected object

$fn = 64;

// -------------------- Parameters --------------------
cutout_W = 40.0;                 // panel cutout width
cutout_H = 27.0;                 // panel cutout height

flange_W = 50.0;
flange_H = 32.0;
flange_t = 2.5;

body_depth = 28.0;
body_wall_t = 1.8;
body_clearance = 0.3;

screw_hole_d = 3.2;
screw_hole_spacing_W = 44.0;
screw_hole_offset_Y = 0.0;

terminal_block_W = 22.0;
terminal_block_H = 16.0;
terminal_block_depth = 10.0;

overlap = 1.2;                   // 1-2mm overlap for robust unions

// Side retention "ears"/clips (kept connected)
clip_W = 8.0;
clip_T = 2.0;
clip_L = 10.0;

// Rear spade terminals (kept connected)
spade_W = 6.3;
spade_T = 0.8;
spade_L = 12.0;
spade_spacing_X = 8.0;
spade_spacing_Y = 6.0;

// Edge softening (small; avoid heavy Minkowski on detailed cutouts)
chamfer_r = 0.8;

// -------------------- IEC C14 front details (cutouts) --------------------
// Approximate IEC C14 socket cavity (trapezoid-ish) + 3 pin holes.
iec_cavity_top_W = 26.0;
iec_cavity_bot_W = 22.0;
iec_cavity_H     = 18.0;
iec_cavity_depth = 9.0;          // recess depth into body

pin_hole_W = 6.0;                // rectangular pin slot width
pin_hole_H = 3.2;                // rectangular pin slot height
pin_hole_depth = 12.0;           // deeper than cavity so it clearly cuts through recess

pin_pitch_X = 10.0;              // L-N spacing
pin_row_Y   = 3.8;               // L/N row above center
pin_gnd_Y   = -4.8;              // ground below center

// Small "key" notches near top corners (common visual cue on IEC inlets)
key_notch_W = 2.2;
key_notch_H = 2.2;
key_notch_depth = 2.0;

// -------------------- Derived reference planes --------------------
// Coordinate convention: FRONT FACE of flange is at z=0, positive z goes rearward.
z_flange_center = flange_t/2;
z_body_front    = flange_t - overlap;                 // body starts slightly into flange
z_body_center   = z_body_front + body_depth/2;
z_body_rear     = z_body_front + body_depth;

z_term_center   = (z_body_rear - overlap) + terminal_block_depth/2;
z_term_rear     = (z_body_rear - overlap) + terminal_block_depth;

z_spade_center  = (z_term_rear - overlap) + spade_L/2;

// -------------------- Helpers --------------------
module rounded_box(size=[10,10,10], r=1.0, center=true) {
  rr = min(r, min(size[0], min(size[1], size[2]))/2 - 0.01);
  if (rr <= 0) cube(size, center=center);
  else minkowski() {
    cube([size[0]-2*rr, size[1]-2*rr, size[2]-2*rr], center=center);
    sphere(r=rr);
  }
}

module screw_hole_cyl(h) {
  cylinder(h=h, r=screw_hole_d/2, center=true);
}

// -------------------- Base solids --------------------
module front_flange_solid() {
  translate([0,0,z_flange_center])
    rounded_box([flange_W, flange_H, flange_t], r=chamfer_r, center=true);
}

module inlet_body_outer() {
  body_W = cutout_W - 2*body_clearance;
  body_H = cutout_H - 2*body_clearance;

  translate([0,0,z_body_center])
    rounded_box([body_W, body_H, body_depth], r=chamfer_r, center=true);
}

module inlet_body_inner_void() {
  // Hollow from the rear, leaving walls and leaving the front face intact
  body_W = cutout_W - 2*body_clearance;
  body_H = cutout_H - 2*body_clearance;

  inner_W = body_W - 2*body_wall_t;
  inner_H = body_H - 2*body_wall_t;
  inner_D = body_depth - body_wall_t;

  // Start the void slightly behind the body front so the front face remains solid
  // (and so the IEC recess/pin cutouts have material around them).
  z_void_center = (z_body_front + body_wall_t) + inner_D/2;

  translate([0,0,z_void_center])
    cube([inner_W, inner_H, inner_D], center=true);
}

module rear_terminal_block() {
  translate([0,0,z_term_center])
    rounded_box([terminal_block_W, terminal_block_H, terminal_block_depth], r=chamfer_r, center=true);
}

module retention_clips() {
  // Side ears connected to body sides
  body_W = cutout_W - 2*body_clearance;

  xL = -(body_W/2 + clip_W/2 - overlap);
  xR = +(body_W/2 + clip_W/2 - overlap);

  // Put clips near the front, overlapping into the body
  zC = z_body_front + clip_L/2;

  union() {
    translate([xL, 0, zC]) cube([clip_W, clip_T, clip_L], center=true);
    translate([xR, 0, zC]) cube([clip_W, clip_T, clip_L], center=true);
  }
}

module terminal_spades() {
  union() {
    translate([-spade_spacing_X/2,  spade_spacing_Y/2, z_spade_center])
      cube([spade_W, spade_T, spade_L], center=true); // L
    translate([ spade_spacing_X/2,  spade_spacing_Y/2, z_spade_center])
      cube([spade_W, spade_T, spade_L], center=true); // N
    translate([ 0,                -spade_spacing_Y/2, z_spade_center])
      cube([spade_W, spade_T, spade_L], center=true); // G
  }
}

// -------------------- Negative geometry (cutouts) --------------------
module panel_cutout_envelope() {
  // Thin gauge at the front, overlapping the flange so it stays connected
  gauge_t = 0.8;
  translate([0,0,gauge_t/2 - overlap/2])
    cube([cutout_W, cutout_H, gauge_t + overlap], center=true);
}

module flange_opening_void() {
  // Through-hole in flange matching panel cutout
  translate([0,0,z_flange_center])
    cube([cutout_W, cutout_H, flange_t + 2*overlap], center=true);
}

module mounting_screw_holes_void() {
  h = flange_t + 2*overlap;
  translate([-screw_hole_spacing_W/2, screw_hole_offset_Y, z_flange_center]) screw_hole_cyl(h);
  translate([ screw_hole_spacing_W/2, screw_hole_offset_Y, z_flange_center]) screw_hole_cyl(h);
}

module front_bezel_recess_void() {
  // Shallow rectangular recess around the cavity to mimic the IEC face bezel
  bezel_W = 32.0;
  bezel_H = 22.0;
  bezel_d = 1.2;

  translate([0,0,bezel_d/2])
    cube([bezel_W, bezel_H, bezel_d], center=true);
}

module iec_front_cavity_void() {
  // Trapezoidal recess cut from the very front (z=0) into the body
  translate([0,0,iec_cavity_depth/2])
    linear_extrude(height=iec_cavity_depth, center=true, convexity=10)
      polygon(points=[
        [-iec_cavity_bot_W/2, -iec_cavity_H/2],
        [ iec_cavity_bot_W/2, -iec_cavity_H/2],
        [ iec_cavity_top_W/2,  iec_cavity_H/2],
        [-iec_cavity_top_W/2,  iec_cavity_H/2]
      ]);
}

module iec_pin_holes_void() {
  // Three rectangular pin slots cut deeper than the cavity
  translate([0,0,pin_hole_depth/2]) union() {
    translate([-pin_pitch_X/2, pin_row_Y, 0])
      cube([pin_hole_W, pin_hole_H, pin_hole_depth], center=true);
    translate([ pin_pitch_X/2, pin_row_Y, 0])
      cube([pin_hole_W, pin_hole_H, pin_hole_depth], center=true);
    translate([0, pin_gnd_Y, 0])
      cube([pin_hole_W, pin_hole_H, pin_hole_depth], center=true);
  }
}

module iec_key_notches_void() {
  // Small square notches near the top corners of the cavity area (visual IEC cue)
  // Positioned relative to the cavity top width and height.
  x_off = iec_cavity_top_W/2 - key_notch_W/2;
  y_off = iec_cavity_H/2 - key_notch_H/2;

  translate([0,0,key_notch_depth/2]) union() {
    translate([ x_off, y_off, 0]) cube([key_notch_W, key_notch_H, key_notch_depth], center=true);
    translate([-x_off, y_off, 0]) cube([key_notch_W, key_notch_H, key_notch_depth], center=true);
  }
}

// -------------------- Assembly --------------------
module main_solid() {
  union() {
    front_flange_solid();
    inlet_body_outer();
    rear_terminal_block();
    retention_clips();
    terminal_spades();

    // Connected gauge for the 40x27 cutout reference
    panel_cutout_envelope();
  }
}

module complete_model() {
  difference() {
    main_solid();

    // Flange opening + screw holes
    flange_opening_void();
    mounting_screw_holes_void();

    // Hollow the body from the rear
    inlet_body_inner_void();

    // IEC C14 recognizable front details
    front_bezel_recess_void();
    iec_front_cavity_void();
    iec_pin_holes_void();
    iec_key_notches_void();
  }
}

// Final Output
complete_model();

// IEC lugless connector (approximate IEC C14 inlet style) - single connected solid
// Fixes: recognizable IEC C14-ish mating face (keyed opening + 3 slots),
// lugless termination (no external lugs; rear cable stub only),
// all parts connected with formula-based placement + overlap.

$fn = 72;

// ---------- Parameters ----------
body_L = 50; //[25:100:1]
body_W = 28; //[14:56:1]
body_H = 22; //[11:44:1]

wall_t = 2.5; //[1.25:5:0.1]

mating_opening_W = 22; //[11:44:0.5]
mating_opening_H = 16; //[8:32:0.5]
mating_opening_depth = 12; //[6:24:0.5]

flange_W = 32; //[16:64:1]
flange_t = 3; //[1.5:6:0.1]

mount_hole_d = 3.5; //[2:7:0.1]
mount_hole_spacing = 48; //[24:96:1]

rear_entry_d = 10; //[5:20:0.5]
rear_entry_L = 12; //[6:24:1]

overlap = 1.2; //[0.5:2:0.1]
label_recess_depth = 0.8; //[0.4:1.6:0.1]

// IEC-ish face details
face_bezel_t = max(2, wall_t);
face_bezel_margin = max(2, wall_t*0.8);
nose_L = max(7, wall_t*2.4);
nose_W = min(body_W*0.94, mating_opening_W + 2*face_bezel_margin + 2);
nose_H = min(body_H*0.94, mating_opening_H + 2*face_bezel_margin + 2);

// Panel-mount "ears" (lugless: no solder lugs; panel ears/feet are common)
ear_t = max(2.2, flange_t);          // thickness along X
ear_W = max(6, wall_t*3.0);          // width along Y
ear_H = max(4, wall_t*2.0);          // height along Z
ear_y_inset = max(1.0, wall_t*0.4);  // keep ears within flange width

// Face chamfer / wedge to resemble IEC standardized profile
chamfer_L = max(3.5, wall_t*1.6);    // length of chamfer region along X
chamfer_drop = max(1.2, wall_t*0.6); // how much top/bottom taper in Z

// Internal contact slots (C14 inlet: 2 blades + ground)
pin_slot_W = 6; //[3:12:0.5]
pin_slot_H = 3; //[1.5:6:0.5]
pin_slot_depth = 10; //[5:20:0.5]
pin_slot_spacing = 10; //[6:16:0.5]

ground_slot_W = 6; //[3:12:0.5]
ground_slot_H = 4; //[2:8:0.5]

// Keying notch to make the mating opening look more IEC-like (simplified)
key_notch_W = max(6, mating_opening_W*0.35);
key_notch_H = max(3, mating_opening_H*0.28);

// Rounding
corner_r = min(2.5, min(body_W, body_H)*0.12);

// ---------- Helpers ----------
module rounded_box(L, W, H, r) {
    r2 = min(r, min(W, H)/2 - 0.01);
    hull() {
        for (sy = [-1, 1], sz = [-1, 1])
            translate([0, sy*(W/2 - r2), sz*(H/2 - r2)])
                rotate([0, 90, 0]) cylinder(r=r2, h=L, center=true);
    }
}

module wedge_chamfer(L, W, H, drop) {
    polyhedron(
        points=[
            [-L/2, -W/2, -H/2],
            [-L/2,  W/2, -H/2],
            [-L/2,  W/2,  H/2],
            [-L/2, -W/2,  H/2],

            [ L/2, -W/2, -H/2 + drop],
            [ L/2,  W/2, -H/2 + drop],
            [ L/2,  W/2,  H/2 - drop],
            [ L/2, -W/2,  H/2 - drop]
        ],
        faces=[
            [0,1,2,3],
            [4,7,6,5],
            [0,4,5,1],
            [1,5,6,2],
            [2,6,7,3],
            [3,7,4,0]
        ]
    );
}

// ---------- Base solids ----------
module main_body() {
    rounded_box(body_L, body_W, body_H, corner_r);
}

module panel_flange() {
    // Flange centered on mating face plane (x = -body_L/2)
    translate([-(body_L/2 + flange_t/2 - overlap), 0, 0])
        rounded_box(flange_t, flange_W, body_H, min(corner_r, 2));
}

module panel_ears() {
    // Two small ears on top/bottom edges of flange to resemble IEC panel-mount outline
    x = -(body_L/2 + ear_t/2 - overlap);
    y = (flange_W/2 - ear_W/2 - ear_y_inset);
    z = (body_H/2 - ear_H/2);

    for (sz = [-1, 1]) {
        translate([x,  y, sz*z]) rounded_box(ear_t, ear_W, ear_H, min(1.2, corner_r));
        translate([x, -y, sz*z]) rounded_box(ear_t, ear_W, ear_H, min(1.2, corner_r));
    }
}

module front_nose() {
    // Protruding nose on mating side to resemble IEC interface housing
    translate([-(body_L/2 + nose_L/2 - overlap), 0, 0])
        rounded_box(nose_L, nose_W, nose_H, min(corner_r, 2));
}

module rear_strain_relief() {
    // Cable entry stub on rear side (x = +body_L/2) - connected with overlap
    translate([(body_L/2 + rear_entry_L/2 - overlap), 0, 0])
        rotate([0, 90, 0])
            cylinder(r=rear_entry_d/2, h=rear_entry_L, center=true);
}

// ---------- Cuts / details ----------
module mating_opening_cut() {
    // Main rectangular opening starts at the mating face and goes inward
    translate([-(body_L/2) + mating_opening_depth/2 - overlap, 0, 0])
        cube([mating_opening_depth + 2*overlap, mating_opening_W, mating_opening_H], center=true);

    // Keying notch (simplified) to make it read as IEC-style face geometry
    // Notch at top center of opening
    notch_z = (mating_opening_H/2 - key_notch_H/2);
    translate([-(body_L/2) + (mating_opening_depth*0.55)/2 - overlap, 0, notch_z])
        cube([mating_opening_depth*0.55 + 2*overlap, key_notch_W, key_notch_H], center=true);
}

module face_bezel_relief_cut() {
    // Shallow recess around the opening on the nose to suggest a bezel
    pocket_t = min(face_bezel_t, nose_L*0.85);
    // Place pocket so it starts at the very front of the nose and goes inward
    x_front_nose = -(body_L/2 + nose_L) + overlap;
    x_center = x_front_nose + pocket_t/2;
    translate([x_center, 0, 0])
        cube([pocket_t + 2*overlap,
              mating_opening_W + 2*face_bezel_margin,
              mating_opening_H + 2*face_bezel_margin], center=true);
}

module face_chamfers_cut() {
    // Subtract top/bottom wedges near the very front to mimic IEC face profile
    x_front = -(body_L/2 + nose_L) + overlap;
    x_center = x_front + chamfer_L/2;

    translate([x_center, 0, (nose_H/2 - chamfer_drop/2)])
        wedge_chamfer(chamfer_L + 2*overlap, nose_W + 2*overlap, chamfer_drop*2 + 2*overlap, chamfer_drop);

    translate([x_center, 0, -(nose_H/2 - chamfer_drop/2)])
        wedge_chamfer(chamfer_L + 2*overlap, nose_W + 2*overlap, chamfer_drop*2 + 2*overlap, chamfer_drop);
}

module mounting_holes_cut() {
    // Two holes through flange thickness (along X)
    x0 = -(body_L/2 + flange_t/2 - overlap);
    for (sy = [-1, 1]) {
        translate([x0, sy*(mount_hole_spacing/2), 0])
            rotate([0, 90, 0])
                cylinder(r=mount_hole_d/2, h=flange_t + 4*overlap, center=true);
    }
}

module label_recess_cut() {
    // Shallow recess on top surface
    translate([0, 0, (body_H/2 - label_recess_depth/2 + overlap)])
        cube([body_L*0.35, body_W*0.6, label_recess_depth + 2*overlap], center=true);
}

module internal_slots_cut() {
    // Approximate IEC C14 inlet: two blade slots + ground slot
    // Place slots near the front, inside the opening volume.
    x = -(body_L/2) + wall_t + pin_slot_depth/2;

    // Blade slots (left/right)
    translate([x, -(pin_slot_spacing/2), 0])
        cube([pin_slot_depth + 2*overlap, pin_slot_W, pin_slot_H], center=true);
    translate([x,  (pin_slot_spacing/2), 0])
        cube([pin_slot_depth + 2*overlap, pin_slot_W, pin_slot_H], center=true);

    // Ground slot (upper center for C14 inlet look)
    z = (mating_opening_H/2) - ground_slot_H/2 - wall_t*0.25;
    translate([x, 0, z])
        cube([pin_slot_depth + 2*overlap, ground_slot_W, ground_slot_H], center=true);
}

module inner_cavity_cut() {
    // Hollow out behind the opening to avoid a solid block and better match connector shell
    cav_L = max(10, body_L - (wall_t*2 + 6));
    cav_W = max(6, body_W - 2*wall_t);
    cav_H = max(6, body_H - 2*wall_t);

    // Start cavity behind the opening depth to preserve face strength
    x_start = -(body_L/2) + mating_opening_depth + wall_t;
    // Ensure cavity stays within body length
    x_end_limit = (body_L/2) - wall_t;
    cav_L_eff = min(cav_L, max(6, x_end_limit - x_start));
    x_center = x_start + cav_L_eff/2;

    translate([x_center, 0, 0])
        rounded_box(cav_L_eff + 2*overlap, cav_W, cav_H, max(0.8, corner_r*0.6));
}

// ---------- Final model ----------
module iec_lugless_connector() {
    difference() {
        union() {
            // One connected solid: body + flange + ears + nose + rear cable stub
            main_body();
            panel_flange();
            panel_ears();
            front_nose();
            rear_strain_relief();
        }

        // IEC face opening + details (recognizable C14-ish)
        mating_opening_cut();
        face_bezel_relief_cut();
        face_chamfers_cut();

        // Internal features
        internal_slots_cut();
        inner_cavity_cut();

        // Mounting + cosmetic
        mounting_holes_cut();
        label_recess_cut();
    }
}

iec_lugless_connector();

$fn = 96;

// =====================
// Parameters (mm)
// =====================
flange_W = 40.0;          // overall flange width (X)
flange_H = 32.0;          // overall flange height (Y)
flange_t = 2.5;           // flange thickness (Z)

body_W   = 28.0;          // rear body width
body_H   = 20.0;          // rear body height
body_D   = 30.0;          // rear body depth (behind flange)

cutout_W = 30.0;          // IEC mouth width (opening)
cutout_H = 22.0;          // IEC mouth height (opening)

corner_r = 1.5;           // rounding radius for flange outline (2D)

mount_hole_d        = 3.2;
mount_hole_pitch_W  = 34.0;
mount_hole_pitch_H  = 26.0;

terminal_block_W = 24.0;
terminal_block_H = 16.0;
terminal_block_D = 12.0;

wire_clearance_D = 15.0;

overlap = 1.2;            // overlap to guarantee connectivity/robust booleans (1–2mm)

// IEC C14-ish front geometry (approx)
bezel_recess_t = 1.2;     // shallow recess on front face
bezel_margin   = 2.0;     // recess larger than opening by this margin
inner_step_t   = 2.0;     // deeper step behind recess
inner_step_m   = 0.8;     // step slightly larger than opening

// IEC "pin" features (simplified) - make it recognizable
pin_w = 4.2;
pin_h = 6.0;
pin_pitch_x = 10.0;
pin_pitch_y = 7.5;
pin_depth = 6.0;          // how far pins protrude into the socket cavity

// Rear terminals (spade tabs) - simplified but recognizable
tab_w = 6.3;
tab_t = 0.8;
tab_L = 10.0;
tab_pitch_x = 10.0;
tab_pitch_y = 8.0;

// Side retention bumps (instead of floating clips)
clip_bump_W = 3.0;
clip_bump_H = 8.0;
clip_bump_L = 8.0;

// Cosmetic screw heads on front
screw_head_d = 6.5;
screw_head_h = 2.0;

// =====================
// Helpers
// =====================
module rounded_rect_2d(w, h, r) {
  r2 = min(r, min(w, h)/2);
  offset(r=r2) square([w-2*r2, h-2*r2], center=true);
}

module rounded_box(w, h, d, r) {
  linear_extrude(height=d, center=true)
    rounded_rect_2d(w, h, r);
}

// =====================
// Feature modules
// =====================
module flange_solid() {
  rounded_box(flange_W, flange_H, flange_t, corner_r);
}

module body_solid() {
  // Body sits behind flange (positive Z), overlaps into flange by 'overlap'
  translate([0, 0, flange_t/2 + body_D/2 - overlap])
    rounded_box(body_W, body_H, body_D, max(0.6, corner_r*0.6));
}

module terminal_block_solid() {
  // Terminal block behind body, overlaps into body
  translate([0, 0, flange_t/2 + body_D + terminal_block_D/2 - 2*overlap])
    rounded_box(terminal_block_W, terminal_block_H, terminal_block_D, 0.8);
}

module strain_relief_solid() {
  // Clearance envelope behind terminal block, overlaps into terminal block
  translate([0, 0,
    flange_t/2 + body_D + terminal_block_D + wire_clearance_D/2 - 3*overlap
  ])
    rounded_box(terminal_block_W, terminal_block_H, wire_clearance_D, 0.8);
}

module side_clip_bumps_solid() {
  // Small bumps on the sides of the rear body near the flange (connected)
  zc = flange_t/2 + clip_bump_L/2 - overlap;
  xL = -body_W/2 - clip_bump_W/2 + overlap;
  xR =  body_W/2 + clip_bump_W/2 - overlap;

  union() {
    translate([xL, 0, zc]) rounded_box(clip_bump_W, clip_bump_H, clip_bump_L, 0.6);
    translate([xR, 0, zc]) rounded_box(clip_bump_W, clip_bump_H, clip_bump_L, 0.6);
  }
}

module spade_tabs_solid() {
  // Three rear spade tabs, attached to the terminal block rear face
  // Place so their front overlaps into terminal block by 'overlap'
  z_term_center = flange_t/2 + body_D + terminal_block_D/2 - 2*overlap;
  z_term_back   = z_term_center + terminal_block_D/2; // back face plane
  zc = z_term_back + tab_L/2 - overlap;

  module tab_at(x,y){
    translate([x, y, zc])
      cube([tab_w, tab_t, tab_L], center=true);
  }

  union() {
    tab_at( tab_pitch_x/2,  tab_pitch_y/2);
    tab_at(-tab_pitch_x/2,  tab_pitch_y/2);
    tab_at(0,              -tab_pitch_y/2);
  }
}

module screw_heads_solid() {
  // Cosmetic screw heads on front face; overlap into flange
  zc = -flange_t/2 - screw_head_h/2 + overlap;
  union() {
    translate([ mount_hole_pitch_W/2,  mount_hole_pitch_H/2, zc]) cylinder(h=screw_head_h, r=screw_head_d/2, center=true);
    translate([-mount_hole_pitch_W/2,  mount_hole_pitch_H/2, zc]) cylinder(h=screw_head_h, r=screw_head_d/2, center=true);
    translate([ mount_hole_pitch_W/2, -mount_hole_pitch_H/2, zc]) cylinder(h=screw_head_h, r=screw_head_d/2, center=true);
    translate([-mount_hole_pitch_W/2, -mount_hole_pitch_H/2, zc]) cylinder(h=screw_head_h, r=screw_head_d/2, center=true);
  }
}

module mounting_holes_cut() {
  // Through flange (and slightly beyond) for robust subtraction
  h = flange_t + 4*overlap;
  union() {
    translate([ mount_hole_pitch_W/2,  mount_hole_pitch_H/2, 0]) cylinder(h=h, r=mount_hole_d/2, center=true);
    translate([-mount_hole_pitch_W/2,  mount_hole_pitch_H/2, 0]) cylinder(h=h, r=mount_hole_d/2, center=true);
    translate([ mount_hole_pitch_W/2, -mount_hole_pitch_H/2, 0]) cylinder(h=h, r=mount_hole_d/2, center=true);
    translate([-mount_hole_pitch_W/2, -mount_hole_pitch_H/2, 0]) cylinder(h=h, r=mount_hole_d/2, center=true);
  }
}

// ---------------------
// IEC inlet face geometry (recognizable C14-ish)
// ---------------------
module iec_front_recess_cut() {
  // Shallow recess on the front face
  w = cutout_W + 2*bezel_margin;
  h = cutout_H + 2*bezel_margin;
  d = bezel_recess_t + 2*overlap;

  // Center so it opens on the front face (negative Z side)
  zc = -flange_t/2 + bezel_recess_t/2 - overlap;
  translate([0, 0, zc])
    rounded_box(w, h, d, 1.6);
}

module iec_inner_step_cut() {
  // Deeper step behind the recess (within flange thickness and slightly into body)
  w = cutout_W + 2*inner_step_m;
  h = cutout_H + 2*inner_step_m;
  d = inner_step_t + 2*overlap;

  z_front = -flange_t/2 + bezel_recess_t; // start after recess
  zc = z_front + inner_step_t/2 - overlap;
  translate([0, 0, zc])
    rounded_box(w, h, d, 1.2);
}

module socket_opening_cut() {
  // Main through opening into the body (C14-ish mouth)
  cut_depth = flange_t + body_D*0.85;
  zc = -flange_t/2 + cut_depth/2 - overlap;
  translate([0, 0, zc])
    rounded_box(cutout_W, cutout_H, cut_depth + 2*overlap, 1.0);
}

module iec_pins_solid() {
  // Three simplified "pins" inside the socket cavity.
  // FIX: ensure pins are physically connected to the surrounding solid (not floating in the void).
  // We anchor them to the *back wall* of the socket cutout by extending them slightly beyond it.
  cut_depth = flange_t + body_D*0.85;
  z_cut_front = -flange_t/2 - overlap;          // where the cut starts (approx)
  z_cut_back  = z_cut_front + cut_depth + 2*overlap; // where the cut ends (approx)

  // Place pins near the back of the cavity and make them longer so they intersect the body.
  pin_attach = 2.0; // extra length to bite into the body (>= overlap)
  pin_d = pin_depth + pin_attach;

  // Center so the rear of the pin extends into solid beyond the cut's back plane
  zc = (z_cut_back - pin_d/2) + overlap;

  module pin_at(x,y){
    translate([x, y, zc])
      rounded_box(pin_w, pin_h, pin_d, 0.6);
  }

  union() {
    pin_at( pin_pitch_x/2,  pin_pitch_y/2);
    pin_at(-pin_pitch_x/2,  pin_pitch_y/2);
    pin_at(0,              -pin_pitch_y/2);
  }
}

// =====================
// Complete model (ONE connected solid)
// =====================
module complete_model() {
  difference() {
    union() {
      flange_solid();
      body_solid();
      terminal_block_solid();
      strain_relief_solid();
      side_clip_bumps_solid();
      spade_tabs_solid();
      screw_heads_solid();

      // IEC recognizable internal features (now guaranteed to connect to body)
      iec_pins_solid();
    }

    mounting_holes_cut();

    // IEC inlet front geometry
    iec_front_recess_cut();
    iec_inner_step_cut();
    socket_opening_cut();
  }
}

// Final output
complete_model();

// IEC power inlet module (IEC inlet filtered), panel cutout 40.0mm x 29.0mm
// One connected solid with recognizable IEC C14 inlet geometry (beveled mouth + key notch),
// pin cavities, rear filter can, flange, and snap tabs. All placements are formula-based.

$fn = 72;

// -------------------- Parameters --------------------
cutout_W = 40.0;          // panel cutout width (X)
cutout_H = 29.0;          // panel cutout height (Y)

flange_W = 50.0;
flange_H = 35.0;
flange_t = 2.5;

body_D = 34.0;            // depth behind panel
body_W = cutout_W + 2.0;  // slightly larger than cutout
body_H = cutout_H + 2.0;

front_face_t = 3.0;       // thickness of front "nose" region

// IEC C14-ish opening (visual, not a certified profile)
iec_open_W = 27.5;
iec_open_H = 19.5;
iec_corner_r = 2.0;

// Key notch (top center) typical of IEC inlets (visual)
key_notch_W = 7.0;
key_notch_H = 2.2;

// Bevel / funnel depth for inlet mouth
mouth_depth = 3.0;

// Pin cavity details (visual)
pin_r = 1.25;
pin_cav_d = 11.0;
pin_spacing = 10.0;
pin_row_y = -iec_open_H * 0.18;
ground_pin_y =  iec_open_H * 0.22;

// Rear filter can (visual)
filter_can_D = 20.0;
filter_can_W = body_W - 4.0;
filter_can_H = body_H - 4.0;

// Strain relief (visual)
strain_relief_r = 6.0;
strain_relief_L = 10.0;

// Snap tabs (visual)
snap_tab_overhang = 1.2;  // how far tab protrudes beyond body side
snap_tab_t = 1.6;
snap_tab_L = 9.0;

// Rounding
bezel_corner_r = 2.2;

// Robustness
eps = 0.01;
overlap = 0.8; // intentional overlap to guarantee connectivity

// -------------------- Helpers --------------------
module rounded_rect_2d(w, h, r) {
  r2 = min(r, min(w, h)/2 - eps);
  hull() {
    for (sx = [-1, 1], sy = [-1, 1])
      translate([sx*(w/2 - r2), sy*(h/2 - r2)]) circle(r=r2);
  }
}

module rounded_box(w, h, d, r, center=true) {
  linear_extrude(height=d, center=center)
    rounded_rect_2d(w, h, r);
}

module iec_open_2d(w, h, r) {
  // Base rounded rectangle with a small top-center key notch removed
  difference() {
    rounded_rect_2d(w, h, r);
    translate([0, h/2 - key_notch_H/2 + eps])
      square([key_notch_W, key_notch_H + 2*eps], center=true);
  }
}

// Coordinate convention:
// Front face at z = 0, positive z goes outward (front), negative z goes rearward (inside equipment).
// Flange spans z in [0, flange_t]. Main body spans z in [-body_D, 0].

// -------------------- Main solids --------------------
module front_flange() {
  translate([0, 0, flange_t/2])
    rounded_box(flange_W, flange_H, flange_t, bezel_corner_r, center=true);
}

module main_body() {
  // Touch flange at z=0 with overlap
  translate([0, 0, -body_D/2 + overlap/2])
    rounded_box(body_W, body_H, body_D + overlap, bezel_corner_r, center=true);
}

module rear_filter_can() {
  // Attached to rear of main body (rear face at z = -body_D)
  translate([0, 0, -body_D - filter_can_D/2 + overlap/2])
    rounded_box(filter_can_W, filter_can_H, filter_can_D + overlap, bezel_corner_r, center=true);
}

module strain_relief() {
  // Attached to rear of filter can (rear face at z = -body_D - filter_can_D)
  translate([0, 0, -body_D - filter_can_D - strain_relief_L/2 + overlap/2])
    cylinder(r=strain_relief_r, h=strain_relief_L + overlap, center=true);
}

module snap_tab(side=1) {
  // side = -1 (left), +1 (right)
  tab_w = snap_tab_t;
  tab_h = cutout_H * 0.42;
  tab_d = snap_tab_L;

  // Place so it overlaps body side and protrudes outward by snap_tab_overhang
  x = side*(body_W/2 + tab_w/2 - snap_tab_overhang);
  z = -(tab_d/2) + overlap/2; // near front, extends rearward
  translate([x, 0, z])
    cube([tab_w + overlap, tab_h, tab_d + overlap], center=true);
}

module snap_tabs() {
  union() {
    snap_tab(-1);
    snap_tab( 1);
  }
}

// -------------------- Cutouts (subtractions) --------------------
module iec_mouth_funnel() {
  // Beveled mouth: larger at the very front, tapering to the nominal opening
  // Implemented as a hull between two 2D profiles extruded at different Z.
  // Cuts through flange and into the front face region.
  z0 = -eps;                 // start at very front
  z1 = mouth_depth;          // into the part (positive z is outward, but flange is at z>0)
  // Our solid exists from z=0..flange_t (flange) and z<=0 (body).
  // So we cut from z=0 into negative z. We'll build the funnel in that direction.
  // Use z positions: 0 down to -mouth_depth.
  z_front = 0 + eps;
  z_back  = -mouth_depth;

  scale_front = 1.10;        // slightly larger at the very front
  scale_back  = 1.00;

  hull() {
    translate([0, 0, z_front])
      linear_extrude(height=eps, center=false)
        scale([scale_front, scale_front])
          iec_open_2d(iec_open_W, iec_open_H, iec_corner_r);

    translate([0, 0, z_back])
      linear_extrude(height=eps, center=false)
        scale([scale_back, scale_back])
          iec_open_2d(iec_open_W, iec_open_H, iec_corner_r);
  }
}

module iec_through_opening() {
  // Continue the nominal opening through flange and into body
  cut_d = flange_t + front_face_t + 10; // ensure it reaches into body
  // Start at front of flange and cut rearward (negative z)
  translate([0, 0, flange_t + eps])  // start just behind flange front
    rotate([180, 0, 0])              // extrude "down" in -Z
      linear_extrude(height=cut_d, center=false)
        iec_open_2d(iec_open_W, iec_open_H, iec_corner_r);
}

module iec_pin_cavities() {
  // Cylindrical cavities behind the opening (visual)
  zc = -(front_face_t + pin_cav_d/2); // behind front face
  union() {
    translate([-pin_spacing/2, pin_row_y, zc])
      cylinder(r=pin_r, h=pin_cav_d, center=true);
    translate([ pin_spacing/2, pin_row_y, zc])
      cylinder(r=pin_r, h=pin_cav_d, center=true);
    translate([0, ground_pin_y, zc])
      cylinder(r=pin_r, h=pin_cav_d, center=true);
  }
}

module inner_hollow() {
  // Hollow out the main body to avoid a solid block look (keeps shell)
  wall = 2.0;
  iw = max(1, body_W - 2*wall);
  ih = max(1, body_H - 2*wall);
  id = max(1, body_D - wall); // leave material at front
  // Keep front wall thickness ~wall by starting hollow behind z=0
  translate([0, 0, -id/2 - wall/2 + overlap/2])
    rounded_box(iw, ih, id + overlap, max(0.6, bezel_corner_r-0.9), center=true);
}

module rear_cable_passage() {
  // Small passage into strain relief area (visual)
  pass_r = max(2.5, strain_relief_r - 2.0);
  pass_d = filter_can_D + strain_relief_L + 2;
  zc = -body_D - filter_can_D - strain_relief_L/2;
  translate([0, 0, zc])
    cylinder(r=pass_r, h=pass_d, center=true);
}

// -------------------- Assembly --------------------
module iec_inlet_filtered_40x29() {
  difference() {
    union() {
      // Connected solids
      front_flange();
      main_body();
      rear_filter_can();
      strain_relief();
      snap_tabs();

      // Bridging rib to guarantee manifold connection between flange and body
      translate([0, 0, -overlap/2])
        cube([cutout_W, cutout_H, overlap], center=true);
    }

    // Subtractions for recognizable features
    iec_mouth_funnel();
    iec_through_opening();
    iec_pin_cavities();
    inner_hollow();
    rear_cable_passage();
  }
}

// Final output
iec_inlet_filtered_40x29();

// Threaded heat-set insert (simple cylinder)
// Spec: 4.0mm outer diameter, 4.6mm long, for M2.5 screws
// One connected solid, no flange/countersink head.

$fn = 128;

// --- Parameters (spec) ---
od = 4.0;                 // outer diameter (mm)
L  = 4.6;                 // length (mm)

// M2.5 internal thread (visual approximation)
thread_pitch = 0.45;      // M2.5 coarse pitch (mm)
minor_d = 2.05;           // approximate minor diameter / tap drill (mm)

// Small lead-in chamfers (not a head/flange)
end_chamfer = 0.15;       // mm (kept small to avoid "countersunk head" look)

// Visual thread controls
show_internal_thread = true;
thread_depth = 0.18;      // radial depth of visual thread (mm)
thread_profile_w = 0.22;  // thickness of visual thread ridge (mm)

// Robust boolean overlap
eps = 0.02;

// --- Helpers ---
function clamp(x,a,b) = min(max(x,a),b);

// Outer body: simple cylinder with tiny end chamfers
module outer_body() {
  ch = clamp(end_chamfer, 0, L/2 - eps);

  union() {
    // Main cylinder
    cylinder(h=L, r=od/2, center=true);

    // Tiny chamfer at top (subtract later via intersection-like add? easier: add small frustum)
    // Here we "shape" by adding frustums that do not exceed OD (no flange).
    if (ch > 0) {
      translate([0,0, L/2 - ch/2])
        cylinder(h=ch, r1=od/2 - ch, r2=od/2, center=true);
      translate([0,0,-L/2 + ch/2])
        cylinder(h=ch, r1=od/2, r2=od/2 - ch, center=true);
    }
  }
}

// Internal bore (minor diameter) through
module internal_bore() {
  cylinder(h=L + 2*eps, r=minor_d/2, center=true);
}

// Visual internal thread: subtract a helical ridge from the bore
module internal_thread_visual() {
  r_bore = minor_d/2;
  r_thread = max(0.01, r_bore - thread_depth);

  // Keep thread away from ends a bit
  z0 = -L/2 + end_chamfer + 0.10;
  z1 =  L/2 - end_chamfer - 0.10;
  th = max(0, z1 - z0);

  if (th > 0) {
    translate([0,0,z0])
      linear_extrude(
        height = th,
        twist  = -360 * (th / thread_pitch),
        slices = max(60, ceil(th / (thread_pitch/16)))
      )
        translate([r_thread, 0, 0])
          square([thread_profile_w, thread_profile_w], center=true);
  }
}

// Final model
difference() {
  outer_body();
  internal_bore();
  if (show_internal_thread) internal_thread_visual();
}

// Threaded heat-set insert (M3), OD=3.0mm, L=4.6mm
// One connected solid: cylindrical body with external knurl + internal helical thread (cut)

$fn = 128;

// ---------------- Parameters ----------------
od = 3.0;                       //[1.5:6.0:0.1]
L  = 4.6;                       //[2.3:9.2:0.1]

thread_nominal_d   = 3.0;       //[2.0:6.0:0.1]   // M3
thread_pitch       = 0.5;       //[0.25:1.0:0.05] // M3 coarse = 0.5
thread_minor_d     = 2.5;       //[1.5:5.0:0.05]  // approx internal minor diameter for M3
bore_depth         = 4.6;       //[2.3:9.2:0.1]

knurl_depth        = 0.20;      //[0.1:0.6:0.05]
knurl_pitch        = 0.60;      //[0.3:1.2:0.05]
knurl_tooth_width  = 0.25;      //[0.15:0.6:0.05]
knurl_band_margin  = 0.40;      //[0.2:1.0:0.05]

chamfer            = 0.25;      //[0.1:0.8:0.05]
lead_in_len        = 0.60;      //[0.3:1.5:0.05]
lead_in_rad_reduction = 0.12;  //[0.05:0.4:0.05]

thread_relief_len  = 0.50;      //[0.3:1.5:0.05]
thread_relief_extra_d = 0.25;  //[0.1:0.8:0.05]

end_mark_d         = 0.80;      //[0.4:1.6:0.05]
end_mark_depth     = 0.15;      //[0.05:0.4:0.05]

overlap            = 0.20;      //[0.05:1.0:0.05]

// ---------------- Derived ----------------
od_r      = od/2;
minor_r   = thread_minor_d/2;
major_r   = thread_nominal_d/2;

// ---------------- Helpers ----------------
module body_base() {
  // Solid outer body (connected), with slight lead-in tapers
  union() {
    cylinder(h=L, r=od_r, center=true);

    // lead-in tapers (OD reduction near ends), connected by overlap
    translate([0,0,  L/2 - lead_in_len/2])
      cylinder(h=lead_in_len + overlap, r1=od_r, r2=od_r - lead_in_rad_reduction, center=true);

    translate([0,0, -L/2 + lead_in_len/2])
      cylinder(h=lead_in_len + overlap, r1=od_r - lead_in_rad_reduction, r2=od_r, center=true);
  }
}

module end_chamfers_cut() {
  // Subtractive chamfers at both ends
  union() {
    translate([0,0,  L/2 - chamfer/2])
      cylinder(h=chamfer + 2*overlap, r1=od_r + overlap, r2=max(0.01, od_r - chamfer), center=true);

    translate([0,0, -L/2 + chamfer/2])
      cylinder(h=chamfer + 2*overlap, r1=max(0.01, od_r - chamfer), r2=od_r + overlap, center=true);
  }
}

module knurl_cutters() {
  // Subtractive vertical grooves around OD (serrations), within margins
  knurl_h = max(0.01, L - 2*knurl_band_margin);
  n = max(12, floor((PI*od)/knurl_pitch));

  for (i = [0:n-1]) {
    rotate([0,0, i*360/n])
      // place cutter so it bites into OD by knurl_depth
      translate([od_r - knurl_depth/2, 0, 0])
        cube([knurl_depth + 2*overlap, knurl_tooth_width, knurl_h + 2*overlap], center=true);
  }
}

module internal_bore_cut() {
  // Base bore at minor diameter (for M3 screw clearance of thread form)
  th_len = min(bore_depth, L);
  cylinder(h=th_len + 2*overlap, r=minor_r, center=true);
}

module thread_reliefs_cut() {
  // Slightly larger bore at both ends to relieve thread start/stop
  th_len = min(bore_depth, L);
  relief_r = (thread_minor_d + thread_relief_extra_d)/2;

  union() {
    translate([0,0,  th_len/2 - thread_relief_len/2])
      cylinder(h=thread_relief_len + 2*overlap, r=relief_r, center=true);

    translate([0,0, -th_len/2 + thread_relief_len/2])
      cylinder(h=thread_relief_len + 2*overlap, r=relief_r, center=true);
  }
}

module end_mark_dimple_cut() {
  translate([0,0, L/2 - end_mark_depth/2])
    cylinder(h=end_mark_depth + 2*overlap, r=end_mark_d/2, center=true);
}

// Internal helical thread cutter (triangular-ish profile) to make visible internal thread
module internal_thread_cut() {
  th_len = min(bore_depth, L);
  turns  = th_len / thread_pitch;

  // radial thread depth from major to minor
  thread_depth = max(0.10, major_r - minor_r);

  // Make a small triangular "tooth" that sweeps helically; subtract from bore
  // Positioned so its outermost point reaches major_r (thread crest), inner stays near minor_r.
  linear_extrude(
      height = th_len + 2*overlap,
      center = true,
      twist  = turns*360,
      slices = max(60, ceil(turns*120))
    )
    translate([minor_r + thread_depth*0.55, 0, 0])
      polygon(points=[
        [ thread_depth*0.55, 0 ],
        [-thread_depth*0.45,  thread_pitch*0.22],
        [-thread_depth*0.45, -thread_pitch*0.22]
      ]);
}

// ---------------- Assembly ----------------
module heat_set_insert() {
  difference() {
    // Solid body (single connected solid before cuts)
    body_base();

    // External knurl grooves
    knurl_cutters();

    // End chamfers
    end_chamfers_cut();

    // Internal features (bore + thread + reliefs)
    union() {
      internal_bore_cut();
      internal_thread_cut();
      thread_reliefs_cut();
    }

    // End marking dimple
    end_mark_dimple_cut();
  }
}

// ---------------- Output ----------------
color("Gold") heat_set_insert();

// Threaded heat-set insert (M4), 4.0mm OD, 6.3mm long
// One connected solid; cylindrical body with knurls; internal helical thread

$fn = 96;

// Parameters
od = 4.0;                     // outer diameter of main body
L = 6.3;                      // overall length
thread_nom_d = 4.0;           // M4 nominal
thread_pitch = 0.7;           // M4 coarse
bore_minor_d = 3.3;           // internal minor diameter (approx for M4)
thread_depth = (thread_nom_d - bore_minor_d)/2;

chamfer_len = 0.4;

flange_od = 4.8;
flange_thk = 0.6;

knurl_count = 12;
knurl_depth = 0.25;
knurl_axial_len = 4.6;
knurl_width = 0.6;
knurl_overlap = 0.6;

runout_len = 0.8;
runout_extra_d = 0.4;

mark_groove_depth = 0.15;
mark_groove_width = 0.4;
mark_groove_offset_from_top = 1.2;

eps = 0.02;

// ---------- Helpers ----------
module zcyl(h, r, center=true) { cylinder(h=h, r=r, center=center); }

module insert_outer_body() {
  // Main cylindrical body (excluding flange thickness)
  translate([0,0,-flange_thk/2])
    zcyl(h=L - flange_thk, r=od/2, center=true);
}

module installation_flange() {
  // Flange at top end
  translate([0,0,(L - flange_thk)/2])
    zcyl(h=flange_thk, r=flange_od/2, center=true);
}

module external_knurl_seed() {
  // Knurl tooth overlaps into body to ensure connectivity
  // Place tooth so its inner face is at (od/2 - knurl_overlap)
  translate([ (od/2 - knurl_overlap) + (knurl_depth + knurl_overlap)/2, 0, -flange_thk/2 ])
    cube([knurl_depth + knurl_overlap, knurl_width, knurl_axial_len], center=true);
}

module external_knurls() {
  for (i = [0:knurl_count-1])
    rotate([0,0,i*360/knurl_count])
      external_knurl_seed();
}

module surface_markings_groove() {
  // Shallow circumferential groove near top
  translate([0,0, L/2 - mark_groove_offset_from_top])
    difference() {
      zcyl(h=mark_groove_width, r=od/2 + eps, center=true);
      zcyl(h=mark_groove_width + 2*eps, r=od/2 - mark_groove_depth, center=true);
    }
}

// ---------- Internal features ----------
module lead_in_chamfer(zpos) {
  // Simple conical lead-in at each end of bore
  translate([0,0,zpos])
    cylinder(h=chamfer_len, r1=thread_nom_d/2, r2=bore_minor_d/2, center=true);
}

module internal_runout() {
  // Slightly larger unthreaded runout at bottom
  translate([0,0,-L/2 + runout_len/2])
    zcyl(h=runout_len + 2*eps, r=(bore_minor_d + runout_extra_d)/2, center=true);
}

module internal_thread(length) {
  // Helical thread approximation: subtract a twisted triangular "tooth" swept along Z
  // This creates visible internal threading suitable for rendering/printing.
  turns = length / thread_pitch;

  // Keep thread inside the insert wall
  r_root = bore_minor_d/2;
  r_crest = r_root + thread_depth;

  // 2D profile (in X-Y) placed at radius r_root; extruded with twist
  // Triangle points: root -> crest -> root (slightly offset in Y to give flank)
  profile = [
    [r_root, -thread_pitch*0.18],
    [r_crest, 0],
    [r_root,  thread_pitch*0.18]
  ];

  translate([0,0,-length/2])
    linear_extrude(height=length, twist=-360*turns, slices=max(ceil(turns*40), 60), convexity=10)
      polygon(profile);
}

module internal_bore_and_thread() {
  // Base bore (minor diameter) + thread cut + runout + chamfers
  union() {
    // Minor bore through
    zcyl(h=L + 2*eps, r=bore_minor_d/2, center=true);

    // Threaded region (avoid flange thickness and chamfers)
    thread_len = (L - flange_thk) - 2*chamfer_len;
    translate([0,0,-flange_thk/2])  // align with main body center
      internal_thread(thread_len);

    internal_runout();

    // Chamfers at both ends
    lead_in_chamfer( L/2 - chamfer_len/2);
    lead_in_chamfer(-L/2 + chamfer_len/2);
  }
}

// ---------- Final model ----------
module final_insert() {
  difference() {
    // Outer solid (connected)
    difference() {
      union() {
        insert_outer_body();
        installation_flange();
        external_knurls();
      }
      surface_markings_groove();
    }

    // Subtract internal bore + thread
    internal_bore_and_thread();
  }
}

