thread_pitch = 0.8;       // M5 coarse pitch (mm)

thread_class_allow = 0.15; // (mm) enlarge internal thread slightly for print/fit

// Lead-in / counterbore (optional)
counterbore_d = 5.6;      // (mm) small lead-in
counterbore_depth = 0.8;  // (mm)

// End chamfers
