        usable_h = length - 2*chamfer_height;
        n_rings  = max(1, floor((usable_h - knurl_ring_height)/knurl_pitch) + 1);
        z0       = -length/2 + chamfer_height + knurl_ring_height/2;

        for (i = [0:n_rings-1]) {
            zi = z0 + i*knurl_pitch;
            if (zi <= (length/2 - chamfer_height - knurl_ring_height/2 + 1e-9))
