      difference() {
        difference() {
          difference() {
            difference() {
              outer_cylinder_body();
              chamfer_or_lead_in_top();
              chamfer_or_lead_in_bottom();
            }
            lubrication_groove(-bearing_L/4);
            lubrication_groove(0);
            lubrication_groove(bearing_L/4);
