          retaining_ring_groove(bearing_L/2 - ret_groove_offset);
          retaining_ring_groove(-bearing_L/2 + ret_groove_offset);
        }
        through_bore();
      }
      ball_track_cutter(0);
      ball_track_cutter(90);
      ball_track_cutter(180);
      ball_track_cutter(270);
    }
    ball_cage_relief();
  }
}

