// Old unswitched mains socket (UK-style) — simplified but recognizable
// Single connected solid; all translate() values derived from dimensions

$fn = 64;

// ---------------- Parameters ----------------
plate_W = 86;
plate_H = 86;
plate_T = 3;

edge_bevel_inset = 2;
edge_bevel_drop  = 0.6;

// Shallow front dish (kept subtle so apertures remain visible)
recess_W = 62;
recess_H = 62;
recess_D = 0.9;

// Back housing (depth)
housing_W = 70;
housing_H = 70;
housing_D = 28;
housing_wall = 2.2;

// Socket cavity behind apertures (front-to-back)
cavity_W = 46;
cavity_H = 46;
cavity_D = 18;

// UK apertures (rectangular slots)
slot_w = 6.5;
slot_h = 14;
slot_depth = 12;

earth_w = 6.5;
earth_h = 10;
earth_depth = 12;

// Slot positions (UK: earth above, L/N below)
slot_x  = 12.7;
slot_y  = 9.5;
earth_y = 18;

// Mounting screws
screw_hole_d = 3.8;
screw_cbore_d = 7.5;
screw_cbore_depth = 1.2;
screw_hole_spacing = 60.3;

// Back-side screw bosses
boss_od = 10;
boss_id = 3.2;
boss_h  = 8;

// Raised front detailing (frame around apertures)
aperture_frame_T = 0.8;
aperture_frame_margin = 3.2;
aperture_frame_r = 2.0;

// Small overlap for robust booleans / unions
overlap = 1.2;

// ---------------- Helpers ----------------
module rounded_box(size=[10,10,10], r=1, center=true) {
  minkowski() {
    cube([max(0.01,size[0]-2*r), max(0.01,size[1]-2*r), max(0.01,size[2]-2*r)], center=center);
    sphere(r=r);
  }
}

module faceplate_beveled() {
  hull() {
    cube([plate_W, plate_H, plate_T], center=true);
    translate([0,0,edge_bevel_drop/2])
      cube([plate_W-2*edge_bevel_inset, plate_H-2*edge_bevel_inset, plate_T-edge_bevel_drop], center=true);
  }
}

module front_recess_cut() {
  // Cut from the front face inward
  translate([0,0, plate_T/2 - recess_D/2])
    cube([recess_W, recess_H, recess_D + overlap], center=true);
}

module housing_outer() {
  // Plate back face is at z = -plate_T/2
  // Housing front face slightly overlaps into plate by overlap
  // => housing center z = (-plate_T/2 + overlap) - housing_D/2
  zc = (-plate_T/2 + overlap) - housing_D/2;
  translate([0,0, zc])
    rounded_box([housing_W, housing_H, housing_D], r=2, center=true);
}

module housing_inner_cut() {
  // Hollow from the back, leaving a front wall thickness = housing_wall
  inner_W = housing_W - 2*housing_wall;
  inner_H = housing_H - 2*housing_wall;
  inner_D = housing_D - housing_wall;

  // housing front face = (-plate_T/2 + overlap)
  // inner front face = housing front - housing_wall
  inner_front = (-plate_T/2 + overlap) - housing_wall;
  zc = inner_front - inner_D/2;

  translate([0,0, zc])
    cube([inner_W, inner_H, inner_D + overlap], center=true);
}

module socket_cavity_cut() {
  // Cavity starts at the front face and goes inward
  translate([0,0, plate_T/2 - cavity_D/2])
    cube([cavity_W, cavity_H, cavity_D + overlap], center=true);
}

module slot_cut(pos=[0,0], w=6, h=14, d=10) {
  // Cut from the front face inward
  translate([pos[0], pos[1], plate_T/2 - d/2])
    cube([w, h, d + overlap], center=true);
}

module screw_counterbore_cut(ypos) {
  translate([0, ypos, plate_T/2 - screw_cbore_depth/2])
    cylinder(h=screw_cbore_depth + overlap, r=screw_cbore_d/2, center=true);
}

module boss_at(ypos) {
  // Place bosses just behind the housing inner front wall so they survive inner hollowing
  housing_front = (-plate_T/2 + overlap);
  inner_front   = housing_front - housing_wall;

  // Boss should be behind inner_front by a small amount, but still inside housing
  zc = inner_front - overlap - boss_h/2;

  translate([0, ypos, zc])
    difference() {
      cylinder(h=boss_h, r=boss_od/2, center=true);
      cylinder(h=boss_h + overlap, r=boss_id/2, center=true);
    }
}

module aperture_frame() {
  // Raised frame around the three apertures (front detailing)
  frame_W = 2*slot_x + slot_w + 2*aperture_frame_margin;
  frame_H = (earth_y + earth_h/2) - (-slot_y - slot_h/2) + 2*aperture_frame_margin;

  // Sit on the front face with slight overlap into plate
  zc = plate_T/2 + aperture_frame_T/2 - overlap/2;

  translate([0, 0, zc])
    difference() {
      rounded_box([frame_W, frame_H, aperture_frame_T], r=aperture_frame_r, center=true);
      rounded_box([frame_W - 2*aperture_frame_margin,
                   frame_H - 2*aperture_frame_margin,
                   aperture_frame_T + overlap],
                  r=max(0.5, aperture_frame_r-0.8), center=true);
    }
}

// ---------------- Build ----------------
module socket_solid() {
  union() {
    faceplate_beveled();
    housing_outer();

    // Raised frame (makes it read as a socket, not a rocker)
    aperture_frame();

    // Back bosses aligned with screw holes
    boss_at( screw_hole_spacing/2);
    boss_at(-screw_hole_spacing/2);
  }
}

module socket_model() {
  difference() {
    socket_solid();

    // Shallow front recess (dish)
    front_recess_cut();

    // Hollow housing from back (keeps walls)
    housing_inner_cut();

    // Socket cavity behind apertures
    socket_cavity_cut();

    // UK apertures: L/N vertical slots, earth vertical slot above
    slot_cut([ -slot_x, -slot_y], slot_w, slot_h, slot_depth);
    slot_cut([  slot_x, -slot_y], slot_w, slot_h, slot_depth);
    slot_cut([0, earth_y], earth_w, earth_h, earth_depth);

    // Mounting screw holes through + shallow counterbore on front
    translate([0,  screw_hole_spacing/2, 0])
      cylinder(h=plate_T + housing_D + 2*overlap, r=screw_hole_d/2, center=true);
    translate([0, -screw_hole_spacing/2, 0])
      cylinder(h=plate_T + housing_D + 2*overlap, r=screw_hole_d/2, center=true);

    screw_counterbore_cut( screw_hole_spacing/2);
    screw_counterbore_cut(-screw_hole_spacing/2);
  }
}

// Final
color("Silver") socket_model();

$fn = 96;

// -------------------- Parameters --------------------
plate_W = 146; //[73:292:1]
plate_H = 86;  //[43:172:1]
plate_T = 3;   //[1.5:6:0.1]
plate_corner_R = 6; //[3:12:0.5]

socket_recess_W = 70; //[35:140:1]
socket_recess_H = 55; //[27.5:110:1]
socket_recess_D = 1.5; //[0.5:3:0.1]
recess_corner_R = 4; //[2:8:0.5]
socket_recess_offset_x = -20; //[-40:0:1]
socket_recess_offset_y = 0;   //[-20:20:1]

switch_W = 24; //[12:48:1]
switch_H = 34; //[17:68:1]
switch_T = 4;  //[2:8:0.1]
switch_offset_x = 50; //[0:80:1]
switch_offset_y = 0;  //[-20:20:1]
switch_aperture_clearance = 1; //[0.5:2:0.1]

indicator_W = 6;  //[3:12:0.5]
indicator_H = 12; //[6:24:0.5]
indicator_inset_from_top = 6; //[3:12:0.5]

screw_hole_d = 4.2; //[2.5:6:0.1]
screw_csk_d = 8.5;  //[6:12:0.1]
screw_csk_depth = 1.2; //[0.6:2.5:0.1]
screw_hole_spacing = 120; //[60:160:1]
screw_hole_offset_y = 0; //[-20:20:1]

backbox_W = 120; //[60:180:1]
backbox_H = 70;  //[35:120:1]
backbox_D = 25;  //[12:50:1]

overlap = 1; //[0.5:2:0.1]

// UK socket aperture (stylised)
pin_bot_w = 7;
pin_bot_h = 16;
pin_spacing_x = 22;
pin_offset_y = -2;

earth_w = 8;
earth_h = 18;
earth_offset_y = 14;

// Ensure apertures actually cut through the front face (and a bit beyond)
aperture_depth = plate_T + 2*overlap;

// Socket outline (raised bezel) inside recess
socket_bezel_inset = 4; //[2:8:0.5]
socket_bezel_h = 0.8;   //[0.4:1.6:0.1]

// Optional subtle emboss around apertures (kept simple)
aperture_bezel_h = 0.6;
aperture_bezel_r = 1.2;

// -------------------- Helpers --------------------
module rounded_rect_2d(w,h,r){
  r2 = min(r, min(w,h)/2);
  hull(){
    translate([ w/2-r2,  h/2-r2]) circle(r=r2);
    translate([-w/2+r2,  h/2-r2]) circle(r=r2);
    translate([-w/2+r2, -h/2+r2]) circle(r=r2);
    translate([ w/2-r2, -h/2+r2]) circle(r=r2);
  }
}

module rounded_box(w,h,t,r,center=true){
  linear_extrude(height=t, center=center)
    rounded_rect_2d(w,h,r);
}

module faceplate(){
  rounded_box(plate_W, plate_H, plate_T, plate_corner_R, center=true);
}

module socket_recess_cut(){
  // Cut from the FRONT face downwards into the plate
  translate([socket_recess_offset_x,
             socket_recess_offset_y,
             plate_T/2 - socket_recess_D/2])
    rounded_box(socket_recess_W, socket_recess_H, socket_recess_D + overlap, recess_corner_R, center=true);
}

module socket_inner_recess_cut(){
  inner_w = socket_recess_W - 10;
  inner_h = socket_recess_H - 10;
  inner_d = min(2.2, socket_recess_D + 0.9);
  translate([socket_recess_offset_x,
             socket_recess_offset_y,
             plate_T/2 - inner_d/2])
    rounded_box(inner_w, inner_h, inner_d + overlap, max(1.5, recess_corner_R-1), center=true);
}

module uk_pin_apertures_cut(){
  // Place cutting solids centered at z=0 so they cut through the plate.
  translate([socket_recess_offset_x, socket_recess_offset_y, 0]){
    // Earth
    translate([0, earth_offset_y, 0])
      cube([earth_w, earth_h, aperture_depth], center=true);

    // Live/Neutral
    translate([-pin_spacing_x/2, pin_offset_y, 0])
      cube([pin_bot_w, pin_bot_h, aperture_depth], center=true);
    translate([ pin_spacing_x/2, pin_offset_y, 0])
      cube([pin_bot_w, pin_bot_h, aperture_depth], center=true);

    // Shutter hint slots (thin cut-through)
    shutter_w = 10;
    shutter_h = 2.2;
    translate([-pin_spacing_x/2, pin_offset_y + pin_bot_h/2 - 3, 0])
      cube([shutter_w, shutter_h, aperture_depth], center=true);
    translate([ pin_spacing_x/2, pin_offset_y + pin_bot_h/2 - 3, 0])
      cube([shutter_w, shutter_h, aperture_depth], center=true);
  }
}

module switch_aperture_cut(){
  pocket_d = min(1.2, plate_T*0.6);
  translate([switch_offset_x,
             switch_offset_y,
             plate_T/2 - pocket_d/2])
    rounded_box(switch_W + 2*switch_aperture_clearance,
                switch_H + 2*switch_aperture_clearance,
                pocket_d + overlap,
                1.5,
                center=true);
}

module screw_hole_cut(pos){
  translate(pos)
    cylinder(r=screw_hole_d/2, h=plate_T + 2*overlap, center=true);
}

module screw_countersink_cut(pos){
  // Countersink on front face only
  translate([pos[0], pos[1], plate_T/2 - screw_csk_depth/2])
    cylinder(r1=screw_csk_d/2, r2=screw_hole_d/2, h=screw_csk_depth + overlap, center=true);
}

module switch_rocker(){
  // Rocker sits on top of plate, overlapping slightly to ensure connection
  rocker_r = 2;
  translate([switch_offset_x,
             switch_offset_y,
             plate_T/2 + switch_T/2 - overlap])
    rounded_box(switch_W, switch_H, switch_T, rocker_r, center=true);
}

module switch_indicator_window_cut(){
  translate([switch_offset_x,
             switch_offset_y + switch_H/2 - indicator_inset_from_top - indicator_H/2,
             plate_T/2 + switch_T/2 - overlap])
    cube([indicator_W, indicator_H, switch_T + 2*overlap], center=true);
}

module rocker_bevel_cut(){
  // Create a rocker-like top by shaving two opposite edges
  shave = 1.2;
  zc = plate_T/2 + switch_T/2 - overlap;
  translate([switch_offset_x, switch_offset_y, zc]){
    translate([0, switch_H/2 - shave/2, 0])
      rotate([45,0,0])
        cube([switch_W + 2*overlap, shave*2, switch_T + 4*overlap], center=true);
    translate([0, -switch_H/2 + shave/2, 0])
      rotate([-45,0,0])
        cube([switch_W + 2*overlap, shave*2, switch_T + 4*overlap], center=true);
  }
}

module socket_bezel(){
  // Raised outline inside the recess to make the socket recognizable
  bezel_w = socket_recess_W - 2*socket_bezel_inset;
  bezel_h = socket_recess_H - 2*socket_bezel_inset;
  bezel_r = max(1.5, recess_corner_R - 1.5);

  // Place on front face with overlap into plate so it is connected
  translate([socket_recess_offset_x,
             socket_recess_offset_y,
             plate_T/2 + socket_bezel_h/2 - overlap])
    difference(){
      rounded_box(bezel_w, bezel_h, socket_bezel_h, bezel_r, center=true);
      rounded_box(bezel_w - 6, bezel_h - 6, socket_bezel_h + 2*overlap, max(1, bezel_r-1), center=true);
    }
}

module socket_aperture_bezels(){
  // Subtle raised rims around the three main apertures to read as a socket.
  // These are CONNECTED to the plate by overlapping into it.
  zc = plate_T/2 + aperture_bezel_h/2 - overlap;

  translate([socket_recess_offset_x, socket_recess_offset_y, zc]){
    // Earth bezel
    translate([0, earth_offset_y, 0])
      difference(){
        rounded_box(earth_w + 6, earth_h + 6, aperture_bezel_h, aperture_bezel_r, center=true);
        cube([earth_w + 1.2, earth_h + 1.2, aperture_bezel_h + 2*overlap], center=true);
      }

    // Live/Neutral bezels
    for (sx = [-pin_spacing_x/2, pin_spacing_x/2]){
      translate([sx, pin_offset_y, 0])
        difference(){
          rounded_box(pin_bot_w + 6, pin_bot_h + 6, aperture_bezel_h, aperture_bezel_r, center=true);
          cube([pin_bot_w + 1.2, pin_bot_h + 1.2, aperture_bezel_h + 2*overlap], center=true);
        }
    }
  }
}

module backbox(){
  // Connected to back of plate with slight overlap
  translate([0, 0, -plate_T/2 - backbox_D/2 + overlap])
    rounded_box(backbox_W, backbox_H, backbox_D, 2, center=true);
}

// -------------------- Build --------------------
module plate_with_features(){
  difference(){
    faceplate();

    // Socket recess + inner well
    socket_recess_cut();
    socket_inner_recess_cut();

    // UK pin apertures (cut-through)
    uk_pin_apertures_cut();

    // Switch pocket
    switch_aperture_cut();

    // Screw holes + countersinks
    screw_hole_cut([-screw_hole_spacing/2, screw_hole_offset_y, 0]);
    screw_hole_cut([ screw_hole_spacing/2, screw_hole_offset_y, 0]);
    screw_countersink_cut([-screw_hole_spacing/2, screw_hole_offset_y, 0]);
    screw_countersink_cut([ screw_hole_spacing/2, screw_hole_offset_y, 0]);
  }
}

module rocker_with_window(){
  difference(){
    switch_rocker();
    switch_indicator_window_cut();
    rocker_bevel_cut();
  }
}

// Final: ONE connected solid (union of connected parts)
union(){
  plate_with_features();

  // Socket recognizability features (connected via overlap)
  socket_bezel();
  socket_aperture_bezels();

  // Switch (connected via overlap)
  rocker_with_window();

  // Backbox (connected via overlap)
  backbox();
}

// Screwfix Essential (style) UK 13A unswitched socket (BS1363) - improved geometry
// One connected solid, no floating parts, all translations derived from dimensions.

$fn = 72;

// -------------------- Parameters --------------------
plate_W = 86;
plate_H = 86;
plate_T = 7;
corner_R = 6;

// Front recess / inner "module" area
recess_W = 52;
recess_H = 52;
recess_D = 1.6;

// Front raised module (around apertures)
module_proud_W = 50;
module_proud_H = 50;
module_proud_T = 2.2;
module_proud_corner_R = 2;

// Back terminal housing (rear body)
backbox_W = 60;
backbox_H = 60;
backbox_D = 28;
backbox_corner_R = 3;

// Rear "terminal block" bulge (suggests Screwfix Essential rear features)
termblock_W = 52;
termblock_H = 34;
termblock_D = 10;
termblock_corner_R = 2.5;

// Cable entry boss (rear)
cable_boss_W = 22;
cable_boss_H = 14;
cable_boss_D = 6;
cable_boss_corner_R = 2;

// Cable entry hole (rear)
cable_hole_d = 10;

// Terminal clamp bosses (rear detail)
clamp_boss_d = 8;
clamp_boss_h = 4;
clamp_hole_d = 3.2;

// Pin apertures (UK BS1363)
earth_slot_W = 6.5;
earth_slot_H = 12.5;
live_slot_W  = 6.5;
live_slot_H  = 10.5;
neutral_slot_W = 6.5;
neutral_slot_H = 10.5;

// Slot spacing (BS1363 characteristic)
slot_spacing_X = 22;
slot_spacing_Y = 18;

// Mounting screws (UK faceplate: vertical)
screw_hole_d = 3.8;
screw_countersink_d = 8.5;
screw_countersink_depth = 2.2;
screw_spacing_Y = 60;

// Backbox fixing bosses aligned with faceplate screws
boss_d = 10;
boss_h = 7;
boss_hole_d = 3.2;

// Shutter suggestion (shallow relief; remains one solid)
shutter_T = 0.6;
shutter_inset = 0.5;
shutter_margin = 1.2;

// General
eps = 0.01;
overlap = 0.8; // intentional overlap to guarantee connectivity

// -------------------- Helpers --------------------
module rounded_rect_prism(w, h, t, r, center=true) {
  translate(center ? [0,0,0] : [w/2, h/2, t/2])
    hull() {
      for (sx = [-1, 1], sy = [-1, 1])
        translate([sx*(w/2 - r), sy*(h/2 - r), 0])
          cylinder(r=r, h=t, center=true);
    }
}

module countersunk_hole(thru_h, hole_d, cs_d, cs_h) {
  union() {
    cylinder(d=hole_d, h=thru_h + 2*eps, center=true);
    translate([0,0, thru_h/2 - cs_h/2])
      cylinder(d=cs_d, h=cs_h + 2*eps, center=true);
  }
}

module pin_apertures_cut(total_cut_h) {
  // BS1363: Earth at top, L/N at bottom
  union() {
    translate([0, slot_spacing_Y/2, 0])
      cube([earth_slot_W, earth_slot_H, total_cut_h], center=true);

    translate([-slot_spacing_X/2, -slot_spacing_Y/2, 0])
      cube([neutral_slot_W, neutral_slot_H, total_cut_h], center=true);

    translate([ slot_spacing_X/2, -slot_spacing_Y/2, 0])
      cube([live_slot_W, live_slot_H, total_cut_h], center=true);
  }
}

module shutter_relief() {
  // Shallow raised plates behind apertures (still one solid)
  z = plate_T/2 - recess_D - shutter_inset - shutter_T/2;
  union() {
    translate([0, slot_spacing_Y/2, z])
      cube([earth_slot_W + 2*shutter_margin, earth_slot_H + 2*shutter_margin, shutter_T], center=true);
    translate([-slot_spacing_X/2, -slot_spacing_Y/2, z])
      cube([neutral_slot_W + 2*shutter_margin, neutral_slot_H + 2*shutter_margin, shutter_T], center=true);
    translate([ slot_spacing_X/2, -slot_spacing_Y/2, z])
      cube([live_slot_W + 2*shutter_margin, live_slot_H + 2*shutter_margin, shutter_T], center=true);
  }
}

// -------------------- Main Solid --------------------
module socket_solid() {
  // Z reference: plate centered at Z=0, front is +Z, back is -Z
  union() {
    // Faceplate
    rounded_rect_prism(plate_W, plate_H, plate_T, corner_R, center=true);

    // Inner raised module on front (proud)
    translate([0,0, plate_T/2 + module_proud_T/2 - overlap])
      rounded_rect_prism(module_proud_W, module_proud_H, module_proud_T, module_proud_corner_R, center=true);

    // Backbox (rear body)
    translate([0,0, -(plate_T/2 + backbox_D/2 - overlap)])
      rounded_rect_prism(backbox_W, backbox_H, backbox_D, backbox_corner_R, center=true);

    // Rear terminal block bulge (attached to backbox rear face)
    translate([0,0,
      -(plate_T/2 + backbox_D - overlap) - termblock_D/2 + overlap])
      rounded_rect_prism(termblock_W, termblock_H, termblock_D, termblock_corner_R, center=true);

    // Cable entry boss on rear terminal block (attached)
    translate([0,0,
      -(plate_T/2 + backbox_D - overlap) - termblock_D + overlap - cable_boss_D/2 + overlap])
      rounded_rect_prism(cable_boss_W, cable_boss_H, cable_boss_D, cable_boss_corner_R, center=true);

    // Screw bosses inside backbox aligned with faceplate screws
    for (sy = [-1, 1]) {
      translate([0, sy*screw_spacing_Y/2, -(plate_T/2 + boss_h/2 - overlap)])
        cylinder(d=boss_d, h=boss_h, center=true);
    }

    // Rear terminal clamp bosses (3) on terminal block face (suggests L/N/E terminals)
    // Positioned to correspond to BS1363 layout (E top, N left, L right)
    clamp_face_z = -(plate_T/2 + backbox_D - overlap) - termblock_D/2 + overlap; // center of termblock
    clamp_front_z = clamp_face_z + termblock_D/2 - clamp_boss_h/2 - 1.0; // slightly inset from termblock front face
    union() {
      translate([0,  slot_spacing_Y/2, clamp_front_z])
        cylinder(d=clamp_boss_d, h=clamp_boss_h, center=true);
      translate([-slot_spacing_X/2, -slot_spacing_Y/2, clamp_front_z])
        cylinder(d=clamp_boss_d, h=clamp_boss_h, center=true);
      translate([ slot_spacing_X/2, -slot_spacing_Y/2, clamp_front_z])
        cylinder(d=clamp_boss_d, h=clamp_boss_h, center=true);
    }

    // Shutter relief (raised, not separate)
    shutter_relief();
  }
}

module socket_cuts() {
  // Front recess
  translate([0,0, plate_T/2 - recess_D/2])
    cube([recess_W, recess_H, recess_D + 2*eps], center=true);

  // Pin apertures: cut through plate + proud module + a bit into backbox
  total_cut_h = plate_T + module_proud_T + 8;
  // Center the cut so it starts at the front and extends inward
  cut_center_z = (plate_T/2 + module_proud_T - overlap) - total_cut_h/2 + 0.5;
  translate([0,0, cut_center_z])
    pin_apertures_cut(total_cut_h);

  // Mounting screw holes + countersinks (front)
  for (sy = [-1, 1]) {
    translate([0, sy*screw_spacing_Y/2, 0])
      countersunk_hole(plate_T + 2*eps, screw_hole_d, screw_countersink_d, screw_countersink_depth);
  }

  // Boss pilot holes (within bosses only)
  for (sy = [-1, 1]) {
    translate([0, sy*screw_spacing_Y/2, -(plate_T/2 + boss_h/2 - overlap)])
      cylinder(d=boss_hole_d, h=boss_h + 2*eps, center=true);
  }

  // Rear cable entry hole (through cable boss + into terminal block slightly)
  cable_boss_center_z =
    -(plate_T/2 + backbox_D - overlap) - termblock_D + overlap - cable_boss_D/2 + overlap;
  translate([0,0, cable_boss_center_z])
    cylinder(d=cable_hole_d, h=cable_boss_D + 4, center=true);

  // Rear terminal clamp screw holes (shallow, do not pass through front)
  clamp_face_z = -(plate_T/2 + backbox_D - overlap) - termblock_D/2 + overlap;
  clamp_front_z = clamp_face_z + termblock_D/2 - clamp_boss_h/2 - 1.0;
  for (p = [
      [0,  slot_spacing_Y/2, clamp_front_z],
      [-slot_spacing_X/2, -slot_spacing_Y/2, clamp_front_z],
      [ slot_spacing_X/2, -slot_spacing_Y/2, clamp_front_z]
    ]) {
    translate(p)
      cylinder(d=clamp_hole_d, h=clamp_boss_h + 2*eps, center=true);
  }
}

// -------------------- Final Output (ONE connected solid) --------------------
difference() {
  socket_solid();
  socket_cuts();
}

// Hex nut for 2.0mm screw
// Target: 4.9mm across flats, 1.6mm thick, through-hole 2.0mm

$fn = 96;

// Parameters
across_flats   = 4.9;   // mm
thickness      = 1.6;   // mm
hole_diameter  = 2.0;   // mm (clearance/through-hole)
chamfer        = 0.2;   // mm (edge bevel on top/bottom)
eps            = 0.02;  // mm (robust boolean overlap)

// Derived: circumradius (center to vertex) for a regular hex with given across-flats
hex_R = across_flats / sqrt(3);   // because across_flats = sqrt(3) * R

module hex_prism(h=thickness, R=hex_R) {
    cylinder(h=h, r=R, center=true, $fn=6);
}

module chamfer_cut(zsign=1) {
    // zsign = +1 for top, -1 for bottom
    // Use a conical frustum to remove material and create a bevel.
    // Place it so it intersects only the corresponding face.
    translate([0, 0, zsign*(thickness/2 - chamfer/2)])
        cylinder(
            h = chamfer + 2*eps,
            r1 = hex_R + chamfer,
            r2 = hex_R - chamfer,
            center = true,
            $fn = 6
        );
}

difference() {
    // Outer hex body with parallel top/bottom faces
    hex_prism();

    // Through-hole for screw
    cylinder(h=thickness + 2*eps, r=hole_diameter/2, center=true);

    // Top and bottom chamfers (subtractive)
    chamfer_cut(+1);
    chamfer_cut(-1);
}

// Hex nut: M2.5, 5.8mm across flats, 2.2mm thick
// One connected solid, no face bumps/markings, with internal thread approximation.

$fn = 96;

// --- Parameters (mm) ---
nut_af      = 5.8;     // across flats
nut_thk     = 2.2;     // thickness

// M2.5 coarse thread (approx)
thread_pitch = 0.45;   // mm
major_d      = 2.5;    // nominal major diameter
minor_d      = 2.05;   // approximate minor diameter for internal thread

// Edge chamfer (small, typical)
chamfer      = 0.20;

// Robust boolean overlap
overlap      = 0.20;

// --- Helpers ---
function hex_R(af) = af / sqrt(3); // circumradius for a hex with given across-flats

module hex_prism(af, h) {
    linear_extrude(height=h, center=true)
        polygon(points=[
            [ hex_R(af), 0],
            [ hex_R(af)/2,  af/2],
            [-hex_R(af)/2,  af/2],
            [-hex_R(af), 0],
            [-hex_R(af)/2, -af/2],
            [ hex_R(af)/2, -af/2]
        ]);
}

// Simple internal thread approximation using linear_extrude twist.
// This is not a standards-perfect ISO profile, but it is a helical threaded void.
module internal_thread(d_major, d_minor, pitch, length) {
    turns = length / pitch;
    // Use a triangular "tooth" in 2D, extruded with twist to form a helix.
    // The triangle spans from minor radius to major radius.
    r_maj = d_major/2;
    r_min = d_minor/2;

    // Tooth thickness along Y kept small to avoid self-intersection.
    tooth_w = pitch * 0.35;

    linear_extrude(height=length + 2*overlap, center=true, twist=turns*360, slices=max(ceil(turns*40), 60))
        translate([0,0,0])
            polygon(points=[
                [r_min, -tooth_w/2],
                [r_maj,  0],
                [r_min,  tooth_w/2]
            ]);
}

// Chamfer cutter (top or bottom) as a conical frustum ring.
module chamfer_cutter(af, chamfer_h, zsign=1) {
    // Place cutter so it intersects the nut edge by chamfer_h.
    // zsign: +1 for top, -1 for bottom.
    R = hex_R(af);
    zc = zsign*(nut_thk/2 - chamfer_h/2);
    translate([0,0,zc])
        cylinder(h=chamfer_h + 2*overlap,
                 r1=R + chamfer_h,
                 r2=R - chamfer_h,
                 center=true);
}

// --- Final nut ---
module hex_nut_M25() {
    difference() {
        // Body
        hex_prism(nut_af, nut_thk);

        // Internal thread void (helical)
