across_flats = 7.0; //[3.5:14.0:0.1]
thickness = 2.2; //[1.1:4.4:0.1]
hole_diameter = 4.0; //[2.0:8.0:0.1]
chamfer_size = 0.3; //[0.1:0.8:0.05]
overlap = 0.6; //[0.2:1.5:0.1]
hex_circumradius = 4.041; //[2.0:8.5:0.001]
