hole_r = hole_diameter / 2;

module hex_nut() {
    difference() {
        // Outer hex prism (flats aligned to X/Y so top/bottom views are hex)
        cylinder(r=hex_R, h=thickness, center=true, $fn=6);

        // Through hole
