        // Top chamfer (remove material near outer edge)
        translate([0, 0, thickness/2 - chamfer_size/2])
            cylinder(
                r1 = hex_R + overlap,
                r2 = max(hole_r, hex_R - chamfer_size),
                h  = chamfer_size + overlap,
                center = true,
                $fn = 6
            );

        // Bottom chamfer
        translate([0, 0, -thickness/2 + chamfer_size/2])
            cylinder(
                r1 = max(hole_r, hex_R - chamfer_size),
                r2 = hex_R + overlap,
                h  = chamfer_size + overlap,
                center = true,
                $fn = 6
            );
