overlap = 1;           //[0.5:2:0.1]
bezel_edge_r = 1.2;    //[0.5:3:0.1]

// Display + recess
display_win_W = 36;    //[18:72:0.5]
display_win_H = 16;    //[8:32:0.5]
screen_recess_margin = 2;   //[1:4:0.5]
screen_recess_depth  = 0.9; //[0.3:2:0.1]

// Bottom control strip (buttons area)
button_area_W = 36;    //[18:72:0.5]
button_area_H = 8;     //[4:16:0.5]
button_recess_depth = 0.9;  //[0.3:2:0.1]

// Front controls
encoder_r = 3.4;       //[2:6:0.1]
encoder_h = 2.0;       //[0.8:3:0.1]
btn_r = 1.6;           //[1:3:0.1]
btn_h = 1.4;           //[0.6:2.5:0.1]
btn_spacing = 8;       //[5:12:0.5]

// Flange lip
flange_extra = 2.0;    //[0.5:5:0.1]
flange_T = 1.2;        //[0.6:3:0.1]

// Side mounting clips (spring tabs)
clip_W = 6;            //[3:12:0.5]
clip_T = 1.5;          //[0.8:3:0.1]
clip_overhang = 1.8;   //[0.5:3:0.1]
clip_z_span = 10;      //[6:16:0.5]

// Rear terminal block (screw terminal)
connector_W = 22;      //[10:40:0.5]
connector_H = 9;       //[4:16:0.5]
connector_D = 8;       //[3:14:0.5]
term_screw_r = 1.4;    //[0.8:2.5:0.1]
term_screw_h = 1.2;    //[0.6:2.5:0.1]
term_pitch = 6.0;      //[4:8:0.1]
term_count = 3;        //[2:6:1]

// Rear JST-style header block
header_W = 12;         //[6:20:0.5]
header_H = 6;          //[3:12:0.5]
header_D = 6;          //[3:12:0.5]
header_pin_r = 0.8;    //[0.5:1.2:0.1]
header_pin_h = 1.2;    //[0.6:2.5:0.1]
header_pin_pitch = 2.54;
header_pin_count = 4;  //[2:8:1]

// Rear rails / ribs (common on modules)
rail_W = 6;            //[3:12:0.5]
rail_H = 3;            //[1.5:6:0.5]
rail_D = 10;           //[6:18:0.5]

// PCB placeholder + standoffs (kept connected)
pcb_W = 40;            //[20:80:0.5]
pcb_H = 22;            //[11:44:0.5]
pcb_T = 1.6;           //[0.8:3.2:0.1]
boss_r = 2.2;          //[1.2:4.4:0.1]
boss_h = 6;            //[3:12:0.5]
boss_inset = 3.5;      //[2:7:0.5]

// ---------- Z references ----------
function z_bezel_center() = 0;
function z_bezel_front()  = z_bezel_center() + bezel_T/2;
function z_bezel_back()   = z_bezel_center() - bezel_T/2;

function z_body_center()  = z_bezel_back() - body_D/2 + overlap; // overlaps into bezel
function z_body_back()    = z_body_center() - body_D/2;
function z_body_front()   = z_body_center() + body_D/2;

// Layout on front face
function y_display_center() = (bezel_H/2 - display_win_H/2 - button_area_H - 1);
function y_button_center()  = -(bezel_H/2 - button_area_H/2 - 1);

// ---------- Helpers ----------
module rounded_box(size=[10,10,2], r=1) {
  // Minkowski rounded edges
  minkowski() {
    cube([max(0.01,size[0]-2*r), max(0.01,size[1]-2*r), max(0.01,size[2]-2*r)], center=true);
    sphere(r=r);
  }
}

module chamfered_box(size=[10,10,2], c=0.8) {
  // Simple chamfer-ish look using hull of inset cubes (lighter than minkowski)
  hull() {
    cube([size[0], size[1], size[2]-2*c], center=true);
    translate([0,0,(size[2]-2*c)/2]) cube([size[0]-2*c, size[1]-2*c, 0.01], center=true);
    translate([0,0,-(size[2]-2*c)/2]) cube([size[0]-2*c, size[1]-2*c, 0.01], center=true);
  }
}

// ---------- Front bezel + flange ----------
module front_bezel() {
  rounded_box([bezel_W, bezel_H, bezel_T], r=bezel_edge_r);
}

module front_flange() {
  translate([0,0, z_bezel_back() - flange_T/2 + overlap])
    rounded_box([bezel_W + 2*flange_extra, bezel_H + 2*flange_extra, flange_T], r=bezel_edge_r);
}

// ---------- Rear body ----------
module rear_body() {
  translate([0, 0, z_body_center()])
    chamfered_box([body_W, body_H, body_D], c=0.8);
}

// ---------- Cuts (openings/recesses) ----------
module display_window_cut() {
  translate([0, y_display_center(), z_bezel_center()])
    cube([display_win_W, display_win_H, bezel_T + 6*overlap], center=true);
}

module screen_recess_cut() {
  translate([0, y_display_center(),
             z_bezel_front() - screen_recess_depth/2 + overlap/2])
    cube([display_win_W + 2*screen_recess_margin,
          display_win_H + 2*screen_recess_margin,
          screen_recess_depth + overlap], center=true);
}

module button_recess_cut() {
  translate([0, y_button_center(),
             z_bezel_front() - button_recess_depth/2 + overlap/2])
    cube([button_area_W, button_area_H, button_recess_depth + overlap], center=true);
}

// ---------- Front positive features ----------
module front_controls_positive() {
  // Encoder knob centered in button strip + two small buttons
  z_knob = z_bezel_front() + encoder_h/2 - overlap/2;
  z_btn  = z_bezel_front() + btn_h/2     - overlap/2;

  // Knob
  translate([0, y_button_center(), z_knob])
    cylinder(r=encoder_r, h=encoder_h, center=true);

  // Two buttons
  translate([-btn_spacing/2, y_button_center(), z_btn])
    cylinder(r=btn_r, h=btn_h, center=true);
  translate([ btn_spacing/2, y_button_center(), z_btn])
    cylinder(r=btn_r, h=btn_h, center=true);
}

// ---------- Side mounting clips (spring tabs) ----------
module mounting_clip(side=1) {
  // side = -1 left, +1 right
  // Clip is attached to body side and extends outward to catch panel.
  clip_len_x = clip_overhang + clip_T;
  x_center = side * (body_W/2 + clip_len_x/2 - overlap);

  // Place clips around mid-height, spanning a region behind bezel (panel area)
  z_center = z_bezel_back() - (clip_z_span/2) + overlap;

  translate([x_center, 0, z_center])
    cube([clip_len_x, clip_W, clip_z_span], center=true);
}

// ---------- Rear terminal block + screw bumps ----------
module rear_terminal_block() {
  // Attached to rear body back face with overlap.
  y_center = -(body_H/2 - connector_H/2 - overlap);
  z_center = z_body_back() - connector_D/2 + overlap;

  union() {
    translate([0, y_center, z_center])
      chamfered_box([connector_W, connector_H, connector_D], c=0.6);

    // Screw bumps on the back face of the terminal block
    // Place along X with pitch, centered.
    x0 = -((term_count-1)*term_pitch)/2;
    z_screw = (z_center - connector_D/2) - term_screw_h/2 + overlap; // protrude further back
    for (i=[0:term_count-1]) {
      translate([x0 + i*term_pitch, y_center, z_screw])
        cylinder(r=term_screw_r, h=term_screw_h, center=true);
    }
  }
}

// ---------- Rear header block + pins ----------
module rear_header_block() {
  // Place above terminal block, centered, attached to rear body back face.
  y_center = (body_H/2 - header_H/2 - overlap);
  z_center = z_body_back() - header_D/2 + overlap;

  union() {
    translate([0, y_center, z_center])
      chamfered_box([header_W, header_H, header_D], c=0.5);

    // Pin bumps on back face
    x0 = -((header_pin_count-1)*header_pin_pitch)/2;
    z_pin = (z_center - header_D/2) - header_pin_h/2 + overlap;
    for (i=[0:header_pin_count-1]) {
      translate([x0 + i*header_pin_pitch, y_center, z_pin])
        cylinder(r=header_pin_r, h=header_pin_h, center=true);
    }
  }
}

// ---------- Rear rails / ribs ----------
module rear_rails() {
  // Two ribs on rear body, left/right, attached to back face.
  x_off = (body_W/2 - rail_W/2 - overlap);
  z_center = z_body_back() - rail_D/2 + overlap;

  union() {
    translate([-x_off, 0, z_center])
      cube([rail_W, body_H - 2*overlap, rail_D], center=true);
    translate([ x_off, 0, z_center])
      cube([rail_W, body_H - 2*overlap, rail_D], center=true);
  }
}

// ---------- PCB + standoffs (connected) ----------
module pcb_and_standoffs() {
  // PCB inside body; connected via standoffs to body.
  z_pcb_center = z_bezel_back() - 2 - pcb_T/2;

  x_off = min(pcb_W/2 - boss_inset, body_W/2 - boss_inset);
  y_off = min(pcb_H/2 - boss_inset, body_H/2 - boss_inset);

  // Standoff top meets PCB with overlap; bottom embedded in body.
  z_standoff_center = z_pcb_center + pcb_T/2 - boss_h/2 + overlap;

  union() {
    translate([0, 0, z_pcb_center])
      cube([pcb_W, pcb_H, pcb_T], center=true);

    for (sx = [-1, 1], sy = [-1, 1]) {
      translate([sx*x_off, sy*y_off, z_standoff_center])
        cylinder(r=boss_r, h=boss_h, center=true);
    }
  }
}

// ---------- Panel cutout interface slab (kept connected) ----------
module panel_cutout_interface() {
  translate([0, 0, z_bezel_back() - panel_T/2 + overlap])
    cube([cutout_W, cutout_H, panel_T], center=true);
}

// ---------- Bezel with openings ----------
module front_bezel_with_openings() {
  difference() {
    union() {
      front_bezel();
      front_flange();
    }
    display_window_cut();
    screen_recess_cut();
    button_recess_cut();
  }
}

// ---------- Assembly ----------
module module_solid() {
  union() {
    // Front bezel + openings
    front_bezel_with_openings();

    // Rear body
    rear_body();

    // Front raised controls
    front_controls_positive();

    // Side mounting clips
    mounting_clip(-1);
    mounting_clip( 1);

    // Rear connectors
    rear_terminal_block();
    rear_header_block();

    // Rear ribs
    rear_rails();

    // Internal PCB + standoffs (connected)
    pcb_and_standoffs();

    // Panel interface slab (connected)
    panel_cutout_interface();
  }
}

// ---------- Final Output ----------
module_solid();

// Peacefair PZEM-001 style AC panel meter (approximate)
// One connected solid, no text. All placements derived from dimensions.

$fn = 64;

// ---------- Parameters ----------
bezel_W = 80; //[40:160:1]
bezel_H = 43; //[22:86:1]
bezel_T = 3;  //[2:6:1]

housing_W = 76; //[38:152:1]
housing_H = 39; //[20:78:1]
housing_D = 72; //[36:144:1]

panel_cutout_W = 76; //[38:152:1]
panel_cutout_H = 39; //[20:78:1]

window_W = 60; //[30:120:1]
window_H = 26; //[13:52:1]
window_offset_Z = 2; //[-10:10:1]  // vertical offset on face (Z)

face_recess_depth = 1.2; //[0.6:2.4:0.1]
recess_margin = 3; //[1:8:1]

clip_count_per_side = 1; //[1:3:1]
clip_W = 12; //[5:20:1]
clip_H = 7;  //[3:12:1]
clip_T = 2.2;  //[1:4:0.1]
clip_offset_from_front = 18; //[8:36:1]

terminal_block_W = 44; //[20:80:1]
terminal_block_H = 18; //[9:36:1]
terminal_block_D = 16; //[8:32:1]
terminal_block_offset_from_back = 0; //[0:10:1]

vent_slot_W = 3; //[1:6:0.5]
vent_slot_H = 10; //[5:20:1]
vent_slot_T = 2; //[1:4:0.5]
vent_slot_count = 5; //[3:9:1]

lcd_plate_T = 0.9; //[0.4:2:0.1]
lcd_plate_margin = 2; //[1:5:0.5]
lcd_segment_T = 0.6; //[0.3:1.5:0.1]
lcd_segment_W = 6; //[3:12:0.5]
lcd_segment_H = 12; //[6:24:1]

screw_head_r = 2.5; //[1.5:5:0.5]
screw_head_h = 1.5; //[0.8:3:0.1]

overlap = 1; //[0.5:2:0.5]

// Extra PZEM-001 recognizable features (no text)
bezel_corner_r = 2.2;
bezel_lip = 2.0;          // bezel overhang around housing
bezel_step = 1.2;         // bezel "frame" thickness around recessed face
bezel_step_r = 1.6;

window_corner_r = 1.2;

button_W = 10;
button_H = 6;
button_depth = 0.9;
button_gap = 3;

led_r = 1.2;
led_depth = 0.8;

mount_ear_W = 6.5;        // small front bezel ears (top/bottom corners)
mount_ear_H = 4.0;
mount_ear_T = 1.6;

term_rib_W = 6;           // small ribs on terminal block top
term_rib_H = 2.2;
term_rib_D = 2.0;
term_rib_count = 4;

function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// ---------- Derived ----------
bezel_inner_W = housing_W + 2*bezel_lip;
bezel_inner_H = housing_H + 2*bezel_lip;

buttons_total_W = 3*button_W + 2*button_gap;
buttons_z_offset = -(window_H/2 + button_H/2 + 3); // below window (negative Z)
buttons_z_offset_clamped =
    clamp(buttons_z_offset,
          -(bezel_H/2 - recess_margin - button_H/2),
           (bezel_H/2 - recess_margin - button_H/2));

// Coordinate convention:
// X = left/right, Y = front/back (front positive), Z = up/down
bezel_yc = 0;
housing_yc = -(bezel_T/2 + housing_D/2 - overlap);
housing_zc = 0;

panel_if_T = bezel_T + overlap;
panel_if_yc = -(bezel_T/2 + panel_if_T/2 - overlap);

// Clips: on left/right sides, slightly behind bezel
clip_yc = -(bezel_T/2 + clip_offset_from_front);
clip_x_left  = -(housing_W/2 + clip_W/2 - overlap);
clip_x_right =  (housing_W/2 + clip_W/2 - overlap);

// Terminal block: attached to rear-bottom of housing
term_yc = housing_yc - housing_D/2 + terminal_block_D/2 + terminal_block_offset_from_back + overlap;
term_zc = housing_zc - housing_H/2 + terminal_block_H/2 + overlap;

// LCD plate: inside front recess (slightly behind front face)
lcd_yc = (bezel_T/2 - face_recess_depth) - lcd_plate_T/2 + overlap;

// LCD segments: slightly behind plate
seg_yc = (bezel_T/2 - face_recess_depth) - lcd_plate_T - lcd_segment_T/2 + overlap;

// Screw heads: on terminal block rear face, near top corners
screw_yc = term_yc - terminal_block_D/2 + screw_head_h/2 - overlap; // rear-most face (more negative Y)
screw_zc = term_zc + terminal_block_H/2 - screw_head_r - overlap;
screw_x_left  = -terminal_block_W/2 + screw_head_r + overlap;
screw_x_right =  terminal_block_W/2 - screw_head_r - overlap;

// Bezel ears: at top/bottom corners, protruding slightly
ear_yc = bezel_yc + bezel_T/2 - mount_ear_T/2 + overlap;
ear_x = bezel_W/2 - mount_ear_W/2;
ear_z = bezel_H/2 - mount_ear_H/2;

// LED indicators: small recessed circles above window
led_z = window_offset_Z + window_H/2 + 4;
led_z_clamped = clamp(led_z, -bezel_H/2 + recess_margin + led_r, bezel_H/2 - recess_margin - led_r);
led_x_span = window_W*0.35;
led_yc = bezel_yc + bezel_T/2 - (led_depth/2) - overlap;

// ---------- Primitives ----------
module rrect_xy(size=[10,10,2], r=1, center=true) {
  w = size[0]; d = size[1]; h = size[2];
  translate(center ? [0,0,-h/2] : [0,0,0])
    linear_extrude(height=h)
      offset(r=r)
        square([max(0.01,w-2*r), max(0.01,d-2*r)], center=true);
}

module rrect_xz(size=[10,2,10], r=1, center=true) {
  // Rounded rectangle in XZ, extruded along Y (thickness is size[1])
  w = size[0]; t = size[1]; h = size[2];
  translate(center ? [0,-t/2,0] : [0,0,0])
    rotate([90,0,0])
      linear_extrude(height=t)
        offset(r=r)
          square([max(0.01,w-2*r), max(0.01,h-2*r)], center=true);
}

module front_bezel_outer() {
  rrect_xz([bezel_W, bezel_T, bezel_H], r=bezel_corner_r, center=true);
}

module front_bezel_step_cut() {
  // Creates a "frame" step: remove a larger shallow area, leaving a raised rim
  rrect_xz([bezel_W - 2*bezel_step, face_recess_depth + 2*overlap, bezel_H - 2*bezel_step],
           r=max(0.8, bezel_step_r), center=true);
}

module front_face_recess_cut() {
  // Inner recess area (slightly smaller than step cut) for LCD/button region
  rrect_xz([bezel_W - 2*recess_margin, face_recess_depth + 2*overlap, bezel_H - 2*recess_margin],
           r=max(0.8, bezel_corner_r-0.8), center=true);
}

module display_window_opening_cut() {
  rrect_xz([window_W, bezel_T + 4*overlap, window_H], r=window_corner_r, center=true);
}

module button_recess_cut(xc) {
  translate([xc, 0, window_offset_Z + buttons_z_offset_clamped])
    rrect_xz([button_W, button_depth + 2*overlap, button_H], r=0.8, center=true);
}

module led_recess_cut(xc) {
  translate([xc, led_yc, led_z_clamped])
    rotate([90,0,0])
      cylinder(r=led_r, h=led_depth + 2*overlap, center=true);
}

module rear_housing_block() {
  rrect_xy([housing_W, housing_D, housing_H], r=1.2, center=true);
}

module panel_cutout_interface_block() {
  rrect_xy([panel_cutout_W, panel_if_T, panel_cutout_H], r=0.8, center=true);
}

module clip_block() {
  rrect_xy([clip_W, clip_T, clip_H], r=0.6, center=true);
}

module rear_terminal_block_envelope() {
  rrect_xy([terminal_block_W, terminal_block_D, terminal_block_H], r=1.0, center=true);
}

module terminal_rib() {
  rrect_xy([term_rib_W, term_rib_D, term_rib_H], r=0.6, center=true);
}

module lcd_plate() {
  rrect_xz([window_W + 2*lcd_plate_margin, lcd_plate_T, window_H + 2*lcd_plate_margin], r=1.0, center=true);
}

module lcd_segment() {
  rrect_xz([lcd_segment_W, lcd_segment_T, lcd_segment_H], r=0.6, center=true);
}

module screw_head() {
  cylinder(r=screw_head_r, h=screw_head_h, center=true);
}

module bezel_ear() {
  rrect_xz([mount_ear_W, mount_ear_T, mount_ear_H], r=0.8, center=true);
}

module rear_vent_slot_cut(i) {
  x_pos = -(housing_W/2) + (housing_W/(vent_slot_count+1))*i;
  // rear face of housing (more negative Y), near top (positive Z)
  translate([x_pos,
             housing_yc - housing_D/2 + (vent_slot_T/2),
             housing_zc + housing_H/2 - vent_slot_H/2 - overlap])
    cube([vent_slot_W, vent_slot_T + 2*overlap, vent_slot_H], center=true);
}

// ---------- Operations ----------
module front_bezel_with_details() {
  difference() {
    union() {
      front_bezel_outer();

      // Small bezel ears (top-left, top-right, bottom-left, bottom-right)
      translate([ ear_x, ear_yc,  ear_z]) bezel_ear();
      translate([-ear_x, ear_yc,  ear_z]) bezel_ear();
      translate([ ear_x, ear_yc, -ear_z]) bezel_ear();
      translate([-ear_x, ear_yc, -ear_z]) bezel_ear();
    }

    // Step cut (frame)
    translate([0, bezel_yc + bezel_T/2 - (face_recess_depth + 2*overlap)/2, 0])
      front_bezel_step_cut();

    // Inner recess (LCD/button region)
    translate([0, bezel_yc + bezel_T/2 - (face_recess_depth + 2*overlap)/2, 0])
      front_face_recess_cut();

    // Window opening
    translate([0, bezel_yc, window_offset_Z])
      display_window_opening_cut();

    // Button recesses (3)
    button_recess_cut(-(buttons_total_W/2) + button_W/2);
    button_recess_cut(0);
    button_recess_cut((buttons_total_W/2) - button_W/2);

    // LED recesses (2)
    led_recess_cut(-led_x_span/2);
    led_recess_cut( led_x_span/2);
  }
}

module rear_housing_with_vents() {
  difference() {
    translate([0, housing_yc, housing_zc])
      rear_housing_block();

    for (i = [1:vent_slot_count])
      rear_vent_slot_cut(i);
  }
}

module terminal_block_with_ribs() {
  union() {
    translate([0, term_yc, term_zc])
      rear_terminal_block_envelope();

    // Ribs on top of terminal block (connected)
    rib_yc = term_yc + (terminal_block_D/2 - term_rib_D/2) - overlap;
    rib_zc = term_zc + (terminal_block_H/2 + term_rib_H/2) - overlap;
    for (k = [1:term_rib_count]) {
      xk = -(terminal_block_W/2) + (terminal_block_W/(term_rib_count+1))*k;
      translate([xk, rib_yc, rib_zc])
        terminal_rib();
    }
  }
}

module meter_body_union() {
  union() {
    // Front bezel
    translate([0, bezel_yc, 0])
      front_bezel_with_details();

    // Rear housing (connected with overlap)
    rear_housing_with_vents();

    // Panel cutout interface (neck)
    translate([0, panel_if_yc, 0])
      panel_cutout_interface_block();

    // Side clips (connected to housing)
    translate([clip_x_left, clip_yc, 0])
      clip_block();
    translate([clip_x_right, clip_yc, 0])
      clip_block();

    // Rear terminal block + ribs (connected to housing)
    terminal_block_with_ribs();

    // LCD plate (solid detail inside recess)
    translate([0, lcd_yc, window_offset_Z])
      lcd_plate();

    // LCD segments (solid detail)
    translate([-(window_W/2) + lcd_plate_margin + lcd_segment_W/2, seg_yc, window_offset_Z])
      lcd_segment();
    translate([0, seg_yc, window_offset_Z])
      lcd_segment();
    translate([(window_W/2) - lcd_plate_margin - lcd_segment_W/2, seg_yc, window_offset_Z])
      lcd_segment();

    // Terminal screws (solid bumps) on rear face of terminal block
