// ---------- Helpers ----------
module rounded_rect_prism(L, W, H, r) {
    // 2D rounded rectangle extruded
    linear_extrude(height=H, center=true)
        offset(r=r)
            square([L - 2*r, W - 2*r], center=true);
}

module pcb_base() {
    color([0.0, 0.4, 0.2])
        rounded_rect_prism(board_L, board_W, board_T, corner_r);
