module mounting_holes_cut() {
    // Through-holes cut from PCB
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx*(board_L/2 - hole_edge), sy*(board_W/2 - hole_edge), 0])
            cylinder(h=board_T + 2*overlap, d=hole_d, center=true);
    }
