module test_points_top() {
    // Small posts near top edge
    for (i = [0:2]) {
        x_tp = -pcb_L*0.05 + i*(pcb_L*0.06);
        translate([x_tp,
                   pcb_W*0.30,
                   pcb_T/2 + testpoint_H/2 - conn_overlap])
            cylinder(d=testpoint_d, h=testpoint_H, center=true);
    }
}

