module end_chamfer_cut(zsign=1) {
    // Subtractive chamfer cut at each end of the body
    translate([0, 0, zsign*(L/2 - chamfer/2)])
        cylinder(h=chamfer + overlap, r1=body_r + 0.01, r2=max(body_r - chamfer, 0.01), center=true);
