module shaft_bore_cut() {
    // Through-bore along X through entire housing (visible through housing)
    rotate([0, 90, 0])
        translate([0, 0, bore_z])
            cylinder(r=(shaft_d + bore_clearance)/2, h=housing_L + 6*overlap, center=true);
