module insert_seat_cut() {
    // Shallow seat for insert (visual) centered in housing
    rotate([0, 90, 0])
        translate([0, 0, bore_z])
            cylinder(r=insert_OD/2, h=insert_seat_depth + 2*overlap, center=true);
