base_L = 55.0;                 // base length (X)
base_W = 42.0;                 // base width  (Y)
base_T = 6.0;                  // base thickness (Z)

bore_D = 8.0;                  // shaft diameter
bore_clearance = 0.2;

center_height = 18.0;          // shaft center above bottom of base

// Typical 2-hole pillow block uses 2 mounting holes along X
mount_hole_D = 6.5;
mount_hole_spacing_L = 40.0;   // hole spacing along X
mount_slot_L = 12.0;           // slot length along X (>= hole_D)
counterbore_D = 11.0;
counterbore_depth = 3.0;

housing_L = 40.0;              // housing length (X)
housing_W = 30.0;              // housing width  (Y)
housing_H = 22.0;              // housing block height (Z)

housing_seat_R = 12.0;         // outer "cap" radius around bore
cap_len = housing_L;           // cap length along X

grease_boss_D = 8.0;
grease_boss_H = 6.0;

set_screw_D = 4.0;
set_screw_depth = 12.0;

fillet_R = 1.0;                // small edge softening
overlap = 0.6;                 // boolean overlap

// -------------------- Derived --------------------
bore_R = (bore_D + bore_clearance)/2;
shaft_Z = center_height;

base_top_Z = base_T;

housing_bottom_Z = base_top_Z - overlap;
housing_top_Z = housing_bottom_Z + housing_H;

// Cap centered on shaft axis; ensure it intersects housing
cap_center_Z = shaft_Z;
cap_bottom_Z = cap_center_Z - housing_seat_R;
cap_raise = max(0, (housing_bottom_Z + 1.0) - cap_bottom_Z);
cap_center_Z_adj = cap_center_Z + cap_raise;

// Ensure housing reaches up to cap (if parameters change)
cap_bottom_Z_adj = cap_center_Z_adj - housing_seat_R;
housing_H_adj = max(housing_H, (cap_bottom_Z_adj - housing_bottom_Z) + 1.0);

// Mounting hole Y position (2-hole base, symmetric)
mount_hole_Y = base_W * 0.30;  // visually similar to typical pillow blocks, stays within base

// -------------------- Primitives --------------------
module base_plate() {
    translate([0, 0, base_T/2])
        cube([base_L, base_W, base_T], center=true);
}

module housing_block() {
    translate([0, 0, housing_bottom_Z + housing_H_adj/2])
        cube([housing_L, housing_W, housing_H_adj], center=true);
}

module bearing_cap() {
    translate([0, 0, cap_center_Z_adj])
        rotate([0, 90, 0])
            cylinder(r=housing_seat_R, h=cap_len, center=true);
}

module grease_boss() {
    translate([0, 0, (cap_center_Z_adj + housing_seat_R) + grease_boss_H/2 - overlap])
        cylinder(d=grease_boss_D, h=grease_boss_H, center=true);
}

module shaft_bore() {
    // Through bore along X (clearly visible)
    translate([0, 0, cap_center_Z_adj])
        rotate([0, 90, 0])
            cylinder(r=bore_R, h=base_L + 2*housing_seat_R + 20, center=true);
}

module set_screw_hole() {
    // Radial set screw from +Y side into bore (along -Y)
    y_outside = max(housing_W/2, housing_seat_R) + set_screw_depth/2 - overlap;
    translate([0, y_outside, cap_center_Z_adj])
        rotate([90, 0, 0])
            cylinder(d=set_screw_D, h=set_screw_depth + 2*overlap, center=true);
}

module mount_slots_and_counterbores() {
    // 2 mounting slots along X, symmetric about origin, located near Y edges
    // Slot made by hull of two cylinders; counterbore similarly from top.
    slot_r = mount_hole_D/2;
    slot_half = max(0, mount_slot_L/2 - slot_r);

    for (sy = [-1, 1]) {
        y = sy * mount_hole_Y;

        // Through slot
        hull() {
            translate([+slot_half, y, base_T/2])
                cylinder(r=slot_r, h=base_T + 2*overlap, center=true);
            translate([-slot_half, y, base_T/2])
                cylinder(r=slot_r, h=base_T + 2*overlap, center=true);
        }

        // Counterbore slot from top
        cb_r = counterbore_D/2;
        cb_half = max(0, mount_slot_L/2 - cb_r);
        hull() {
            translate([+cb_half, y, base_T - counterbore_depth/2])
                cylinder(r=cb_r, h=counterbore_depth + 2*overlap, center=true);
            translate([-cb_half, y, base_T - counterbore_depth/2])
                cylinder(r=cb_r, h=counterbore_depth + 2*overlap, center=true);
        }
    }
}

// -------------------- Main solid --------------------
module pillow_block_solid() {
    union() {
        base_plate();
        housing_block();   // overlaps into base via housing_bottom_Z
        bearing_cap();     // intersects housing by construction
        grease_boss();     // overlaps into cap
    }
}

module pillow_block() {
    difference() {
        pillow_block_solid();
        shaft_bore();
        mount_slots_and_counterbores();
        set_screw_hole();
    }
}

// Fillet/soften edges while keeping one connected solid
minkowski() {
    pillow_block();
    sphere(r=fillet_R);
}

// Pillow block bearing housing (UCP-style simplified, improved)
// Target: 8.0mm shaft bore, 55.0mm x 42.0mm base
// ONE connected solid; no floating parts; all translates derived from dimensions.

$fn = 128;

// ---------- Parameters ----------
base_L = 55.0;                 // base length (X)
base_W = 42.0;                 // base width  (Y)
base_H = 10.0;                 // base thickness (Z)

shaft_d = 8.0;                 // shaft bore diameter (critical)

mount_hole_d = 6.5;
mount_hole_spacing_L = 40.0;   // center-to-center along X
mount_boss_d = 14.0;
mount_boss_h = 2.0;

// Housing proportions (typical pillow block look)
housing_W = 30.0;              // width of housing body (Y)
housing_block_H = 14.0;        // rectangular portion above base (Z)
arch_r = 16.0;                 // top arch radius (YZ)
housing_L = 34.0;              // length of housing body (X)

// Bearing seat (raised ring around bore on both sides)
seat_d = 22.0;                 // visual bearing OD seat
seat_ring_t = 4.0;             // ring thickness along X (each side)

// Split cap groove (visual detail)
cap_groove_w = 1.2;            // groove width along Z
cap_groove_depth = 1.2;        // groove depth into housing along Y

// Set screw (simple radial hole from top into bore)
set_screw_d = 4.0;
set_screw_z_from_top = 6.0;

// Grease boss
grease_boss_d = 8.0;
grease_boss_h = 6.0;
grease_hole_d = 2.0;

// Edge chamfer on base
edge_chamfer = 1.0;

// Robust boolean overlap
overlap = 0.8;

// ---------- Derived positions ----------
base_z0 = -base_H/2;
base_top_z = base_H/2;

housing_block_zc = base_top_z + housing_block_H/2 - overlap;
arch_axis_z = base_top_z + housing_block_H - overlap; // cylinder axis for arch

// Total housing height (approx) = base_H + housing_block_H + arch_r
z_top = arch_axis_z + arch_r;

// ---------- Helpers ----------
module chamfer_base_edges() {
  // subtract small wedges at base perimeter (keeps base size verifiable)
  for (sx = [-1, 1]) {
    translate([sx*(base_L/2 - edge_chamfer/2), 0, 0])
      rotate([0, 0, 45])
        cube([edge_chamfer, base_W + 2*overlap, base_H + 2*overlap], center=true);
  }
  for (sy = [-1, 1]) {
    translate([0, sy*(base_W/2 - edge_chamfer/2), 0])
      rotate([0, 0, 45])
        cube([base_L + 2*overlap, edge_chamfer, base_H + 2*overlap], center=true);
  }
}

module base_solid() {
  union() {
    cube([base_L, base_W, base_H], center=true);

    // mounting pads on top face (connected)
    for (sx = [-1, 1]) {
      translate([sx*mount_hole_spacing_L/2, 0, base_top_z + mount_boss_h/2 - overlap])
        cylinder(d=mount_boss_d, h=mount_boss_h, center=true);
    }
  }
}

module housing_outer() {
  // Outer housing: rectangular block + top arch, connected to base
  union() {
    // rectangular portion
    translate([0, 0, housing_block_zc])
      cube([housing_L, housing_W, housing_block_H], center=true);

    // arched top (cylinder along X)
    translate([0, 0, arch_axis_z])
      rotate([0, 90, 0])
        cylinder(r=arch_r, h=housing_L, center=true);

    // raised bearing seat rings on both sides (connected to housing)
    for (sx = [-1, 1]) {
      translate([sx*(housing_L/2 + seat_ring_t/2 - overlap), 0, arch_axis_z])
        rotate([0, 90, 0])
          cylinder(d=seat_d + 2*4.0, h=seat_ring_t, center=true); // outer ring diameter
    }

    // grease boss on top center (connected)
    translate([0, 0, z_top + grease_boss_h/2 - overlap])
      cylinder(d=grease_boss_d, h=grease_boss_h, center=true);
  }
}

module cap_split_groove() {
  // Visual split line around the cap: a shallow groove across the arch
  // Implemented as a thin rectangular cut that wraps by intersecting the arch region.
  // Positioned slightly above arch axis (typical cap split).
  groove_z = arch_axis_z + arch_r*0.35;
  translate([0, 0, groove_z])
    cube([housing_L + 2*seat_ring_t + 4*overlap, housing_W + 2*overlap, cap_groove_w], center=true);

  // Side relief to make it look like a split cap (small notches on both sides)
  for (sy = [-1, 1]) {
    translate([0, sy*(housing_W/2 - cap_groove_depth/2 + overlap), groove_z])
      cube([housing_L + 2*seat_ring_t + 4*overlap, cap_groove_depth, cap_groove_w*2], center=true);
  }
}

module mounting_holes() {
  for (sx = [-1, 1]) {
    translate([sx*mount_hole_spacing_L/2, 0, 0])
      cylinder(d=mount_hole_d, h=base_H + 2*mount_boss_h + 6*overlap, center=true);
  }
}

module shaft_bore() {
  // Shaft bore along X through entire housing + seat rings
  bore_len = housing_L + 2*seat_ring_t + 2*arch_r + 8*overlap;
  translate([0, 0, arch_axis_z])
    rotate([0, 90, 0])
      cylinder(d=shaft_d, h=bore_len, center=true);
}

module bearing_seat_bore() {
  // Larger bore region (visual bearing insert seat) centered in housing
  // Keep it shorter than full housing to leave material at ends.
  seat_len = housing_L - 2*6.0;
  translate([0, 0, arch_axis_z])
    rotate([0, 90, 0])
      cylinder(d=seat_d, h=seat_len, center=true);
}

module set_screw_hole() {
  // Radial hole from top down into bore (axis along Y)
  z_pos = z_top - set_screw_z_from_top;
  translate([0, 0, z_pos])
    rotate([90, 0, 0])
      cylinder(d=set_screw_d, h=housing_W + 2*arch_r + 8*overlap, center=true);
}

module grease_feed_hole() {
  // Vertical grease hole from boss down to bore region
  z1 = z_top + grease_boss_h;
  z0 = arch_axis_z;
  h = (z1 - z0) + 4*overlap;
  translate([0, 0, (z1 + z0)/2])
    cylinder(d=grease_hole_d, h=h, center=true);
}

// ---------- Final Model ----------
module pillow_block_bearing() {
  difference() {
    // ONE connected solid
    union() {
      // base with chamfered edges
      difference() {
        base_solid();
        chamfer_base_edges();
      }

      // housing on top of base (overlapped)
      housing_outer();
    }

    // subtract features
    union() {
      mounting_holes();
      shaft_bore();
      bearing_seat_bore();
      set_screw_hole();
      grease_feed_hole();
      cap_split_groove();
    }
  }
}

pillow_block_bearing();

// Parameters
body_length = 12; //[6:24:1]
body_width = 11; //[6:22:1]
body_height = 6; //[3:12:1]
shaft_diameter = 6; //[3:12:0.5]
shaft_height = 10; //[5:20:1]
collar_diameter = 8; //[4:16:0.5]
collar_height = 2; //[1:6:0.5]
lead_thickness = 0.5; //[0.25:1:0.05]
lead_width = 1; //[0.5:2:0.1]
lead_length = 4; //[2:10:0.5]
lead_pitch = 2.54; //[1.27:5.08:0.01]
lead_row_offset = 1.5; //[0.5:4:0.1]
shaft_flat_depth = 0.8; //[0.2:2:0.1]
shaft_flat_width = 4; //[2:8:0.5]
overlap = 1; //[0.5:2:0.1]
terminal_bend_length = 2; //[1:6:0.5]
anti_rotation_tab_length = 3; //[1.5:8:0.5]
anti_rotation_tab_width = 2; //[1:6:0.5]
anti_rotation_tab_thickness = 1; //[0.5:3:0.5]
mounting_thread_diameter = 7; //[4:14:0.5]
mounting_thread_height = 1.5; //[0.5:4:0.5]
chamfer_amount = 0.6; //[0.2:1.5:0.1]

// Main body with chamfers
module main_body() {
  difference() {
    cube([body_length, body_width, body_height], center=true);
    translate([0, 0, 0])
      cube([body_length - 2*chamfer_amount, body_width - 2*chamfer_amount, body_height - 2*chamfer_amount], center=true);
  }
}

// Bushing collar
module bushing_collar() {
  translate([0, 0, body_height/2 + collar_height/2 - overlap])
    cylinder(h=collar_height, r=collar_diameter/2, center=true);
}

// Shaft with flat
module shaft_with_flat() {
  difference() {
    translate([0, 0, body_height/2 + collar_height + shaft_height/2 - overlap])
      cylinder(h=shaft_height, r=shaft_diameter/2, center=true);
    translate([shaft_diameter/2 - shaft_flat_depth + shaft_diameter/2, 0, body_height/2 + collar_height + shaft_height/2 - overlap])
      cube([shaft_diameter, shaft_flat_width, shaft_height + collar_height + body_height], center=true);
  }
}

// Mounting thread detail
module mounting_thread_detail() {
  translate([0, 0, body_height/2 + mounting_thread_height/2 - overlap])
    cylinder(h=mounting_thread_height, r=mounting_thread_diameter/2, center=true);
}

// Anti-rotation tab
module anti_rotation_tab() {
  translate([collar_diameter/2 + anti_rotation_tab_length/2 - overlap, 0, body_height/2 + anti_rotation_tab_thickness/2 - overlap])
    cube([anti_rotation_tab_length, anti_rotation_tab_width, anti_rotation_tab_thickness], center=true);
}

// Terminals
module terminals() {
  union() {
    translate([body_length/2 + lead_length/2 - overlap, lead_row_offset - lead_pitch, -body_height/2 + lead_thickness/2 + overlap])
      cube([lead_length, lead_width, lead_thickness], center=true);
    translate([body_length/2 + lead_length/2 - overlap, lead_row_offset, -body_height/2 + lead_thickness/2 + overlap])
      cube([lead_length, lead_width, lead_thickness], center=true);
    translate([body_length/2 + lead_length/2 - overlap, lead_row_offset + lead_pitch, -body_height/2 + lead_thickness/2 + overlap])
      cube([lead_length, lead_width, lead_thickness], center=true);
    translate([body_length/2 + lead_thickness/2 - overlap, lead_row_offset - lead_pitch, -body_height/2 - terminal_bend_length/2 + overlap])
      cube([lead_thickness, lead_width, terminal_bend_length], center=true);
    translate([body_length/2 + lead_thickness/2 - overlap, lead_row_offset, -body_height/2 - terminal_bend_length/2 + overlap])
      cube([lead_thickness, lead_width, terminal_bend_length], center=true);
    translate([body_length/2 + lead_thickness/2 - overlap, lead_row_offset + lead_pitch, -body_height/2 - terminal_bend_length/2 + overlap])
      cube([lead_thickness, lead_width, terminal_bend_length], center=true);
    translate([body_length/2 + lead_thickness/2 - overlap, lead_row_offset, -body_height/2 + lead_thickness/2 + overlap])
      cube([lead_thickness, 2*lead_pitch + lead_width, lead_thickness], center=true);
  }
}

// Complete model
module complete_model() {
  union() {
    main_body();
    bushing_collar();
    mounting_thread_detail();
    anti_rotation_tab();
    terminals();
    shaft_with_flat();
  }
}

// Render the complete model
complete_model();

