    polygon(points=[
        [r_root_safe - tooth_overlap, -tooth_root_width/2],
        [r_root_safe - tooth_overlap,  tooth_root_width/2],
        [r_tip_safe,                   tooth_tip_width/2],
        [r_tip_safe,                  -tooth_tip_width/2]
