    intersection() {
        cylinder(r=valley_r, h=pulley_width + 2*union_overlap, center=true);

        linear_extrude(height=pulley_width + 2*union_overlap, center=true, convexity=10)
            polygon(points=[
                [0,0],
                [valley_r*2, 0],
                [valley_r*2*cos(valley_angle/2),  valley_r*2*sin(valley_angle/2)],
                [valley_r*2*cos(valley_angle/2), -valley_r*2*sin(valley_angle/2)]
