}

module side_flange_left() {
  translate([0, 0, -pulley_width/2 + flange_thk/2])
    cylinder(r= pulley_od/2, h= flange_thk, center=true);
}

module side_flange_right() {
  translate([0, 0, pulley_width/2 - flange_thk/2])
    cylinder(r= pulley_od/2, h= flange_thk, center=true);
}

