    // side = +1 (positive Y), -1 (negative Y)
    translate([0,
               side * (rail_width/2 - race_depth),
               -rail_height/2 + race_z])
        rotate([0, 90, 0])
            cylinder(h=rail_length + 2, r=race_r, center=true);
