                cylinder(h=rail_width + 2, d=hole_d, center=true);

        // Counterbore from top face (Z+)
        translate([x, 0, rail_height/2 - csk_h/2])
            rotate([90, 0, 0])
                cylinder(h=rail_width + 2, d=csk_d, center=true);
    }
