        for (i = [0:hole_count-1]) {
            mounting_hole(-rail_L/2 + hole_edge_offset + i*hole_pitch);
        }

        // End chamfers
        end_chamfer(+1);
        end_chamfer(-1);

        // Raceway details (4 grooves: two per side, top/bottom)
        side_raceway(+1, +1);
        side_raceway(+1, -1);
        side_raceway(-1, +1);
        side_raceway(-1, -1);

        // Small top groove
        top_relief_groove();
    }
}

