// uxcell M5x0.8 Right Hand Thread - Self-Lubricating Joint Rod End (Heim Joint)
// STRUCTURAL FIXES:
// - Make it a recognizable rod end: eye housing + spherical ball + integrated threaded shank
// - Ensure EVERYTHING is one connected solid (no floating parts)
// - Recalculate ALL translate() values so shank attaches to the eye with overlap
// - Keep geometry simple/clean; threads simplified

$fn = 128;

// -------------------- Parameters --------------------
overlap = 1.5;                 // 1–2mm overlap to guarantee connectivity
bridge_t = 0.55;               // tiny bridges to fuse ball to race (single solid)

thread_major_d = 5.0;          // M5 major diameter
thread_pitch   = 0.8;          // M5x0.8
thread_len     = 20.0;

shank_plain_d   = 4.6;
shank_plain_len = 2.0;

runout_relief_d   = 4.2;
runout_relief_len = 1.2;

shoulder_d   = 7.0;
shoulder_len = 2.0;

head_od        = 12.0;         // outer diameter of eye
head_thickness = 6.0;          // thickness along shank axis (X)

bore_d       = 5.0;            // bolt hole through eye (Y axis)
bore_chamfer = 0.45;

ball_d      = 8.0;             // spherical ball OD
race_wall_t = 1.6;             // housing wall around ball cavity

edge_chamfer = 0.6;

wrench_flat_width = 6.0;
wrench_flat_len   = 6.0;

dust_seal_t = 0.6;
dust_seal_r = 4.2;

// Eye shaping
eye_flat_width = 10.0;         // across flats (Y direction)
eye_flat_depth = 0.9;          // shave from OD to create flats

// Thread profile (simple printable triangular thread)
thread_depth = 0.32;           // radial depth (approx for M5)
thread_profile_w = 0.38;       // width of triangular ridge at base (2D profile)
thread_slices_per_turn = 28;   // smoothness of helix

// Derived
head_r   = head_od/2;
ball_r   = ball_d/2;
cavity_r = ball_r + race_wall_t;

// -------------------- Helpers --------------------
module cylX(r,h,center=true){ rotate([0,90,0]) cylinder(r=r,h=h,center=center); }
module cylY(r,h,center=true){ rotate([90,0,0]) cylinder(r=r,h=h,center=center); }

module end_chamfer_X(xpos, r){
    translate([xpos,0,0])
        rotate([0,90,0])
            cylinder(h=2*edge_chamfer, r1=r+edge_chamfer, r2=r, center=true);
}

module chamfer_bore_Y(sign=1){
    // conical chamfer at +/-Y face of bore
    translate([0, sign*(head_r - bore_chamfer), 0])
        rotate([90,0,0])
            cylinder(h=2*bore_chamfer, r1=bore_d/2 + bore_chamfer, r2=bore_d/2, center=true);
}

// -------------------- Head (Eye Housing) --------------------
module head_outer(){
    difference(){
        cylX(head_r, head_thickness, center=true);

        // Flats on +/-Y
        for (s=[-1,1]){
            translate([0, s*(head_r - eye_flat_depth/2), 0])
                cube([head_thickness + 2, eye_flat_depth, head_od + 2], center=true);
        }

        // Trim outside desired flat width (keeps flats from becoming too wide)
        for (s=[-1,1]){
            translate([0, s*(eye_flat_width/2 + (head_od-eye_flat_width)/2), 0])
                cube([head_thickness + 2, head_od + 2, head_od + 2], center=true);
        }

        // Edge chamfers on +/-X faces
        for (s=[-1,1]){
            translate([s*(head_thickness/2 - edge_chamfer),0,0])
                rotate([0,90,0])
                    cylinder(h=2*edge_chamfer, r1=head_r+edge_chamfer, r2=head_r, center=true);
        }
    }
}

module head_internal_cuts(){
    union(){
        // Ball cavity
        sphere(r=cavity_r);

        // Through-bore for bolt (Y axis)
        cylY(bore_d/2, head_od + 2, center=true);

        // Bore chamfers
        chamfer_bore_Y(1);
        chamfer_bore_Y(-1);
    }
}

module rod_end_head_housing(){
    difference(){
        head_outer();
        head_internal_cuts();
    }
}

// -------------------- Ball (Spherical Bearing) --------------------
module spherical_ball_with_bore_and_bridges(){
    union(){
        // Ball with through-bore
        difference(){
            sphere(r=ball_r);
            cylY(bore_d/2, ball_d + 2, center=true);
        }

        // Bridges: thin ribs connecting ball to cavity wall (single connected solid)
        // Ensure ribs actually reach into the housing by a small amount.
        rib_len = (cavity_r - ball_r) + bridge_t + 0.2;
        rib_w   = bridge_t;
        rib_h   = bridge_t;

        for (a=[0,90,180,270]){
            rotate([0,a,0])  // around Y
                translate([(ball_r + cavity_r)/2, 0, 0])
                    cube([rib_len, rib_w, rib_h], center=true);
        }
    }
}

// -------------------- Thread (Right-hand external) --------------------
module right_hand_thread_X(major_d, pitch, len, depth, profile_w){
    minor_r = major_d/2 - depth;

    union(){
        // Core cylinder at minor diameter (ensures solid shank)
        cylX(minor_r, len, center=true);

        // Helical ridge
        turns = len / pitch;
        steps = max(ceil(turns * thread_slices_per_turn), 24);

        rotate([0,90,0])  // make extrude axis align to X
            linear_extrude(height=len, twist=turns*360, slices=steps, center=true, convexity=10)
                translate([minor_r, 0, 0])
                    polygon(points=[
                        [0, -profile_w/2],
                        [depth, 0],
                        [0,  profile_w/2]
                    ]);
    }
}

// -------------------- Shank (Male Threaded, INTEGRAL) --------------------
// Build shank in LOCAL coords where x=0 is the head +X face, shank extends +X.
// Then translate so x=0 aligns to global x = +head_thickness/2 with overlap into the head.
module shank_local_solids(){
    x0 = 0;

    // Centers of each segment in LOCAL coords
    x_shoulder_c = x0 + shoulder_len/2;
    x_plain_c    = x0 + shoulder_len + shank_plain_len/2;
    x_runout_c   = x0 + shoulder_len + shank_plain_len + runout_relief_len/2;
    x_thread_c   = x0 + shoulder_len + shank_plain_len + runout_relief_len + thread_len/2;

    union(){
        translate([x_shoulder_c,0,0]) cylX(shoulder_d/2, shoulder_len, center=true);
        translate([x_plain_c,0,0])    cylX(shank_plain_d/2, shank_plain_len, center=true);
        translate([x_runout_c,0,0])   cylX(runout_relief_d/2, runout_relief_len, center=true);
        translate([x_thread_c,0,0])
            right_hand_thread_X(thread_major_d, thread_pitch, thread_len, thread_depth, thread_profile_w);
    }
}

module wrench_flats_cut_local(){
    // Flats near the start of the threaded section (LOCAL coords)
    x_thread_start = shoulder_len + shank_plain_len + runout_relief_len;
    x_flat_c = x_thread_start + wrench_flat_len/2;

    // Cut on +/-Z to create two flats
    for (s=[-1,1]){
        translate([x_flat_c, 0, s*(wrench_flat_width/2 + (thread_major_d - wrench_flat_width)/2)])
            cube([wrench_flat_len + 2, thread_major_d + 2, thread_major_d + 2], center=true);
    }
}

module shank_complete(){
    // CRITICAL CONNECTIVITY FIX:
    // Global head +X face is at +head_thickness/2.
    // Place local x=0 slightly INSIDE the head by 'overlap' so it fuses.
    shank_attach_tx = head_thickness/2 - overlap;

    translate([shank_attach_tx,0,0]){
        difference(){
            shank_local_solids();
            wrench_flats_cut_local();
        }

        // End chamfer at far end of thread (LOCAL coords)
        x_thread_end = shoulder_len + shank_plain_len + runout_relief_len + thread_len;
        x_end = x_thread_end - edge_chamfer;
        end_chamfer_X(x_end, thread_major_d/2);
    }
}

// -------------------- Dust seals (fused to head) --------------------
module dust_seals(){
    // Place seals so they overlap into the head by a small amount
    for (s=[-1,1]){
        translate([s*(head_thickness/2 - dust_seal_t/2 - overlap/2),0,0])
            rotate([0,90,0])
                rotate_extrude(convexity=10)
                    translate([dust_seal_r,0,0])
                        circle(r=dust_seal_t/2);
    }
}

// -------------------- Assembly (ONE connected solid) --------------------
module heim_joint_complete(){
    union(){
        rod_end_head_housing();                 // eye housing
        spherical_ball_with_bore_and_bridges(); // ball fused via bridges
        shank_complete();                       // integral shank (attached with overlap)
        dust_seals();                           // fused to head
    }
}

heim_joint_complete();

// Socket Head Cap Screw — 2.0mm shank dia, 3.8mm head dia, 2.0mm head height, 10mm overall length
// Includes simplified external threads (visual helical ridge) while keeping major diameter = 2.0mm.

$fn = 128;

// Parameters (mm)
shank_d = 2.0;
length  = 10.0;

head_d  = 3.8;
head_h  = 2.0;

// Internal hex socket (across flats) + depth
socket_af    = 1.5;
socket_depth = 1.2;

// Thread (visual approximation)
thread_pitch = 0.40;   // mm per turn (approx for M2)
thread_depth = 0.18;   // radial height of ridge (kept small)
thread_start = 0.35;   // unthreaded lead-in from tip
thread_end   = 0.25;   // unthreaded under-head relief

// Small edge breaks
tip_chamfer_h      = 0.35;
head_top_chamfer_h = 0.20;

// Overlap for robust booleans/unions
overlap = 0.06;

// Derived
shank_h = length - head_h;

// Helpers
function hex_R_from_AF(af) = af / sqrt(3); // circumradius for hex with given across-flats

module hex_prism(af, h) {
    R = hex_R_from_AF(af);
    linear_extrude(height=h, center=false)
        polygon(points=[ for (i=[0:5]) [ R*cos(60*i), R*sin(60*i) ] ]);
}

// Helical ridge thread (unioned onto a core cylinder)
// Major diameter remains shank_d; core is reduced by 2*thread_depth.
module thread_ridge(major_d, pitch, depth, h) {
    core_r = major_d/2 - depth;
    ridge_r = depth;

    // A small circular "wire" swept helically around the core
    // Using twist = 360*h/pitch to get correct pitch.
    linear_extrude(height=h, twist=360*h/pitch, slices=max(24, ceil(h/pitch*24)), center=false)
        translate([core_r, 0, 0])
            circle(r=ridge_r, $fn=24);
}

module screw_body() {
    union() {
        // Threaded shank (connected to head)
        // Core cylinder + helical ridge, both start at z=0.
        thread_h = max(0, shank_h - thread_start - thread_end);

        // Core (minor diameter)
        cylinder(h=shank_h, r=shank_d/2 - thread_depth);

        // Helical ridge (threads) placed between lead-in and under-head relief
        if (thread_h > 0)
            translate([0,0,thread_start])
                thread_ridge(shank_d, thread_pitch, thread_depth, thread_h);

        // Tip chamfer (kept within major diameter)
        cylinder(h=tip_chamfer_h, r1=0, r2=shank_d/2);

        // Head (cylindrical), connected at z=shank_h
        translate([0,0,shank_h - overlap])
            cylinder(h=head_h + overlap, r=head_d/2);

        // Head top chamfer (slight)
        translate([0,0,shank_h + head_h - head_top_chamfer_h])
            cylinder(h=head_top_chamfer_h, r1=head_d/2, r2=max(0.01, head_d/2 - head_top_chamfer_h));
    }
}

module socket_cut() {
    // Internal hex socket recessed from top face
    translate([0,0,shank_h + head_h - socket_depth])
        hex_prism(socket_af, socket_depth + overlap);
}

// Final (one connected solid)
difference() {
    screw_body();
    socket_cut();
}

// Socket Head Cap Screw (M2-like) — 2.0mm shank dia, 3.8mm head dia, 10mm overall length
// One connected solid, cylindrical head with internal hex socket, cylindrical shank with simple helical thread.

$fn = 96;

// -------- Parameters (mm) --------
shank_d        = 2.0;   // major diameter
overall_L      = 10.0;  // total length (top of head to tip)
head_d         = 3.8;   // head diameter
head_h         = 2.0;   // head height

// Socket (internal hex)
socket_af      = 1.5;   // across flats
socket_depth   = 1.2;   // depth from top face

// Thread (simple helical approximation)
thread_L       = 8.0;   // threaded length from tip upward
pitch          = 0.4;   // thread pitch
thread_h       = 0.18;  // radial thread height (visual)
thread_profile_w = 0.22; // profile width (visual)

// Small overlaps to ensure watertight unions/differences
eps            = 0.02;
overlap        = 0.15;

// Derived
shank_L = overall_L - head_h;
head_z0 = 0;                 // head bottom at z=0
head_z1 = head_h;            // head top at z=head_h
shank_z0 = -shank_L;         // shank bottom at z=-shank_L
shank_z1 = 0;                // shank top meets head bottom at z=0

thread_z0 = shank_z0;                         // start at tip
thread_z1 = max(shank_z0, shank_z0 + thread_L); // end upward
thread_len = thread_z1 - thread_z0;

// -------- Helpers --------
module hex_prism_af(af, h, center=false) {
  // Regular hex with given across-flats (af)
  // For a regular hex, across-flats = 2 * apothem; apothem = r*cos(30) => r = af / sqrt(3)
  r = af / sqrt(3);
  cylinder(r=r, h=h, $fn=6, center=center);
}

// -------- Geometry --------
module head_cyl() {
  // Cylindrical socket head
  translate([0,0,head_z0])
    cylinder(d=head_d, h=head_h, center=false);
}

module shank_cyl() {
  // Cylindrical shank (minor diameter base for thread)
  translate([0,0,shank_z0])
    cylinder(d=shank_d - 2*thread_h, h=shank_L, center=false);
}

module thread_helix() {
  // Simple helical ridge around the shank (visual thread)
  // Uses linear_extrude with twist; profile is a small rectangle at radius.
  if (thread_len > 0) {
    turns = thread_len / pitch;
    translate([0,0,thread_z0])
      linear_extrude(height=thread_len, twist=turns*360, slices=max(ceil(turns*40), 40), center=false)
        translate([ (shank_d/2 - thread_h) + thread_h/2, 0, 0 ])
          square([thread_h, thread_profile_w], center=true);
  }
}

module tip_chamfer() {
  // Small chamfer at tip for nicer end
  cham_h = 0.35;
  translate([0,0,shank_z0 - eps])
    cylinder(h=cham_h + eps, r1=(shank_d/2 - thread_h), r2=max((shank_d/2 - thread_h) - 0.25, 0.2), center=false);
}

module socket_recess() {
  // Internal hex socket cut from the top face downward
  translate([0,0,head_z1 - socket_depth - overlap])
    hex_prism_af(socket_af, socket_depth + overlap + eps, center=false);
}

module screw_solid() {
  union() {
    // Ensure head and shank are connected (share plane at z=0) with slight overlap
    union() {
      head_cyl();
      translate([0,0, -overlap]) shank_cyl();
    }

    // Add thread ridge (union) and a small tip chamfer
    thread_helix();
    tip_chamfer();
  }
}

// -------- Final --------
difference() {
  screw_solid();
  socket_recess();
}

$fn = 96;

// Requested dimensions (mm)
shank_d = 2.0;
length_under_head = 10.0;
head_d = 3.5;
head_h = 1.3;

// Simple thread look (cosmetic rings; not a true helix)
thread_pitch = 0.4;
thread_len = 9.0;
thread_depth = 0.12;
thread_ridge_w = 0.18;

// Tip
tip_chamfer_h = 0.5;

// Recess (cylindrical; keep small so head stays dome-like)
drive_recess_d = 1.4;
drive_recess_h = 0.7;

// Connectivity / robustness
overlap = 0.05;

// Derived
shank_r = shank_d/2;
head_r  = head_d/2;

// Coordinate convention:
// z=0 at underside of head (bearing surface)
// shank extends to negative z
// head extends to positive z

module shank_body() {
  translate([0,0,-length_under_head/2])
    cylinder(h=length_under_head, r=shank_r, center=true);
}

module tip_cone() {
  // Cone replaces last tip_chamfer_h of the shank
  translate([0,0,-length_under_head + tip_chamfer_h/2])
    cylinder(h=tip_chamfer_h + overlap, r1=shank_r, r2=0, center=true);
}

module cosmetic_threads() {
  // Rings along the threaded portion (from near tip upward)
  // Threaded region ends at z=0 (under head)
  start_z = -thread_len;
  n = max(1, floor(thread_len/thread_pitch));
  for (i = [0:n-1]) {
    zc = start_z + (i+0.5)*thread_pitch;
    translate([0,0,zc])
      cylinder(h=thread_ridge_w, r=shank_r + thread_depth, center=true);
  }
}

module dome_head() {
  // Spherical cap with exact base diameter head_d at z=0 and height head_h at z=head_h
  // Sphere radius R = (a^2 + h^2)/(2h), center at z = h - R
  a = head_r;
  h = head_h;
  R = (a*a + h*h)/(2*h);
  zc = h - R;

  intersection() {
    translate([0,0,zc]) sphere(r=R);
    // Keep only 0..h
    translate([0,0,h/2]) cube([head_d*2, head_d*2, h], center=true);
  }
}

module drive_recess() {
  // Cylindrical recess from top of head downward
  translate([0,0,head_h - drive_recess_h/2])
    cylinder(h=drive_recess_h + overlap, r=drive_recess_d/2, center=true);
}

module screw_solid() {
  union() {
    shank_body();
    // Ensure tip is connected and replaces end
    tip_cone();
    // Cosmetic threads (connected by overlap with shank)
    cosmetic_threads();
    // Head connected at z=0 with slight overlap into shank
    translate([0,0,-overlap]) dome_head();
  }
}

difference() {
  screw_solid();
  drive_recess();
}

// Socket head cap screw (simplified, no threads)
// Dimensions requested:
// shank dia = 2.5mm, head dia = 4.5mm, head height = 2.5mm, overall length = 10mm

$fn = 96;

// --- Parameters (mm) ---
d_shank   = 2.5;
d_head    = 4.5;
h_head    = 2.5;
L_overall = 10;

socket_hex_af = 2.0;   // internal hex across flats (approx for this size)
socket_depth  = 1.6;   // recess depth

// Small edge treatments
top_chamfer = 0.25;    // head top chamfer height
tip_chamfer = 0.35;    // shank tip chamfer height
eps         = 0.02;    // overlap/robustness

// Derived
L_shank = L_overall - h_head;

// --- Helpers ---
function hex_R_from_AF(af) = af / sqrt(3); // circumradius for regular hex given across-flats

module hex_prism(af, h, center=false) {
    R = hex_R_from_AF(af);
    linear_extrude(height=h, center=center)
        polygon([ for (i=[0:5]) [ R*cos(60*i), R*sin(60*i) ] ]);
}

// --- Main model ---
module socket_head_cap_screw() {
    difference() {
        union() {
            // Head: cylinder with slight top chamfer (frustum)
            translate([0,0,L_shank])
            union() {
                // main head body (minus chamfer height)
                cylinder(h=h_head - top_chamfer, r=d_head/2);

                // top chamfer
                translate([0,0,h_head - top_chamfer])
                    cylinder(h=top_chamfer, r1=d_head/2, r2=max(d_head/2 - top_chamfer, 0.01));
            }

            // Shank: cylinder with slight tip chamfer
            union() {
                // main shank
                cylinder(h=max(L_shank - tip_chamfer, 0), r=d_shank/2);

                // tip chamfer (at bottom end)
                if (tip_chamfer > 0)
                    translate([0,0,max(L_shank - tip_chamfer, 0)])
                        cylinder(h=tip_chamfer, r1=d_shank/2, r2=max(d_shank/2 - tip_chamfer, 0.01));
            }
        }

        // Internal hex socket recess (subtracted from head top)
        // Place so its top is flush with head top surface.
        translate([0,0,L_shank + h_head - socket_depth])
            hex_prism(socket_hex_af, socket_depth + eps, center=false);
    }
}

socket_head_cap_screw();

// Dome head screw (M2.5-ish) — 2.5mm shank dia, 5.35mm head dia, 1.6mm head height, 10mm long
// One connected solid, smooth dome head, visible helical thread, no side protrusions.

$fn = 96;

// -------- Parameters (mm) --------
d_nom   = 2.5;     // shank major diameter
L       = 10;      // length under head
head_d  = 5.35;    // head diameter
head_h  = 1.6;     // head height

// Thread (visual, not ISO-accurate but clearly threaded)
thread_pitch = 0.45;
thread_depth = 0.22;     // radial height of thread above core
thread_width = 0.28;     // bead diameter for thread ridge
thread_start_clear = 0.25; // unthreaded just under head

// Tip
tip_len = 0.7;     // conical tip length
tip_d2  = 0.6;     // tip end diameter

// Drive recess (simple round recess)
recess_d = 2.0;
recess_h = 0.9;

// Small overlaps to guarantee watertight unions/differences
eps = 0.02;
ov  = 0.15;

// -------- Derived --------
r_shank = d_nom/2;
r_head  = head_d/2;

// Core radius so thread ridge reaches ~d_nom
r_core  = max(0.01, r_shank - thread_depth);

// Place head bottom at z=0, head top at z=head_h, shank extends to z=-L
z_head_bot = 0;
z_head_top = head_h;
z_shank_top = z_head_bot;
z_shank_bot = -L;

// Dome: spherical cap that meets the head cylinder at z=head_h with radius head_d/2
// Choose sphere radius R >= r_head; compute center so sphere intersects plane z=head_h at radius r_head.
R_dome = max(r_head + 0.2, 3.2); // keep smooth dome; >= r_head
z_sphere_c = z_head_top - sqrt(max(0, R_dome*R_dome - r_head*r_head));

// -------- Helpers --------
module dome_head_solid() {
    // Cylinder + spherical cap, clipped to head height with a clean underside at z=0
    difference() {
        intersection() {
            union() {
                // head cylinder
                translate([0,0,(z_head_bot+z_head_top)/2])
                    cylinder(h=head_h, r=r_head, center=true);

                // dome sphere
                translate([0,0,z_sphere_c])
                    sphere(r=R_dome);
            }
            // clip to [0, head_h]
            translate([0,0,head_h/2])
                cube([head_d*2, head_d*2, head_h + 2*eps], center=true);
        }

        // drive recess from top
        translate([0,0,z_head_top - recess_h/2 + eps])
            cylinder(h=recess_h + 2*eps, r=recess_d/2, center=true);
    }
}

module shank_core() {
    // Core cylinder (minor diameter) + conical tip, connected to head at z=0
    union() {
        // core cylinder
        translate([0,0,(z_shank_bot + z_shank_top)/2])
            cylinder(h=L + ov, r=r_core, center=true);

        // conical tip at bottom
        translate([0,0,z_shank_bot + tip_len/2])
            cylinder(h=tip_len + ov, r1=r_core, r2=tip_d2/2, center=true);
    }
}

module helical_thread() {
    // Helical ridge made by linear_extrude with twist of a small circle offset from axis.
    // Starts slightly below head to avoid intersecting recess/underside.
    thread_len = max(0.01, L - tip_len - thread_start_clear);
    turns = thread_len / thread_pitch;
    twist = -360 * turns;

    // Start z for thread
    z0 = z_shank_top - thread_start_clear - thread_len;

    translate([0,0,z0])
        linear_extrude(height=thread_len + ov, twist=twist, slices=max(ceil(turns*40), 80), convexity=10)
            translate([r_core + thread_depth, 0, 0])
                circle(d=thread_width, $fn=32);
}

module screw() {
    union() {
        // Head (bottom at z=0)
        dome_head_solid();

        // Shank core (extends down)
        shank_core();

        // Thread ridge (adds visible threads)
        helical_thread();

        // Small neck blend to ensure robust connection between head and shank
        // (kept subtle; does not add side protrusions)
        translate([0,0,z_head_bot - 0.15])
            cylinder(h=0.3 + ov, r1=r_core, r2=r_shank, center=true);
    }
}

// -------- Final --------
screw();

// Pan head screw with threads (ONE connected solid)
// Target dimensions:
// - Shank major Ø2.5
// - Head Ø4.7
// - Head height 1.7
// - Length 10 (under-head)

$fn = 128;

// ---------------- Parameters ----------------
shank_d   = 2.5;   // major diameter
length    = 10;    // under-head length

head_d    = 4.7;
head_h    = 1.7;

// Pan head profile controls (kept within head_h)
head_top_crown_h = 0.55;                 // height of rounded crown above the cylindrical skirt
head_skirt_h     = head_h - head_top_crown_h;

// Phillips recess (simple, consistent from top)
drive_d       = 2.4;   // overall cross width
drive_arm_w   = 0.6;   // arm thickness
drive_depth   = 1.05;  // recess depth (must be < head_h)

// Thread approximation (helical ridge)
pitch         = 0.55;  // mm per turn (approx for M2.5)
thread_h      = 0.22;  // radial height of thread above minor diameter
thread_flat   = 0.18;  // tangential thickness of ridge (controls sharpness)
thread_start_clear = 0.35; // unthreaded length under head
thread_end_clear   = 0.35; // unthreaded at tip

// Tip
tip_chamfer_h = 0.7;
tip_minor_reduction = 0.35; // reduces radius at tip

// Connectivity / robustness
overlap = 0.06;

// Z references (Z=0 at underside of head)
z_head_bottom = 0;
z_head_top    = head_h;
z_shank_top   = z_head_bottom;
z_shank_bot   = z_shank_top - length;

// ---------------- Helpers ----------------
function clamp(x,a,b) = x < a ? a : (x > b ? b : x);

// ---------------- Geometry ----------------
module pan_head_solid() {
  // Pan head: cylindrical skirt + rounded crown (not a ball)
  // Build in Z=[0..head_h]
  r = head_d/2;

  union() {
    // Skirt (straight side)
    translate([0,0,head_skirt_h/2])
      cylinder(h=head_skirt_h, r=r, center=true);

    // Crown: rotate_extrude a smooth arc that stays within head_h
    // Profile in (x,z): from (r, head_skirt_h) to (0, head_h)
    // Use a quarter-circle-like arc for a pan head look.
    rotate_extrude(convexity=10)
      polygon(points=
        concat(
          [[0, head_skirt_h], [r, head_skirt_h]],  // base of crown
          [ for (i=[0:24])
              let(t=i/24)
              // arc: x decreases from r to 0, z increases from head_skirt_h to head_h
              [ r*(1 - t*t), head_skirt_h + head_top_crown_h*(1 - (1-t)*(1-t)) ]
          ],
          [[0, head_h], [0, head_skirt_h]]         // close to axis
        )
      );
  }
}

module phillips_recess() {
  // Cut from top down; centered on axis
  z_center = z_head_top - drive_depth/2;

  translate([0,0,z_center])
    union() {
      cube([drive_d, drive_arm_w, drive_depth + 2*overlap], center=true);
      cube([drive_arm_w, drive_d, drive_depth + 2*overlap], center=true);
    }
}

module threaded_shank() {
  // Approximate external thread as a helical ridge on a minor cylinder.
  // Major diameter remains shank_d (minor is reduced by 2*thread_h).
  major_r = shank_d/2;
  minor_r = major_r - thread_h;

  // Threaded region
  z_thread_top = z_shank_top - thread_start_clear;
  z_thread_bot = z_shank_bot + thread_end_clear;
  thread_len   = z_thread_top - z_thread_bot;

  // Ensure non-negative
  thread_len_ok = thread_len > 0 ? thread_len : 0;

  union() {
    // Minor cylinder for core (full length)
    translate([0,0,(z_shank_top + z_shank_bot)/2])
      cylinder(h=length + overlap, r=minor_r, center=true);

    // Helical ridge (only if there is room)
    if (thread_len_ok > 0.01) {
      turns = thread_len_ok / pitch;
      // Place ridge so it spans exactly the threaded region
      translate([0,0,z_thread_bot - overlap/2])
        linear_extrude(height=thread_len_ok + overlap, twist=turns*360, slices=max(ceil(turns*40), 40), convexity=10)
          translate([minor_r, 0, 0])
            square([thread_h, thread_flat], center=false);
    }

    // Under-head unthreaded major cylinder (short) to look like a proper runout
    // This also guarantees a clean connection to the head.
    translate([0,0,(z_shank_top + (z_shank_top - thread_start_clear))/2])
      cylinder(h=thread_start_clear + overlap, r=major_r, center=true);

    // Tip unthreaded major cylinder (short) before chamfer
    translate([0,0,((z_shank_bot + thread_end_clear) + z_shank_bot)/2])
      cylinder(h=thread_end_clear + overlap, r=major_r, center=true);
  }
}

module tip_chamfer() {
  major_r = shank_d/2;
  r2 = major_r - tip_minor_reduction;

  translate([0,0,z_shank_bot + tip_chamfer_h/2 + overlap/2])
    cylinder(h=tip_chamfer_h + overlap, r1=major_r, r2=r2, center=true);
}

module screw_solid() {
  union() {
    // Head
    pan_head_solid();

    // Shank (threaded) connected at Z=0
    threaded_shank();

    // Tip chamfer connected at end
    tip_chamfer();
  }
}

difference() {
  screw_solid();
  // Drive feature from top
  phillips_recess();
}

// Socket Head Cap Screw (M3-ish) — 3.0mm shank dia, 5.5mm head dia, 3.0mm head height, 10mm overall length

$fn = 96;

// Parameters (mm)
shank_d        = 3.0;
overall_L      = 10.0;   // total length including head
head_d         = 5.5;
head_h         = 3.0;

socket_hex_af  = 2.5;    // across flats
socket_depth   = 2.0;

underhead_fillet_r = 0.25;
head_top_chamfer_h = 0.25;

thread_pitch   = 0.5;    // visual thread
thread_depth   = 0.18;   // radial depth
thread_len     = overall_L - head_h; // threaded length (full shank)

tip_chamfer_h  = 0.4;

eps = 0.02;

// Helpers
function hex_R_from_AF(af) = af / sqrt(3); // circumradius for regular hex with given across-flats

module hex_prism_af(af, h, center=false) {
  r = hex_R_from_AF(af);
  linear_extrude(height=h, center=center)
    polygon([for (i=[0:5]) [r*cos(60*i), r*sin(60*i)]]);
}

// Place head on top of shank: head spans z=[0, head_h], shank spans z=[-thread_len, 0]
module head_solid() {
  // Cylindrical head with slight top chamfer and small underhead fillet
  union() {
    // Main head cylinder
    cylinder(h=head_h, r=head_d/2);

    // Top chamfer (subtract later via difference in final head module)
    // Underhead fillet (adds a small torus-like blend)
    translate([0,0,0])
      rotate_extrude()
        translate([head_d/2 - underhead_fillet_r, 0, 0])
          circle(r=underhead_fillet_r);
  }
}

module head_with_features() {
  difference() {
    head_solid();

    // Top chamfer cut
    translate([0,0,head_h - head_top_chamfer_h])
      cylinder(h=head_top_chamfer_h + eps, r1=head_d/2, r2=max(0.01, head_d/2 - head_top_chamfer_h));

    // Internal hex socket recess (from top)
    translate([0,0,head_h - socket_depth])
      hex_prism_af(socket_hex_af, socket_depth + eps, center=false);
  }
}

module shank_core() {
  // Cylindrical shank (minor diameter core for thread to sit on)
  // Minor diameter approximated as shank_d - 2*thread_depth
  minor_d = max(0.2, shank_d - 2*thread_depth);
  translate([0,0,-thread_len])
    cylinder(h=thread_len, r=minor_d/2);
}

module helical_thread() {
  // Simple visual external thread using linear_extrude with twist
  // Cross-section is a small triangular "tooth" placed at minor radius.
  minor_r = max(0.1, (shank_d/2) - thread_depth);
  turns = thread_len / thread_pitch;
  tooth_w = 0.45 * thread_pitch; // along Z in the extrude direction (2D Y)
  tooth_h = thread_depth;        // radial height (2D X)

  translate([0,0,-thread_len])
    linear_extrude(height=thread_len, twist=turns*360, slices=max(ceil(turns*24), 60), convexity=10)
      translate([minor_r, 0])
        polygon(points=[
          [0, -tooth_w/2],
          [tooth_h, 0],
          [0,  tooth_w/2]
        ]);
}

module tip_chamfer() {
  // Chamfer at the very end of the screw
  translate([0,0,-thread_len])
    cylinder(h=tip_chamfer_h, r1=shank_d/2, r2=max(0.01, shank_d/2 - thread_depth));
}

module screw() {
  union() {
    // Head (z=0..head_h)
    head_with_features();

    // Shank + thread (z=-thread_len..0) with slight overlap into head for watertight union
    union() {
      translate([0,0,-eps]) cylinder(h=eps, r=shank_d/2); // tiny overlap disk into head
      translate([0,0,-thread_len]) cylinder(h=thread_len, r=shank_d/2); // major diameter envelope
      shank_core();
      helical_thread();
      tip_chamfer();
    }
  }
}

