// Socket head cap screw (M3 x 10) - one connected solid
// Dimensions requested: 3.0mm shank diameter, 6.0mm head diameter, 10mm length (under head)

$fn = 120;

// Parameters
d_nom = 3.0;          // shank major diameter
L = 10.0;             // length under head
head_d = 6.0;         // head diameter
head_h = 3.0;         // head height

// Hex socket (approx for M3)
socket_af = 2.5;      // across flats
socket_depth = 1.6;   // depth

// Simple visual thread approximation (helical ridge)
thread_pitch = 0.5;
thread_depth = 0.18;  // radial height of ridge (visual)
thread_len = L;       // threaded length (full length)
tip_chamfer_h = 0.6;  // end chamfer

// Small overlaps to guarantee manifold unions/differences
eps = 0.02;
ov  = 0.15;

// Helpers
function hex_R_from_AF(af) = af / sqrt(3); // circumradius for hex with given across-flats

module hex_socket_cut(af, depth) {
    // Cut from top face downward
    translate([0,0, head_h - depth/2 + ov])
        linear_extrude(height=depth + 2*ov, center=true)
            polygon(points=[
                [ hex_R_from_AF(af)*cos(  0), hex_R_from_AF(af)*sin(  0)],
                [ hex_R_from_AF(af)*cos( 60), hex_R_from_AF(af)*sin( 60)],
                [ hex_R_from_AF(af)*cos(120), hex_R_from_AF(af)*sin(120)],
                [ hex_R_from_AF(af)*cos(180), hex_R_from_AF(af)*sin(180)],
                [ hex_R_from_AF(af)*cos(240), hex_R_from_AF(af)*sin(240)],
                [ hex_R_from_AF(af)*cos(300), hex_R_from_AF(af)*sin(300)]
            ]);
}

module head() {
    // Cylindrical socket head with slight top chamfer
    difference() {
        union() {
            // main head
            cylinder(d=head_d, h=head_h);

            // small underhead fillet-ish ring (kept simple, connected)
            translate([0,0, -ov])
                cylinder(d1=head_d*0.98, d2=d_nom*1.05, h=0.6 + ov);
        }

        // top chamfer (remove a frustum)
        translate([0,0, head_h - 0.35])
            cylinder(d1=head_d + 0.2, d2=head_d - 0.6, h=0.45 + ov);

        // hex socket recess
        hex_socket_cut(socket_af, socket_depth);
    }
}

module shank_core() {
    // Shank starts at z=0 (under head) and goes down to -L
    translate([0,0, -L])
        cylinder(d=d_nom, h=L + ov);
}

module tip_chamfer() {
    // Chamfer at the tip (bottom end)
    translate([0,0, -L - eps])
        cylinder(d1=d_nom, d2=d_nom - 2*0.6, h=tip_chamfer_h + eps);
}

module helical_thread_ridge() {
    // Visual thread ridge: a thin rectangular rib swept helically around the shank
    // Ensures it is connected by overlapping into the shank radius.
    turns = thread_len / thread_pitch;
    rib_w = thread_pitch * 0.45; // along Z per turn (approx)
    rib_t = thread_depth;        // radial thickness

    // Place ridge around radius slightly inside the shank to guarantee union
    r_mid = d_nom/2 - rib_t*0.35;

    translate([0,0, -thread_len])
        linear_extrude(height=thread_len + ov, twist=turns*360, slices=max(40, ceil(turns*40)))
            translate([r_mid, 0, 0])
                square([rib_t*1.2, rib_w], center=true);
}

module screw() {
    union() {
        // Head sits from z=0..head_h
        head();

        // Shank sits from z=0 down to z=-L, with overlap into head
        translate([0,0, -ov])
            shank_core();

        // Thread ridge (visual) on shank
        helical_thread_ridge();

        // Tip chamfer (connected)
        tip_chamfer();
    }
}

screw();

// Dome head screw (button/dome head) with helical threads
// Target: shank Ø3.0, head Ø5.7, head height 1.65, overall length 10.0
// Coordinate system: tip at z=0, underside of head at z=shank_L, top of head at z=screw_L

$fn = 128;

// Parameters
shank_d = 3.0;          // mm (major diameter over threads)
screw_L = 10.0;         // mm (overall length, tip to top of head)
head_d  = 5.7;          // mm
head_h  = 1.65;         // mm

thread_pitch   = 0.5;   // mm
thread_depth   = 0.18;  // mm (radial)
thread_L       = 8.0;   // mm (threaded length from tip upward)
runout_L       = 1.0;   // mm (unthreaded near head)
tip_chamfer_h  = 0.6;   // mm

drive_d     = 2.0;      // mm
drive_depth = 1.0;      // mm

overlap = 0.05;         // mm small overlap to ensure watertight unions

// Derived
shank_r = shank_d/2;
head_r  = head_d/2;

shank_L = screw_L - head_h;                 // length under head (tip to underside of head)
thread_L_eff = min(thread_L, max(0, shank_L - runout_L));
unthread_L = max(0, shank_L - thread_L_eff);

// --- Geometry helpers ---

// Smooth dome head as a spherical cap of height head_h and base radius head_r
// Underside plane at z=0 for this module; top at z=head_h
module dome_head_cap() {
    h = head_h;
    a = head_r;

    // Sphere radius for cap: R = (a^2 + h^2) / (2h)
    R  = (a*a + h*h) / (2*h);
    zc = h - R; // sphere center relative to underside plane

    intersection() {
        translate([0,0,zc]) sphere(r=R);
        // keep only 0..h
        translate([0,0,h/2]) cube([2*head_d, 2*head_d, h], center=true);
    }
}

// Helical thread as a swept triangular ridge around the shank
module helical_thread(len, pitch, major_r, depth) {
    turns = len / pitch;
    linear_extrude(height=len, twist=turns*360,
                   slices=max(ceil(turns*48), 80), convexity=10)
        polygon(points=[
            [major_r - depth, -pitch*0.25],
            [major_r,          0],
            [major_r - depth,  pitch*0.25]
        ]);
}

// --- Main model ---

module screw_solid() {
    minor_r = max(0.01, shank_r - thread_depth);

    union() {
        // Shank core (minor diameter) from tip to underside of head
        cylinder(h=shank_L + overlap, r=minor_r);

        // Tip chamfer on core at z=0
        cylinder(h=tip_chamfer_h, r1=minor_r, r2=0);

        // Threads from tip upward for thread_L_eff
        if (thread_L_eff > 0)
            helical_thread(thread_L_eff + overlap, thread_pitch, shank_r, thread_depth);

        // Unthreaded runout section near head at major diameter
        if (unthread_L > 0)
            translate([0,0,thread_L_eff - overlap])
                cylinder(h=unthread_L + 2*overlap, r=shank_r);

        // Head: underside at z=shank_L, top at z=screw_L
        // Add a thin cylindrical collar at the underside to guarantee a clean, connected interface
        translate([0,0,shank_L - overlap])
            cylinder(h=overlap*2, r=head_r);

        translate([0,0,shank_L])
            dome_head_cap();
    }
}

module drive_recess() {
    // Cylindrical recess from head top down by drive_depth
    translate([0,0,screw_L - drive_depth - overlap])
        cylinder(h=drive_depth + 2*overlap, r=drive_d/2);
}

difference() {
    screw_solid();
    drive_recess();
}

// Parameters
thread_diameter = 3.0; //[1.5:6.0:0.1]
thread_pitch = 0.5; //[0.25:1.0:0.05]
screw_length = 6.0; //[3.0:12.0:0.5]
major_diameter = 3.0; //[1.5:6.0:0.1]
minor_diameter = 2.4; //[1.2:4.8:0.05]
thread_length = 6.0; //[3.0:12.0:0.5]
tip_chamfer = 0.3; //[0.1:0.8:0.05]
socket_af = 1.5; //[0.8:3.0:0.1]
socket_depth = 2.0; //[1.0:4.0:0.1]
overlap = 0.8; //[0.3:2.0:0.1]
thread_runout_length = 0.6; //[0.3:1.5:0.1]
drive_end_chamfer = 0.25; //[0.1:0.8:0.05]
thread_ridge_height = 0.15; //[0.05:0.35:0.01]
thread_ridge_width = 0.25; //[0.1:0.6:0.05]
thread_ridge_count = 10; //[4:24:1]
marking_depth = 0.08; //[0.03:0.2:0.01]
marking_width = 0.3; //[0.15:0.8:0.05]

// Base shapes
module threaded_cylindrical_body() {
  translate([0, 0, 0])
    cylinder(h=thread_length, r=minor_diameter/2, center=true);
}

module thread_ridge(position_index) {
  translate([0, 0, -thread_length/2 + position_index * (thread_length/(thread_ridge_count+1))])
    cylinder(h=thread_ridge_width, r=minor_diameter/2 + thread_ridge_height, center=true);
}

module thread_runout() {
  translate([0, 0, thread_length/2 - thread_runout_length/2 + overlap/2])
    rotate([180, 0, 0])
    cylinder(h=thread_runout_length, r1=minor_diameter/2 + thread_ridge_height, r2=0, center=true);
}

module tip_end() {
  translate([0, 0, -thread_length/2 - tip_chamfer/2 + overlap/2])
    cylinder(h=tip_chamfer, r1=minor_diameter/2, r2=0, center=true);
}

module tip_style_detail() {
  translate([0, 0, -thread_length/2 - tip_chamfer + (minor_diameter/2) - overlap])
    sphere(r=minor_diameter/2, center=true);
}

module drive_end_chamfer_solid() {
  translate([0, 0, thread_length/2 + drive_end_chamfer/2 - overlap/2])
    rotate([180, 0, 0])
    cylinder(h=drive_end_chamfer, r1=minor_diameter/2, r2=0, center=true);
}

module drive_socket() {
  translate([0, 0, thread_length/2 - socket_depth/2 + overlap/2])
    linear_extrude(height=socket_depth + overlap, center=true)
    polygon(points=[
      [socket_af/2, 0],
      [socket_af/4, socket_af*0.4330127019],
      [-socket_af/4, socket_af*0.4330127019],
      [-socket_af/2, 0],
      [-socket_af/4, -socket_af*0.4330127019],
      [socket_af/4, -socket_af*0.4330127019]
    ]);
}

module surface_marking_groove(rotation_angle) {
  translate([0, 0, thread_length/2 - socket_depth - thread_runout_length/2])
    rotate([0, 0, rotation_angle])
    cube([minor_diameter + 2*thread_ridge_height + overlap, marking_width, marking_depth*2], center=true);
}

// Operations
module threaded_body_with_ridges() {
  union() {
    threaded_cylindrical_body();
    for (i = [1:thread_ridge_count])
      thread_ridge(i);
  }
}

module body_with_tip_and_runout() {
  union() {
    threaded_body_with_ridges();
    tip_end();
    tip_style_detail();
    thread_runout();
    drive_end_chamfer_solid();
  }
}

module body_minus_drive_socket() {
  difference() {
    body_with_tip_and_runout();
    drive_socket();
  }
}

module surface_markings() {
  difference() {
    body_minus_drive_socket();
    surface_marking_groove(0);
    surface_marking_groove(90);
  }
}

