drive_mark_d = 1.6;            // top mark diameter
drive_mark_depth = 0.3;        // top mark depth
thread_ring_depth = 0.15;      // decorative ring depth (radial)
thread_ring_width = 0.2;       // decorative ring axial width

// Derived
