// ---------------- Helpers ----------------
module rounded_slot_2d(len, w, r) {
    // 2D rounded rectangle centered at origin
    hull() {
        translate([ len/2 - r, 0]) circle(r=r);
        translate([-len/2 + r, 0]) circle(r=r);
    }
    // expand to width w (ensure r <= w/2)
    offset(delta=max(0, w/2 - r))
        hull() {
            translate([ len/2 - r, 0]) circle(r=r);
            translate([-len/2 + r, 0]) circle(r=r);
        }
