    // Positioned so it overlaps both head underside (z=0) and shank (z<0)
    translate([0,0, 0])
        rotate_extrude($fn=128)
            translate([shank_r + underhead_fillet_radius, 0, 0])
                circle(r=underhead_fillet_radius, $fn=64);
