tip_chamfer_h = 0.8;
tip_chamfer_d_reduction = 1.0;

thread_pitch = 1.0;
thread_depth = 0.45;           // slightly deeper so it reads as a screw in silhouette
thread_length = 9.2;           // keep most of the 10mm shank threaded (simple screw look)

underhead_fillet_r = 0.6;

head_top_chamfer_h = 0.6;
head_top_chamfer_inset = 0.8;

drive_mark_r = 0.6;
drive_mark_depth = 0.25;
drive_mark_offset = 2.2;

overlap = 1.2;                 // robust unions (1–2mm)

// ---------- Derived ----------
head_R = (head_af/2) / cos(30);                 // circumradius for hex (AF -> R)
thread_len_eff = max(0, min(thread_length, shank_L - tip_chamfer_h));  // do not run into chamfer
thread_turns = max(1, thread_len_eff / thread_pitch);

// Coordinate convention:
// z=0 at under-head plane; shank goes to negative z; head goes to positive z.

// ---------- Helpers ----------
module hex_prism(af, h, center=false) {
  R = (af/2) / cos(30);
  linear_extrude(height=h, center=center)
    polygon([ for (i=[0:5]) [ R*cos(60*i), R*sin(60*i) ] ]);
}

// ---------- Parts ----------
module shank_core() {
  // Exact under-head length: z from 0 down to -shank_L
  translate([0,0,-shank_L/2])
    cylinder(h=shank_L, r=shank_d/2, center=true);
}

module tip_chamfer() {
  // Chamfer occupies the last tip_chamfer_h of the shank: z in [-shank_L, -shank_L+tip_chamfer_h]
  translate([0,0,-shank_L + tip_chamfer_h/2])
    cylinder(h=tip_chamfer_h,
             r1=(shank_d - tip_chamfer_d_reduction)/2,
             r2=shank_d/2,
             center=true);
}

module underhead_fillet() {
  // Torus-like fillet centered at z=0 so it intersects both head (z>=0) and shank (z<=0)
  // (rotate_extrude creates a ring in the XY plane around Z)
  translate([0,0,0])
    rotate_extrude()
      translate([shank_d/2 + underhead_fillet_r, 0])
        circle(r=underhead_fillet_r);
}

module hex_head() {
  // Head sits on z=0 plane and extends to +head_h
  translate([0,0,head_h/2])
    hex_prism(head_af, head_h, center=true);
}

module head_top_chamfer_cut() {
  // Subtractive chamfer on top of head; positioned to only affect the top region
  translate([0,0,head_h - head_top_chamfer_h/2 + overlap/2])
    cylinder(h=head_top_chamfer_h + overlap,
             r1=head_R + overlap,
             r2=max(0.01, head_R - head_top_chamfer_inset),
             center=true);
}

module drive_marks_cut() {
  // Shallow circular marks on top face (subtractive)
  zc = head_h - drive_mark_depth/2 + overlap/2;
  for (p = [[ drive_mark_offset, 0],
            [-drive_mark_offset, 0],
            [0,  drive_mark_offset]]) {
    translate([p[0], p[1], zc])
      cylinder(h=drive_mark_depth + overlap, r=drive_mark_r, center=true);
  }
}

module helical_thread_ridge() {
  // Clear, simple helical ridge around the shank to read as "threaded"
  // Built as a twisted extrusion of a small rectangle placed near the shank surface.
  rib_rad = thread_depth;                 // radial thickness of ridge
  rib_ax  = thread_pitch * 0.55;          // axial thickness of ridge section
  r0 = shank_d/2 - rib_rad/2;             // center of rib near shank surface

  // Start at the tip (z=-shank_L) and run upward, stopping before the chamfer region.
  // Add overlap so it fuses into the shank and doesn't leave a gap at either end.
  translate([0,0,-shank_L - overlap/2])
    linear_extrude(height=thread_len_eff + overlap,
                   twist=360*thread_turns,
                   slices=max(ceil(28*thread_turns), 24))
      translate([r0, 0, 0])
        square([rib_rad, rib_ax], center=true);
}

// ---------- Assembly ----------
module screw() {
  difference() {
    union() {
      // Main solids (all connected)
      shank_core();
      tip_chamfer();
      hex_head();
      underhead_fillet();

      // Visible thread feature (intersects shank for a single solid)
      if (thread_len_eff > 0)
        helical_thread_ridge();
    }

    // Subtractive details on head
    head_top_chamfer_cut();
    drive_marks_cut();
  }
}

// ---------- Output ----------
screw();

$fn = 160;

// Target dimensions (mm)
shank_d = 6.0;           // major diameter
screw_L = 10.0;          // length under head (z=0 down to z=-screw_L)
head_d  = 12.0;          // max head diameter
head_h  = 4.75;          // head height (z=0 up to z=head_h)

// Thread (visual, simplified ISO metric-like)
pitch = 1.0;             // coarse-ish for M6 visual
thread_depth = 0.55;     // radial depth (kept modest for robustness)
thread_start = 0.6;      // unthreaded length under head
thread_end_flat = 0.6;   // unthreaded at tip for chamfer/flat

// Pan head shaping
head_crown_h = 1.6;      // rounded crown height (within head_h)
underhead_fillet_r = 0.8;
tip_chamfer_h = 0.8;

// Simple Phillips-like cross recess (approx)
recess_depth = 2.0;
recess_w = 1.6;
recess_len = 7.0;
recess_taper = 0.4;

// Small overlap to guarantee watertight unions/differences
eps = 0.02;

module pan_head_solid() {
    // Head occupies z=[0, head_h]
    skirt_h = max(0.01, head_h - head_crown_h);

    union() {
        // Straight skirt
        translate([0,0,skirt_h/2 - eps])
            cylinder(h=skirt_h + 2*eps, r=head_d/2, center=true);

        // Crown frustum
        top_r = head_d/2 - head_crown_h*0.9;
        top_r = max(top_r, shank_d/2 + 0.6);

        translate([0,0,skirt_h - eps])
            cylinder(h=head_crown_h + 2*eps, r1=head_d/2, r2=top_r, center=false);

        // Spherical cap blended on top
        cap_r = top_r + head_crown_h*0.9;
        translate([0,0,head_h - cap_r + eps])
            intersection() {
                sphere(r=cap_r);
                translate([0,0,cap_r/2])
                    cube([2*head_d, 2*head_d, cap_r], center=true);
            }
    }
}

module underhead_fillet() {
    // Quarter-round fillet between shank and head underside at z=0
    shank_r = shank_d/2;
    rotate_extrude()
        translate([shank_r + underhead_fillet_r, underhead_fillet_r, 0])
            circle(r=underhead_fillet_r);
}

module cross_recess() {
    // Cut from top down into head
    zc = head_h - recess_depth/2;
    h  = recess_depth + 2*eps;

    translate([0,0,zc])
        union() {
            linear_extrude(height=h, center=true,
                          scale=(recess_len - 2*recess_taper)/recess_len)
                square([recess_len, recess_w], center=true);

            rotate([0,0,90])
                linear_extrude(height=h, center=true,
                              scale=(recess_len - 2*recess_taper)/recess_len)
                    square([recess_len, recess_w], center=true);
        }
}

module tip_chamfer_cut() {
    // Subtractive chamfer at the very tip (near z=-screw_L)
    translate([0,0,-screw_L + tip_chamfer_h/2])
        cylinder(h=tip_chamfer_h + 2*eps,
                 r1=shank_d/2 + thread_depth,
                 r2=max(0.01, (shank_d/2 + thread_depth) - tip_chamfer_h),
                 center=true);
}

module threaded_shank_solid() {
    // One connected solid: core cylinder + helical ridge (visual thread)
    shank_r = shank_d/2;
    core_r  = max(0.01, shank_r - thread_depth);

    // Threaded region along z in [-screw_L + thread_end_flat, -thread_start]
    z_top = -thread_start;
    z_bot = -screw_L + thread_end_flat;
    thread_len = max(0.01, z_top - z_bot);

    union() {
        // Core (full length under head)
        translate([0,0,-screw_L/2])
            cylinder(h=screw_L, r=core_r, center=true);

        // Helical ridge (approx triangular section)
        if (thread_len > 0.02) {
            translate([0,0,z_bot])
                linear_extrude(height=thread_len,
                              twist=360*thread_len/pitch,
                              slices=max(24, ceil(thread_len*24)),
                              convexity=10)
                    polygon(points=[
                        [core_r, -pitch*0.22],
                        [shank_r, 0],
                        [core_r,  pitch*0.22]
                    ]);
        }

        // Small unthreaded collar under head to blend into fillet
        // (keeps thread from intersecting the underhead fillet too aggressively)
        collar_h = max(0.01, thread_start);
        translate([0,0,-collar_h/2])
            cylinder(h=collar_h + eps, r=shank_r, center=true);

        // Small unthreaded tip land
        tip_h = max(0.01, thread_end_flat);
        translate([0,0,-screw_L + tip_h/2])
            cylinder(h=tip_h + eps, r=shank_r, center=true);
    }
}

module screw() {
    difference() {
        union() {
            // Head above z=0
            pan_head_solid();

            // Shank below z=0 (connected at z=0)
            threaded_shank_solid();

            // Fillet bridges head underside to shank at z=0
            underhead_fillet();
        }

        // Subtractive features
        cross_recess();
        tip_chamfer_cut();
    }
}

color("Silver") screw();

// Socket Head Cap Screw - M8 x 10 (requested dims)
// Shank Ø8.0, length under head 10.0
// Head Ø13.0, head height 8.0
// One connected solid with a true helical external thread (modeled as a helical ridge)
// and an internal hex socket.

$fn = 160;

// ---- Parameters (mm) ----
shank_d = 8.0;          // major diameter
shank_L = 10.0;         // length under head
head_d  = 13.0;         // head diameter
head_H  = 8.0;          // head height

socket_hex_af = 6.0;    // across flats (approx for M8)
socket_depth  = 5.0;    // socket depth

// Thread (visual but helical and external)
thread_pitch = 1.25;    // M8 coarse
thread_depth = 0.55;    // radial protrusion beyond shank major cylinder (visual)
thread_starts = 1;

// Small overlaps to ensure watertight unions/differences
eps = 0.02;
overlap = 0.25;

// Chamfers
head_top_chamfer_h = 0.8;
tip_chamfer_h      = 0.8;

// ---- Derived Z positions (head on top, shank below) ----
z_head_bot  = 0;
z_head_top  = head_H;
z_shank_top = 0;
z_shank_bot = -shank_L;

// ---- Helpers ----
function hex_R_from_AF(af) = af / sqrt(3); // circumradius for regular hex with given across-flats

module hex_prism(af, h, center=false) {
    R = hex_R_from_AF(af);
    linear_extrude(height=h, center=center)
        polygon(points=[ for (i=[0:5]) [ R*cos(60*i), R*sin(60*i) ] ]);
}

// Helical external thread ridge using rotate_extrude of a small rectangle,
// then linearly extruded with twist to create a true helix.
module helical_thread_ridge(major_d, pitch, length, depth, starts=1) {
    turns = length / pitch;

    // Cross-section of the ridge (in X-Z plane for rotate_extrude):
    // radial thickness = depth, axial thickness = pitch*0.45
    rib_ax = pitch * 0.45;
    rib_rad = max(0.25, depth);

    // Place ridge so its inner face sits at the shank major radius
    r_in = major_d/2 - eps;

    // Build each start as a twisted extrusion of a ring segment
    for (s = [0:starts-1]) {
        rotate([0,0, s*360/starts])
            translate([0,0, z_shank_bot])
                linear_extrude(
                    height = length + overlap,
                    twist  = turns*360,
                    slices = max(ceil(turns*80), 120),
                    convexity = 10
                )
                    rotate_extrude(angle=360, convexity=10)
                        translate([r_in, 0, 0])
                            square([rib_rad, rib_ax], center=false);
    }
}

// ---- Main geometry ----
module screw_body() {
    union() {
        // Shank (major diameter) - centered on shank span
        translate([0,0,(z_shank_bot+z_shank_top)/2])
            cylinder(h=shank_L + overlap, r=shank_d/2, center=true);

        // Head - centered on head span
        translate([0,0,(z_head_bot+z_head_top)/2])
            cylinder(h=head_H + overlap, r=head_d/2, center=true);

        // Head top chamfer
        translate([0,0, z_head_top - head_top_chamfer_h/2])
            cylinder(
                h=head_top_chamfer_h + overlap,
                r1=head_d/2,
                r2=max(head_d/2 - head_top_chamfer_h, shank_d/2),
                center=true
            );

        // Tip chamfer
        translate([0,0, z_shank_bot + tip_chamfer_h/2])
            cylinder(
                h=tip_chamfer_h + overlap,
                r1=shank_d/2,
                r2=max(shank_d/2 - tip_chamfer_h, 0.1),
                center=true
            );

        // External helical thread ridge (true helix)
        helical_thread_ridge(shank_d, thread_pitch, shank_L, thread_depth, thread_starts);
    }
}

module screw_with_socket() {
    difference() {
        screw_body();

        // Hex socket recess from top
        translate([0,0, z_head_top - socket_depth/2 + eps])
            hex_prism(socket_hex_af, socket_depth + overlap, center=true);

        // Small lead-in at socket mouth
        translate([0,0, z_head_top - 0.6/2 + eps])
            cylinder(
                h=0.6 + overlap,
                r1=hex_R_from_AF(socket_hex_af) * 1.10,
                r2=hex_R_from_AF(socket_hex_af),
                center=true
            );
    }
}

// ---- Output ----
screw_with_socket();

// Parameters
thread_major_d = 8; //[4:16:0.1]
length_under_head = 10; //[5:20:0.5]
head_d = 16; //[8:32:0.5]
head_h = 8; //[4:16:0.5]
socket_hex_af = 6; //[3:12:0.1]
socket_depth = 4; //[2:8:0.1]
thread_pitch = 1.25; //[0.5:3:0.05]
overlap = 1; //[0.5:2:0.1]
thread_minor_d = 6.6; //[3.3:13.2:0.1]
thread_relief_d = 7.2; //[3.6:14.4:0.1]
thread_relief_w = 1.2; //[0.6:2.4:0.1]
thread_runout_len = 1.5; //[0.8:3:0.1]
lead_in_len = 1.2; //[0.6:2.4:0.1]
head_top_chamfer_h = 0.8; //[0.4:1.6:0.1]
head_top_chamfer_d2 = 14.4; //[7.2:28.8:0.1]
underhead_fillet_r = 0.8; //[0.4:1.6:0.1]
thread_ring_h = 0.6; //[0.3:1.2:0.05]
