thread_ring_radial = 0.35; //[0.15:0.8:0.05]

// Base Shapes
module socket_head() {
  translate([0, 0, length_under_head + head_h/2 - overlap])
    cylinder(h = head_h, r = head_d/2, center = true);
}

module threaded_shank_core() {
  translate([0, 0, length_under_head/2])
    cylinder(h = length_under_head, r = thread_minor_d/2, center = true);
}

module thread_ring(pos) {
  translate([0, 0, pos])
    cylinder(h = thread_ring_h, r = thread_minor_d/2 + thread_ring_radial, center = true);
}

module thread_rings_union() {
  union() {
    for (i = [0:thread_ring_count-1]) {
      thread_ring(thread_runout_len + (i+0.5)*(length_under_head - thread_runout_len - lead_in_len)/thread_ring_count);
    }
  }
}

module thread_runout() {
  translate([0, 0, length_under_head - thread_runout_len/2])
    cylinder(h = thread_runout_len, r = thread_major_d/2, center = true);
}

module lead_in_chamfer() {
  translate([0, 0, lead_in_len/2])
    cylinder(h = lead_in_len, r1 = thread_major_d/2, r2 = thread_minor_d/2, center = true);
}

module head_top_chamfer() {
  translate([0, 0, length_under_head + head_h - head_top_chamfer_h/2 - overlap])
    cylinder(h = head_top_chamfer_h, r1 = head_d/2, r2 = head_top_chamfer_d2/2, center = true);
}

module underhead_bearing_face() {
  translate([0, 0, length_under_head - overlap/2])
    cylinder(h = overlap, r = head_d/2, center = true);
}

module thread_relief_outer() {
  translate([0, 0, length_under_head - thread_runout_len - thread_relief_w/2])
    cylinder(h = thread_relief_w, r = thread_major_d/2, center = true);
}

module thread_relief_inner() {
  translate([0, 0, length_under_head - thread_runout_len - thread_relief_w/2])
    cylinder(h = thread_relief_w + overlap, r = thread_relief_d/2, center = true);
}

module underhead_fillet_torus() {
  translate([0, 0, length_under_head - underhead_fillet_r])
    rotate_extrude() translate([thread_major_d/2 + underhead_fillet_r, 0])
      circle(r = underhead_fillet_r);
}

module hex_socket_recess() {
  translate([0, 0, length_under_head + head_h - (socket_depth + overlap)/2 - overlap])
    linear_extrude(height = socket_depth + overlap, center = true)
      polygon(points = [
        [socket_hex_af/2, 0],
        [socket_hex_af/4, socket_hex_af*0.4330127019],
        [-socket_hex_af/4, socket_hex_af*0.4330127019],
        [-socket_hex_af/2, 0],
        [-socket_hex_af/4, -socket_hex_af*0.4330127019],
        [socket_hex_af/4, -socket_hex_af*0.4330127019]
      ]);
}

// Operations
module thread_relief_groove() {
  difference() {
    thread_relief_outer();
    thread_relief_inner();
  }
}

module threaded_shank() {
  union() {
    threaded_shank_core();
    thread_rings_union();
    thread_runout();
    lead_in_chamfer();
  }
}

module screw_body_pre_socket() {
  union() {
    socket_head();
    head_top_chamfer();
    underhead_bearing_face();
    threaded_shank();
    underhead_fillet_torus();
  }
}

module screw_body_with_relief() {
  difference() {
    screw_body_pre_socket();
    thread_relief_groove();
  }
}

// Final Model
difference() {
  screw_body_with_relief();
  hex_socket_recess();
}

// Dome head screw: 8.0mm major (thread) diameter, 14.0mm head diameter,
// head height 4.4mm, 10mm under-head length.
// One connected solid, with visible helical threads and an INTERNAL hex socket drive.

$fn = 128;

// -------------------- Parameters --------------------
major_d   = 8.0;     // mm (thread major diameter)
shank_len = 10.0;    // mm (under-head length)
head_d    = 14.0;    // mm
head_h    = 4.4;     // mm

// Thread (visual/printable approximation)
thread_pitch = 1.25; // mm
thread_depth = 0.60; // mm radial depth (major->minor)
thread_len   = 10.0; // mm (threaded length along shank)
tip_chamfer_h = 0.8; // mm

// Underhead blend
underhead_fillet_r = 0.8; // mm

// Drive (internal hex socket)
drive_hex_flat  = 6.0;  // across flats (mm)
drive_depth     = 3.0;  // mm
drive_clearance = 0.2;  // mm

eps = 0.03;

// Dome shaping: spherical cap meeting head_d at z=0 and reaching head_h at top
head_dome_r = (pow(head_d/2,2) + pow(head_h,2)) / (2*head_h);

// -------------------- Helpers --------------------
function clamp(x,a,b) = x < a ? a : (x > b ? b : x);

module hex2d(af=6) {
  // Regular hex with across-flats = af
  r = af / sqrt(3);
  polygon([for(i=[0:5]) [r*cos(60*i), r*sin(60*i)]]);
}

// -------------------- Geometry --------------------
module shank_minor_core(L) {
  // Core at MINOR diameter so threads are clearly visible as raised ridges.
  minor_d = major_d - 2*thread_depth;
  translate([0,0,-L/2])
    cylinder(h=L, r=minor_d/2, center=true);
}

module tip_chamfer_on_minor(L) {
  // Conical tip on the minor core (keeps end neat while threads remain visible)
  minor_d = major_d - 2*thread_depth;
  z0 = -L;
  translate([0,0,z0 + tip_chamfer_h/2])
    cylinder(h=tip_chamfer_h, r1=minor_d/2, r2=0, center=true);
}

module underhead_fillet() {
  // Small fillet between shank and head underside
  rotate_extrude(convexity=10)
    translate([major_d/2 - underhead_fillet_r, 0, 0])
      circle(r=underhead_fillet_r, $fn=64);
}

module dome_head_solid() {
  // Spherical cap from z=0..head_h with base diameter head_d
  zc = -(head_dome_r - head_h);
  intersection() {
    translate([0,0,zc]) sphere(r=head_dome_r, $fn=180);
    translate([0,0,head_h/2]) cylinder(h=head_h, r=head_d/2, center=true);
  }
}

module drive_recess() {
  // Internal hex socket cut from top
  translate([0,0,head_h - drive_depth/2 + eps])
    linear_extrude(height=drive_depth + 2*eps, center=true, convexity=10)
      offset(r=drive_clearance)
        hex2d(drive_hex_flat);
}

module helical_thread(L) {
  // Raised helical ridge around the minor core up to major diameter.
  major_r = major_d/2;
  minor_r = major_r - thread_depth;

  // Thread runs from z=-L .. 0
  translate([0,0,-L])
    linear_extrude(
      height=L,
      twist=360*L/thread_pitch,
      slices=max(ceil(36*L/thread_pitch), 80),
      convexity=10
    )
      // 2D profile: triangular ridge attached to the minor radius
      polygon(points=[
        [minor_r, -thread_pitch*0.28],
        [major_r,  0],
        [minor_r,  thread_pitch*0.28]
      ]);
}

module screw_solid() {
  L = clamp(thread_len, 0, shank_len);

  difference() {
    union() {
      // Threaded shank: minor core + raised helical thread (connected)
      union() {
        shank_minor_core(shank_len);
        tip_chamfer_on_minor(shank_len);
        helical_thread(L);
      }

      // Underhead fillet (touches shank and head)
      underhead_fillet();

      // Dome head (base at z=0)
      dome_head_solid();
    }

    // Internal drive recess
    drive_recess();
  }
}

// -------------------- Output --------------------
screw_solid();

