// Simplified "thread" rings (disabled by default for speed)
enable_thread_rings = false;
thread_L = 10.0;               // mm
thread_pitch = 1.25;           // mm
thread_depth = 0.35;           // mm (radial)
thread_ring_h = 0.35;          // mm (axial thickness of each ring)

drive_hex_AF = 6.0;            // mm
drive_depth = 3.0;             // mm

marking_notch_w = 1.2;         // mm
marking_notch_L = 4.0;         // mm
marking_notch_depth = 0.3;     // mm

// Derived
head_R = head_AF / sqrt(3);
head_top_R2 = (head_AF - 2*head_top_chamfer_inset) / sqrt(3);

z_head_center = 0;
z_head_top = z_head_center + head_H/2;
z_head_bottom = z_head_center - head_H/2;

z_shank_top = z_head_bottom + overlap;
z_shank_bottom = z_shank_top - shank_L;

thread_L_eff = min(thread_L, shank_L);
z_thread_top = z_shank_top;
z_thread_bottom = z_thread_top - thread_L_eff;

// Helpers
module hex_prism(h, af, center=true) {
  cylinder(h=h, r=af/sqrt(3), center=center, $fn=6);
}

module head() {
  union() {
    // Main hex head
    translate([0,0,z_head_center])
      hex_prism(head_H, head_AF, center=true);

    // Top chamfer (frustum)
    translate([0,0,z_head_top - head_top_chamfer_h/2 + overlap/2])
      cylinder(h=head_top_chamfer_h + overlap,
               r1=head_R,
               r2=head_top_R2,
               center=true, $fn=6);

    // Underhead transition (simple taper to shank)
    translate([0,0,z_head_bottom - underhead_taper_h/2 + overlap/2])
      cylinder(h=underhead_taper_h + overlap,
               r1=head_R,
               r2=shank_d/2,
               center=true, $fn=24);
  }
}

module shank() {
  // Simple cylinder at major diameter (fast)
  translate([0,0,(z_shank_top+z_shank_bottom)/2])
    cylinder(h=shank_L, r=shank_d/2, center=true, $fn=32);
}

module tip_chamfer() {
  translate([0,0,z_shank_bottom + tip_chamfer_h/2 - overlap/2])
    cylinder(h=tip_chamfer_h + overlap, r1=shank_d/2, r2=0.25, center=true, $fn=32);
}

// Optional fast "thread" impression: a few thin rings along the shank
module thread_rings() {
  if (!enable_thread_rings) return;
  if (thread_L_eff <= 0) return;

  core_r = shank_d/2 - thread_depth;
  outer_r = shank_d/2;

  n = max(1, floor(thread_L_eff / thread_pitch));
  for (k = [0:n-1]) {
    zc = z_thread_top - (k + 0.5) * thread_pitch;
    if (zc >= z_thread_bottom - thread_pitch/2) {
      translate([0,0,zc])
        difference() {
          cylinder(h=thread_ring_h, r=outer_r, center=true, $fn=24);
          cylinder(h=thread_ring_h + overlap, r=core_r, center=true, $fn=24);
        }
    }
  }
}

module drive_recess_hex() {
  translate([0,0,z_head_top - drive_depth/2 - overlap/2])
    cylinder(h=drive_depth + overlap,
             r=drive_hex_AF/sqrt(3),
             center=true, $fn=6);
}

module marking_notches() {
  translate([0,0,z_head_top - marking_notch_depth/2 - overlap/2]) {
    cube([marking_notch_L, marking_notch_w, marking_notch_depth + overlap], center=true);
    cube([marking_notch_w, marking_notch_L, marking_notch_depth + overlap], center=true);
  }
}

module screw_solid() {
  union() {
    head();
    shank();
    thread_rings();
    tip_chamfer();
  }
}

// Final
difference() {
  screw_solid();
  union() {
    drive_recess_hex();
    marking_notches();
  }
}

// Pan head screw: shank Ø2.2, head Ø4.2, head height 1.7, overall length 10
// One connected solid; all placements derived from dimensions.

$fn = 128;

// ---------------- Parameters ----------------
shank_d = 2.2;          // mm
screw_L = 10;           // mm overall length (tip to head top)
head_d  = 4.2;          // mm
head_h  = 1.7;          // mm

// Drive (simple Phillips-like cross)
drive_d     = 2.0;      // mm
drive_depth = 0.8;      // mm

// Head shaping
head_crown_h = 0.55;       // mm (rounded dome height on top of head)
underhead_fillet_r = 0.25; // mm

// Tip shaping
tip_chamfer_h  = 0.6;   // mm
tip_chamfer_d2 = 1.2;   // mm at very tip

// Thread (lightweight helical ridge)
thread_pitch    = 0.45; // mm
thread_len      = 8.0;  // mm (from near tip upward)
thread_radial_h = 0.18; // mm
thread_tooth_w  = 0.22; // mm
thread_steps    = 220;  // smoother helix

overlap = 0.06;         // small overlap to ensure manifold unions

// ---------------- Derived ----------------
shank_L = screw_L - head_h;   // length below head
z_head_bottom = 0;
z_head_top    = head_h;
z_tip         = -shank_L;

// ---------------- Geometry modules ----------------
module shank_cyl() {
  // Shank from head bottom down to tip
  translate([0, 0, (z_head_bottom + z_tip)/2])
    cylinder(h=shank_L, r=shank_d/2, center=true);
}

module tip_chamfer() {
  // Conical tip at very bottom, connected to shank
  translate([0, 0, z_tip + tip_chamfer_h/2 - overlap/2])
    cylinder(h=tip_chamfer_h + overlap, r1=shank_d/2, r2=tip_chamfer_d2/2, center=true);
}

module pan_head_solid() {
  union() {
    // Main head cylinder
    translate([0, 0, head_h/2])
      cylinder(h=head_h, r=head_d/2, center=true);

    // Rounded crown on top
    hull() {
      translate([0, 0, head_h - overlap])
        cylinder(h=overlap, r=head_d/2, center=false);
      translate([0, 0, head_h + head_crown_h])
        cylinder(h=overlap, r=(head_d*0.55)/2, center=false);
    }

    // Underhead fillet (torus-like blend), overlaps into head and shank
    translate([0, 0, z_head_bottom + underhead_fillet_r - overlap])
      rotate_extrude(convexity=10)
        translate([shank_d/2, 0, 0])
          circle(r=underhead_fillet_r, $fn=64);
  }
}

module drive_recess() {
  // Cross recess cut into head top
  zc = z_head_top - drive_depth/2;
  translate([0, 0, zc])
    union() {
      cube([drive_d, drive_d/4, drive_depth + 2*overlap], center=true);
      cube([drive_d/4, drive_d, drive_depth + 2*overlap], center=true);
    }
}

module head_with_drive() {
  difference() {
    pan_head_solid();
    drive_recess();
  }
}

module thread_tooth_proto() {
  // Small rectangular ridge placed at shank surface
  translate([shank_d/2 + thread_radial_h/2 - overlap, 0, 0])
    cube([thread_radial_h + 2*overlap, thread_tooth_w, thread_pitch*0.6], center=true);
}

module thread_union() {
  // Helical ridge along lower portion of shank
  z0 = z_tip + tip_chamfer_h + thread_pitch*0.25;
  z1 = min(z_tip + thread_len, z_head_bottom - thread_pitch*0.25);
  span = max(0.01, z1 - z0);

  union() {
    for (i = [0:thread_steps-1]) {
      t = i/(thread_steps-1);
      z = z0 + t*span;
      ang = 360 * ((z - z0) / thread_pitch);
      translate([0, 0, z])
        rotate([0, 0, ang])
          thread_tooth_proto();
    }
  }
}

module screw_complete() {
  // Rotate so the screw axis is along X.
  // This makes FRONT/BACK/LEFT/RIGHT orthographic views show the length,
  // while TOP/BOTTOM show the circular head as expected.
  rotate([0, 90, 0])
    union() {
      shank_cyl();
      tip_chamfer();
      head_with_drive();
      thread_union();
    }
}

// ---------------- Render ----------------
color("DimGray") screw_complete();

// Pan head screw: 3.0mm shank dia, 5.5mm head dia, head height 2.0mm, 10mm overall length
// One connected solid, with helical external threads and a Phillips-style cross recess.

$fn = 128;

// -------- Parameters (mm) --------
shank_d = 3.0;
screw_L = 10.0;

head_d = 5.5;
head_h = 2.0;

// Thread (approx M3 coarse)
thread_pitch = 0.5;
thread_major_d = shank_d;      // 3.0
thread_minor_d = 2.4;
thread_L = screw_L - head_h;   // 8.0

// Tip
tip_chamfer_h = 0.6;

// Head shaping
head_crown_h = 0.7;            // domed top height (within head_h)
under_fillet_r = 0.35;         // small under-head fillet

// Drive recess (Phillips-like)
recess_d = 3.0;
recess_depth = 1.2;
recess_arm_w = recess_d/3;

// Quality
thread_slices_per_turn = 28;
overlap = 0.08;

// -------- Coordinate system --------
// Put the screw axis on +Z, with the TOP of the head at z=0.
// This fixes orthographic views (Front/Back/Left/Right show the side profile).
z_head_top  = 0;
z_head_bot  = z_head_top - head_h;
z_tip       = z_head_bot - thread_L;   // bottom end of screw (tip end)

// -------- Helpers --------
module phillips_recess() {
  // Cross recess cut into head from top surface
  translate([0, 0, z_head_top - recess_depth/2 + overlap/2])
  union() {
    cube([recess_d, recess_arm_w, recess_depth + overlap], center=true);
    cube([recess_arm_w, recess_d, recess_depth + overlap], center=true);
  }
}

module pan_head() {
  // Pan head: cylindrical skirt + domed crown + under-head fillet
  union() {
    // Cylindrical skirt (lower part of head)
    translate([0, 0, z_head_bot + (head_h - head_crown_h)/2])
      cylinder(h=head_h - head_crown_h + overlap, r=head_d/2, center=true);

    // Domed crown (top part) as a sphere cap
    translate([0, 0, z_head_top - head_crown_h/2])
      intersection() {
        scale([1, 1, head_crown_h/(head_d/2)]) sphere(r=head_d/2);
        // keep only the lower half of the scaled sphere to form a cap
        translate([0, 0, -head_d]) cube([2*head_d, 2*head_d, 2*head_d], center=true);
      }

    // Under-head fillet (torus-like blend), overlaps into shank region
    translate([0, 0, z_head_bot + under_fillet_r])
      rotate_extrude(angle=360, convexity=10)
        translate([head_d/2 - under_fillet_r, 0, 0])
          circle(r=under_fillet_r, $fn=64);
  }
}

module thread_solid(z0, len, major_d, minor_d, pitch) {
  // Helical external thread approximation using linear_extrude twist of a triangular ridge.
  // z0 is the bottom of the threaded section.
  turns = len / pitch;
  steps = max(12, ceil(turns * thread_slices_per_turn));
  twist_deg = 360 * turns;

  union() {
    // Core (minor diameter)
    translate([0, 0, z0 + len/2])
      cylinder(h=len + overlap, r=minor_d/2, center=true);

    // Helical ridge
    translate([0, 0, z0])
      linear_extrude(height=len + overlap, twist=twist_deg, slices=steps, convexity=10)
        polygon(points=[
          [minor_d/2 - overlap, -pitch*0.18],
          [major_d/2,           0],
          [minor_d/2 - overlap,  pitch*0.18]
        ]);
  }
}

module tip_chamfer(z0) {
  // Conical tip at the end of the threaded section (at the very bottom)
  translate([0, 0, z0 + tip_chamfer_h/2])
    cylinder(h=tip_chamfer_h + overlap, r1=thread_minor_d/2, r2=0, center=true);
}

module screw() {
  difference() {
    union() {
      // Head
      pan_head();

      // Threaded shank: top meets underside of head at z_head_bot (with overlap)
      thread_solid(z_tip, thread_L, thread_major_d, thread_minor_d, thread_pitch);

      // Tip chamfer at the bottom, connected to thread core
      tip_chamfer(z_tip);
    }

    // Drive recess
    phillips_recess();
  }
}

