  union() {
    thread_representation();
    for (i = [1:thread_detail_ridge_count])
      thread_detail_ridge(i);
  }
}

// Screw solid pre-recess
module screw_solid_pre_recess() {
  union() {
    shank();
    head();
    head_to_shank_transition();
    tip_chamfer();
    fillets();
    thread_detail();
