$fn = 96;

// Pan head screw (simplified) per request:
// shank diameter 3.5mm, head diameter 6.7mm, head height 2.2mm, 10mm long (under-head)

shank_d = 3.5;
shank_L = 10;          // under-head length (z from 0 down to -shank_L)

head_d  = 6.7;
head_h  = 2.2;

// Pan head shaping
head_crown_h = 0.7;                 // rounded top height (within head_h)
head_side_h  = head_h - head_crown_h;
head_top_r   = head_d/2 - 0.6;      // slightly smaller top radius for pan profile

// Drive recess (simple Phillips-like cross)
recess_depth = 1.2;
recess_w     = 0.8;
recess_L     = head_d * 0.75;

// Threads (visual, simplified helical ridge)
thread_L = 8.5;                     // threaded length from tip upward
pitch    = 0.7;                     // approx for M3.5
thread_h = 0.25;                    // radial height of ridge
thread_w = 0.35;                    // ridge thickness

// Tip
tip_h = 0.6;

// Connectivity overlap (1–2mm requested)
overlap = 1.0;

// Helpers
function clamp(x,a,b) = x<a ? a : (x>b ? b : x);

// Coordinate convention:
// z=0 at underside of head (bearing surface)
// head spans z=[0, head_h]
// shank spans z=[-shank_L, 0]
// tip extends below shank to z=-(shank_L+tip_h)

module pan_head_solid() {
    union() {
        // cylindrical side portion: z=[0, head_side_h]
        cylinder(h=head_side_h, r=head_d/2, center=false);

        // rounded crown (frustum-like hull): z=[head_side_h, head_h]
        translate([0,0, head_side_h])
            hull() {
                cylinder(h=0.01, r=head_d/2, center=false);
                translate([0,0, head_crown_h])
                    cylinder(h=0.01, r=head_top_r, center=false);
            }

        // smooth dome cap (kept within head height)
        translate([0,0, head_h - head_crown_h*0.35])
            scale([1,1,0.55])
                sphere(r=head_top_r);
    }
}

module drive_recess() {
    // Cut into the top of the head
    translate([0,0, head_h - recess_depth])
        union() {
            cube([recess_L, recess_w, recess_depth + overlap*2], center=false);
            translate([-recess_w/2, -recess_L/2, 0])
                cube([recess_w, recess_L, recess_depth + overlap*2], center=false);
        }
}

module shank_core() {
    // Connected to head underside at z=0, extends down to z=-shank_L with overlap into head
    translate([0,0, -shank_L])
        cylinder(h=shank_L + overlap, r=shank_d/2, center=false); // z=[-shank_L, +overlap]
}

module tip_cone() {
    // Connected to shank end at z=-shank_L, extends to z=-(shank_L+tip_h)
    translate([0,0, -shank_L - tip_h])
        cylinder(
            h=tip_h + overlap, // overlap upward into shank
            r1=clamp(shank_d/2 - 0.8, 0.2, shank_d/2),
            r2=shank_d/2,
            center=false
        );
}

module thread_ridge() {
    // Helical ridge around shank, spanning z=[-thread_L, 0] with overlap into head and downwards
    turns = thread_L / pitch;
    translate([0,0, -thread_L - overlap])
        linear_extrude(
            height=thread_L + overlap*2,
            twist=turns*360,
            slices=max(ceil(turns*40), 80),
            convexity=10
        )
            translate([shank_d/2 + thread_h/2 - 0.05, 0, 0])
                square([thread_h + 0.1, thread_w], center=true);
}

module screw_solid() {
    union() {
        // Head with recess
        difference() {
            pan_head_solid();
            drive_recess();
        }

        // Shank + tip + threads (all connected)
        shank_core();
        tip_cone();
        thread_ridge();
    }
}

color("DimGray") screw_solid();

// Pan head screw - dimensions in mm
// Target: shank Ø4.2, head Ø8.2, head height 3.05, overall length 10 (under-head length)

$fn = 160;

// -------- Parameters --------
shank_d = 4.2;
length  = 10.0;     // under-head length

head_d = 8.2;
head_h = 3.05;

// Pan head profile (rounded dome + small top flat)
top_flat_d = 2.2;   // small flat on top (pan head)
top_flat_h = 0.35;  // thickness of top flat
dome_h     = head_h - top_flat_h; // remaining height for dome

// Under-head fillet (small blend into shank)
under_fillet_h = 0.35;
under_fillet_r = 0.35;

// Tip chamfer
tip_chamfer_h = 0.8;

// Threads (visible, printable approximation)
thread_pitch  = 1.4;
thread_depth  = 0.30;   // radial height of ridge
thread_length = 8.8;    // threaded portion length (<= length)
thread_width  = 0.55;   // tangential width of ridge strip

// Drive recess (hex socket)
drive_hex_flat = 3.0;   // across flats
drive_recess_h = 1.8;

overlap = 0.08;

// -------- Derived --------
shank_r = shank_d/2;
head_r  = head_d/2;

z_tip       = 0;
z_underhead = length;           // underside of head
z_head_top  = length + head_h;

// -------- Helpers --------
module hex_prism(af, h) {
    r = af / sqrt(3); // circumradius from across-flats
    cylinder(h=h, r=r, $fn=6);
}

module pan_head() {
    // Rounded pan head using rotate_extrude profile (no countersink/cone look)
    // Profile is built in XZ plane at y=0, then revolved around Z.
    // Underside at z=z_underhead, top at z=z_head_top.
    union() {
        // Main dome + top flat as a single revolved profile
        translate([0,0,z_underhead])
            rotate_extrude(convexity=10)
                polygon(points=[
                    // start at axis on underside
                    [0, 0],
                    // underside outer edge
                    [head_r, 0],

                    // gentle under-head rounding up a bit (keeps pan head feel)
                    [head_r, under_fillet_h],

                    // dome curve up to start of top flat
                    [head_r*0.92, dome_h*0.55],
                    [head_r*0.70, dome_h*0.85],
                    [top_flat_d/2, dome_h],

                    // top flat
                    [top_flat_d/2, dome_h + top_flat_h],
                    [0, dome_h + top_flat_h]
                ]);

        // Under-head fillet into shank (ensures smooth transition and solid connection)
        // This is a small torus-like blend approximated by hull of two circles revolved.
        translate([0,0,z_underhead - under_fillet_h])
            rotate_extrude(convexity=10)
                polygon(points=[
                    [shank_r, 0],
                    [head_r, under_fillet_h],
                    [head_r, under_fillet_h + overlap],
                    [shank_r, overlap]
                ]);
    }
}

module shank_core() {
    // Core cylinder up to underside of head (connected with slight overlap)
    translate([0,0,z_tip])
        cylinder(h=length + overlap, r=shank_r);
}

module tip_chamfer() {
    // Conical tip at bottom (connected to shank)
    translate([0,0,z_tip])
        cylinder(h=tip_chamfer_h, r1=0, r2=shank_r);
}

module thread_ridge() {
    // Helical ridge around shank (external thread approximation)
    // Use a thin strip swept with twist; positioned so it protrudes beyond shank.
    turns = thread_length / thread_pitch;
    twist_deg = 360 * turns;

    // Start slightly above the very tip to avoid degeneracy
    z0 = tip_chamfer_h * 0.25;
    h  = min(thread_length, length - z0);

    translate([0,0,z0])
        linear_extrude(height=h, twist=twist_deg, slices=max(ceil(turns*60), 120), convexity=10)
            translate([shank_r - thread_depth/2, 0, 0])
                square([thread_depth, thread_width], center=true);
}

module screw_solid() {
    union() {
        shank_core();
        tip_chamfer();
        pan_head();
        thread_ridge();
    }
}

module drive_recess() {
    // Hex socket cut into head from top
    translate([0,0,z_head_top - drive_recess_h])
        hex_prism(drive_hex_flat, drive_recess_h + overlap*2);
}

// -------- Final --------
difference() {
    screw_solid();
    drive_recess();
}

// Lichuan -80M01330B style servo motor (single connected solid)
// Fixes vs prior: correct servo-like form factor with clear front flange + pilot + shaft,
// visible bolt pattern/counterbores, rear connector/boss layout, and side fins.
// All translate() values are dimension-derived (no arbitrary offsets). One connected solid.

$fn = 96;

// ---------- Parameters (mm) ----------
body_L = 120;   // motor length (Z)
body_W = 80;    // motor width  (X)
body_H = 80;    // motor height (Y)

flange_W = 90;
flange_H = 90;
flange_t = 6;

pilot_d = 50;
pilot_h = 2.5;

mount_hole_d = 6.6;
mount_hole_spacing_X = 70;
mount_hole_spacing_Y = 70;
mount_counterbore_d = 11;
mount_counterbore_h = 2.2;

shaft_d = 19;
shaft_L = 40;
shaft_shoulder_d = 22;
shaft_shoulder_L = 5;
shaft_flat_depth = 1.0;
shaft_flat_L = 25;

oil_seal_ring_od = 32;
oil_seal_ring_id = 22;
oil_seal_ring_t = 2;

rear_boss_W = 45;
rear_boss_H = 35;
rear_boss_L = 18;

cable_stub_d = 12;
cable_stub_L = 20;

rear_pin_d = 2;
rear_pin_L = 6;
rear_pin_spacing = 5;

corner_fillet_r = 3.5;

// Cooling fins
fin_t = 2.2;        // fin thickness along Z
fin_depth = 2.0;    // protrusion from side faces (X)
fin_pitch = 8;
fin_span = 0.78;    // fraction of body_L covered by fins

// Front face details
front_step_inset = 6;
front_step_t = 2.5;
front_ring_od = 62;
front_ring_id = 52;
front_ring_t = 1.8;

// Side connector block
conn_W = 22;        // along Y
conn_H = 14;        // along Z
conn_L = 18;        // along X (sticks out)
conn_offset_Y = 0.22; // fraction of body_H from center toward +Y

overlap = 1;

// ---------- Helpers ----------
module rounded_box(size=[10,10,10], r=2) {
  minkowski() {
    cube([max(0.01,size[0]-2*r), max(0.01,size[1]-2*r), max(0.01,size[2]-2*r)], center=true);
    sphere(r=r);
  }
}

module oil_seal_ring() {
  difference() {
    cylinder(d=oil_seal_ring_od, h=oil_seal_ring_t, center=true);
    cylinder(d=oil_seal_ring_id, h=oil_seal_ring_t + 2*overlap, center=true);
  }
}

module shaft_with_flat() {
  difference() {
    cylinder(d=shaft_d, h=shaft_L, center=true);
    // Flat on +X side, near the tip (front)
    translate([shaft_d/2 - shaft_flat_depth/2, 0, shaft_L/2 - shaft_flat_L/2])
      cube([shaft_d, shaft_d, shaft_flat_L], center=true);
  }
}

// ---------- Main Parts ----------
module housing() {
  rounded_box([body_W, body_H, body_L], r=corner_fillet_r);
}

module cooling_fins() {
  fin_len = body_L * fin_span;
  n = max(1, floor(fin_len / fin_pitch));
  z0 = -fin_len/2 + fin_pitch/2;

  for (i=[0:n-1]) {
    zpos = z0 + i*fin_pitch;

    // +X fins
    translate([ body_W/2 + fin_depth/2 - overlap, 0, zpos ])
      cube([fin_depth, body_H*0.92, fin_t], center=true);

    // -X fins
    translate([ -body_W/2 - fin_depth/2 + overlap, 0, zpos ])
      cube([fin_depth, body_H*0.92, fin_t], center=true);
  }
}

module front_flange_with_features() {
  // Flange plate with bolt holes + counterbores + recessed step + front ring
  difference() {
    union() {
      // Main flange
      cube([flange_W, flange_H, flange_t], center=true);

      // Front step pad (on front face)
      translate([0,0, flange_t/2 + front_step_t/2 - overlap])
        cube([flange_W - 2*front_step_inset, flange_H - 2*front_step_inset, front_step_t], center=true);

      // Front ring around pilot (raised)
      translate([0,0, flange_t/2 + front_step_t + front_ring_t/2 - overlap])
        difference() {
          cylinder(d=front_ring_od, h=front_ring_t, center=true);
          cylinder(d=front_ring_id, h=front_ring_t + 2*overlap, center=true);
        }
    }

    // Through holes (go through entire flange stack)
    hole_stack_h = flange_t + front_step_t + front_ring_t + 6*overlap;
    for (sx=[-1,1], sy=[-1,1]) {
      translate([sx*mount_hole_spacing_X/2, sy*mount_hole_spacing_Y/2, 0])
        cylinder(d=mount_hole_d, h=hole_stack_h, center=true);
    }

    // Counterbores on the front side (within step region)
    for (sx=[-1,1], sy=[-1,1]) {
      translate([sx*mount_hole_spacing_X/2, sy*mount_hole_spacing_Y/2,
                 flange_t/2 + front_step_t/2]) // centered in step thickness
        cylinder(d=mount_counterbore_d, h=mount_counterbore_h, center=true);
    }
  }
}

module pilot_and_seal() {
  union() {
    // Pilot boss (front)
    cylinder(d=pilot_d, h=pilot_h, center=true);

    // Oil seal ring slightly behind pilot (still on front side)
    translate([0,0, -pilot_h/2 - oil_seal_ring_t/2 + overlap])
      oil_seal_ring();
  }
}

module rear_boss_and_connector() {
  union() {
    // Rear boss block
    cube([rear_boss_W, rear_boss_H, rear_boss_L], center=true);

    // Connector block on +X side of rear boss (connected)
    translate([
      rear_boss_W/2 + conn_L/2 - overlap,
      (conn_offset_Y*body_H),
      0
    ])
      rounded_box([conn_L, conn_W, conn_H], r=min(2, min(conn_L, min(conn_W, conn_H))/5));

    // Cable stub exiting connector (+X direction), connected
    translate([
      rear_boss_W/2 + conn_L - overlap + cable_stub_L/2 - overlap,
      (conn_offset_Y*body_H),
      0
    ])
      rotate([0,90,0]) cylinder(d=cable_stub_d, h=cable_stub_L, center=true);

    // Rear alignment pins on rear face (Z-), connected
    for (sx=[-1,1], sy=[-1,1]) {
      translate([sx*rear_pin_spacing, sy*rear_pin_spacing, -rear_boss_L/2 - rear_pin_L/2 + overlap])
        cylinder(d=rear_pin_d, h=rear_pin_L, center=true);
    }
  }
}

// ---------- Assembly ----------
module servo_motor() {
  union() {
    // Body + fins
    housing();
    cooling_fins();

    // Front flange at +Z end of body
    translate([0,0, body_L/2 + flange_t/2 - overlap])
      front_flange_with_features();

    // Pilot + seal in front of flange
    translate([0,0, body_L/2 + flange_t + pilot_h/2 - overlap])
      pilot_and_seal();

    // Shaft shoulder in front of flange
    translate([0,0, body_L/2 + flange_t + shaft_shoulder_L/2 - overlap])
      cylinder(d=shaft_shoulder_d, h=shaft_shoulder_L, center=true);

    // Main shaft in front of shoulder
    translate([0,0, body_L/2 + flange_t + shaft_shoulder_L + shaft_L/2 - overlap])
      shaft_with_flat();

    // Rear boss + connector at -Z end of body
    translate([0,0, -body_L/2 - rear_boss_L/2 + overlap])
      rear_boss_and_connector();
  }
}

// ---------- Output ----------
color([0.15, 0.2, 0.35]) servo_motor();

// Lichuan -80M02430B style servo motor (parametric, connected solid)
// Fixes:
// - Adds clearer rear housing + connector layout (two stacked boxes on one side)
// - Adds front-side small terminal/feature block (as seen in orthographic views)
// - Adds rear face pilot ring + center bore on rear (typical encoder/shaft stub detail)
// - Ensures ALL parts are connected via formula-based placement with overlap
// - Keeps ONE connected solid; no text/labels

$fn = 96;

// -------------------- Parameters --------------------
body_size = 80;                 //[40:160:1]  // square body width/height (X/Y)
body_length = 110;              //[55:220:1]  // main body length (Z)

body_corner_r = 2;              //[0:6:0.5]

front_face_thickness = 8;       //[4:16:1]    // front flange thickness (Z)
flange_size = 90;               //[60:130:1]  // front flange square size (X/Y)
flange_corner_r = 6;            //[0:12:0.5]  // flange corner rounding

pilot_diameter = 55;            //[27.5:110:0.5]
pilot_height = 2;               //[1:6:0.5]

mount_hole_diameter = 6.6;      //[3.3:13.2:0.1]
mount_hole_spacing = 65;        //[32.5:130:0.5]
mount_hole_boss_d = 14;         //[8:24:0.5]  // raised bosses around holes
mount_hole_boss_h = 2;          //[0:6:0.5]

shaft_diameter = 19;            //[9.5:38:0.5]
shaft_length = 40;              //[20:80:1]
shaft_step_diameter = 14;       //[7:28:0.5]
shaft_step_length = 10;         //[4:25:1]
shaft_thread_diameter = 10;     //[5:20:0.5]
shaft_thread_depth = 12;        //[6:25:1]

keyway_width = 5;               //[2:10:0.5]
keyway_depth = 2;               //[1:5:0.5]
keyway_length = 25;             //[10:60:1]

// Rear housing (encoder/brake area)
rear_encoder_diameter = 50;     //[25:100:0.5]
rear_encoder_length = 35;       //[18:70:1]
rear_cap_diameter = 56;         //[30:110:0.5]
rear_cap_length = 6;            //[2:15:0.5]

// Rear face pilot ring + center bore (visual identifying feature)
rear_pilot_diameter = 40;       //[20:80:0.5]
rear_pilot_height = 2;          //[1:6:0.5]
rear_center_bore_d = 8;         //[3:16:0.5]
rear_center_bore_depth = 6;     //[2:15:0.5]

// Rear connector boxes (stacked) on one side of rear housing
rear_connector_box_w = 28;      //[14:56:1]   // X (outward from motor)
rear_connector_box_h = 18;      //[9:36:1]    // Z
rear_connector_box_d = 16;      //[8:32:1]    // Y
rear_connector_standoff = 6;    //[3:15:1]    // gap from encoder cylinder surface (still connected via bridge)

// Bridge from encoder cylinder to connector boxes (ensures robust connectivity)
rear_connector_bridge_w = 8;    //[4:16:1]
rear_connector_bridge_h = 14;   //[6:28:1]
rear_connector_bridge_d = 12;   //[6:24:1]

// Front-side small feature block (seen as small tab in front/back views)
front_side_block_w = 8;         //[4:20:1]    // X outward
front_side_block_d = 10;        //[4:25:1]    // Y
front_side_block_h = 10;        //[4:25:1]    // Z
front_side_block_z = 0;         // centered on flange/body mid by default

// Cooling fins (small ribs on one side)
cooling_fin_count = 8;          //[0:16:1]
cooling_fin_thickness = 2;      //[1:5:0.5]  // Z thickness of each rib
cooling_fin_height = 2;         //[0:6:0.5]  // X protrusion
cooling_fin_margin = 10;        //[5:25:1]   // Z margin from ends

overlap = 1;                    //[0.5:2:0.1]

// -------------------- Helpers --------------------
module rounded_square_prism(size=[10,10,10], r=2, center=true) {
  // Minkowski rounded rectangle prism (kept modest for performance)
  minkowski() {
    cube([max(0.01,size[0]-2*r), max(0.01,size[1]-2*r), size[2]], center=center);
    cylinder(r=r, h=0.01, center=true);
  }
}

// -------------------- Main solids --------------------
module motor_body_housing() {
  rounded_square_prism([body_size, body_size, body_length], r=body_corner_r, center=true);
}

module front_flange() {
  translate([0,0, body_length/2 + front_face_thickness/2 - overlap])
    rounded_square_prism([flange_size, flange_size, front_face_thickness], r=flange_corner_r, center=true);
}

module front_mount_bosses() {
  for (sx = [-1,1], sy = [-1,1]) {
    translate([sx*mount_hole_spacing/2, sy*mount_hole_spacing/2,
               body_length/2 + front_face_thickness - mount_hole_boss_h/2 - overlap])
      cylinder(r=mount_hole_boss_d/2, h=mount_hole_boss_h, center=true);
  }
}

module front_pilot_register() {
  translate([0, 0, body_length/2 + front_face_thickness - pilot_height/2 - overlap])
    cylinder(r=pilot_diameter/2, h=pilot_height, center=true);
}

module output_shaft() {
  union() {
    // Main shaft
    translate([0,0, body_length/2 + front_face_thickness + shaft_length/2 - overlap])
      cylinder(r=shaft_diameter/2, h=shaft_length, center=true);

    // Reduced step at tip
    translate([0,0, body_length/2 + front_face_thickness + shaft_length - shaft_step_length/2 - overlap])
      cylinder(r=shaft_step_diameter/2, h=shaft_step_length, center=true);

    // Threaded portion (visual)
    translate([0,0, body_length/2 + front_face_thickness + shaft_length - shaft_thread_depth/2 - overlap])
      cylinder(r=shaft_thread_diameter/2, h=shaft_thread_depth, center=true);
  }
}

module rear_encoder_housing() {
  union() {
    // Encoder cylinder
    translate([0,0, -body_length/2 - rear_encoder_length/2 + overlap])
      cylinder(r=rear_encoder_diameter/2, h=rear_encoder_length, center=true);

    // Rear cap
    translate([0,0, -body_length/2 - rear_encoder_length - rear_cap_length/2 + overlap])
      cylinder(r=rear_cap_diameter/2, h=rear_cap_length, center=true);

    // Rear face pilot ring (on very back face)
    translate([0,0, -body_length/2 - rear_encoder_length - rear_cap_length + rear_pilot_height/2 + overlap])
      cylinder(r=rear_pilot_diameter/2, h=rear_pilot_height, center=true);
  }
}

module rear_connectors() {
  // Place on +X side of rear encoder area, with a bridge to guarantee connection.
  // Z center aligned to encoder cylinder center.
  zc = -body_length/2 - rear_encoder_length/2 + overlap;

  // X positions derived from encoder radius and standoff; bridge spans from cylinder surface to box.
  x_cyl_surface = rear_encoder_diameter/2;
  x_bridge_c = x_cyl_surface + rear_connector_bridge_w/2 - overlap;
  x_box_c = x_cyl_surface + rear_connector_standoff + rear_connector_box_w/2 - overlap;

  union() {
    // Bridge block (touches cylinder and box)
    translate([x_bridge_c, 0, zc])
      cube([rear_connector_bridge_w, rear_connector_bridge_d, rear_connector_bridge_h], center=true);

    // Main connector box
    translate([x_box_c, 0, zc])
      cube([rear_connector_box_w, rear_connector_box_d, rear_connector_box_h], center=true);

    // Secondary smaller box stacked/offset, connected to main box
    translate([
      x_box_c - rear_connector_box_w*0.05, // slight shift but still connected
      rear_connector_box_d/2 + (rear_connector_box_d*0.9)/2 - overlap,
      zc
    ])
      cube([rear_connector_box_w*0.8, rear_connector_box_d*0.9, rear_connector_box_h*0.8], center=true);
  }
}

module front_side_feature_block() {
  // Small block on the side near the front flange (seen as a small tab in orthographic views).
  // Attach to +X side of flange/body region.
  x_c = flange_size/2 + front_side_block_w/2 - overlap;
  z_c = body_length/2 + front_face_thickness/2 + front_side_block_z - overlap;
  translate([x_c, 0, z_c])
    cube([front_side_block_w, front_side_block_d, front_side_block_h], center=true);
}

module cooling_fins() {
  // Side ribs along +X side of main body, connected to body
  if (cooling_fin_count > 0)
  union() {
    fin_span = body_length - 2*cooling_fin_margin;
    for (i = [0:cooling_fin_count-1]) {
      zpos = -body_length/2 + cooling_fin_margin + fin_span*((i+0.5)/cooling_fin_count);
      translate([body_size/2 + cooling_fin_height/2 - overlap, 0, zpos])
        cube([cooling_fin_height, body_size, cooling_fin_thickness], center=true);
    }
  }
}

// -------------------- Subtractions --------------------
module mounting_holes_pattern() {
  for (sx = [-1,1], sy = [-1,1]) {
    translate([sx*mount_hole_spacing/2, sy*mount_hole_spacing/2,
               body_length/2 + front_face_thickness/2 - overlap])
      cylinder(r=mount_hole_diameter/2,
               h=front_face_thickness + pilot_height + overlap*6,
               center=true);
  }
}

module shaft_keyway_cut() {
  zc = body_length/2 + front_face_thickness + keyway_length/2 - overlap;
  translate([0, (shaft_diameter/2 - keyway_depth/2), zc])
    cube([keyway_width, keyway_depth, keyway_length + overlap*4], center=true);
}

module shaft_center_bore_cut() {
  bore_r = max(1, shaft_thread_diameter/2 - 2);
  bore_h = shaft_thread_depth + overlap*6;
  translate([0,0, body_length/2 + front_face_thickness + shaft_length - shaft_thread_depth/2 - overlap])
    cylinder(r=bore_r, h=bore_h, center=true);
}

module rear_center_bore_cut() {
  // Bore into rear pilot/cap (visual)
  zc = -body_length/2 - rear_encoder_length - rear_cap_length + rear_center_bore_depth/2 + overlap;
  translate([0,0, zc])
    cylinder(r=rear_center_bore_d/2, h=rear_center_bore_depth + overlap*6, center=true);
}

// -------------------- Assembly --------------------
module motor_solid_pre_subtract() {
  union() {
    motor_body_housing();
    front_flange();
    front_mount_bosses();
    front_pilot_register();
    output_shaft();

    rear_encoder_housing();
    rear_connectors();

    front_side_feature_block();
    cooling_fins();
  }
}

module motor_final() {
  difference() {
    motor_solid_pre_subtract();
    mounting_holes_pattern();
    shaft_keyway_cut();
    shaft_center_bore_cut();
    rear_center_bore_cut();
  }
}

motor_final();

// Lichuan -80M03530B style servo motor (parametric, single connected solid)
// Fixes:
// - Adds recognizable servo features: front face step, pilot, 4-hole flange, shaft w/ flat,
//   rear register + center boss, rear connector/strain relief, top cap + rear cap,
//   side nameplate pad/recess, side ribs/rails, top grooves (so top view isn't a black square).
// - All translate() values are formula-based (no arbitrary offsets).
// - ONE connected solid ensured via controlled overlaps.
// - No text/labels.

$fn = 96;

// -------------------- Parameters --------------------
body_size = 80;            //[40:160:1]  // square cross-section (X,Z)
body_length = 110;         //[55:220:1]  // along Y
body_corner_r = 3;         //[1.5:6:0.5]

// Front flange / face
front_flange_size = 90;    //[45:180:1]
front_flange_thk = 6;      //[3:12:0.5]
front_face_thk = 1.5;      //[0.8:3:0.1]

// Mounting pattern (through flange)
mount_hole_spacing = 70;   //[35:140:1]
mount_hole_d = 6.6;        //[3.3:13.2:0.1]
mount_hole_csk_d = 10.5;   //[6:18:0.1]  // shallow counterbore look
mount_hole_csk_depth = 1.2;//[0:3:0.1]

// Pilot + shaft
pilot_d = 50;              //[25:100:0.5]
pilot_len = 2;             //[1:4:0.25]

shaft_d = 19;              //[9.5:38:0.5]
shaft_len = 35;            //[17.5:70:1]
shaft_shoulder_d = 28;     //[14:56:0.5]
shaft_shoulder_len = 5;    //[2.5:10:0.5]
shaft_flat_depth = 1.5;    //[0.5:3:0.1]
shaft_flat_width = 8;      //[4:16:0.5]

// Rear features
rear_register_d = 22;      //[10:40:0.5]
rear_register_len = 4;     //[2:10:0.5]
rear_center_boss_d = 12;   //[6:24:0.5]
rear_center_boss_len = 6;  //[3:16:0.5]

// Rear connector housing (cable exit)
conn_w = 22;               //[10:40:1]   // X
conn_h = 14;               //[6:30:1]    // Z
conn_len = 18;             //[8:40:1]    // Y
conn_offset_z = -body_size*0.18; // down a bit like many servos
conn_lip = 1.2;            //[0.5:3:0.1]
conn_side_offset_x = 0;    // keep centered; can be adjusted if needed

// Side rails / ribs
rail_thk = 2.2;            //[1:5:0.1]
rail_inset = 0.6;          //[0:2:0.1]

// Cooling fins (side)
fin_count = 6;             //[0:12:1]
fin_thk = 1.4;             //[0.8:3:0.1]
fin_depth = 2.2;           //[1:5:0.25]
fin_span = 0.78;           //[0.5:0.95:0.01] // fraction of body_length

// Nameplate pad/recess (no text)
plate_h = body_size*0.34;
plate_depth = 0.8;         //[0.2:2:0.1]
plate_y_span = body_length*0.22;

// Top view detail: grooves + cap
top_cap_thk = 2.0;         //[0:5:0.1]
top_cap_inset = 2.0;       //[0:6:0.1]
top_groove_count = 3;      //[0:6:1]
top_groove_w = body_size*0.10;
top_groove_d = 0.9;        //[0:2:0.1]
top_groove_len = body_length*0.62;

// Rear cap / housing step
rear_cap_thk = 2.0;        //[0:6:0.1]
rear_cap_inset = 1.5;      //[0:6:0.1]
rear_cap_height = body_size*0.55; // Z size of rear cap block

overlap = 1;               //[0.5:2:0.1]

// -------------------- Helpers --------------------
module rounded_box(size=[10,10,10], r=1, center=true) {
    // Minkowski rounded cube (keep r modest for performance)
    minkowski() {
        cube([max(size[0]-2*r, 0.01), max(size[1]-2*r, 0.01), max(size[2]-2*r, 0.01)], center=center);
        sphere(r=r);
    }
}

module mount_hole_through(x, z) {
    // Through hole along Y through flange+face
    translate([x, body_length/2 + front_flange_thk/2 - overlap, z])
        rotate([90, 0, 0])
            cylinder(r=mount_hole_d/2, h=front_flange_thk + front_face_thk + overlap*8, center=true);
}

module mount_hole_counterbore(x, z) {
    // Shallow counterbore on outer flange face (front side)
    // Place centered within flange thickness near its front face.
    translate([x,
               body_length/2 + front_flange_thk - mount_hole_csk_depth/2 - overlap,
               z])
        rotate([90, 0, 0])
            cylinder(r=mount_hole_csk_d/2, h=mount_hole_csk_depth + overlap*2, center=true);
}

module mounting_holes_pattern() {
    for (sx = [-1, 1], sz = [-1, 1]) {
        mount_hole_through(sx*mount_hole_spacing/2, sz*mount_hole_spacing/2);
        if (mount_hole_csk_depth > 0)
            mount_hole_counterbore(sx*mount_hole_spacing/2, sz*mount_hole_spacing/2);
    }
}

module shaft_flat_cut() {
    // Flat on shaft (D-shaft). Cut aligned to +Z side.
    translate([0,
               body_length/2 + front_flange_thk + shaft_shoulder_len + shaft_len/2 - overlap,
               shaft_d/2 - shaft_flat_depth])
        cube([shaft_flat_width, shaft_len*0.85, shaft_flat_depth*2 + overlap*2], center=true);
}

// -------------------- Main solids --------------------
module motor_body() {
    // Main housing
    rounded_box([body_size, body_length, body_size], r=body_corner_r, center=true);
}

module edge_rails() {
    // Long rails on left/right edges (break up silhouette)
    rail_len = body_length*0.96;
    rail_h = body_size*0.06;

    for (sx = [-1, 1]) {
        for (sz = [-1, 1]) {
            translate([sx*(body_size/2 - rail_thk/2 - rail_inset),
                       0,
                       sz*(body_size/2 - rail_h/2 - rail_inset)])
                cube([rail_thk, rail_len, rail_h], center=true);
        }
    }
}

module cooling_fins() {
    // Subtle fins on both sides, distributed along Z
    if (fin_count > 0) {
        fin_len = body_length*fin_span;
        fin_h = body_size*0.07;
        for (i = [0:fin_count-1]) {
            zpos = ((i/(max(fin_count-1,1))) - 0.5) * body_size*0.62;

            // Right side fins
            translate([ body_size/2 + fin_depth/2 - overlap, 0, zpos])
                cube([fin_depth, fin_len, fin_h], center=true);

            // Left side fins
            translate([-body_size/2 - fin_depth/2 + overlap, 0, zpos])
                cube([fin_depth, fin_len, fin_h], center=true);
        }
    }
}

module front_face_step() {
    // Slight step between body and flange
    translate([0, body_length/2 + front_face_thk/2 - overlap, 0])
        cube([body_size*0.98, front_face_thk, body_size*0.98], center=true);
}

module front_flange() {
    translate([0, body_length/2 + front_flange_thk/2 - overlap, 0])
        cube([front_flange_size, front_flange_thk, front_flange_size], center=true);
}

module pilot_boss() {
    translate([0, body_length/2 + front_flange_thk + pilot_len/2 - overlap, 0])
        rotate([90, 0, 0])
            cylinder(r=pilot_d/2, h=pilot_len, center=true);
}

module shaft_shoulder() {
    translate([0, body_length/2 + front_flange_thk + shaft_shoulder_len/2 - overlap, 0])
        rotate([90, 0, 0])
            cylinder(r=shaft_shoulder_d/2, h=shaft_shoulder_len, center=true);
}

module output_shaft() {
    translate([0, body_length/2 + front_flange_thk + shaft_shoulder_len + shaft_len/2 - overlap, 0])
        rotate([90, 0, 0])
            cylinder(r=shaft_d/2, h=shaft_len, center=true);
}

module rear_register_and_boss() {
    // Rear circular register + small center boss
    translate([0, -body_length/2 - rear_register_len/2 + overlap, 0])
        rotate([90, 0, 0])
            cylinder(r=rear_register_d/2, h=rear_register_len, center=true);

    translate([0, -body_length/2 - rear_register_len - rear_center_boss_len/2 + overlap, 0])
        rotate([90, 0, 0])
            cylinder(r=rear_center_boss_d/2, h=rear_center_boss_len, center=true);
}

module rear_connector_housing() {
    // Rectangular connector housing on rear face (offset in Z), with a small lip/strain relief
    translate([conn_side_offset_x,
               -body_length/2 - conn_len/2 + overlap,
               conn_offset_z])
        cube([conn_w, conn_len, conn_h], center=true);

    translate([conn_side_offset_x,
               -body_length/2 - (conn_len*0.35)/2 + overlap,
               conn_offset_z])
        cube([conn_w + conn_lip*2, conn_len*0.35, conn_h + conn_lip*2], center=true);
}

module side_nameplate_pad() {
    // Raised pad on +X side
    pad_thk = 1.2;
    translate([body_size/2 + pad_thk/2 - overlap, 0, 0])
        cube([pad_thk, plate_y_span, plate_h], center=true);
}

module top_cap() {
    // Slight inset cap on top surface (adds top-view features)
    if (top_cap_thk > 0) {
        translate([0, 0, body_size/2 + top_cap_thk/2 - overlap])
            rounded_box([body_size - 2*top_cap_inset,
                         body_length*0.92,
                         top_cap_thk],
                        r=max(body_corner_r*0.6, 0.6),
                        center=true);
    }
}

module rear_cap_block() {
    // Rear housing step (common on servos): a block on rear face, inset in X and limited in Z
    if (rear_cap_thk > 0) {
        translate([0,
                   -body_length/2 - rear_cap_thk/2 + overlap,
                   0])
            rounded_box([body_size - 2*rear_cap_inset,
                         rear_cap_thk,
                         rear_cap_height],
                        r=max(body_corner_r*0.6, 0.6),
                        center=true);
    }
}

// -------------------- Cuts (details) --------------------
module side_nameplate_recess_cut() {
    // Recess into the pad to create framed look
    pad_thk = 1.2;
    translate([body_size/2 + pad_thk/2 - overlap/2, 0, 0])
        cube([pad_thk + overlap*3, plate_y_span*0.82, plate_h*0.72], center=true);
}

module top_grooves_cut() {
    // Grooves cut into top cap/body so top view isn't a solid square
    if (top_groove_count > 0 && top_groove_d > 0) {
        // distribute grooves across X
        for (i = [0:top_groove_count-1]) {
            xpos = ((i/(max(top_groove_count-1,1))) - 0.5) * (body_size*0.55);
            translate([xpos, 0, body_size/2 - top_groove_d/2 + overlap*0.2])
                cube([top_groove_w, top_groove_len, top_groove_d + overlap*2], center=true);
        }
    }
}

module front_face_relief_cut() {
    // Small rectangular relief on front face (around pilot) to add recognizable face geometry
    relief_w = body_size*0.55;
    relief_h = body_size*0.55;
    relief_d = 0.8;
    translate([0,
               body_length/2 + relief_d/2 - overlap*0.2,
               0])
        cube([relief_w, relief_d + overlap*2, relief_h], center=true);
}

// -------------------- Assembly --------------------
module main_solid_pre_cuts() {
    union() {
        motor_body();

        // Body details
        edge_rails();
        cooling_fins();
        top_cap();
        rear_cap_block();

        // Front mechanical features
        front_face_step();
        front_flange();
        pilot_boss();
        shaft_shoulder();
        output_shaft();

        // Rear mechanical + connector
        rear_register_and_boss();
        rear_connector_housing();

        // Side pad (nameplate area)
        side_nameplate_pad();
    }
}

module model_with_cuts() {
    difference() {
        main_solid_pre_cuts();

        // Mounting holes through flange
        mounting_holes_pattern();

        // Shaft flat
        shaft_flat_cut();

        // Recess in side pad (no text)
        side_nameplate_recess_cut();

        // Top grooves
        top_grooves_cut();

        // Front face relief
        front_face_relief_cut();
    }
}

// Final Output (single connected solid)
model_with_cuts();

// Lichuan -80M04030B (approximate) - connected solid model
// Axis convention: Z = motor axis (front to rear). Front face at +Z.
// One connected solid: all added features overlap slightly; holes/slots subtracted at end.

$fn = 96;

// ---------------- Parameters ----------------
body_w = 80; //[40:160:1]
body_h = 80; //[40:160:1]
body_l = 120; //[60:240:1]

// Make the housing look like a servo: rounded edges + slight front step
body_corner_r = 6; //[0:12:0.5]
front_step_t  = 4; //[0:10:0.5]
front_step_inset = 3; //[0:8:0.5]

front_face_t = 6; //[3:12:0.5]
rear_cap_t   = 8; //[4:16:0.5]

flange_w = 90; //[60:140:1]
flange_h = 90; //[60:140:1]
flange_chamfer = 2; //[0.5:6:0.5]

mount_hole_d = 6.6; //[3:13.2:0.1]
mount_hole_spacing = 65; //[40:130:0.5]

pilot_d = 55; //[30:110:0.5]
pilot_h = 2.5; //[1:6:0.1]

shaft_d = 19; //[10:38:0.5]
shaft_l = 40; //[20:80:1]
shaft_flat_depth = 1.5; //[0.5:4:0.1]
shaft_flat_len = 25; //[10:60:1]
shaft_tap_d = 6; //[3:12:0.5]
shaft_tap_depth = 15; //[5:30:1]

// Rear features
brake_d = 70; //[40:120:0.5]
brake_l = 25; //[10:60:1]

cable_stub_d = 16; //[8:32:0.5]
cable_stub_l = 25; //[10:50:1]

connector_w = 22; //[10:44:1]
connector_h = 14; //[6:28:1]
connector_l = 18; //[8:36:1]

// Side cooling fins
fin_count = 6; //[3:12:1]
fin_t = 2; //[1:4:0.5]
fin_depth = 4; //[2:10:0.5]
fin_len = 70; //[30:120:1]

// Front face details
face_recess_d = 38; //[20:70:0.5]
face_recess_t = 1.2; //[0.5:3:0.1]
key_slot_w = 6; //[2:12:0.5]
key_slot_h = 2; //[1:6:0.5]
key_slot_l = 18; //[6:30:1]

// Small overlap to guarantee connectivity
overlap = 1; //[0.5:2:0.1]

// ---------------- Helpers ----------------
module chamfered_plate_xy(w,h,t,ch){
  difference(){
    cube([w,h,t], center=true);
    for (sx=[-1,1], sy=[-1,1])
      translate([sx*(w/2 - ch/2), sy*(h/2 - ch/2), 0])
        rotate([0,0,45])
          cube([ch, ch, t + 2*overlap], center=true);
  }
}

module rounded_box(size=[10,10,10], r=2){
  // Minkowski rounded box; centered
  // Keep r reasonable vs size to avoid degeneracy
  rr = min(r, min(size[0], min(size[1], size[2]))/2 - 0.01);
  minkowski(){
    cube([size[0]-2*rr, size[1]-2*rr, size[2]-2*rr], center=true);
    sphere(r=rr);
  }
}

module motor_complete(){
  difference(){
    union(){
      // Main housing (rounded)
      color("Black")
        rounded_box([body_w, body_h, body_l], body_corner_r);

      // Front step (slightly inset) to make front view recognizable
      if (front_step_t > 0)
        color("Black")
          translate([0,0, body_l/2 - front_step_t/2 + overlap])
            rounded_box([body_w-2*front_step_inset, body_h-2*front_step_inset, front_step_t + 2*overlap],
                        max(0, body_corner_r-2));

      // Front flange / mounting face (connected)
      color("Silver")
        translate([0,0, body_l/2 + front_face_t/2 - overlap])
          chamfered_plate_xy(flange_w, flange_h, front_face_t, flange_chamfer);

      // Front pilot boss (connected)
      color("Silver")
        translate([0,0, body_l/2 + front_face_t - overlap + pilot_h/2 - overlap])
          cylinder(h=pilot_h + 2*overlap, r=pilot_d/2, center=true);

      // Output shaft (connected)
      color("Silver")
        translate([0,0, body_l/2 + front_face_t - overlap + shaft_l/2 - overlap])
          cylinder(h=shaft_l + 2*overlap, r=shaft_d/2, center=true);

      // Rear endcap (connected)
      color("Black")
        translate([0,0, -body_l/2 - rear_cap_t/2 + overlap])
          rounded_box([body_w, body_h, rear_cap_t], max(0, body_corner_r-1));

      // Rear brake bulge (connected)
      color("Black")
        translate([0,0, -body_l/2 - rear_cap_t + overlap - brake_l/2 + overlap])
          cylinder(h=brake_l + 2*overlap, r=brake_d/2, center=true);

      // Cable exit stub (connected)
      color("Black")
        translate([0,0, -body_l/2 - rear_cap_t + overlap - cable_stub_l/2 + overlap])
          cylinder(h=cable_stub_l + 2*overlap, r=cable_stub_d/2, center=true);

      // Connector block (connected to rear endcap; offset to side)
      color("Black")
        translate([ body_w/2 - connector_w/2 + overlap,
                    0,
                    -body_l/2 - rear_cap_t + overlap - connector_l/2 + overlap])
          rounded_box([connector_w, connector_h, connector_l + 2*overlap], 1.2);

      // Cooling fins (connected to right side of body)
      color("DimGray")
      for (i = [1:fin_count]){
        translate([ body_w/2 + fin_depth/2 - overlap,
                    -body_h/2 + i*(body_h/(fin_count+1)),
                    0 ])
          cube([fin_depth, fin_t, fin_len], center=true);
      }
    }

    // ---------------- Subtractions ----------------

    // Mounting holes through front face
    for (sx=[-1,1], sy=[-1,1])
      translate([sx*mount_hole_spacing/2, sy*mount_hole_spacing/2,
                 body_l/2 + front_face_t/2 - overlap])
        cylinder(h=front_face_t + 6*overlap, r=mount_hole_d/2, center=true);

    // Front circular recess around pilot (visual detail)
    translate([0,0, body_l/2 + front_face_t - face_recess_t/2 - overlap])
      cylinder(h=face_recess_t + 2*overlap, r=face_recess_d/2, center=true);

    // Small key/slot on front face (visual detail)
    translate([0,0, body_l/2 + front_face_t - key_slot_h/2 - overlap])
      cube([key_slot_w, key_slot_l, key_slot_h + 2*overlap], center=true);

    // Shaft flat (D-shaft) near the tip
    translate([ shaft_d/2 - shaft_flat_depth/2, 0,
                body_l/2 + front_face_t - overlap + shaft_l - shaft_flat_len/2 - overlap])
      cube([shaft_d, shaft_d, shaft_flat_len + 2*overlap], center=true);

    // Tapped hole in shaft end
    translate([0,0,
               body_l/2 + front_face_t - overlap + shaft_l - shaft_tap_depth/2 - overlap])
      cylinder(h=shaft_tap_depth + 2*overlap, r=shaft_tap_d/2, center=true);
  }
}

// Render
motor_complete();

// Rigid shaft coupling: 5.0mm to 8.0mm bore, 12.5mm OD, 25.0mm long
// One connected solid; visible stepped bores + clamp slit + cross set-screw holes.

$fn = 128;

// Parameters
L = 25.0;                 // overall length
OD = 12.5;                // outer diameter

bore_a_d = 5.0;           // end A bore diameter
bore_b_d = 8.0;           // end B bore diameter
bore_a_depth = 12.5;      // depth from end A
bore_b_depth = 12.5;      // depth from end B

step_len = 0.6;           // short transition length at center
eps = 0.02;               // small overlap for robust booleans

set_screw_d = 3.0;        // cross hole diameter
set_screw_z_offset = 6.25;// distance from center along length to each cross hole

slit_w = 1.2;             // clamp slit width
slit_depth = OD/2 + 0.6;  // how far slit cuts radially inward (must reach bore)

chamfer_len = 0.8;        // end chamfer length

// Derived
R = OD/2;
bore_a_r = bore_a_d/2;
bore_b_r = bore_b_d/2;

// --- Base body ---
module body() {
    cylinder(h=L, r=R, center=true);
}

// --- Stepped bores (from each end) ---
module bore_a() {
    // From end A (negative Z) toward center
    translate([0,0, -L/2 + bore_a_depth/2])
        cylinder(h=bore_a_depth + 2*eps, r=bore_a_r, center=true);
}

module bore_b() {
    // From end B (positive Z) toward center
    translate([0,0,  L/2 - bore_b_depth/2])
        cylinder(h=bore_b_depth + 2*eps, r=bore_b_r, center=true);
}

module bore_transition() {
    // Transition centered at Z=0; ensure it bridges between the two bores
    cylinder(h=step_len + 2*eps, r1=bore_a_r, r2=bore_b_r, center=true);
}

// --- Cross set-screw holes (through OD) ---
module set_screw_holes() {
    // Drill along Y axis (after rotate), positioned at +/- set_screw_z_offset along Z
    for (zpos = [-set_screw_z_offset, set_screw_z_offset]) {
        translate([0,0,zpos])
            rotate([90,0,0])
                cylinder(h=OD + 4*eps, r=set_screw_d/2, center=true);
    }
}

// --- Clamp slit (axial slit from OD into bore) ---
module clamp_slit() {
    // A rectangular cut running full length, positioned at +X edge so it opens to outside.
    // Center at x = R - slit_depth/2 so outer face intersects OD and inner face reaches past center.
    translate([R - slit_depth/2, 0, 0])
        cube([slit_depth + 2*eps, slit_w, L + 4*eps], center=true);
}

// --- End chamfers (cut away) ---
module end_chamfers() {
    // Cut cones at both ends to create chamfers
    translate([0,0, -L/2 + chamfer_len/2])
        cylinder(h=chamfer_len + 2*eps, r1=R + eps, r2=R - chamfer_len, center=true);

    translate([0,0,  L/2 - chamfer_len/2])
        cylinder(h=chamfer_len + 2*eps, r1=R - chamfer_len, r2=R + eps, center=true);
}

// --- Final model ---
difference() {
    body();

    // Internal features
    bore_a();
    bore_b();
    bore_transition();

    // External/functional features
    set_screw_holes();
    clamp_slit();
    end_chamfers();
}

// Flexible shaft coupling: 6mm to 8mm bore, 19mm OD, 25mm long
// One connected solid; all placements derived from dimensions.

$fn = 128;

// --- Primary dimensions (mm)
OD = 19;
L  = 25;

// Bores
bore_A_d     = 6;     // end A
bore_B_d     = 8;     // end B
bore_A_depth = 12;
bore_B_depth = 12;

// Middle web between bores (keeps part connected)
center_web = 1.0;     // material thickness between the two bores

// Flex cuts (helical-ish slots around OD)
flex_cut_count        = 6;
flex_cut_width        = 1.2;
flex_cut_radial_depth = 3.2;
flex_cut_axial_len    = 20;
flex_cut_twist_deg    = 25;

// Clamp slit + screw (typical clamping style)
clamp_slit_w = 1.0;   // slit width
clamp_slit_depth = OD/2; // slit reaches to centerline (but not beyond)
set_screw_d = 3.0;
set_screw_z_offset = 4.0; // from each end face toward center

// Edge chamfer
chamfer_h = 0.8;
chamfer_radial = 0.8;

// Robust boolean overlap
eps = 0.2;

// --- Derived checks / constraints
bore_A_depth_eff = min(bore_A_depth, (L - center_web)/2);
bore_B_depth_eff = min(bore_B_depth, (L - center_web)/2);

// Bore centers (from part center, along Z)
bore_A_z = -L/2 + bore_A_depth_eff/2;
bore_B_z =  L/2 - bore_B_depth_eff/2;

// Clamp slit Z extents (each half)
slit_half_len = (L - center_web)/2;

// --- Base body
module coupling_body() {
  cylinder(h=L, r=OD/2, center=true);
}

// --- Bores (blind from each end, leaving center_web)
module bore_end_A() {
  translate([0,0,bore_A_z])
    cylinder(h=bore_A_depth_eff + eps, r=bore_A_d/2, center=true);
}

module bore_end_B() {
  translate([0,0,bore_B_z])
    cylinder(h=bore_B_depth_eff + eps, r=bore_B_d/2, center=true);
}

// --- Outer edge chamfers (simple 45-ish via conical subtraction)
module end_chamfer(zsign=1) {
  // zsign: +1 for +Z end, -1 for -Z end
  z0 = zsign*(L/2 - chamfer_h/2);
  translate([0,0,z0])
    difference() {
      cylinder(h=chamfer_h + eps, r=OD/2 + eps, center=true);
      cylinder(h=chamfer_h + 2*eps, r1=OD/2 - chamfer_radial, r2=OD/2 + eps, center=true);
    }
}

// --- Flex cut slot (hull between twisted top/bottom to suggest helix)
module flex_cut_slot() {
  // Slot positioned near OD, cutting inward by flex_cut_radial_depth
  x_center = (OD/2) - (flex_cut_radial_depth/2);
  slot_len = min(flex_cut_axial_len, L - 2*chamfer_h);

  hull() {
    translate([x_center, 0,  slot_len/2])
      rotate([0,0, flex_cut_twist_deg])
        cube([flex_cut_radial_depth + eps, flex_cut_width, slot_len], center=true);

    translate([x_center, 0, -slot_len/2])
      rotate([0,0,-flex_cut_twist_deg])
        cube([flex_cut_radial_depth + eps, flex_cut_width, slot_len], center=true);
  }
}

module helical_flex_cuts() {
  for (i=[0:flex_cut_count-1])
    rotate([0,0,i*360/flex_cut_count])
      flex_cut_slot();
}

// --- Clamp slits (one per end, do not cross center_web)
module clamp_slit_end(zsign=1) {
  // Slit runs along Z within one half, located at +X side
  zc = zsign*(center_web/2 + slit_half_len/2);
  translate([OD/2 - clamp_slit_depth/2, 0, zc])
    cube([clamp_slit_depth + eps, clamp_slit_w, slit_half_len + eps], center=true);
}

// --- Set screw holes (radial, one per end, aligned with clamp slit)
module set_screw_hole_end(zsign=1) {
  // Place along Z from each end face inward by set_screw_z_offset
  zc = zsign*(L/2 - set_screw_z_offset);
  // Drill along Y (radial), centered on +X side so it intersects the slit region
  translate([OD/2 - clamp_slit_depth + (set_screw_d/2), 0, zc])
    rotate([90,0,0])
      cylinder(h=OD + 2*eps, r=set_screw_d/2, center=true);
}

// --- Final model
module coupling() {
  difference() {
    // Main solid
    coupling_body();

    // Functional voids
    bore_end_A();
    bore_end_B();

    // Flexibility cuts
    helical_flex_cuts();

    // Clamp slits (one per end)
    clamp_slit_end(-1);
    clamp_slit_end( 1);

    // Set screw holes (one per end)
    set_screw_hole_end(-1);
    set_screw_hole_end( 1);

    // End chamfers (subtractive)
    end_chamfer(-1);
    end_chamfer( 1);
  }
}

