// Sheet: carbon fiber (single connected solid with subtle weave relief)

// Parameters
sheet_length = 300; //[150:600:1]
sheet_width = 200;  //[100:400:1]
sheet_thickness = 2; //[1:4:0.1]
corner_radius = 5;  //[2.5:10:0.5]

// Weave relief (kept small but visible)
weave_pitch = 8;     // mm between weave ridges
weave_relief = 0.18; //[0.05:0.4:0.01]
weave_angle = 45;    // degrees
overlap = 0.08;      // ensures unioned solids overlap

$fn = 64;

// Rounded-rectangle prism using linear_extrude of a 2D rounded rectangle
module rounded_rect_prism(L, W, H, R) {
    R2 = min(R, min(L, W)/2 - 0.01);
    linear_extrude(height=H, center=true, convexity=10)
        offset(r=R2)
            square([max(0.01, L - 2*R2), max(0.01, W - 2*R2)], center=true);
}

// 2D diagonal ridge pattern clipped to the sheet outline (rounded rectangle)
module ridge_pattern_2d(L, W, R, pitch, strip_w, angle_deg) {
    R2 = min(R, min(L, W)/2 - 0.01);
    span = sqrt(L*L + W*W) + 2*pitch;

    intersection() {
        // Clip to rounded rectangle footprint
        offset(r=R2)
            square([max(0.01, L - 2*R2), max(0.01, W - 2*R2)], center=true);

        // Repeated strips, rotated
        rotate(angle_deg)
            union() {
                for (x = [-span : pitch : span])
                    translate([x, 0])
                        square([strip_w, 2*span], center=true);
            }
    }
}

// Main module
module carbon_fiber_sheet() {
    L = sheet_length;
    W = sheet_width;
    T = sheet_thickness;
    R = corner_radius;

    // Relief kept within thickness; ensure visible but not excessive
    relief = min(weave_relief, max(0.05, T*0.35));
    strip_w = max(0.8, weave_pitch*0.40);

    // Place relief so it is embedded into the top surface (single connected solid)
    // Relief layer spans from z = T/2 - relief - overlap  to  z = T/2 - overlap
    relief_z = T/2 - relief/2 - overlap/2;

    color([0.06, 0.06, 0.07])
    union() {
        // Base sheet with rounded corners
        rounded_rect_prism(L, W, T, R);

        // Subtle weave: two crossed ridge layers on the top surface (embedded)
        translate([0, 0, relief_z])
            linear_extrude(height=relief + overlap, center=true, convexity=10)
                ridge_pattern_2d(L, W, R, weave_pitch, strip_w, weave_angle);

        translate([0, 0, relief_z])
            linear_extrude(height=relief + overlap, center=true, convexity=10)
                ridge_pattern_2d(L, W, R, weave_pitch, strip_w, -weave_angle);
    }
}

// Render
carbon_fiber_sheet();

// Corrugated cardboard sheet (render-friendly)
// Single connected solid: rounded sheet + internal fluted core + optional exposed edge.
// Simplified: removed heavy face groove cutters and redundant booleans.

// ---------------- Parameters ----------------
sheet_L = 300; //[150:600:1]
sheet_W = 200; //[100:400:1]
sheet_T = 4;   //[2:8:0.1]
liner_T = 0.4; //[0.2:0.8:0.05]

flute_pitch = 8; //[4:16:0.5]
flute_amp = 1.6; //[0.8:3.2:0.1]

corner_R = 8; //[2:20:0.5]

edge_detail_depth = 12; //[0:40:1]
edge_detail_on = 1;     //[0:1:1]

// Quality
$fn = 24;

// ---------------- Derived ----------------
eps = 0.02;
core_T = max(0.2, sheet_T - 2*liner_T);

// ---------------- Helpers ----------------
module rounded_rect_prism(L, W, H, R) {
  r = max(0, min(R, min(L, W)/2 - eps));
  linear_extrude(height=H, center=true, convexity=4)
    offset(r=r)
      square([L - 2*r, W - 2*r], center=true);
}

function wave_y(x, pitch, amp) = amp * sin(360 * x / pitch);

module fluted_core_solid(L, W, T, pitch, amp) {
  // 2D X-Z ribbon extruded along Y
  n = max(24, ceil(L / (pitch/2)));   // reduced segments for speed
  dx = L / n;

  a = min(amp, max(0.05, T/2 - eps));

  top_pts = [
    for (i = [0:n])
      let(x = -L/2 + i*dx)
      [x,  T/2 - a + wave_y(x + L/2, pitch, a)]
  ];

  bot_pts = [
    for (i = [n:-1:0])
      let(x = -L/2 + i*dx)
      [x, -T/2 + a + wave_y(x + L/2, pitch, a)]
  ];

  rotate([90,0,0])
    linear_extrude(height=W, center=true, convexity=6)
      polygon(points=concat(top_pts, bot_pts));
}

module edge_flute_window(L, W, T, pitch, amp, depth) {
  d = max(0, depth);
  if (d > 0) {
    // Add a short fluted section at +X edge (unioned, connected)
    translate([L/2 - d/2 + eps, 0, 0])
      fluted_core_solid(d + 2*eps, W + 2*eps, T, pitch, amp);
  }
}

// ---------------- Main model ----------------
module corrugated_cardboard_sheet() {
  union() {
    // Outer sheet
    rounded_rect_prism(sheet_L, sheet_W, sheet_T, corner_R);

    // Internal fluted core (slightly thicker to ensure intersection with liners)
    fluted_core_solid(sheet_L, sheet_W, core_T + 2*eps, flute_pitch, flute_amp);

    // Optional exposed edge detail
    if (edge_detail_on)
      edge_flute_window(sheet_L, sheet_W, core_T + 2*eps, flute_pitch, flute_amp, edge_detail_depth);
  }
}

// ---------------- Final Output ----------------
corrugated_cardboard_sheet();

// Sheet DiBond (single connected solid)

// Parameters
sheet_length = 1000; //[500:2000:1]
sheet_width = 500;   //[250:1000:1]
sheet_thickness = 3; //[1.5:6:0.1]
corner_radius = 20;  //[5:60:1]
hole_diameter = 6;   //[3:12:0.5]
hole_edge_offset = 25; //[10:80:1]
edge_chamfer = 0.8;  //[0.2:2:0.1]

// Robustness / overlap
eps = 0.01;
overlap = 1; //[0.5:2:0.1]

// Derived checks (avoid invalid geometry)
cr = min(corner_radius, min(sheet_length, sheet_width)/2 - eps);
heo = min(hole_edge_offset, min(sheet_length, sheet_width)/2 - cr - eps);
ch = min(edge_chamfer, sheet_thickness/2 - eps);

// 2D rounded rectangle (exact, no floating corner cutters)
module rounded_rect_2d(L, W, R) {
    hull() {
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx*(L/2 - R), sy*(W/2 - R)])
                circle(r=R, $fn=64);
    }
}

// Final sheet: rounded corners + holes + edge chamfer, all connected
module dibond_sheet() {
    difference() {
        // Chamfered solid made by hulling top and bottom rounded rectangles
        hull() {
            translate([0, 0, -sheet_thickness/2])
                linear_extrude(height=eps)
                    rounded_rect_2d(sheet_length, sheet_width, cr);

            translate([0, 0,  sheet_thickness/2])
                linear_extrude(height=eps)
                    offset(delta=-ch)
                        rounded_rect_2d(sheet_length, sheet_width, cr);
        }

        // Mounting holes (through)
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx*(sheet_length/2 - heo), sy*(sheet_width/2 - heo), 0])
                cylinder(h=sheet_thickness + 2*overlap, r=hole_diameter/2, center=true, $fn=64);
    }
}

// Output
color([0.85, 0.85, 0.8])
dibond_sheet();

// Sheet DiBond (plain single connected solid)

// Parameters
sheet_length = 1000; //[500:2000:1]
sheet_width = 500; //[250:1000:1]
sheet_thickness = 3; //[1.5:6:0.5]
corner_radius = 0; //[0:50:1]
edge_chamfer = 0; //[0:5:0.5]

// Plain sheet request: no holes/markers by default
mount_hole_diameter = 6; //[2:20:0.5]
mount_hole_edge_offset = 20; //[5:100:1]
mount_hole_count = 0; //[0:4:1]
marking_depth = 0; //[0:1:0.1]
marking_margin = 30; //[5:150:1]

overlap = 0.5; //[0.1:2:0.1]

$fn = 96;

// Helpers
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

r_eff  = clamp(corner_radius, 0, min(sheet_length, sheet_width)/2);
ch_eff = clamp(edge_chamfer, 0, min(sheet_length, sheet_width, sheet_thickness)/2);
hole_r = mount_hole_diameter/2;

// 2D rounded rectangle
module rounded_rect_2d(L, W, R) {
  R2 = clamp(R, 0, min(L, W)/2);
  if (R2 <= 0) {
    square([L, W], center=true);
  } else {
    hull() {
      for (sx = [-1, 1], sy = [-1, 1])
        translate([sx*(L/2 - R2), sy*(W/2 - R2)]) circle(r=R2);
    }
  }
}

// Base sheet (extruded 2D profile)
module sheet_solid() {
  linear_extrude(height=sheet_thickness, center=true)
    rounded_rect_2d(sheet_length, sheet_width, r_eff);
}

// Optional mounting holes (through)
module mounting_holes() {
  x = sheet_length/2 - mount_hole_edge_offset;
  y = sheet_width/2  - mount_hole_edge_offset;

  if (mount_hole_count == 4 && x > hole_r && y > hole_r) {
    for (sx = [-1, 1], sy = [-1, 1])
      translate([sx*x, sy*y, 0])
        cylinder(r=hole_r, h=sheet_thickness + 2*overlap, center=true);
  }
}

// Optional surface marking (shallow pocket on top face)
module surface_marking() {
  Lm = sheet_length - 2*marking_margin;
  Wm = sheet_width  - 2*marking_margin;

  if (marking_depth > 0 && Lm > 0 && Wm > 0) {
    translate([0, 0, sheet_thickness/2 - marking_depth/2])
      linear_extrude(height=marking_depth + overlap, center=true)
        rounded_rect_2d(Lm, Wm, max(r_eff - marking_margin, 0));
  }
}

// Optional edge chamfer (simple bevel approximation via hull of two profiles)
module chamfered_sheet() {
  if (ch_eff <= 0) {
    sheet_solid();
  } else {
    // Ensure valid inner dimensions
    L2 = max(sheet_length - 2*ch_eff, 0.01);
    W2 = max(sheet_width  - 2*ch_eff, 0.01);
    R2 = max(r_eff - ch_eff, 0);

    hull() {
      // Bottom face profile (full size)
      translate([0, 0, -sheet_thickness/2])
        linear_extrude(height=0.01, center=false)
          rounded_rect_2d(sheet_length, sheet_width, r_eff);

      // Top face profile (shrunk by chamfer amount)
      translate([0, 0,  sheet_thickness/2])
        linear_extrude(height=0.01, center=false)
          rounded_rect_2d(L2, W2, R2);
    }
  }
}

// Final Model (single connected solid)
module complete_model() {
  difference() {
    chamfered_sheet();
    mounting_holes();
    surface_marking();
  }
}

// Render
color([0.75, 0.75, 0.77]) complete_model();

