module surface_texture_pores() {
  union() {
    translate([-sheet_L/2 + pore_margin, -sheet_W/2 + pore_margin, sheet_T/2 - pore_depth/2 - pore_overlap])
      sphere(r=pore_radius, center=true);
    translate([sheet_L/2 - pore_margin, -sheet_W/2 + pore_margin, sheet_T/2 - pore_depth/2 - pore_overlap])
      sphere(r=pore_radius, center=true);
    translate([-sheet_L/2 + pore_margin, sheet_W/2 - pore_margin, sheet_T/2 - pore_depth/2 - pore_overlap])
      sphere(r=pore_radius, center=true);
    translate([sheet_L/2 - pore_margin, sheet_W/2 - pore_margin, sheet_T/2 - pore_depth/2 - pore_overlap])
      sphere(r=pore_radius, center=true);
    translate([0, 0, sheet_T/2 - pore_depth/2 - pore_overlap])
