metallization_thickness = 0.06; //[0.02:0.2:0.01]

// Small overlap to guarantee connectivity / robust booleans
overlap = 0.08; //[0.01:0.3:0.01]

// --- Helpers ---
function clamp(v, lo, hi) = min(max(v, lo), hi);

