  difference() {
    smd_body();

    // Marking recess on top face
    translate([0, 0, body_height/2 - marking_depth/2 + overlap/2])
      top_marking_cut();

    // Top corner chamfers
    chamfer_cutters();
  }
}

// Final connected model
module complete_model() {
  union() {
    body_with_details();
    metallization_pads();
