shaft_flat_L = 10.0;           // length of flat along shaft (from tip)

connector_W = 12.0;
connector_H = 8.0;
connector_L = 6.0;
connector_offset_Z = 0.0;

body_corner_R = 2.0;           // corner radius for body (rounded square)

