      translate([0, 0, zpos])
        difference() {
          // Rib ring (outer bump)
          cylinder(h=rib_width, r=outer_r + rib_height, center=true);
          // Keep it as a thin ring on the outside (do not fill the bore)
          cylinder(h=rib_width + 2*connect_overlap, r=outer_r - 0.001, center=true);
